INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cb635a7c-c1af-508f-8e12-335ca44b5611', 'The human heart has how many CHAMBERS?', NULL, '4 chambers: right atrium, right ventricle, left atrium, left ventricle. Two-circuit design: right side pumps to lungs (pulmonary), left side pumps to body (systemic). Amphibians have 3 chambers (2 atria + 1 ventricle); fish have 2; birds + mammals have 4.', 'EASY', 'Biology', 'Heart & circulation — mixed tiers', 'BIO_CIRCULATION', '[{"option_text": "2 (one atrium + one ventricle)", "is_correct": false}, {"option_text": "4 (2 atria + 2 ventricles)", "is_correct": true}, {"option_text": "3", "is_correct": false}, {"option_text": "5", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3b2711c7-3fb9-5e57-9433-8ff43ea64ab0', 'The DOUBLE-HELIX structure of DNA was proposed in 1953 by:', NULL, 'James Watson + Francis Crick — proposed the double-helix model in Nature, April 1953. Used the X-ray crystallography ''Photo 51'' produced by Rosalind Franklin (in Maurice Wilkins''s lab at King''s College London). Nobel 1962 — Watson, Crick, Wilkins; Franklin had passed away in 1958 (ovarian cancer); Nobel rules don''t allow posthumous awards. Earlier — Erwin Chargaff (1950) showed A = T, G = C (''Chargaff''s rules''). Frederick Griffith (1928) — bacterial transformation; Avery-MacLeod-McCarty (1944) — DNA, not protein, is the genetic material. Hershey-Chase (1952) — phage experiment confirmed DNA as the hereditary molecule.', 'EASY', 'Biology', 'DNA, RNA and molecular genetics — mixed tiers', 'BIO_GENETICS', '[{"option_text": "Mendel and Darwin", "is_correct": false}, {"option_text": "Watson and Crick (with key X-ray data from Rosalind Franklin and Maurice Wilkins)", "is_correct": true}, {"option_text": "Pasteur and Koch", "is_correct": false}, {"option_text": "Lamarck and Wallace", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6021d2eb-b174-5aa7-baa4-a6855aef5fbf', 'The TROPICAL RAINFOREST biome is characterised by:', NULL, 'TROPICAL RAINFORESTS — found near equator (Amazon, Congo, Indonesia, NE India, Western Ghats). Climate: high temperature (~25-30°C year-round), high humidity, RAINFALL >2000 mm/year (often >3000 mm). HIGHEST BIODIVERSITY of any biome (~50% of world''s species in ~5% of land). Layers: emergent, canopy, understory, forest floor. India: Western Ghats, NE states, Andaman + Nicobar. Threats: deforestation, agriculture, mining. Distractor 1 = tundra. Distractor 3 = desert. Distractor 4 = polar / glacier.', 'EASY', 'Biology', 'Ecology + biomes — mixed tiers', 'BIO_ECOLOGY', '[{"option_text": "Cold winters, sparse vegetation cover", "is_correct": false}, {"option_text": "High temperature + heavy rainfall (>2000 mm)", "is_correct": true}, {"option_text": "Hot dry summers, with little rainfall", "is_correct": false}, {"option_text": "Permanent ice cover over the soil", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('73d2bf16-0b07-571a-a3ed-5474c5c432a8', 'The scientific name of modern humans is:', NULL, 'Homo sapiens sapiens — modern humans. Key extinct relatives: Australopithecus (Lucy, ~3.2 m.y.a.), Homo habilis, Homo erectus, Homo neanderthalensis (cousin, not direct ancestor), Denisovans (known only from genome). All non-sapiens humans extinct by ~30,000 years ago.', 'MEDIUM', 'Biology', 'Evolution — mixed tiers', 'BIO_EVOLUTION', '[{"option_text": "Homo erectus", "is_correct": false}, {"option_text": "Homo sapiens sapiens", "is_correct": true}, {"option_text": "Homo neanderthalensis", "is_correct": false}, {"option_text": "Australopithecus afarensis", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0aa31a3a-7af2-5fbe-bac2-155dadc2e3ed', 'The HUMAN HEART has HOW MANY CHAMBERS?', NULL, 'HUMAN HEART — 4 CHAMBERS: 2 ATRIA (upper, receive blood) + 2 VENTRICLES (lower, pump blood out). RIGHT side (pulmonary circuit): RIGHT ATRIUM receives DEOXYGENATED blood from body (via vena cava) → RIGHT VENTRICLE → pulmonary ARTERY → LUNGS (oxygenation). LEFT side (systemic circuit): LEFT ATRIUM receives OXYGENATED blood from lungs (via pulmonary VEINS) → LEFT VENTRICLE → AORTA → BODY. SEPTUM separates left and right (no direct blood mixing in healthy heart). HEART-CHAMBER COUNT in animals: (1) MAMMALS, BIRDS — 4 chambers (efficient double circulation). (2) REPTILES — 3 chambers (incomplete septum in ventricle; crocodile has 4). (3) AMPHIBIANS — 3 chambers (2 atria, 1 ventricle). (4) FISH — 2 chambers (1 atrium, 1 ventricle). KEY HEART STATS: (1) WEIGHT ~300 g. (2) Beats ~60-100/min at rest, up to ~200/min during exercise. (3) Pumps ~5 L blood/min at rest. (4) ~2 BILLION beats in average lifetime. (5) Heart muscle = MYOCARDIUM (involuntary, striated cardiac muscle); doesn''t fatigue normally. CARDIAC OUTPUT = stroke volume × heart rate. UPSC angle: heart anatomy in NCERT Class 11; biology PT and prelims often have one heart-related Q. PYQ FREQUENCY: 4-chamber heart in NEET, NCERT, SSC GA — 1-2× per cycle.', 'EASY', 'Biology', 'Heart Circulation III', 'BIO_CIRCULATION', '[{"option_text": "Four (2 atria + 2 ventricles)", "is_correct": true}, {"option_text": "Three (one atrium, two ventricles)", "is_correct": false}, {"option_text": "Two chambers (heart of fish)", "is_correct": false}, {"option_text": "Six chambers (an over-count)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c08c5559-2eea-576e-b52d-5fd844af59ff', 'The human heart has how many chambers?', NULL, 'Four chambers: right atrium → right ventricle → pulmonary artery → lungs (deoxygenated blood); left atrium ← pulmonary veins ← lungs (oxygenated blood) → left ventricle → aorta. Septum between left and right halves prevents mixing. Average size ~fist, mass ~300 g, beats ~72 bpm at rest = ~100,000 beats/day. Fish — 2 chambers (1A + 1V); frogs/reptiles — 3 (2A + 1V, except crocodiles); birds + mammals — 4 (complete double circulation).', 'EASY', 'Biology', 'Human heart and circulation — mixed tiers', 'BIO_CIRCULATION', '[{"option_text": "2", "is_correct": false}, {"option_text": "4 (two atria + two ventricles)", "is_correct": true}, {"option_text": "3", "is_correct": false}, {"option_text": "1", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8ee62a0c-45ad-5ca5-bd16-30e3558ac2f7', 'Mendel''s Law of Segregation states that:', NULL, 'Law of Segregation: the two alleles at a locus separate from each other during meiosis so each gamete carries only one allele.', 'EASY', 'Biology', 'Genetics and Heredity', 'BIO_GENETICS', '[{"option_text": "Genes on different chromosomes assort independently", "is_correct": false}, {"option_text": "Two alleles for a trait separate during gamete formation", "is_correct": true}, {"option_text": "Dominant allele always suppresses the recessive", "is_correct": false}, {"option_text": "Traits acquired during lifetime can be inherited", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('01f92b6b-3ebd-5ce0-b618-062f141d1f8f', 'Malaria is caused by:', NULL, 'Malaria is caused by protozoan parasites of genus Plasmodium (P. falciparum most deadly) transmitted through the bite of infected female Anopheles mosquitoes.', 'EASY', 'Biology', 'Human Diseases', 'BIO_DIS_BACTERIAL_VIRAL', '[{"option_text": "A bacterium — Mycobacterium", "is_correct": false}, {"option_text": "A virus", "is_correct": false}, {"option_text": "A fungus", "is_correct": false}, {"option_text": "Plasmodium (a protozoan parasite)", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3d4605be-dde6-5380-9d62-3afa8a9edfe7', 'Tuberculosis (TB) is caused by:', NULL, 'Tuberculosis is a bacterial infection caused by Mycobacterium tuberculosis. It primarily affects the lungs (pulmonary TB) but can affect other organs.', 'EASY', 'Biology', 'Human Diseases', 'BIO_DIS_BACTERIAL_VIRAL', '[{"option_text": "Vibrio cholerae", "is_correct": false}, {"option_text": "Plasmodium vivax", "is_correct": false}, {"option_text": "Streptococcus pneumoniae", "is_correct": false}, {"option_text": "Mycobacterium tuberculosis", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('256945b4-738d-5f56-ad5a-83adcf8acf71', 'The HUMAN HEART has how many chambers?', NULL, 'Human heart = 4 chambers: 2 ATRIA (upper, receive blood) + 2 VENTRICLES (lower, pump blood out). Right side handles DEOXYGENATED blood (body → lungs); Left side handles OXYGENATED blood (lungs → body). 4-chamber design = COMPLETE separation of oxygenated + deoxygenated blood; allows DOUBLE CIRCULATION + high O₂ delivery. FISH = 2 chambers (one atrium + one ventricle). FROGS / REPTILES = 3 chambers (incomplete septum in ventricle). MAMMALS + BIRDS = 4 chambers.', 'EASY', 'Biology', 'Human heart — mixed tiers', 'BIO_CIRCULATION', '[{"option_text": "Two — atrium and ventricle only", "is_correct": false}, {"option_text": "Four — 2 atria and 2 ventricles", "is_correct": true}, {"option_text": "Three — like reptiles or amphibians", "is_correct": false}, {"option_text": "One — single chamber pulsing pump", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('47cbf960-ead8-5134-a01e-cd94beaeaaaa', 'Which of the following diseases is NOT caused by a virus?', NULL, 'Tuberculosis — bacterial, caused by Mycobacterium tuberculosis. India carries the world''s largest TB burden. Polio — viral (poliovirus, now near-eradicated globally thanks to OPV). Hepatitis B — viral (HBV, DNA virus). COVID-19 — viral (SARS-CoV-2, RNA virus). Common bacterial diseases — TB, typhoid, cholera, tetanus, plague, leprosy, pneumonia. Common viral — measles, mumps, rubella, flu, AIDS, rabies, dengue, chikungunya.', 'MEDIUM', 'Biology', 'Immunity and common diseases — mixed tiers', 'BIO_IMMUNITY', '[{"option_text": "Polio", "is_correct": false}, {"option_text": "Tuberculosis", "is_correct": true}, {"option_text": "Hepatitis B", "is_correct": false}, {"option_text": "COVID-19", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b078b728-8b7c-55bd-bb12-a46cfedfc861', 'The functional UNIT of the kidney is the:', NULL, 'NEPHRON — basic structural + functional unit of kidney. Each kidney has ~1 MILLION nephrons. Parts: GLOMERULUS (capillary tuft) inside BOWMAN''S CAPSULE (cup-shaped); PCT (proximal convoluted tubule); LOOP OF HENLE (descending + ascending limbs, in medulla); DCT (distal CT); COLLECTING DUCT (multiple nephrons join here, drain into renal pelvis → ureter → bladder).', 'MEDIUM', 'Biology', 'Kidney + excretion — mixed tiers', 'BIO_EXCRETION', '[{"option_text": "Neuron, the nerve cell unit", "is_correct": false}, {"option_text": "Nephron, the filtration unit", "is_correct": true}, {"option_text": "Nephritis, an inflammation type", "is_correct": false}, {"option_text": "Glomerulus, only one part of nephron", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8c580599-507d-5c62-8842-539bfb6c3bf9', 'The LARGEST gland in the human body is the:', NULL, 'Liver — ~1.5 kg in an adult, and the largest INTERNAL organ + largest gland. Performs bile secretion (exocrine) + many endocrine-like functions (regulates blood sugar via glycogen, produces IGF-1, etc.).', 'EASY', 'Biology', 'Biology — mixed tiers (Clerk → UPSC)', 'BIO_HUMAN_BODY', '[{"option_text": "Pancreas", "is_correct": false}, {"option_text": "Liver", "is_correct": true}, {"option_text": "Thyroid", "is_correct": false}, {"option_text": "Adrenal", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('52aabaa0-36bd-5620-809b-381c31b0d356', 'The basic functional unit of the NERVOUS SYSTEM is the:', NULL, 'NEURON = the FUNCTIONAL and STRUCTURAL unit of the nervous system. Specialized cells that TRANSMIT electrical+chemical signals. STRUCTURE: (1) CELL BODY (SOMA) — contains nucleus, cytoplasm, organelles. (2) DENDRITES — branched extensions; RECEIVE signals from other neurons (input). (3) AXON — single long fibre; SENDS signals AWAY from cell body (output). (4) AXON TERMINALS — end of axon; release neurotransmitters at synapses. (5) MYELIN SHEATH — fatty insulating layer around axons (made by Schwann cells in PNS, oligodendrocytes in CNS); speeds signal transmission via SALTATORY CONDUCTION. (6) NODES OF RANVIER — gaps in myelin where signal jumps. SIZE: human brain has ~86 BILLION neurons + similar number of GLIAL cells (support cells). NEURON LENGTHS: from a few µm (interneurons in cortex) to 1+ METRE (sciatic nerve neurons spanning spine to toe). LIFESPAN: most neurons last a LIFETIME — they don''t divide (with limited exceptions in hippocampus, olfactory bulb). NEUROGENESIS — adult brain creates ~700 new neurons/day in hippocampus. PYQ FREQUENCY: ''functional unit of nervous system'' is a NEET, NCERT-driven SSC 1-mark guarantee.', 'EASY', 'Biology', 'Neurons Basics', 'BIO_NERVOUS', '[{"option_text": "Neuron (a single nerve cell)", "is_correct": true}, {"option_text": "Neurotransmitter is the unit", "is_correct": false}, {"option_text": "Spinal cord serves the role", "is_correct": false}, {"option_text": "Synapse counts as the unit", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('35f786ce-fe35-570a-b3b3-74f15da37ee1', 'The overall equation of PHOTOSYNTHESIS is:', NULL, 'Photosynthesis: 6CO₂ + 6H₂O + light energy → C₆H₁₂O₆ + 6O₂ (using chlorophyll). Reverse reaction is cellular respiration. Site: chloroplasts (thylakoids for light reactions, stroma for Calvin cycle).', 'EASY', 'Biology', 'Photosynthesis — mixed tiers', 'BIO_PLANT_PHYS', '[{"option_text": "6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂", "is_correct": true}, {"option_text": "C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O", "is_correct": false}, {"option_text": "CO₂ + H₂O → O₂ + C", "is_correct": false}, {"option_text": "6CO₂ → C₆H₁₂O₆", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c30393cc-583b-57e9-85a6-ef59a7e3ccca', 'The OXYGEN released during photosynthesis comes from:', NULL, 'Photolysis of water (H₂O → 4 H⁺ + O₂ + 4 e⁻) on the thylakoid — oxygen released is the byproduct. Proved by Robin Hill (Hill reaction) + Sam Ruben / Martin Kamen isotope-labelling experiments (¹⁸O-labelled water gave ¹⁸O₂). H₂O, via photolysis.', 'HARD', 'Biology', 'Photosynthesis — mixed tiers', 'BIO_PLANT_PHYS', '[{"option_text": "CO₂", "is_correct": false}, {"option_text": "Water", "is_correct": true}, {"option_text": "Glucose", "is_correct": false}, {"option_text": "Soil", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1a5961f2-cf08-52e8-af67-4f46442e6fda', 'The overall equation of photosynthesis is:', NULL, 'Photosynthesis: in the presence of sunlight and chlorophyll, 6 CO₂ + 6 H₂O → C₆H₁₂O₆ + 6 O₂. Respiration is the reverse. (The more precise form ''6CO₂ + 12 H₂O → C₆H₁₂O₆ + 6 O₂ + 6 H₂O'' balances oxygen-labelling-experiment stoichiometry but the simpler net form is the standard textbook version.)', 'MEDIUM', 'Biology', 'Plant biology — mixed tiers', 'BIO_PLANT_KINGDOM', '[{"option_text": "6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂", "is_correct": true}, {"option_text": "C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O", "is_correct": false}, {"option_text": "CO₂ + H₂ → CH₄ + O₂", "is_correct": false}, {"option_text": "6CO₂ + 12H₂O → C₆H₁₂O₆ + 6O₂", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e63dabc8-dcc6-54b7-bd39-ff48bb9a23fc', 'Fertilisation in humans normally takes place in the:', NULL, 'Fertilisation occurs in the AMPULLARY region of the fallopian tube (the wider segment closer to the ovary). Sperm travel from vagina → cervix → uterus → fallopian tube; fertilise the egg released from the ovary at ovulation. The resulting zygote moves down the tube over ~5-7 days, dividing → blastocyst → implants in the uterus'' endometrium. Implantation = pregnancy onset. IVF (in-vitro fertilisation) bypasses the tube — fertilisation happens in a petri dish, then transferred to uterus.', 'MEDIUM', 'Biology', 'Human reproductive system — mixed tiers', 'BIO_REPRODUCTION', '[{"option_text": "Uterus", "is_correct": false}, {"option_text": "Ampulla of the fallopian tube (oviduct)", "is_correct": true}, {"option_text": "Vagina", "is_correct": false}, {"option_text": "Cervix", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ed3d3c41-3b40-59fb-aa64-cedb5bee1b5f', 'Oxygen is transported in blood MAINLY by:', NULL, '~98% of oxygen in blood is carried by haemoglobin in RBCs. ~2% dissolved in plasma. Haemoglobin is an iron-containing protein; each molecule carries up to 4 O₂. CO₂ is transported ~70% as bicarbonate, ~20% as carbamino-haemoglobin, ~10% dissolved.', 'MEDIUM', 'Biology', 'Respiration — mixed tiers', 'BIO_RESPIRATION', '[{"option_text": "Plasma", "is_correct": false}, {"option_text": "Haemoglobin in red blood cells", "is_correct": true}, {"option_text": "White blood cells", "is_correct": false}, {"option_text": "Platelets", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1e2c2d06-fcd0-5427-ba2c-b704298bf4fe', 'VITAMIN K is essential for:', NULL, 'VITAMIN K — essential for BLOOD CLOTTING. Required for synthesis of PROTHROMBIN (Factor II) + several other CLOTTING FACTORS (VII, IX, X, Proteins C + S). DEFICIENCY: PROLONGED BLEEDING from minor wounds, hemorrhage, easy bruising. VITAMIN K — chemically: PHYLLOQUINONE (K1, from plants) or MENAQUINONES (K2, from gut bacteria). DISCOVERY: HENRIK DAM (Danish, 1929) — Nobel 1943 (with E. Doisy who isolated structure). ''K'' stands for ''KOAGULATION'' (German, clotting). NATURAL SOURCES: (1) GREEN LEAFY VEGETABLES (spinach, kale, broccoli, lettuce, cabbage) — richest. (2) Vegetable oils (soybean, canola). (3) Some fruits. (4) GUT BACTERIA SYNTHESIZE Vit K2! (long-term antibiotics can cause deficiency by killing these bacteria). RDA: 90-120 µg/day. NEONATAL VITAMIN K: NEWBORNS deficient → Vit K SHOT given at birth (intramuscular) — prevents HEMORRHAGIC DISEASE OF NEWBORNS (HDN). Standard practice in India + globally. ANTICOAGULANT DRUGS: WARFARIN (rat poison + medical anticoagulant) works by INHIBITING Vit K cycle → reduces clotting. Used in patients at thrombosis risk; needs careful Vit K diet management. KEY: GREEN LEAFY VEGETABLES + GUT BACTERIA usually keep Vit K adequate. EXCESS not stored well; daily intake recommended. INDIAN CONTEXT: traditional diet high in greens; deficiency uncommon. NOBEL: HENRIK DAM 1943. CARL DAM HOENISBERG isolated Vit K2. UPSC angle: nutrition foundations + paediatric public health. PYQ FREQUENCY: Vit K-clotting in NEET, NCERT, SSC GA 1× per cycle.', 'MEDIUM', 'Biology', 'Vitamins Deficiencies II', 'BIO_VITAMINS', '[{"option_text": "Blood clotting (prothrombin synthesis)", "is_correct": true}, {"option_text": "Vision (Vit A is for vision) (not this)", "is_correct": false}, {"option_text": "Bone strength (Vit D''s role) (not this)", "is_correct": false}, {"option_text": "Red blood cell formation (B12)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ee81eb1a-ce5b-52fc-ae21-fb2b71e38b18', 'Which of the following is a strong acid?', NULL, 'HCl is a strong acid — it completely dissociates in water. Acetic, carbonic, and citric acids are weak acids that partially dissociate.', 'EASY', 'Chemistry', 'Acids, Bases & Salts', 'CHE_ACIDS_BASES', '[{"option_text": "Acetic acid (CH₃COOH)", "is_correct": false}, {"option_text": "Carbonic acid (H₂CO₃)", "is_correct": false}, {"option_text": "Citric acid", "is_correct": false}, {"option_text": "Hydrochloric acid (HCl)", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c5655d98-cb65-55aa-9cfd-70e431f34b41', 'Litmus paper turns red in:', NULL, 'Litmus is a natural dye indicator. It turns red in acidic solutions (pH < 7) and blue in basic (alkaline) solutions.', 'EASY', 'Chemistry', 'Acids, Bases & Salts', 'CHE_ACIDS_BASES', '[{"option_text": "Basic solutions", "is_correct": false}, {"option_text": "Neutral solutions", "is_correct": false}, {"option_text": "Distilled water", "is_correct": false}, {"option_text": "Acidic solutions", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('95aa86f4-4ec7-58f0-a3db-5814eff4fb97', 'When excess sodium hydroxide solution is slowly added to copper sulphate solution, a precipitate forms immediately. What is the colour and chemical identity of this precipitate?', NULL, 'The reaction is CuSO4 + 2NaOH → Cu(OH)2↓ + Na2SO4. Cu(OH)2 precipitates as a pale blue gelatinous solid. Option A (CuO, black) is the most tempting distractor — CuO forms only on strong heating of Cu(OH)2 above 80°C, not in an aqueous room-temperature reaction. Sodium sulphate remains fully dissolved and does not precipitate under these conditions.', 'MEDIUM', 'Chemistry', 'Acids, Bases, and Salts', 'CHEM_ACIDS_BASES_SALTS_MIXED', '[{"option_text": "Copper oxide (CuO), a black crystalline solid", "is_correct": false}, {"option_text": "Sodium sulphate (Na2SO4), a white crystalline solid", "is_correct": false}, {"option_text": "Copper hydroxide (Cu(OH)2), a blue gelatinous solid", "is_correct": true}, {"option_text": "Cupric carbonate (CuCO3), a green powdery solid", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('58d95309-c616-5f95-b2b4-52f8ebdd3b9e', 'A household in a hard-water region notices a white chalky layer forming inside their electric kettle after repeated boiling. The water source is known to cause only temporary hardness. What compound constitutes this deposit?', NULL, 'Temporary hardness is caused by dissolved Ca(HCO3)2. On boiling: Ca(HCO3)2 → CaCO3↓ + H2O + CO2. The insoluble CaCO3 deposits as white scale. Option D is the sharpest trap — Ca(HCO3)2 is indeed the cause of temporary hardness, but it is the dissolved reactant in water, not the deposit. CaSO4 causes permanent hardness and cannot be removed by boiling. MgCl2 also contributes to permanent, not temporary, hardness.', 'HARD', 'Chemistry', 'Acids, Bases, and Salts', 'CHEM_ACIDS_BASES_SALTS_MIXED', '[{"option_text": "Calcium carbonate (CaCO3), precipitated from bicarbonate ions", "is_correct": true}, {"option_text": "Calcium sulphate (CaSO4), a sparingly soluble sulphate salt", "is_correct": false}, {"option_text": "Magnesium chloride (MgCl2), a product of permanent hardness", "is_correct": false}, {"option_text": "Calcium bicarbonate (Ca(HCO3)2), which causes temporary hardness", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('95aa86f4-4ec7-58f0-a3db-5814eff4fb97', 'The pH of a neutral solution at 25°C is:', NULL, 'pH scale: 0–6.9 = acidic, 7 = neutral, 7.1–14 = basic. At 25°C, pure water has pH=7 ([H⁺]=[OH⁻]=10⁻⁷ mol/L). Strong acids approach 0; strong bases approach 14.', 'EASY', 'Science — Chemistry', 'Acids, Bases and Salts', 'CHE_SALTS', '[{"option_text": "0", "is_correct": false}, {"option_text": "7", "is_correct": true}, {"option_text": "10", "is_correct": false}, {"option_text": "14", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('58d95309-c616-5f95-b2b4-52f8ebdd3b9e', 'Which of the following is a STRONG acid?', NULL, 'Strong acids dissociate completely: HCl, H₂SO₄, HNO₃, HClO₄, HBr, HI. Weak acids partially dissociate: acetic acid (vinegar), citric acid (lemons), carbonic acid (fizzy drinks). Strong vs. weak is about degree of ionisation, not concentration.', 'EASY', 'Science — Chemistry', 'Acids, Bases and Salts', 'CHE_SALTS', '[{"option_text": "Acetic acid (CH₃COOH)", "is_correct": false}, {"option_text": "Citric acid", "is_correct": false}, {"option_text": "Hydrochloric acid (HCl)", "is_correct": true}, {"option_text": "Carbonic acid (H₂CO₃)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5e8b72f2-3eec-5382-b05e-c1407f6b2575', 'Brass is an alloy of:', NULL, 'BRASS = COPPER (Cu) + ZINC (Zn). Typically 60-70% Cu and 30-40% Zn. Properties: golden colour, corrosion resistant, good acoustic properties, easy to machine. USES: musical instruments (trumpets, trombones, cymbals), door fittings, cartridge cases, decorative items. ALLOY COMPARISON TABLE: (1) BRASS = Cu + Zn. (2) BRONZE = Cu + Sn (tin). (3) STEEL = Fe + C (<2%). (4) STAINLESS STEEL = Fe + C + Cr + Ni. (5) DURALUMIN = Al + Cu + Mn + Mg. (6) SOLDER = Pb + Sn. (7) AMALGAM = Hg + other metals. (8) GERMAN SILVER = Cu + Zn + Ni (despite the name, contains no silver!). (9) INVAR = Fe + Ni (36%) — very low thermal expansion, used in clocks. MEMORY AID: BRASS = BRonze''s sibling but with Zinc (B-R-A-S-S = Blends Readily: A Substitute for Silver). ACTUAL: Brass + Zn, Bronze + tiN. PYQ FREQUENCY: brass composition appears in every major competitive exam — SSC CGL, IBPS PO GA, RRB NTPC 1-2× per cycle.', 'EASY', 'Chemistry', 'Alloys — composition, properties and uses', 'CHE_METALLURGY', '[{"option_text": "Copper and zinc (Cu + Zn)", "is_correct": true}, {"option_text": "Copper and tin (Cu + Sn = bronze)", "is_correct": false}, {"option_text": "Iron and carbon (Fe + C = steel)", "is_correct": false}, {"option_text": "Aluminium and copper (Al + Cu = duralumin)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('adea8076-f098-55cf-a832-3f4698f7b168', 'IODINE deficiency in the diet causes:', NULL, 'Iodine — required for thyroid hormones T3 (triiodothyronine) and T4 (thyroxine). Deficiency → thyroid enlarges (goitre) trying to compensate; can cause cretinism in children, hypothyroidism in adults. India had high goitre belt in Sub-Himalayan zones; Universal Salt Iodisation (UPS) program since 1990s — iodised salt mandatory under Food Safety law. Distractor 1 = thiamine deficiency. Distractor 3 = vitamin C deficiency. Distractor 4 = vitamin D deficiency.', 'MEDIUM', 'Chemistry', 'Halogens (Group 17) — mixed tiers', 'CHE_NON_METALS', '[{"option_text": "Beri-beri due to nutritional thiamine loss", "is_correct": false}, {"option_text": "Goitre, an enlargement of the thyroid gland", "is_correct": true}, {"option_text": "Scurvy, with bleeding gums and skin spots", "is_correct": false}, {"option_text": "Rickets, with softened bones in growing children", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('732cd969-477c-5774-a92b-c7e0b72bcb60', 'BRASS is an alloy of:', NULL, 'BRASS — alloy of COPPER (~70%) + ZINC (~30%); proportions vary by use. PROPERTIES: golden-yellow color, more workable than pure copper, corrosion-resistant. USES: musical instruments (trumpets, trombones, saxophones — ''brass band''), screws, locks, plumbing fittings, decorative items, ammunition cartridges (brass casings), idols (especially in India — kanchi/madurai brass idols). KEY ALLOYS to memorize: (1) BRASS — Cu + Zn. (2) BRONZE — Cu + Sn (the ''Bronze Age'', ~3000 BCE; tools, statues, bells). (3) STEEL — Fe + C (~0.1-2% C); MILD steel ~0.2%, HIGH-CARBON steel ~0.7-1%. (4) STAINLESS STEEL — Fe + Cr (10-30%) + Ni; rust-resistant. (5) DURALUMIN — Al + Cu + Mg + Mn; light + strong; aircraft. (6) GERMAN SILVER — Cu + Zn + Ni (no actual silver, despite name). (7) SOLDER — Pb + Sn (lead-tin); used for joining wires. (8) PEWTER — Sn + Sb + Cu; tableware. (9) MAGNALIUM — Al + Mg; light-weight aircraft parts. (10) AMALGAM — Hg + other metals (dental fillings, gold extraction). HISTORICAL: Brass cymbals popular in many percussion sets; bronze coinage in ancient Rome, Greece, Mauryan India. PYQ FREQUENCY: alloy compositions in NEET, NCERT, SSC GA 1-2× per cycle. EXAMINER MINDSET: tests memory of alloy compositions.', 'EASY', 'Chemistry', 'Metallurgy II', 'CHE_METALLURGY', '[{"option_text": "Copper and zinc (Cu+Zn)", "is_correct": true}, {"option_text": "Copper and tin (Cu+Sn = bronze)", "is_correct": false}, {"option_text": "Iron and carbon (Fe+C = steel)", "is_correct": false}, {"option_text": "Aluminium and copper (Cu+Al)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0d0fb5be-acdc-564f-a2e9-840e6088aa13', 'Which element has the HIGHEST electronegativity on the Pauling scale?', NULL, 'Pauling electronegativity ranking: F (3.98) > O (3.44) > Cl (3.16) > N (3.04) > Br (2.96) > I (2.66) > C (2.55) > H (2.20) > Cs/Fr (~0.7). Fluorine is the most electronegative because of small atomic size + high effective nuclear charge. Drives its extreme reactivity (forms compounds with nearly every other element). Distractor 1 — oxygen is 2nd, not 1st. Distractor 3 — chlorine 3rd. Distractor 4 — nitrogen 4th.', 'EASY', 'Chemistry', 'Periodic table trends II — mixed tiers', 'CHE_PERIODIC_TABLE', '[{"option_text": "Oxygen, the most abundant element by mass", "is_correct": false}, {"option_text": "Fluorine, the most reactive halogen of all", "is_correct": true}, {"option_text": "Chlorine, found mostly as common rock salt", "is_correct": false}, {"option_text": "Nitrogen, the most abundant gas in air around us", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5ff9d9e3-ba07-572f-bdcf-8755627531a8', 'The pH scale ranges from:', NULL, 'pH SCALE typically ranges from 0 to 14 for AQUEOUS solutions at 25°C. KEY VALUES: pH < 7 = ACIDIC. pH = 7 = NEUTRAL (pure water). pH > 7 = BASIC/ALKALINE. DEFINITION: pH = −log₁₀[H⁺] (negative log of hydrogen-ion concentration in mol/L). EACH UNIT change in pH = 10× change in [H⁺]: pH 3 has 10× more H⁺ than pH 4. EXAMPLES — pH of common things: (1) Battery acid: 0. (2) Stomach acid (HCl): 1-2. (3) Lemon juice: 2. (4) Vinegar: 2.4. (5) Coffee: 5. (6) Milk: 6.5. (7) Pure water: 7. (8) Blood: 7.4 (tightly regulated). (9) Sea water: 8.1. (10) Baking soda: 9. (11) Soap: 10. (12) Bleach: 12-13. (13) Drain cleaner (NaOH): 14. EXTREMES: super-acidic ''magic acid'' has pH < 0; super-basic NaOH solutions can have pH > 14 (rare). HISTORY: pH invented by SØREN SØRENSEN (Danish, 1909) — the ''p'' stands for ''potens'' (power) or ''potentia hydrogenii''. TEMPERATURE EFFECT: pH of pure water is 7 only at 25°C; at higher T, pure water has lower pH (still neutral). PYQ FREQUENCY: pH range is a NEET, NCERT-driven SSC 1-mark guarantee.', 'EASY', 'Chemistry', 'pH and Indicators', 'CHE_ACIDS_BASES', '[{"option_text": "0 to 14 (most aqueous solutions)", "is_correct": true}, {"option_text": "1 to 10 (limited basic range)", "is_correct": false}, {"option_text": "−7 to +7 (around neutrality)", "is_correct": false}, {"option_text": "0 to 100 (percentage scale)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6f5b0737-3335-50ce-b3f2-140e71321b16', 'Natural rubber is a polymer of which monomer?', NULL, 'NATURAL RUBBER = cis-1,4-polyisoprene. Monomer: ISOPRENE = CH₂=C(CH₃)-CH=CH₂ (2-methylbuta-1,3-diene). SOURCE: latex from Hevea brasiliensis tree (Para rubber tree; native to Amazon, now grown in Kerala, India; Thailand = world''s top producer). cis CONFIGURATION: natural rubber (elastic, flexible). trans CONFIGURATION = GUTTA-PERCHA (hard, non-elastic — used in golf balls, dental material). GUTTAPERCHA vs RUBBER: same monomer (isoprene), different geometry (trans vs cis). BUTADIENE RUBBER (Buna): polymer of butadiene (CH₂=CH-CH=CH₂) — no methyl group, different from isoprene. SYNTHETIC ISOPRENE RUBBER: can replicate natural rubber — used when supply of natural rubber is scarce. PYQ FREQUENCY: natural rubber monomer in SSC CGL, IBPS PO Chemistry GA, RRB NTPC 1-2× per cycle. MEMORY: ''iSOprene → i for iSOlated-C rubber; ISO = same = cis (same side).''', 'EASY', 'Chemistry', 'Polymer Chemistry II — natural rubber, Teflon, biodegradable polymers, vulcanisation', 'CHE_POLYMERS', '[{"option_text": "Isoprene (2-methylbuta-1,3-diene) — natural rubber = cis-polyisoprene", "is_correct": true}, {"option_text": "Ethylene (CH₂=CH₂) — this is the monomer of polyethylene, not natural rubber", "is_correct": false}, {"option_text": "Styrene (C₆H₅-CH=CH₂) — this is the monomer of polystyrene, not natural rubber", "is_correct": false}, {"option_text": "Propylene (CH₃-CH=CH₂) — this is the monomer of polypropylene, not natural rubber", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('71b461ab-2dd4-58e5-a22b-ea5a8d09df95', 'The FIRST LAW of thermodynamics states that:', NULL, 'FIRST LAW — energy conservation, applied to thermodynamic systems. Mathematically: ΔU = q − w (or q + w, sign convention varies); change in internal energy = heat added minus work done by the system. Forbids perpetual-motion machines of the FIRST kind. Distractor 1 — opposite of true; heat flows from hot to cold (Second Law / Clausius). Distractor 3 = SECOND law (entropy increase). Distractor 4 = THIRD law violation (absolute zero is unreachable in finite steps).', 'MEDIUM', 'Chemistry', 'Thermodynamics basics — mixed tiers', 'CHE_THERMO', '[{"option_text": "Heat always flows from cold bodies to hot bodies spontaneously", "is_correct": false}, {"option_text": "Energy can be neither created nor destroyed, only transformed", "is_correct": true}, {"option_text": "Entropy of an isolated system is always increasing over time", "is_correct": false}, {"option_text": "Absolute zero of temperature can be reached in finite steps", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5df50be0-582a-5871-bad1-7f94a2fb920b', 'Which metal is liquid at room temperature?', NULL, 'MERCURY (Hg) — ONLY METAL liquid at standard room temperature (m.p. = −38.83°C). Group 12, d-block. Latin name ''hydrargyrum'' (Hg) = ''liquid silver''. Uses: thermometers (now banned), barometers, fluorescent lamps, dental amalgams (decreasing), gold extraction. TOXIC (especially organic Hg, e.g., methyl-Hg) — Minamata disaster (Japan, 1950s, mercury poisoning). MINAMATA CONVENTION (2013) — phasing out mercury globally. Other metals close to liquid at RT: Cs (m.p. 28.5°C — melts in hand); Ga (m.p. 29.8°C — melts on warm day); Fr, Br (Br is the only liquid non-metal at RT).', 'EASY', 'Chemistry', 'd-block transition metals — mixed tiers', 'CHE_METALS', '[{"option_text": "Sodium (Na), a soft metal", "is_correct": false}, {"option_text": "Mercury (Hg), the only one", "is_correct": true}, {"option_text": "Potassium (K), reactive alkali", "is_correct": false}, {"option_text": "Aluminium (Al), light metal", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b6c35217-18a0-5c43-b184-538325873cce', 'The MODERN periodic table is arranged by:', NULL, 'Moseley (1913) — atomic number (Z) is the fundamental basis. Mendeleev''s original (1869) ordering by atomic mass had inconsistencies (Te-I, Ar-K, Co-Ni swaps). Moving to atomic number fixed these. Modern table: 7 periods, 18 groups (s, p, d, f blocks). Moseley''s law.', 'MEDIUM', 'Chemistry', 'Atomic structure — mixed tiers', 'CHE_ATOMIC_STRUCT', '[{"option_text": "Atomic mass (Mendeleev''s rule)", "is_correct": false}, {"option_text": "Atomic number", "is_correct": true}, {"option_text": "Number of neutrons", "is_correct": false}, {"option_text": "Reactivity", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ee7142f7-2ccc-5be2-aa46-694e5c5eccf0', 'The ONLY non-metal that is LIQUID at room temperature is:', NULL, 'Bromine (Br₂) — only LIQUID non-metal at room temperature (reddish-brown liquid, MP −7 °C, BP 59 °C). Iodine is solid (sublimes). Sulphur is yellow solid. Mercury (Hg) is the only LIQUID METAL at room temperature.', 'MEDIUM', 'Chemistry', 'Metals, non-metals & alloys — mixed tiers', 'CHE_METALS', '[{"option_text": "Mercury", "is_correct": false}, {"option_text": "Bromine", "is_correct": true}, {"option_text": "Iodine", "is_correct": false}, {"option_text": "Sulphur", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('82228da5-bee1-59ab-be19-d48e8f208731', 'Which of the following is NOT a greenhouse gas?', NULL, 'Molecular N2 does NOT absorb infrared radiation (its vibrational modes are IR-inactive because it is a homo-nuclear diatomic with no dipole moment). It is ~78 % of the atmosphere but not a greenhouse gas. CH4, N2O, O3, CO2, H2O, CFCs, HFCs, SF6 all ARE greenhouse gases.', 'MEDIUM', 'Chemistry', 'Organic basics — multi-statement / everyday context', 'CHE_ORGANIC', '[{"option_text": "Nitrous oxide (N2O)", "is_correct": false}, {"option_text": "Ozone (O3)", "is_correct": false}, {"option_text": "Nitrogen (N2)", "is_correct": true}, {"option_text": "Methane (CH4)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('53ed6d3f-8c52-5647-b414-d3a2ddc3cd7d', 'Which of the following is an operating system?', NULL, 'Windows is an operating system — system software that manages hardware and provides a platform for applications. MS Word (word processor), Google Chrome (browser), and Photoshop (image editor) are all application software that run ON an operating system. Other OS examples: Linux, macOS, Android, iOS.', 'EASY', 'Computer Knowledge', 'Software and Operating Systems', 'COMP_SOFTWARE', '[{"letter": "A", "text": "MS Word"}, {"letter": "B", "text": "Windows"}, {"letter": "C", "text": "Google Chrome"}, {"letter": "D", "text": "Photoshop"}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b0bd5bf2-8e92-58b8-8be8-c7e52e8acaae', 'Which of the following is NOT a function of the Reserve Bank of India?', NULL, 'Direct taxes (income-tax, corporate tax) are collected by the CBDT; indirect taxes (GST, customs) by the CBIC — both under the Department of Revenue, Ministry of Finance. The RBI''s functions include currency issuance (notes of ₹2 and above — ₹1 notes are by the Finance Ministry), banker to Government and banks, monetary policy (repo, CRR), foreign-exchange management, consumer protection, macro-prudential regulation.', 'MEDIUM', 'Economics', 'Banking basics — mixed tiers', 'ECO_BANKING', '[{"option_text": "Issuing currency notes", "is_correct": false}, {"option_text": "Collecting direct taxes", "is_correct": true}, {"option_text": "Acting as banker to the Government", "is_correct": false}, {"option_text": "Regulating commercial banks", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a0e87888-bd14-5521-a9db-6974f7242946', 'The Reserve Bank of India was established in:', NULL, 'The Reserve Bank of India was established on 1 April 1935 under the Reserve Bank of India Act, 1934.', 'EASY', 'Economics', 'Banking Basics', 'ECO_BANKING', '[{"option_text": "1920", "is_correct": false}, {"option_text": "1947", "is_correct": false}, {"option_text": "1949", "is_correct": false}, {"option_text": "1935", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('892dcd38-ce32-5194-b61f-04e6f15376e8', 'The Repo Rate is the rate at which:', NULL, 'Repo rate is the rate at which the RBI provides short-term liquidity to commercial banks by buying their eligible securities.', 'EASY', 'Economics', 'Banking Basics', 'ECO_BANKING', '[{"option_text": "Banks lend to each other", "is_correct": false}, {"option_text": "RBI borrows from commercial banks", "is_correct": false}, {"option_text": "Government borrows from RBI", "is_correct": false}, {"option_text": "RBI lends money to commercial banks against government securities", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('528100ec-852b-52bd-8eb8-7f92c2cd93fd', 'The Repo Rate is the rate at which:', NULL, 'Repo Rate (Repurchase Agreement Rate): rate at which RBI lends short-term funds to commercial banks against government securities. Increasing repo rate makes borrowing expensive → reduces inflation.', 'EASY', 'Economics', 'Banking & Finance', 'ECO_BANKING', '[{"option_text": "RBI lends money to commercial banks (short-term)", "is_correct": true}, {"option_text": "Commercial banks lend to customers", "is_correct": false}, {"option_text": "RBI borrows from commercial banks", "is_correct": false}, {"option_text": "Banks charge each other overnight", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('888c6c1c-1753-5309-ace9-41414bec3637', 'Fiscal Deficit is defined as:', NULL, 'Fiscal Deficit = Total Government Expenditure − Total Government Receipts (excluding borrowings). It represents the amount the government needs to borrow to meet its expenditures. It is the most watched deficit indicator for macroeconomic stability.', 'EASY', 'Economics', 'Union Budget and Fiscal Policy', 'ECO_BUDGET', '["Revenue expenditure minus revenue receipts", "Total interest payments on outstanding debt", "Total expenditure minus total receipts excluding borrowings", "Capital expenditure minus capital receipts only"]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fc58b9ba-301d-598b-a039-fa17f7ce8eac', 'Which of the following is a DIRECT tax in India?', NULL, 'Income tax (both personal income tax and corporate income tax/CIT) is a direct tax — it is paid directly by the person or entity on whom it is imposed. GST, Customs Duty, and Excise Duty are indirect taxes (levied on goods/services and passed on to the consumer).', 'MEDIUM', 'Economics', 'Union Budget and Fiscal Policy', 'ECO_BUDGET', '["Goods and Services Tax (GST)", "Customs Duty (import/export tax)", "Income Tax (personal and corporate)", "Central Excise Duty"]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bb60fdb5-6e49-55e1-ad56-7b624f70e7a9', 'Which of the following is a DIRECT TAX?', NULL, 'Direct tax — burden cannot be shifted; paid directly by the person/entity (Income Tax, Corporate Tax, Capital Gains Tax, Wealth Tax [abolished]). Indirect tax — burden shifted to consumer (GST, customs, excise).', 'EASY', 'Economics', 'Budget & fiscal policy — mixed tiers', 'ECO_BUDGET', '[{"option_text": "GST", "is_correct": false}, {"option_text": "Customs Duty", "is_correct": false}, {"option_text": "Corporate Income Tax", "is_correct": true}, {"option_text": "Excise Duty", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('71e24070-0cb8-5e4f-acc1-4e0a0dfac65a', 'The FINANCE COMMISSION of India is constituted every:', NULL, 'Article 280 — the President constitutes a Finance Commission every 5 years (or earlier if necessary). It recommends the devolution of taxes between the Union and the States. The 15th FC (Chair: N. K. Singh) covered FY 2021-22 to FY 2025-26. The 16th FC is now in operation.', 'MEDIUM', 'Economics', 'Budget & fiscal policy — mixed tiers', 'ECO_BUDGET', '[{"option_text": "Year", "is_correct": false}, {"option_text": "2 years", "is_correct": false}, {"option_text": "5 years", "is_correct": true}, {"option_text": "10 years", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('88b44240-f447-5382-bdcd-f38d37dc1946', 'Fiscal deficit is defined as:', NULL, 'Fiscal deficit = Total expenditure − Total receipts (excluding borrowings). It represents the government''s borrowing requirement.', 'MEDIUM', 'Economics', 'Fiscal Policy', 'ECO_BUDGET', '[{"option_text": "Total expenditure minus tax revenue", "is_correct": false}, {"option_text": "Current account deficit", "is_correct": false}, {"option_text": "Trade deficit", "is_correct": false}, {"option_text": "Total expenditure minus total receipts excluding borrowings", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8a6c9309-ea6f-5686-a064-e135d66478fe', 'Which of the following is a direct tax?', NULL, 'Income Tax is a direct tax — levied on and paid directly by the person who earns the income. GST, excise, and customs are indirect taxes.', 'EASY', 'Economics', 'Fiscal Policy', 'ECO_BUDGET', '[{"option_text": "GST", "is_correct": false}, {"option_text": "Excise Duty", "is_correct": false}, {"option_text": "Customs Duty", "is_correct": false}, {"option_text": "Income Tax", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e3b60d0d-4f1e-59c1-a839-d3cc67beba3c', 'The Finance Commission of India is constituted every:', NULL, 'Under Article 280, the Finance Commission is constituted every five years to recommend the distribution of tax revenues between the Centre and States.', 'EASY', 'Economics', 'Fiscal Policy', 'ECO_BUDGET', '[{"option_text": "3 years", "is_correct": false}, {"option_text": "2 years", "is_correct": false}, {"option_text": "10 years", "is_correct": false}, {"option_text": "5 years", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b7158807-04e1-5e17-aed3-0ccde063999e', 'India''s GDP measured at Purchasing Power Parity (PPP) is substantially larger than at current market exchange rates mainly because?', NULL, 'PPP equalises price levels using a common basket of goods. In India, non-tradables (local food, housing, personal services) cost far less in rupee terms than their dollar equivalents in the US — the Balassa-Samuelson effect. PPP conversion captures this higher real purchasing power, raising India''s PPP-GDP relative to market-rate GDP. Option C is wrong: the rupee is typically undervalued on forex markets (which would actually raise market-rate GDP), and PPP addresses price-level differences, not currency misalignment. Option A conflates PPP methodology with informal-sector measurement.', 'HARD', 'Economics', 'GDP, GVA and national accounting — mixed tiers', 'ECO_GDP_GVA_MIXED', '[{"option_text": "PPP also captures informal sector output omitted from official GDP data", "is_correct": false}, {"option_text": "Non-traded goods and services are relatively cheaper in India than in the US", "is_correct": true}, {"option_text": "The rupee is systematically overvalued against the dollar in forex markets", "is_correct": false}, {"option_text": "PPP calculations incorporate projected real growth of emerging economies", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b7158807-04e1-5e17-aed3-0ccde063999e', 'Per capita income is calculated as:', NULL, 'Per capita income = National income (GNI or NNI) ÷ Total population. It is a rough proxy for average living standard. GDP per capita (GDP ÷ population) is also used internationally. High GDP with very unequal distribution gives high per capita income but may not reflect welfare of all citizens.', 'EASY', 'Economics', 'GDP, GVA and National Accounts', 'ECO_NAT_INCOME', '[{"option_text": "GDP ÷ Area of the country", "is_correct": false}, {"option_text": "GDP ÷ Total population", "is_correct": true}, {"option_text": "GDP × Population", "is_correct": false}, {"option_text": "National income ÷ Tax revenue", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('000372cc-ad95-5230-8503-5b29999a0fc4', 'The Reserve Bank of India was established in:', NULL, 'RBI was established on 1 April 1935 under the RBI Act, 1934. Nationalised in 1949.', 'EASY', 'Economics', 'Indian Economy — Basics', 'ECO_GROWTH', '[{"option_text": "1935", "is_correct": true}, {"option_text": "1947", "is_correct": false}, {"option_text": "1949", "is_correct": false}, {"option_text": "1952", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a2dd9d52-f127-5415-a1a8-4a08715333f4', 'Fiscal deficit is defined as:', NULL, 'Fiscal Deficit = Total Expenditure − Total Receipts (excluding borrowings). It indicates the government''s total borrowing requirement.', 'MEDIUM', 'Economics', 'Indian Economy — Basics', 'ECO_GROWTH', '[{"option_text": "Total expenditure minus total receipts excluding borrowings", "is_correct": true}, {"option_text": "Revenue expenditure minus capital expenditure", "is_correct": false}, {"option_text": "Total imports minus total exports", "is_correct": false}, {"option_text": "Revenue deficit plus capital deficit", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1c20df6f-0aa1-580a-8ca1-fa998012ab99', 'Which of the following is a direct tax in India?', NULL, 'Direct taxes are levied on the person who bears the burden (income tax, corporate tax). Indirect taxes (GST, customs) are passed to consumers.', 'EASY', 'Economics', 'Indian Economy — Basics', 'ECO_GROWTH', '[{"option_text": "Income tax", "is_correct": true}, {"option_text": "GST", "is_correct": false}, {"option_text": "Customs duty", "is_correct": false}, {"option_text": "Excise duty", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a2b4dfca-6bf2-5363-a34a-27062975ae7a', 'PER CAPITA INCOME of a country is calculated as:', NULL, 'Per Capita Income = National Income / Population. India''s per capita income (FY24): ~₹2.13 lakh (~$2,500). World average: ~$13,000. Per capita gives a sense of average prosperity but hides inequality. INDIA''s per capita is much lower than China''s (~$13,000), Bangladesh''s ($2,800 — recently overtook India in some years). Income inequality measured by GINI coefficient (0 = perfect equality, 1 = max inequality). Distractor 1 = density-related concept. Distractors 3, 4 are unrelated.', 'EASY', 'Economics', 'National income II — mixed tiers', 'ECO_NAT_INCOME', '[{"option_text": "GDP divided by total area of the country", "is_correct": false}, {"option_text": "National Income divided by total population", "is_correct": true}, {"option_text": "Total tax revenue divided by population", "is_correct": false}, {"option_text": "Imports plus exports divided by population", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d7de8f49-5d2f-58e3-8711-273bb4856e43', 'The ''Repo Rate'' is the rate at which:', NULL, 'Repo (repurchase agreement) — bank sells G-secs to RBI today and repurchases at a higher price tomorrow; the difference = interest = repo rate. REVERSE repo — opposite direction (RBI borrows from banks). Other RBI rates: MSF (Marginal Standing Facility, repo + 0.25%), Bank Rate (= MSF normally), CRR (Cash Reserve Ratio), SLR (Statutory Liquidity Ratio). When RBI hikes repo → cost of funds for banks rises → lending rates rise → demand cools → inflation falls (textbook effect).', 'MEDIUM', 'Economics', 'RBI — functions and structure — mixed tiers', 'ECO_RBI', '[{"option_text": "Commercial banks lend to RBI", "is_correct": false}, {"option_text": "RBI lends short-term funds to commercial banks against government securities (sale-and-repurchase)", "is_correct": true}, {"option_text": "Banks lend among themselves overnight", "is_correct": false}, {"option_text": "RBI buys forex from the market", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5613b916-a42b-5f52-959f-b5a1d8de7049', 'Which of the following is a direct tax?', NULL, 'Income Tax is a direct tax — it is levied directly on the income of individuals and entities, and the burden cannot be shifted to another. GST, customs duty, and excise duty are indirect taxes levied on goods/services/transactions, where the burden can be passed on to the consumer.', 'EASY', 'Economics', 'Taxation and GST', 'ECO_TAXATION', '[{"letter": "A", "text": "GST"}, {"letter": "B", "text": "Customs Duty"}, {"letter": "C", "text": "Income Tax"}, {"letter": "D", "text": "Excise Duty"}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5df34d64-49a6-5192-bc3a-eacb43437616', 'The World Trade Organization (WTO) was established in:', NULL, 'WTO — established 1 January 1995, headquartered at Geneva, Switzerland. Successor to the GATT (General Agreement on Tariffs and Trade, 1947 — only a treaty, not an organisation). Created by the URUGUAY ROUND of GATT negotiations (1986-94), formalised by the MARRAKESH AGREEMENT (April 1994). India is a founding member. As of 2024 — 166 member countries (Comoros and Timor-Leste joined Aug 2024). Director-General — Ngozi Okonjo-Iweala (Nigeria; first woman, first African to hold the post; reappointed for second 4-year term ending 2029).', 'EASY', 'Economics', 'World Trade Organization — mixed tiers', 'ECO_INTL_ORG', '[{"option_text": "1947", "is_correct": false}, {"option_text": "1995 (succeeding GATT, after the Marrakesh Agreement of April 1994)", "is_correct": true}, {"option_text": "1971", "is_correct": false}, {"option_text": "2001", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ee8d7760-0de9-52ff-9ecc-216eaba07cfd', 'Identify the CORRECT passive form of: ''They have been building the dam for three years.''', NULL, 'B is correct. Active: ''have been building'' = present perfect continuous. Passive of present perfect continuous: have/has + been + being + past participle. ''The dam HAS BEEN BEING BUILT for three years by them.'' Note: this form is grammatically correct but rarely used in practice — which is exactly why SSC tests it. Trap: ''has been built'' = present perfect simple passive (for completed action, not continuous); ''was being built'' = past continuous passive (wrong tense: active uses HAVE not WAS).', 'HARD', 'English', 'Active and Passive Voice — Advanced Conversion and Error Identification for SSC CGL (W13 B1)', 'ENG_ACTIVE_PASSIVE_ADVANCED_W13_B1', '[{"option_text": "The dam has been built for three years by them.", "is_correct": false}, {"option_text": "The dam has been being built for three years by them.", "is_correct": true}, {"option_text": "The dam was being built for three years by them.", "is_correct": false}, {"option_text": "The dam had been built for three years by them.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b0f5b542-aee2-57ee-a345-b5c93c87d404', 'Which sentence correctly converts ''Let the work be completed by Friday'' to active voice?', NULL, 'A is correct. ''Let + object + be + past participle'' (passive imperative) → Active imperative: ''Complete the work by Friday.'' The passive imperative ''Let it be done'' converts to the direct command ''Do it.'' The subject (''you'') is implied. Trap: ''The work should be completed'' = a suggestion/modal, not the direct active command; ''We let the work complete'' = uses ''let'' as ''allow'' (different sense).', 'MEDIUM', 'English', 'Active and Passive Voice — Advanced Conversion and Error Identification for SSC CGL (W13 B1)', 'ENG_ACTIVE_PASSIVE_ADVANCED_W13_B1', '[{"option_text": "Complete the work by Friday.", "is_correct": true}, {"option_text": "The work should be completed by Friday.", "is_correct": false}, {"option_text": "We let the work complete by Friday.", "is_correct": false}, {"option_text": "You are let to complete the work by Friday.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dec3d516-e6c5-5da1-930a-51580d4fa927', 'Choose the CORRECT passive voice of: ''Someone has stolen my wallet.''', NULL, 'C is correct. Active: ''has stolen'' = present perfect. Passive of present perfect: has/have + been + past participle = ''has been stolen''. Agent: ''someone'' is vague and dropped in passive (standard practice — do not write ''by someone''). Result: ''My wallet has been stolen.'' Trap: ''was stolen'' = simple past passive (tense mismatch — active is present perfect, not simple past); ''had been stolen'' = past perfect passive (wrong tense).', 'MEDIUM', 'English', 'Active and Passive Voice — Advanced Conversion and Error Identification for SSC CGL (W13 B1)', 'ENG_ACTIVE_PASSIVE_ADVANCED_W13_B1', '[{"option_text": "My wallet was stolen by someone.", "is_correct": false}, {"option_text": "My wallet had been stolen.", "is_correct": false}, {"option_text": "My wallet has been stolen.", "is_correct": true}, {"option_text": "My wallet was being stolen.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ccb54c97-0133-500a-b553-831a13b7d3c6', 'Convert to passive voice: ''People say that honesty is the best policy.''', NULL, 'A is correct. When ''people say/think/believe/know/consider'' has a that-clause object, passive can be formed two ways: (1) It + is + said + that-clause: ''It is said that honesty is the best policy.'' (2) Subject of that-clause + is + said + to-infinitive: ''Honesty is said TO BE the best policy.'' Both are correct but option A matches form (2). Note: ''by people'' is dropped (vague agent). Trap: ''was said'' = past tense (active uses present ''say''); ''has been said'' = present perfect (mismatch).', 'MEDIUM', 'English', 'Active and Passive Voice — Advanced Conversion and Error Identification for SSC CGL (W13 B1)', 'ENG_ACTIVE_PASSIVE_ADVANCED_W13_B1', '[{"option_text": "Honesty is said to be the best policy.", "is_correct": true}, {"option_text": "It is saying that honesty is the best policy.", "is_correct": false}, {"option_text": "Honesty was said to be the best policy by people.", "is_correct": false}, {"option_text": "Honesty has been said to be the best policy.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d8515cdd-30d2-5321-bf66-8df18350cf3c', 'Which passive voice conversion is INCORRECT?', NULL, 'D is correct — D is the INCORRECT conversion. ''Belong to'' is a STATIVE VERB (state of possession/relationship) and cannot be converted to passive voice. Stative verbs (resemble, contain, belong, consist, lack, possess, own) do not have passive forms. You cannot say ''A wealthy family is belonged to by her.'' Trap: A is correct (stative ''know'' CAN form passive in this case as it describes the state of knowledge); B is correct (phrasal verb ''laugh at'' → ''was laughed at'' — preposition keeps with verb in passive); C is correct (emotional/causative verbs like ''surprise'', ''please'', ''interest'' have passive forms).', 'HARD', 'English', 'Active and Passive Voice — Advanced Conversion and Error Identification for SSC CGL (W13 B1)', 'ENG_ACTIVE_PASSIVE_ADVANCED_W13_B1', '[{"option_text": "Active: ''She knows the answer.'' → Passive: ''The answer is known by her.''", "is_correct": false}, {"option_text": "Active: ''He laughed at the joke.'' → Passive: ''The joke was laughed at by him.''", "is_correct": false}, {"option_text": "Active: ''The news surprised me.'' → Passive: ''I was surprised by the news.''", "is_correct": false}, {"option_text": "Active: ''She belongs to a wealthy family.'' → Passive: ''A wealthy family is belonged to by her.''", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2579a54b-fcba-56ee-842d-ab56b2023612', 'Convert to active voice: ''The meeting is being attended by all senior officials.''', NULL, 'A is correct. Passive: ''is being attended'' = present continuous passive. Active: ''is/are + verb-ing'' = present continuous. Subject = ''all senior officials'' (plural) → ''are attending''. Result: ''All senior officials ARE ATTENDING the meeting.'' Trap: ''attend'' = simple present (drops the continuous aspect: ''is being'' → ''are -ing''); ''were attending'' = past continuous (wrong tense: ''is being'' is present, not past).', 'MEDIUM', 'English', 'Active and Passive Voice — Advanced Conversion and Error Identification for SSC CGL (W13 B1)', 'ENG_ACTIVE_PASSIVE_ADVANCED_W13_B1', '[{"option_text": "All senior officials are attending the meeting.", "is_correct": true}, {"option_text": "All senior officials attend the meeting.", "is_correct": false}, {"option_text": "All senior officials have attended the meeting.", "is_correct": false}, {"option_text": "All senior officials were attending the meeting.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d0cccad0-8fdb-5eaf-9956-4a8e4891a818', 'Choose the correct passive voice of the imperative: ''Please post this letter.''', NULL, 'B is correct. Passive of a POLITE imperative (with ''please''): ''You are requested to + base verb + object.'' The structure preserves the polite request. ''Please post this letter'' → ''You are requested to post this letter.'' The imperative passive uses ''You are requested/advised/ordered to...'' — the ''you'' (implied subject in the active imperative) becomes explicit in the passive. Trap: ''This letter is requested to be posted'' = grammatically awkward (letter cannot be ''requested''); ''should have been posted'' = past modal — completely wrong tense.', 'MEDIUM', 'English', 'Active and Passive Voice — Advanced Conversion and Error Identification for SSC CGL (W13 B1)', 'ENG_ACTIVE_PASSIVE_ADVANCED_W13_B1', '[{"option_text": "This letter is requested to be posted.", "is_correct": false}, {"option_text": "You are requested to post this letter.", "is_correct": true}, {"option_text": "This letter was posted please.", "is_correct": false}, {"option_text": "This letter should have been posted.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d3c596b9-a5ce-5c07-8766-c14e969e3bcd', 'Convert to passive voice: ''The manager gave the employee a promotion.''', NULL, 'C is correct. When an active sentence has both DIRECT OBJECT (DO) and INDIRECT OBJECT (IO), TWO passive forms are possible: (1) IO becomes subject: ''The employee (IO) was given a promotion (DO) by the manager.'' (2) DO becomes subject: ''A promotion (DO) was given to the employee (IO) by the manager.'' Both are grammatically correct. This is one of the most frequently tested passive rules in SSC — the double-object passive. Trap: Both A and B are correct; choosing only one misses half the rule.', 'HARD', 'English', 'Active and Passive Voice — Advanced Conversion and Error Identification for SSC CGL (W13 B1)', 'ENG_ACTIVE_PASSIVE_ADVANCED_W13_B1', '[{"option_text": "A promotion was given to the employee by the manager.", "is_correct": false}, {"option_text": "The employee was given a promotion by the manager.", "is_correct": false}, {"option_text": "Both A and B are correct passive transformations.", "is_correct": true}, {"option_text": "A promotion has been given to the employee.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ae77edfb-c4ee-5646-b2c0-b618b1ea7f5a', 'Identify the sentence that uses passive voice INCORRECTLY:', NULL, 'B is correct — B is INCORRECT. ''Is being constructed since last year'' uses PRESENT CONTINUOUS PASSIVE with ''since'' — but ''since'' requires PRESENT PERFECT (not continuous) because it marks the start of an ongoing action extending to now. Correct: ''The bridge HAS BEEN BEING CONSTRUCTED since last year'' (present perfect continuous passive) or more naturally ''The bridge has been under construction since last year.'' The error: mixing present continuous (''is being'') with a ''since'' time marker that requires present perfect. Trap: A, C, D are all grammatically correct passive sentences.', 'HARD', 'English', 'Active and Passive Voice — Advanced Conversion and Error Identification for SSC CGL (W13 B1)', 'ENG_ACTIVE_PASSIVE_ADVANCED_W13_B1', '[{"option_text": "Hindi is spoken by millions of people.", "is_correct": false}, {"option_text": "The bridge is being constructed since last year.", "is_correct": true}, {"option_text": "The results will be declared by the board tomorrow.", "is_correct": false}, {"option_text": "The evidence had been tampered with before the trial.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8fe736ad-3cd4-5634-9a63-f25b237a0858', 'Convert to active voice: ''It is expected that the project will be completed by December.''', NULL, 'D is correct. ''It is expected that...'' is a passive construction with an impersonal subject ''It''. Converting to active: the passive agent is ''they'' (unspecified people — the same transformation as ''It is said that people say that''). Active: ''They expect that the project will be completed by December.'' Note: ''will be completed'' remains as the inner clause is itself passive. Trap: ''We expect'' = changes unspecified ''they'' to specific ''we''; ''The project is expected to be completed'' = changes to another passive form (not active); ''People expect'' = acceptable but ''they expect'' is the standard active transformation of impersonal passive ''it is expected''.', 'HARD', 'English', 'Active and Passive Voice — Advanced Conversion and Error Identification for SSC CGL (W13 B1)', 'ENG_ACTIVE_PASSIVE_ADVANCED_W13_B1', '[{"option_text": "We expect the project to be completed by December.", "is_correct": false}, {"option_text": "People expect that the project will be completed by December.", "is_correct": false}, {"option_text": "The project is expected to be completed by December.", "is_correct": false}, {"option_text": "They expect that the project will be completed by December.", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a9f130f4-490f-5fcc-b048-2f6291ded2c2', 'Change to passive voice: ''She writes a letter every day.''', NULL, 'A is correct. Simple Present Active → Simple Present Passive: Object + is/are + V3 + by + Subject. ''She writes'' → ''is written by her''. The time phrase ''every day'' stays unchanged. Trap: ''was written'' = Simple Past passive (wrong tense); ''is being written'' = Present Continuous passive (wrong — original is habitual, not ongoing now).', 'EASY', 'English', 'Active and Passive Voice — Transformation across Tenses (W12 B1)', 'ENG_ACTIVE_PASSIVE_ADV_W12_B1', '[{"option_text": "A letter is written by her every day.", "is_correct": true}, {"option_text": "A letter was written by her every day.", "is_correct": false}, {"option_text": "A letter is being written by her every day.", "is_correct": false}, {"option_text": "A letter will be written by her every day.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c19ee88d-3b4f-5d40-af32-a9eafe4d86bb', 'Change to passive voice: ''He ate the food.''', NULL, 'B is correct. Simple Past Active → Simple Past Passive: Object + was/were + V3 + by + Subject. ''He ate'' → ''was eaten by him''. Subject ''food'' is singular → ''was''. Trap: ''is eaten'' = Present tense (wrong — original is past tense ''ate''); ''has been eaten'' = Present Perfect passive (past action but with present relevance — the original simply uses Simple Past); ''had been eaten'' = Past Perfect passive (too far back — implies another past event happened after).', 'EASY', 'English', 'Active and Passive Voice — Transformation across Tenses (W12 B1)', 'ENG_ACTIVE_PASSIVE_ADV_W12_B1', '[{"option_text": "The food is eaten by him.", "is_correct": false}, {"option_text": "The food was eaten by him.", "is_correct": true}, {"option_text": "The food has been eaten by him.", "is_correct": false}, {"option_text": "The food had been eaten by him.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a200f15e-a635-5970-8309-fd31a407f6c8', 'Change to passive voice: ''They will complete the project.''', NULL, 'C is correct. Simple Future Active → Simple Future Passive: Object + will be + V3 + by + Subject. ''Will complete'' → ''will be completed by them''. Trap: ''is completed'' = Simple Present passive (wrong tense); ''has been completed'' = Present Perfect passive (wrong — original uses future ''will''); ''was completed'' = Simple Past passive (wrong tense).', 'EASY', 'English', 'Active and Passive Voice — Transformation across Tenses (W12 B1)', 'ENG_ACTIVE_PASSIVE_ADV_W12_B1', '[{"option_text": "The project is completed by them.", "is_correct": false}, {"option_text": "The project has been completed by them.", "is_correct": false}, {"option_text": "The project will be completed by them.", "is_correct": true}, {"option_text": "The project was completed by them.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c599f2f9-9144-568f-a5eb-d5b5076caaab', 'Change to passive voice: ''The teacher has taught the students.''', NULL, 'C is correct. Present Perfect Active → Present Perfect Passive: Object + has/have been + V3 + by + Subject. Subject is ''the students'' (plural) → ''have been''. ''Has taught'' → ''have been taught by the teacher''. Trap: ''are taught'' = Simple Present passive (missing the ''have been'' perfect aspect); ''had been taught'' = Past Perfect passive (no past reference point was established — original is Present Perfect).', 'MEDIUM', 'English', 'Active and Passive Voice — Transformation across Tenses (W12 B1)', 'ENG_ACTIVE_PASSIVE_ADV_W12_B1', '[{"option_text": "The students are taught by the teacher.", "is_correct": false}, {"option_text": "The students were taught by the teacher.", "is_correct": false}, {"option_text": "The students have been taught by the teacher.", "is_correct": true}, {"option_text": "The students had been taught by the teacher.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f515ecc8-831f-5af8-9880-b6fddc999fa3', 'Change to passive voice: ''We are making a film.''', NULL, 'D is correct. Present Continuous Active → Present Continuous Passive: Object + is/are being + V3 + by + Subject. ''We are making'' → ''is being made by us'' (singular ''a film'' → ''is being''). Key: the distinctive Continuous passive uses ''being''. Trap: ''is made'' = Simple Present passive (drops the continuous aspect); ''was being made'' = Past Continuous passive (wrong tense); ''has been made'' = Present Perfect passive (wrong aspect).', 'MEDIUM', 'English', 'Active and Passive Voice — Transformation across Tenses (W12 B1)', 'ENG_ACTIVE_PASSIVE_ADV_W12_B1', '[{"option_text": "A film is made by us.", "is_correct": false}, {"option_text": "A film was being made by us.", "is_correct": false}, {"option_text": "A film has been made by us.", "is_correct": false}, {"option_text": "A film is being made by us.", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e795408e-ce8e-5ea4-862e-5117d1d1a875', 'Change to passive voice: ''She was writing a novel when the lights went out.''', NULL, 'B is correct. Past Continuous Active → Past Continuous Passive: Object + was/were being + V3 + by + Subject. ''Was writing'' → ''was being written by her''. The time clause ''when the lights went out'' remains unchanged. Trap: ''was written'' = Simple Past passive (loses the ongoing/continuous aspect that was present in ''was writing''); ''had been written'' = Past Perfect passive (implies completion before another past event — not what the original means).', 'MEDIUM', 'English', 'Active and Passive Voice — Transformation across Tenses (W12 B1)', 'ENG_ACTIVE_PASSIVE_ADV_W12_B1', '[{"option_text": "A novel was written by her when the lights went out.", "is_correct": false}, {"option_text": "A novel was being written by her when the lights went out.", "is_correct": true}, {"option_text": "A novel had been written by her when the lights went out.", "is_correct": false}, {"option_text": "A novel is being written by her when the lights went out.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0b9da008-55ca-5d07-9863-7cc0be570e33', 'Change to passive voice: ''They had finished the work before noon.''', NULL, 'C is correct. Past Perfect Active → Past Perfect Passive: Object + had been + V3 + by + Subject. ''Had finished'' → ''had been finished by them''. The time phrase ''before noon'' remains. Trap: ''was finished'' = Simple Past passive (drops the ''had been'' perfect-before-past aspect); ''has been finished'' = Present Perfect (wrong tense — original is Past Perfect).', 'MEDIUM', 'English', 'Active and Passive Voice — Transformation across Tenses (W12 B1)', 'ENG_ACTIVE_PASSIVE_ADV_W12_B1', '[{"option_text": "The work was finished before noon.", "is_correct": false}, {"option_text": "The work has been finished before noon.", "is_correct": false}, {"option_text": "The work had been finished before noon by them.", "is_correct": true}, {"option_text": "The work will have been finished before noon by them.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a4d342cf-6ca3-5955-a62b-7589ee1c0056', 'Change to passive voice: ''Who broke the window?''', NULL, 'B is correct. Interrogative Active with ''who'' → Passive: ''By whom was the Object + V3?'' The question word ''who'' (subject in active) becomes ''by whom'' (agent phrase in passive), and the verb inverts into question form: ''was...broken''. Trap: ''Who was the window broken by?'' = ends with a preposition (incorrect formal style; also ''who'' should become ''whom''); ''The window was broken by whom?'' = statement word order (not a question); ''By whom the window was broken?'' = subject-verb order wrong (no inversion).', 'MEDIUM', 'English', 'Active and Passive Voice — Transformation across Tenses (W12 B1)', 'ENG_ACTIVE_PASSIVE_ADV_W12_B1', '[{"option_text": "Who was the window broken by?", "is_correct": false}, {"option_text": "By whom was the window broken?", "is_correct": true}, {"option_text": "The window was broken by whom?", "is_correct": false}, {"option_text": "By whom the window was broken?", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ca1657af-c3de-55bd-a112-bffba7221935', 'Change to passive voice: ''People say that he is honest.''', NULL, 'C is correct. The ''it-cleft'' passive for reporting verbs: ''People say that...'' → ''It is said that...''. The agent ''by people'' is dropped as it is generic/obvious. An equivalent form: ''He is said to be honest.'' (Using infinitive in second passive structure.) Trap: ''He is said that he is honest'' = grammatically wrong (cannot have two subjects ''he'' and ''he is honest'' in this structure); ''It is said by people'' = technically correct but the ''by people'' is redundant and atypical for generic agents; ''He is said to have been honest'' = wrong tense (implies past honesty, not present).', 'HARD', 'English', 'Active and Passive Voice — Transformation across Tenses (W12 B1)', 'ENG_ACTIVE_PASSIVE_ADV_W12_B1', '[{"option_text": "He is said that he is honest.", "is_correct": false}, {"option_text": "It is said that he is honest by people.", "is_correct": false}, {"option_text": "It is said that he is honest.", "is_correct": true}, {"option_text": "He is said to have been honest.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('544c528a-c44a-546c-b647-bd95bd6de041', 'Identify the correct ACTIVE voice version of: ''I was asked to submit the report by the manager.''', NULL, 'A is correct. Passive: ''I was asked to submit the report by the manager.'' → Active: Subject (manager) + V (asked) + Object (me) + infinitive (to submit the report). The passive uses Simple Past ''was asked'' → active uses Simple Past ''asked''. The agent ''by the manager'' becomes the active subject ''the manager''. Trap: ''was asking'' = Past Continuous (wrong — ''was asked'' is Simple Past passive); ''I asked the manager'' = reverses subject and object (now I''m asking, not the manager); ''had been asking'' = Past Perfect Continuous (wrong tense).', 'HARD', 'English', 'Active and Passive Voice — Transformation across Tenses (W12 B1)', 'ENG_ACTIVE_PASSIVE_ADV_W12_B1', '[{"option_text": "The manager asked me to submit the report.", "is_correct": true}, {"option_text": "The manager was asking me to submit the report.", "is_correct": false}, {"option_text": "I asked the manager to submit the report.", "is_correct": false}, {"option_text": "The manager had been asking me to submit the report.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
