INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7bd31c77-d795-5f08-8831-f7fa1db93b3f', 'Choose the correct passive voice:
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a9ff07af-5a46-5b89-bfdd-413001178c7e', 'Which sentence CANNOT be converted to passive voice?', NULL, 'B is correct. Intransitive verbs (verbs with no object) cannot be made passive because there is no object to become the subject. ''The rain fell'' — ''fell'' is intransitive here (fell = descended, no direct object). You cannot say ''A night was fallen by the rain'' — it makes no sense. Compare: A=saw a sunset (saw=transitive, ''sunset'' is object → ''A beautiful sunset was seen by her''✓); C=built a hospital ✓; D=cooked a meal ✓. Only B uses an intransitive verb.', 'HARD', 'English', 'Active and Passive Voice — Conversion (W11 B2)', 'ENG_ACTIVE_PASSIVE_W11_B2', '[{"option_text": "She saw a beautiful sunset.", "is_correct": false}, {"option_text": "The rain fell all night.", "is_correct": true}, {"option_text": "They built a new hospital.", "is_correct": false}, {"option_text": "The chef cooked a delicious meal.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0810f876-e4bf-5da1-9cd3-88c59ae6c2b5', 'Change to passive voice: ''The cat chased the mouse.''', NULL, 'A is correct. Simple past active → simple past passive: ''was + past participle''. The object ''mouse'' becomes the subject.', 'EASY', 'English', 'Active and Passive Voice (W9)', 'ENG_ACTIVE_PASSIVE_W9', '[{"option_text": "The mouse was chased by the cat.", "is_correct": true}, {"option_text": "The mouse has been chased by the cat.", "is_correct": false}, {"option_text": "The mouse is being chased by the cat.", "is_correct": false}, {"option_text": "The mouse chased the cat.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('09345c31-f641-53fe-83a0-346ba33c9516', 'Change to passive voice: ''She is singing a song.''', NULL, 'B is correct. Present continuous active → ''is/am/are + being + past participle'': ''is being sung by her''.', 'EASY', 'English', 'Active and Passive Voice (W9)', 'ENG_ACTIVE_PASSIVE_W9', '[{"option_text": "A song was being sung by her.", "is_correct": false}, {"option_text": "A song is being sung by her.", "is_correct": true}, {"option_text": "A song has been sung by her.", "is_correct": false}, {"option_text": "A song is sung by her.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b12cb18a-d99a-5bee-ab5c-7b8cc1c66508', 'Change to passive voice: ''They have completed the project.''', NULL, 'B is correct. Present perfect active → ''has/have + been + past participle'': ''has been completed by them''.', 'EASY', 'English', 'Active and Passive Voice (W9)', 'ENG_ACTIVE_PASSIVE_W9', '[{"option_text": "The project was completed by them.", "is_correct": false}, {"option_text": "The project has been completed by them.", "is_correct": true}, {"option_text": "The project is completed by them.", "is_correct": false}, {"option_text": "The project had been completed by them.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('45b84d6a-0524-5756-b33f-6a80a4dc8749', 'Change to active voice: ''The letter was written by Ram.''', NULL, 'B is correct. Past passive (''was written'') → past simple active: ''Ram wrote the letter''.', 'MEDIUM', 'English', 'Active and Passive Voice (W9)', 'ENG_ACTIVE_PASSIVE_W9', '[{"option_text": "Ram writes the letter.", "is_correct": false}, {"option_text": "Ram wrote the letter.", "is_correct": true}, {"option_text": "Ram is writing the letter.", "is_correct": false}, {"option_text": "Ram has written the letter.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9fe6aa4d-98d6-52d9-8541-7f3b044838b0', 'Change to passive voice: ''Will you help me?''', NULL, 'A is correct. ''Will + object + be + past participle'': ''Will I be helped by you?'' The interrogative structure and tense (will) are preserved.', 'MEDIUM', 'English', 'Active and Passive Voice (W9)', 'ENG_ACTIVE_PASSIVE_W9', '[{"option_text": "Will I be helped by you?", "is_correct": true}, {"option_text": "Am I helped by you?", "is_correct": false}, {"option_text": "Can I be helped by you?", "is_correct": false}, {"option_text": "Would I be helped by you?", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b15e5a3d-46c4-5ed4-bef1-3b59b67afd32', 'Change to passive voice: ''Open the door.'' (imperative)', NULL, 'B is correct. Imperative passive = ''Let + object + be + past participle'': ''Let the door be opened''.', 'MEDIUM', 'English', 'Active and Passive Voice (W9)', 'ENG_ACTIVE_PASSIVE_W9', '[{"option_text": "The door is opened.", "is_correct": false}, {"option_text": "Let the door be opened.", "is_correct": true}, {"option_text": "The door must be opened.", "is_correct": false}, {"option_text": "The door should be opened.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c1d61035-f296-5fb4-ae72-7aeafdaebf3a', 'Change to passive voice: ''She will complete the task tomorrow.''', NULL, 'A is correct. Future simple passive = ''will + be + past participle'': ''The task will be completed by her tomorrow''.', 'MEDIUM', 'English', 'Active and Passive Voice (W9)', 'ENG_ACTIVE_PASSIVE_W9', '[{"option_text": "The task will be completed by her tomorrow.", "is_correct": true}, {"option_text": "The task was completed by her tomorrow.", "is_correct": false}, {"option_text": "The task is completed by her tomorrow.", "is_correct": false}, {"option_text": "The task has been completed by her tomorrow.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bfc2d4f5-4130-582d-b652-70a93c9d912e', 'Change to active voice: ''The cake was eaten by the children.''', NULL, 'A is correct. ''Was eaten'' (past passive) → ''ate'' (past simple active): ''The children ate the cake''.', 'MEDIUM', 'English', 'Active and Passive Voice (W9)', 'ENG_ACTIVE_PASSIVE_W9', '[{"option_text": "The children ate the cake.", "is_correct": true}, {"option_text": "The children eat the cake.", "is_correct": false}, {"option_text": "The children will eat the cake.", "is_correct": false}, {"option_text": "The children have eaten the cake.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6ad701f8-3863-51ae-b9fe-a92e084799fe', 'Change to passive voice: ''Someone has stolen my wallet.'' (agent is unknown)', NULL, 'B is correct. When the agent is vague (''someone''), it is omitted in the passive. Present perfect → ''has been stolen''. Option A keeps ''someone'' which is unusual to specify.', 'HARD', 'English', 'Active and Passive Voice (W9)', 'ENG_ACTIVE_PASSIVE_W9', '[{"option_text": "My wallet was stolen by someone.", "is_correct": false}, {"option_text": "My wallet has been stolen.", "is_correct": true}, {"option_text": "My wallet is stolen.", "is_correct": false}, {"option_text": "My wallet had been stolen.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4ca35bd6-b34b-5ffa-9b7c-7ae6a97a047f', 'Which options correctly express the passive of: ''People believe that he is honest''?', NULL, 'C is correct. Two valid passive constructions exist for ''people believe that S V'': (1) ''It is believed that he is honest'' (preparatory-it construction) and (2) ''He is believed to be honest'' (raising construction). Both are standard.', 'HARD', 'English', 'Active and Passive Voice (W9)', 'ENG_ACTIVE_PASSIVE_W9', '[{"option_text": "It is believed that he is honest.", "is_correct": false}, {"option_text": "He is believed to be honest.", "is_correct": false}, {"option_text": "Both options A and B are correct passive forms.", "is_correct": true}, {"option_text": "Neither option is a valid passive form.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cc15ae2b-e8f8-5b9b-97ea-2186ddeee48e', 'Choose the antonym of ANCIENT:', NULL, 'C is correct. Modern is the best antonym of ancient (old vs. new/contemporary). ''New'' and ''recent'' are close but ''modern'' is the standard SSC-exam antonym.', 'EASY', 'English', 'Antonyms (W9)', 'ENG_ANTONYMS_W9', '[{"option_text": "Old", "is_correct": false}, {"option_text": "New", "is_correct": false}, {"option_text": "Modern", "is_correct": true}, {"option_text": "Recent", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('83de4926-2257-56e6-b536-e0496c609f9c', 'Choose the antonym of GENEROUS:', NULL, 'C is correct. Stingy (unwilling to give) is the antonym of generous. Kind, giving and warm are near-synonyms of generous.', 'EASY', 'English', 'Antonyms (W9)', 'ENG_ANTONYMS_W9', '[{"option_text": "Kind", "is_correct": false}, {"option_text": "Giving", "is_correct": false}, {"option_text": "Stingy", "is_correct": true}, {"option_text": "Warm", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3a82c347-c0be-5280-97a1-f307c8604dcb', 'Choose the antonym of RAPID:', NULL, 'B is correct. Slow is the antonym of rapid. Quick, fast and brisk are all synonyms of rapid.', 'EASY', 'English', 'Antonyms (W9)', 'ENG_ANTONYMS_W9', '[{"option_text": "Quick", "is_correct": false}, {"option_text": "Slow", "is_correct": true}, {"option_text": "Fast", "is_correct": false}, {"option_text": "Brisk", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('23576d6a-44e5-527f-9d1d-507e2be7e3c9', 'Choose the antonym of LOQUACIOUS:', NULL, 'C is correct. Loquacious = very talkative. Taciturn = reserved, habitually silent. Talkative and vocal are synonyms.', 'MEDIUM', 'English', 'Antonyms (W9)', 'ENG_ANTONYMS_W9', '[{"option_text": "Talkative", "is_correct": false}, {"option_text": "Verbal", "is_correct": false}, {"option_text": "Taciturn", "is_correct": true}, {"option_text": "Vocal", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e221ca8c-3550-5464-b002-6e34ab4e4a64', 'Choose the antonym of ZENITH:', NULL, 'C is correct. Zenith = highest point. Nadir = lowest point. Apex, summit and peak are synonyms of zenith.', 'MEDIUM', 'English', 'Antonyms (W9)', 'ENG_ANTONYMS_W9', '[{"option_text": "Apex", "is_correct": false}, {"option_text": "Summit", "is_correct": false}, {"option_text": "Nadir", "is_correct": true}, {"option_text": "Peak", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b98122e7-d545-579f-9088-f588b72d7416', 'Choose the antonym of DILIGENT:', NULL, 'B is correct. Diligent = hardworking and careful. Lazy (idle) is its antonym. Hardworking, sincere and attentive are synonyms.', 'MEDIUM', 'English', 'Antonyms (W9)', 'ENG_ANTONYMS_W9', '[{"option_text": "Hardworking", "is_correct": false}, {"option_text": "Lazy", "is_correct": true}, {"option_text": "Sincere", "is_correct": false}, {"option_text": "Attentive", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5ddce968-05f4-513a-89e5-29b17d539372', 'Choose the antonym of EXACERBATE:', NULL, 'C is correct. Exacerbate = make worse. Alleviate = make better/relieve. Worsen, aggravate and intensify are synonyms of exacerbate.', 'MEDIUM', 'English', 'Antonyms (W9)', 'ENG_ANTONYMS_W9', '[{"option_text": "Worsen", "is_correct": false}, {"option_text": "Aggravate", "is_correct": false}, {"option_text": "Alleviate", "is_correct": true}, {"option_text": "Intensify", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('06b7acc1-8a16-516c-b775-c3f14ec9a59a', 'Choose the antonym of VERBOSE:', NULL, 'B is correct. Verbose = using more words than necessary. Concise (brief and clear) is its antonym. Long-winded, flowery and elaborate are synonyms.', 'MEDIUM', 'English', 'Antonyms (W9)', 'ENG_ANTONYMS_W9', '[{"option_text": "Long-winded", "is_correct": false}, {"option_text": "Concise", "is_correct": true}, {"option_text": "Flowery", "is_correct": false}, {"option_text": "Elaborate", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('67a75aef-a407-52ac-9b8c-19b44223d787', 'Choose the antonym of SANGUINE:', NULL, 'C is correct. Sanguine = optimistic, especially in a difficult situation. Pessimistic is its antonym. Optimistic, confident and hopeful are synonyms.', 'HARD', 'English', 'Antonyms (W9)', 'ENG_ANTONYMS_W9', '[{"option_text": "Optimistic", "is_correct": false}, {"option_text": "Confident", "is_correct": false}, {"option_text": "Pessimistic", "is_correct": true}, {"option_text": "Hopeful", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8976d595-1f47-574a-8fb2-4a833f61771c', 'Choose the antonym of PERSPICACIOUS:', NULL, 'C is correct. Perspicacious = having a ready insight into things; shrewd. Obtuse = slow to understand; mentally dull. Shrewd, keen and insightful are synonyms.', 'HARD', 'English', 'Antonyms (W9)', 'ENG_ANTONYMS_W9', '[{"option_text": "Shrewd", "is_correct": false}, {"option_text": "Keen", "is_correct": false}, {"option_text": "Obtuse", "is_correct": true}, {"option_text": "Insightful", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
