INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8ec9590e-e4f6-5607-9ead-d2e9fa61c5d4', 'Passage 2 (continued): International bodies have long (8)___ the need for universal primary education...
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1122ad9f-40c8-507a-a618-3dc925c75673', 'Passage 2 (continued): ...recognising it as the (9)___ on which a just society must be built.
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e4e3544b-7b65-504d-b5d4-6b61c3402921', 'Passage 2 (continued): Without educated citizens, a democracy cannot (10)___ effectively.
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2e1c7d3b-167f-566e-a9fe-0bf324494d73', 'Passage 1: ''The impact of climate change on global agriculture has been both (1)___ and far-reaching.'' Choose the correct word for blank (1).', NULL, 'A is correct. ''profound and far-reaching'' is a standard collocation for describing wide-ranging, deep impacts. ''Far-reaching'' (having wide effects) pairs naturally with ''profound'' (deep, significant) to form a pair of synonymous intensifiers. Trap: ''trivial'' = contradicts ''far-reaching'' entirely (trivial means minor); ''temporary'' = does not collocate with ''far-reaching'' (temporary implies limited duration, far-reaching implies wide scope); ''pleasant'' = climate change impact on agriculture is not pleasant.', 'MEDIUM', 'English', 'Cloze Test — Climate Change & Indian Classical Music Passages (W12 B1)', 'ENG_CLOZE_TEST_IV_W12_B1', '[{"option_text": "profound", "is_correct": true}, {"option_text": "trivial", "is_correct": false}, {"option_text": "temporary", "is_correct": false}, {"option_text": "pleasant", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5cdf73bc-08f4-5875-888f-66314354e80b', 'Passage 1 (continued): ''Rising temperatures have (2)___ crop yields in many tropical regions...'' Choose the correct word for blank (2).', NULL, 'C is correct. Rising temperatures harm agriculture in tropical regions (which are already hot), reducing crop yields. The broader passage is about the negative impact of climate change, so ''reduced'' fits the overall negative tone. Trap: ''enhanced'' = incorrect; rising temps in already-hot tropical regions hurt crops, not help them; ''stabilised'' = neutral, doesn''t fit a passage about negative impact; ''diversified'' = doesn''t collocate correctly with ''crop yields''.', 'MEDIUM', 'English', 'Cloze Test — Climate Change & Indian Classical Music Passages (W12 B1)', 'ENG_CLOZE_TEST_IV_W12_B1', '[{"option_text": "stabilised", "is_correct": false}, {"option_text": "diversified", "is_correct": false}, {"option_text": "reduced", "is_correct": true}, {"option_text": "enhanced", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0e69822f-7f91-563a-a560-d004f6af3dd2', 'Passage 1 (continued): ''...while simultaneously creating (3)___ farming conditions in some northern areas.'' Choose the correct word for blank (3).', NULL, 'B is correct. The sentence contrasts tropical regions (reduced yields) with northern areas using ''while simultaneously'' — this contrast signals an opposite effect. Warming that hurts tropical farming creates ''favourable'' (good, beneficial) conditions in northern areas previously too cold to farm well. Trap: ''perilous'' = would make the sentence non-contrasting (both tropical and northern suffering — ''while'' loses its contrast force); ''identical'' = no contrast; ''obsolete'' = does not collocate with ''farming conditions''.', 'EASY', 'English', 'Cloze Test — Climate Change & Indian Classical Music Passages (W12 B1)', 'ENG_CLOZE_TEST_IV_W12_B1', '[{"option_text": "identical", "is_correct": false}, {"option_text": "favourable", "is_correct": true}, {"option_text": "perilous", "is_correct": false}, {"option_text": "obsolete", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f550300c-7032-580c-a9b8-e265e4b40932', 'Passage 1 (continued): ''Scientists warn that without (4)___ intervention, food security could become severely compromised...'' Choose the correct word for blank (4).', NULL, 'D is correct. ''Scientists warn'' conveys urgency, and ''without ___ intervention'' means acting is critical now. ''Immediate'' (right away) is the word that creates the necessary urgency. Trap: ''delayed'' = is the opposite — delayed intervention is precisely what scientists warn against; ''reluctant'' = ''reluctant intervention'' would describe governments acting unwillingly, not the concept of needing action urgently; ''symbolic'' = symbolic intervention means no real action, contradicting the warning.', 'HARD', 'English', 'Cloze Test — Climate Change & Indian Classical Music Passages (W12 B1)', 'ENG_CLOZE_TEST_IV_W12_B1', '[{"option_text": "reluctant", "is_correct": false}, {"option_text": "delayed", "is_correct": false}, {"option_text": "symbolic", "is_correct": false}, {"option_text": "immediate", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0e99b634-ddc7-5e93-8e79-59d51861c264', 'Passage 1 (continued): ''...food security could become (5)___ compromised within the next few decades.'' Choose the correct word for blank (5).', NULL, 'D is correct. The passage discusses a serious crisis (scientists warning, food security at risk); ''severely compromised'' matches the alarming tone. ''Severely'' = to a great degree, intensifying ''compromised''. Trap: ''mildly'' = undercuts the crisis tone established throughout the passage; ''selectively'' = ''selectively compromised'' is not idiomatic and doesn''t convey the global scale; ''partially'' = weakens the warning and contradicts ''without immediate intervention'' urgency.', 'EASY', 'English', 'Cloze Test — Climate Change & Indian Classical Music Passages (W12 B1)', 'ENG_CLOZE_TEST_IV_W12_B1', '[{"option_text": "mildly", "is_correct": false}, {"option_text": "selectively", "is_correct": false}, {"option_text": "partially", "is_correct": false}, {"option_text": "severely", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('834c9bc3-8964-5b72-8887-da7fcc535682', 'Passage 2: ''Indian classical music is one of the world''s oldest (6)___ musical traditions.'' Choose the correct word for blank (6).', NULL, 'B is correct. ''One of the world''s oldest living traditions'' is a standard expression meaning it originated very long ago and is still actively practised today. The word ''living'' modifies ''traditions'' to distinguish from extinct ones. Trap: ''extinct'' = the opposite; Indian classical music is very much alive; ''celebrated'' = ''celebrated traditions'' is possible but ''oldest celebrated'' is a weaker collocation — ''oldest living'' is the set phrase; ''documented'' = ''oldest documented traditions'' changes the meaning to recordkeeping, not survival.', 'MEDIUM', 'English', 'Cloze Test — Climate Change & Indian Classical Music Passages (W12 B1)', 'ENG_CLOZE_TEST_IV_W12_B1', '[{"option_text": "extinct", "is_correct": false}, {"option_text": "living", "is_correct": true}, {"option_text": "celebrated", "is_correct": false}, {"option_text": "documented", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('842ed4c8-ceaf-5d0a-b782-782818a4a472', 'Passage 2 (continued): ''It is built upon ragas, which are (7)___ melodic modes governing not just the notes but also the timing and emotional mood of a performance.'' Choose the correct word for blank (7).', NULL, 'B is correct. Ragas are not improvised freely; they follow strict rules governing which notes to use, when to perform them, and the mood to evoke. ''Prescribed melodic modes'' = modes with defined rules. ''Governing not just the notes but also the timing and mood'' further confirms a rule-based structure. Trap: ''random'' = contradicts ''governing'' (governing implies rules); ''optional'' = if ragas were optional, the music wouldn''t be ''built upon'' them; ''informal'' = opposite — ragas are highly formal and structured.', 'MEDIUM', 'English', 'Cloze Test — Climate Change & Indian Classical Music Passages (W12 B1)', 'ENG_CLOZE_TEST_IV_W12_B1', '[{"option_text": "random", "is_correct": false}, {"option_text": "prescribed", "is_correct": true}, {"option_text": "optional", "is_correct": false}, {"option_text": "informal", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a2e3ec66-2ee7-53d3-93b3-9e0ce3ad1790', 'Passage 2 (continued): ''ragas govern not just the notes but also the (8)___ and emotional mood of a performance.'' Choose the correct word for blank (8).', NULL, 'C is correct. Each raga in Indian classical music is associated with a specific time of day or season — morning ragas (Bhairav), evening ragas (Yaman), monsoon ragas (Megh Malhar). ''Timing and emotional mood'' captures two core dimensions ragas govern beyond mere notes. Trap: ''lyrics'' = many ragas are purely instrumental; ''lyrics'' is not the defining governed element; ''instruments'' = ragas are independent of instruments (sitar, sarod, voice all perform the same raga); ''venue'' = ragas have no venue restriction.', 'HARD', 'English', 'Cloze Test — Climate Change & Indian Classical Music Passages (W12 B1)', 'ENG_CLOZE_TEST_IV_W12_B1', '[{"option_text": "instruments", "is_correct": false}, {"option_text": "lyrics", "is_correct": false}, {"option_text": "timing", "is_correct": true}, {"option_text": "venue", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('447a4f09-487e-523f-aef9-5191f0e9bce1', 'Passage 2 (continued): ''Unlike Western classical music, Indian classical music places great (9)___ on improvisation.'' Choose the correct word for blank (9).', NULL, 'C is correct. ''Place great emphasis on'' is the standard idiomatic expression meaning to consider something very important. The sentence says Indian classical music values improvisation highly. Trap: ''burden'' = ''places a burden on improvisation'' distorts meaning; burden = hardship, but improvisation is a strength; ''reliance'' = ''places reliance on'' is not standard idiom; ''reliance'' collocates with ''has a reliance on''; ''restriction'' = opposite meaning — improvisation is valued, not restricted.', 'EASY', 'English', 'Cloze Test — Climate Change & Indian Classical Music Passages (W12 B1)', 'ENG_CLOZE_TEST_IV_W12_B1', '[{"option_text": "burden", "is_correct": false}, {"option_text": "reliance", "is_correct": false}, {"option_text": "emphasis", "is_correct": true}, {"option_text": "restriction", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('84bc983b-2b41-5d11-ab28-d54ca467df80', 'Passage 2 (continued): ''...requiring musicians to demonstrate both technical (10)___ and creative spontaneity.'' Choose the correct word for blank (10).', NULL, 'B is correct. The sentence requires two contrasting qualities: ''technical ___'' (a formal, disciplined quality) and ''creative spontaneity'' (a free, improvisational quality). ''Technical mastery'' = deep, expert command of technique. This contrast of discipline vs. freedom is central to Indian classical music. Trap: ''curiosity'' = ''technical curiosity'' is weak; mastery is the earned outcome, not just curiosity; ''indifference'' = ''technical indifference'' (not caring about technique) directly contradicts the demanding nature of classical training; ''struggle'' = ''technical struggle'' implies failure, not expertise.', 'MEDIUM', 'English', 'Cloze Test — Climate Change & Indian Classical Music Passages (W12 B1)', 'ENG_CLOZE_TEST_IV_W12_B1', '[{"option_text": "curiosity", "is_correct": false}, {"option_text": "mastery", "is_correct": true}, {"option_text": "indifference", "is_correct": false}, {"option_text": "struggle", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bdad9660-5053-503e-b84c-df7cc773b96e', 'Passage 1: ''India''s rapid urbanisation has created both (1)___ and challenges. Cities now drive over 60% of national GDP, yet millions of migrants arrive annually seeking better livelihoods, straining existing (2)___ like housing, water and transport.'' — Choose the correct word for blank (1).', NULL, 'B is correct. ''Both ___ and challenges'' requires a POSITIVE noun to contrast with ''challenges''. ''Opportunities'' = favourable conditions for advancement — perfect contrast. The context confirms this: cities driving 60% of GDP is a positive economic contribution = an opportunity. Trap: problems, penalties, obstacles = all negative words (would make ''both positive and negative'' sound strange as ''both negative and negative'').', 'EASY', 'English', 'Cloze Test — Urbanisation & Digital Economy Passages (W13 B1)', 'ENG_CLOZE_TEST_VIII_W13_B1', '[{"option_text": "problems", "is_correct": false}, {"option_text": "opportunities", "is_correct": true}, {"option_text": "penalties", "is_correct": false}, {"option_text": "obstacles", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('88ce6ced-5cef-554d-b4a6-7ecfed540a0d', 'Passage 1 (continued): ''...straining existing (2)___ like housing, water and transport.'' Choose the correct word for blank (2).', NULL, 'C is correct. ''Existing ___ like housing, water and transport'' — the blank must name the category that includes housing, water and transport. INFRASTRUCTURE = the basic physical and organisational structures needed for society (roads, bridges, water, housing, power, transport) ✓. Trap: authorities = the governing bodies (not a category that includes housing and water); alternatives = different options (these are not alternatives, they are essentials); innovations = new ideas (housing and transport are not innovations).', 'EASY', 'English', 'Cloze Test — Urbanisation & Digital Economy Passages (W13 B1)', 'ENG_CLOZE_TEST_VIII_W13_B1', '[{"option_text": "authorities", "is_correct": false}, {"option_text": "alternatives", "is_correct": false}, {"option_text": "infrastructure", "is_correct": true}, {"option_text": "innovations", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fd902b51-45cf-5ff1-a102-487e09690f32', 'Passage 1 (continued): ''Urban planners must find (3)___ solutions that can accommodate growth without sacrificing liveability or environmental quality.'' Choose the correct word for blank (3).', NULL, 'C is correct. ''Solutions that accommodate growth WITHOUT sacrificing liveability or environment'' describes solutions that work long-term for both people and nature = SUSTAINABLE (meeting present needs without compromising future ones). Trap: temporary = the opposite of what''s needed (short-term solutions worsen the problem); expensive = a quality of solutions, not a description of their sustainability; outdated = the opposite of what planners need.', 'EASY', 'English', 'Cloze Test — Urbanisation & Digital Economy Passages (W13 B1)', 'ENG_CLOZE_TEST_VIII_W13_B1', '[{"option_text": "temporary", "is_correct": false}, {"option_text": "expensive", "is_correct": false}, {"option_text": "sustainable", "is_correct": true}, {"option_text": "outdated", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c6f8e958-f5ad-5bdc-b12a-987b12fdd2cb', 'Passage 1 (continued): ''Smart cities that use data and technology to manage resources (4)___ represent one promising approach to this challenge.'' Choose the correct word for blank (4).', NULL, 'B is correct. Smart cities use data and technology to manage resources ''EFFICIENTLY'' = in a way that avoids waste and maximises output. The ''promising approach'' phrase confirms the positive outcome. Trap: wastefully, randomly, carelessly = all negative adverbs contradicting the idea that smart cities are a PROMISING (positive) approach to resource management.', 'MEDIUM', 'English', 'Cloze Test — Urbanisation & Digital Economy Passages (W13 B1)', 'ENG_CLOZE_TEST_VIII_W13_B1', '[{"option_text": "wastefully", "is_correct": false}, {"option_text": "efficiently", "is_correct": true}, {"option_text": "randomly", "is_correct": false}, {"option_text": "carelessly", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('aa18fbfc-7f0c-54ad-8a6c-8d7943ca837d', 'Passage 1 (continued): ''However, the benefits of urban growth have been (5)___ distributed, with peri-urban and slum areas often left behind despite their proximity to prosperous city centres.'' Choose the correct word for blank (5).', NULL, 'D is correct. ''However'' signals contrast with positive urban growth. ''Peri-urban and slum areas often left behind'' confirms UNEVEN distribution = some areas benefit, others don''t. UNEVENLY = not in an equal or uniform way ✓. Trap: equally, fairly, uniformly = all signal EVEN distribution — directly contradicted by ''slum areas left behind''.', 'MEDIUM', 'English', 'Cloze Test — Urbanisation & Digital Economy Passages (W13 B1)', 'ENG_CLOZE_TEST_VIII_W13_B1', '[{"option_text": "equally", "is_correct": false}, {"option_text": "fairly", "is_correct": false}, {"option_text": "uniformly", "is_correct": false}, {"option_text": "unevenly", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('96171cd9-b79d-5b2e-bae9-9987fe8ed157', 'Passage 2: ''India''s digital economy has witnessed (6)___ growth over the past decade, driven by affordable smartphones, widespread internet penetration and government initiatives like Digital India.'' Choose the correct word for blank (6).', NULL, 'C is correct. The context (affordable smartphones + widespread internet + Digital India initiative) describes major drivers of rapid, large-scale growth. EXPONENTIAL = increasing very rapidly (doubling/multiplying at an accelerating rate). The passage implies dramatic, not slow, growth. Trap: negligible = very small (opposite of what''s described); modest = moderate/small-scale (contradicts the ''widespread'' and ''government initiative'' scale); gradual = slow and steady (contradicts the ''witnessed'' rapid transformation implied).', 'MEDIUM', 'English', 'Cloze Test — Urbanisation & Digital Economy Passages (W13 B1)', 'ENG_CLOZE_TEST_VIII_W13_B1', '[{"option_text": "negligible", "is_correct": false}, {"option_text": "modest", "is_correct": false}, {"option_text": "exponential", "is_correct": true}, {"option_text": "gradual", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('72991f55-6261-5714-bce0-0f325c1e9139', 'Passage 2 (continued): ''The UPI payment system alone processes over 10 billion transactions monthly, making India a global (7)___ in digital payments.'' Choose the correct word for blank (7).', NULL, 'C is correct. ''Processing 10 billion transactions monthly'' = a massive achievement that places India at the TOP of digital payments. ''Global LEADER'' = country that leads the world in a field ✓. Trap: laggard and follower = countries that are behind others (contradicted by the enormous volume: 10 billion/month is world-leading); bystander = uninvolved observer (completely wrong — India is an active participant and leader).', 'EASY', 'English', 'Cloze Test — Urbanisation & Digital Economy Passages (W13 B1)', 'ENG_CLOZE_TEST_VIII_W13_B1', '[{"option_text": "laggard", "is_correct": false}, {"option_text": "follower", "is_correct": false}, {"option_text": "leader", "is_correct": true}, {"option_text": "bystander", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fa8dbf63-617f-5ab9-9b5b-d5b1fe7edc4b', 'Passage 2 (continued): ''Yet the digital divide remains a serious concern — rural populations and the elderly often lack the (8)___ skills or connectivity needed to benefit from these advances.'' Choose the correct word for blank (8).', NULL, 'B is correct. The context is about the ''digital divide'' — the gap between those who have access to and can use digital technology versus those who cannot. ''DIGITAL skills'' = the ability to use computers, smartphones, apps and the internet. The blank collocates with ''connectivity'' (digital infrastructure) and both relate to the digital divide. Trap: physical skills = manual/motor abilities (not relevant to internet/apps); financial skills = money management (separate from digital literacy); political skills = governance/negotiation (unrelated).', 'MEDIUM', 'English', 'Cloze Test — Urbanisation & Digital Economy Passages (W13 B1)', 'ENG_CLOZE_TEST_VIII_W13_B1', '[{"option_text": "physical", "is_correct": false}, {"option_text": "digital", "is_correct": true}, {"option_text": "financial", "is_correct": false}, {"option_text": "political", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('41ae0f71-779b-546e-af2f-c7f6db3b5f70', 'Passage 2 (continued): ''Bridging this divide requires not just providing access to technology but also (9)___ training programmes that teach people how to use it safely and productively.'' Choose the correct word for blank (9).', NULL, 'B is correct. The sentence emphasises not just providing ACCESS but also ensuring people can use technology ''safely AND productively'' (two goals). A training programme that achieves both must be COMPREHENSIVE = complete and thorough, covering all necessary aspects. Trap: optional = training that may or may not be taken (the word ''requires'' implies it is necessary, not optional); superficial = shallow/surface-level (opposite of what''s needed for safe AND productive use); eliminating = removing (doesn''t modify ''training programmes'').', 'HARD', 'English', 'Cloze Test — Urbanisation & Digital Economy Passages (W13 B1)', 'ENG_CLOZE_TEST_VIII_W13_B1', '[{"option_text": "eliminating", "is_correct": false}, {"option_text": "comprehensive", "is_correct": true}, {"option_text": "optional", "is_correct": false}, {"option_text": "superficial", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a5292c30-325d-5328-86fa-d486977ca821', 'Passage 2 (concluded): ''Only then can India truly (10)___ its digital potential and ensure that no citizen is left behind in the information age.'' Choose the correct word for blank (10).', NULL, 'C is correct. ''Truly ___ its digital potential'' — the blank needs a positive verb meaning ''to make good use of'' or ''to unlock and use''. HARNESS = to capture and use (power, energy, potential) effectively (harness the wind; harness technology; harness potential). ''Harness its digital potential'' = fully use and benefit from it ✓. Trap: squander = waste (the opposite of using potential well); undermine = weaken (the opposite); suppress = hold down/restrain (the opposite of unleashing potential).', 'HARD', 'English', 'Cloze Test — Urbanisation & Digital Economy Passages (W13 B1)', 'ENG_CLOZE_TEST_VIII_W13_B1', '[{"option_text": "squander", "is_correct": false}, {"option_text": "undermine", "is_correct": false}, {"option_text": "harness", "is_correct": true}, {"option_text": "suppress", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5328b9f3-d43e-5239-acaf-cf3e2e01de15', 'Passage 1: ''Reading is one of the most (1)___ habits a person can cultivate. Unlike passive entertainment such as television, reading engages the mind actively and builds vocabulary, concentration and empathy.'' Choose the word for blank (1).', NULL, 'C is correct. The passage praises reading (''builds vocabulary, concentration and empathy''). ''One of the most ___ habits'' must be positive in meaning. ''Beneficial'' = producing good or helpful results — perfectly fits the praising tone. Trap: ''tedious'' and ''destructive'' = negative words contradicting the passage''s tone; ''expensive'' = irrelevant to the value of reading as a mental habit.', 'EASY', 'English', 'Cloze Test — The Joy of Reading & River Pollution Passages (W12 B1)', 'ENG_CLOZE_TEST_V_W12_B1', '[{"option_text": "destructive", "is_correct": false}, {"option_text": "expensive", "is_correct": false}, {"option_text": "beneficial", "is_correct": true}, {"option_text": "tedious", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9ea39524-8bb2-5545-84ce-3460eca22ec5', 'Passage 1 (continued): ''Studies have shown that regular readers have (2)___ vocabularies and stronger analytical skills than non-readers.'' Choose the word for blank (2).', NULL, 'C is correct. ''Richer vocabularies'' = a larger, more varied word bank — the positive outcome consistent with the passage''s pro-reading argument. The blank is paired with ''stronger analytical skills'', both describing advantages. ''Richer'' is the standard collocation for vocabulary (''rich vocabulary'' = extensive and varied). Trap: ''smaller'', ''weaker'', ''narrower'' = all negative — contradicting the positive comparison regular readers vs. non-readers that the passage draws.', 'EASY', 'English', 'Cloze Test — The Joy of Reading & River Pollution Passages (W12 B1)', 'ENG_CLOZE_TEST_V_W12_B1', '[{"option_text": "weaker", "is_correct": false}, {"option_text": "smaller", "is_correct": false}, {"option_text": "richer", "is_correct": true}, {"option_text": "narrower", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0c5f3f16-6aa2-5ae3-8270-6547be696546', 'Passage 1 (continued): ''Fiction, in particular, (3)___ readers to step into other lives and understand experiences very different from their own.'' Choose the word for blank (3).', NULL, 'C is correct. ''Allows readers to step into other lives'' = fiction enables or permits this perspective-taking. ''Allows'' = makes it possible for someone to do something; it is the neutral-positive verb that enables. Trap: ''forces'' = too coercive (fiction doesn''t compel; it enables); ''prevents'' and ''discourages'' = negative meanings contradicting the empathy-building benefit described.', 'EASY', 'English', 'Cloze Test — The Joy of Reading & River Pollution Passages (W12 B1)', 'ENG_CLOZE_TEST_V_W12_B1', '[{"option_text": "prevents", "is_correct": false}, {"option_text": "forces", "is_correct": false}, {"option_text": "allows", "is_correct": true}, {"option_text": "discourages", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7aca58da-0628-584d-95b2-ac1eab549fa2', 'Passage 1 (continued): ''Despite the rise of digital media, books remain (4)___ sources of deep, sustained engagement with ideas.'' Choose the word for blank (4).', NULL, 'B is correct. ''Despite the rise of digital media'' = concessive clause signalling that books still have enduring value. ''Remain irreplaceable'' = cannot be substituted or replaced, maintaining unique value. The paragraph defends reading, so the blank must be strongly positive. Trap: ''obsolete'' = outdated/no longer useful — contradicts ''despite'' clause and the passage''s pro-reading stance; ''expensive'', ''inconvenient'' = minor practical concerns unrelated to the point about deep engagement.', 'MEDIUM', 'English', 'Cloze Test — The Joy of Reading & River Pollution Passages (W12 B1)', 'ENG_CLOZE_TEST_V_W12_B1', '[{"option_text": "obsolete", "is_correct": false}, {"option_text": "irreplaceable", "is_correct": true}, {"option_text": "expensive", "is_correct": false}, {"option_text": "inconvenient", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('463f0923-525c-59c5-99c6-ecb171f3a2f9', 'Passage 1 (continued): ''Those who read widely tend to be more (5)___ in their world view, open to perspectives beyond their immediate experience.'' Choose the word for blank (5).', NULL, 'C is correct. ''Open to perspectives beyond their immediate experience'' defines the blank — someone with a global, open worldview. COSMOPOLITAN = having wide international experience; open-minded, familiar with many cultures and ideas. This is exactly what ''reading widely'' produces. Trap: ''narrow-minded'', ''intolerant'', ''parochial'' (limited to local concerns) = all describe the opposite of the openness described in the rest of the sentence.', 'MEDIUM', 'English', 'Cloze Test — The Joy of Reading & River Pollution Passages (W12 B1)', 'ENG_CLOZE_TEST_V_W12_B1', '[{"option_text": "narrow-minded", "is_correct": false}, {"option_text": "intolerant", "is_correct": false}, {"option_text": "cosmopolitan", "is_correct": true}, {"option_text": "parochial", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('56b0b56d-e032-59c9-972a-81e09d10eb3a', 'Passage 2: ''India''s rivers are among the most (6)___ in the world, sustaining agriculture, industry and millions of people who depend on them for drinking water and livelihoods.'' Choose the word for blank (6).', NULL, 'C is correct. The sentence emphasises the rivers'' importance: ''sustaining agriculture, industry and millions of people.'' ''Most vital'' = of the greatest importance for survival — perfectly captures this life-sustaining role. Trap: ''polluted'' = would create a contradiction (if they''re most polluted, calling them important for drinking water is alarming — while true, the sentence is structured as a positive opening statement of significance, not a warning); ''dangerous'' = negative and inappropriate in context of ''millions depending on them''.', 'MEDIUM', 'English', 'Cloze Test — The Joy of Reading & River Pollution Passages (W12 B1)', 'ENG_CLOZE_TEST_V_W12_B1', '[{"option_text": "polluted", "is_correct": false}, {"option_text": "narrow", "is_correct": false}, {"option_text": "vital", "is_correct": true}, {"option_text": "dangerous", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5161ba9d-cf9d-5fd8-a00e-c46c6543ceee', 'Passage 2 (continued): ''Yet decades of industrial (7)___, untreated sewage discharge and agricultural runoff have severely degraded river water quality across the country.'' Choose the word for blank (7).', NULL, 'C is correct. The sentence lists sources of river pollution: ___ (from industries), sewage discharge and agricultural runoff. Industrial EFFLUENTS = liquid waste or sewage discharged by a factory into a river or the sea. This is the precise technical term for industrial liquid waste pollutants. Trap: ''progress'', ''investment'', ''prosperity'' = all positive terms related to industry (cannot cause degradation as described); the ''Yet'' at the start signals a negative contrast to the opening positive description.', 'MEDIUM', 'English', 'Cloze Test — The Joy of Reading & River Pollution Passages (W12 B1)', 'ENG_CLOZE_TEST_V_W12_B1', '[{"option_text": "progress", "is_correct": false}, {"option_text": "investment", "is_correct": false}, {"option_text": "effluents", "is_correct": true}, {"option_text": "prosperity", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('851d1fc6-ff03-5a3d-ae87-0ec1e27ad3ae', 'Passage 2 (continued): ''The Ganga, once revered as a sacred life-giving river, is now classified as one of the most (8)___ rivers in Asia.'' Choose the word for blank (8).', NULL, 'C is correct. The sentence contrasts the Ganga''s sacred past (''once revered'') with its current degraded state (''now classified as...''). The contrast ''once life-giving → now most ___'' clearly requires a negative environmental descriptor. ''Polluted'' = contaminated with harmful substances. The context of the entire passage (river water quality degraded) confirms the blank. Trap: ''celebrated'' and ''photographed'' = positive (contradict the ''now'' contrast); ''navigable'' = about boat travel (not relevant to water quality or the revered→degraded contrast).', 'EASY', 'English', 'Cloze Test — The Joy of Reading & River Pollution Passages (W12 B1)', 'ENG_CLOZE_TEST_V_W12_B1', '[{"option_text": "celebrated", "is_correct": false}, {"option_text": "navigable", "is_correct": false}, {"option_text": "polluted", "is_correct": true}, {"option_text": "photographed", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('adf6a1aa-4dd6-52b3-81f6-b1a77e6c2438', 'Passage 2 (continued): ''Government initiatives like the Namami Gange programme aim to (9)___ the river by treating sewage, reducing industrial discharge and planting trees on riverbanks.'' Choose the word for blank (9).', NULL, 'C is correct. ''Treating sewage, reducing discharge and planting trees'' = remediation activities aimed at improving the river. The blank must describe the positive goal of these actions — to REVIVE (restore to health/vitality) the river. The contrast with pollution described earlier reinforces the positive intent of government programmes. Trap: ''pollute'' = opposite of the goal; ''bypass'' = to go around (irrelevant); ''privatise'' = transfer to private ownership (nothing in the sentence suggests this).', 'MEDIUM', 'English', 'Cloze Test — The Joy of Reading & River Pollution Passages (W12 B1)', 'ENG_CLOZE_TEST_V_W12_B1', '[{"option_text": "pollute", "is_correct": false}, {"option_text": "bypass", "is_correct": false}, {"option_text": "revive", "is_correct": true}, {"option_text": "privatise", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c10d7439-84be-5477-9dc9-ead707677929', 'Passage 2 (continued): ''Without urgent and sustained action, future generations may inherit rivers that are (10)___ beyond recovery, unable to support the ecosystems and communities that depend on them.'' Choose the word for blank (10).', NULL, 'C is correct. ''Beyond recovery'' and ''unable to support ecosystems'' signal severe deterioration. DEGRADED = having declined significantly in quality — the word preceding ''beyond recovery'' must describe severely worsened environmental quality. ''Degraded beyond recovery'' = so damaged that restoration is impossible. Trap: ''flourishing'' and ''pristine'' = positive states (the opposite of what the warning describes); ''celebrated'' = positive recognition (irrelevant to environmental condition).', 'HARD', 'English', 'Cloze Test — The Joy of Reading & River Pollution Passages (W12 B1)', 'ENG_CLOZE_TEST_V_W12_B1', '[{"option_text": "flourishing", "is_correct": false}, {"option_text": "pristine", "is_correct": false}, {"option_text": "degraded", "is_correct": true}, {"option_text": "celebrated", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ebd9f45c-0781-5b76-b84f-82ff85c188cd', 'Read the following passage and answer questions 1–10 based on it.
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('828d25c5-71a4-5e53-a657-069a52867163', '(Passage repeated in exam setting — same passage as Q1.)
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('23a64547-690a-5176-b973-a00b03e33ee8', 'Blank (3): ''ISRO has achieved __(3)__ milestones.''', NULL, 'C is correct. The entire passage praises ISRO''s achievements — ''remarkable milestones'' (extraordinary, noteworthy) fits the tone. Trap: ''ordinary'', ''minor'', and ''forgettable'' all downplay achievements, contradicting the passage''s celebratory tone and specific examples (first Asian Mars mission, 104-satellite record).', 'EASY', 'English', 'Cloze Test — India''s Space Programme (W10)', 'ENG_CLOZE_TEST_W10', '[{"option_text": "ordinary", "is_correct": false}, {"option_text": "minor", "is_correct": false}, {"option_text": "remarkable", "is_correct": true}, {"option_text": "forgettable", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5537036f-9f5f-51b4-b522-e0e69f542555', 'Blank (4): ''...the first Asian nation to __(4)__ Martian orbit on its...''', NULL, 'C is correct. ''Enter Martian orbit'' = reach and begin orbiting Mars — the precise achievement of the Mars Orbiter Mission. Trap: ''miss Martian orbit'' contradicts the success; ''leave'' and ''escape'' imply departing from orbit (not arriving at it). The mission entered orbit on its first attempt, which is the next blank''s context.', 'MEDIUM', 'English', 'Cloze Test — India''s Space Programme (W10)', 'ENG_CLOZE_TEST_W10', '[{"option_text": "miss", "is_correct": false}, {"option_text": "leave", "is_correct": false}, {"option_text": "enter", "is_correct": true}, {"option_text": "escape", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8d5bd173-2e13-5732-8a59-2191ef63ffa7', 'Blank (5): ''...first Asian nation to enter Martian orbit on its __(5)__ attempt.''', NULL, 'A is correct. ''Maiden attempt'' = the first attempt (often used for firsts: maiden voyage, maiden speech, maiden century). India succeeded on its FIRST try — a historic achievement. Trap: ''final attempt'' would imply multiple tries before success; ''repeated'' means more than once; ''failed'' directly contradicts the success described.', 'MEDIUM', 'English', 'Cloze Test — India''s Space Programme (W10)', 'ENG_CLOZE_TEST_W10', '[{"option_text": "maiden", "is_correct": true}, {"option_text": "final", "is_correct": false}, {"option_text": "repeated", "is_correct": false}, {"option_text": "failed", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('596a4a46-3029-596b-a109-13602c1b45d9', 'Blank (6): ''ISRO set a world record by __(6)__ 104 satellites in a single launch vehicle.''', NULL, 'A is correct. ''Launching satellites'' = sending them into orbit using a rocket. ISRO''s PSLV-C37 mission (2017) launched 104 satellites in one go — a world record at the time. Trap: ''losing'', ''cancelling'', and ''destroying'' all imply failure or negative outcomes, contradicting the record-setting achievement.', 'MEDIUM', 'English', 'Cloze Test — India''s Space Programme (W10)', 'ENG_CLOZE_TEST_W10', '[{"option_text": "launching", "is_correct": true}, {"option_text": "losing", "is_correct": false}, {"option_text": "cancelling", "is_correct": false}, {"option_text": "destroying", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c8cff7b9-3588-57e0-a94c-2107a10c1f4e', 'Blank (7): ''These successes have greatly __(7)__ India''s standing in the global space community.''', NULL, 'B is correct. ''Boosted India''s standing'' = improved and elevated India''s reputation and position. The passage describes achievements, so their effect must be positive. Trap: ''damaged'', ''reduced'', and ''questioned'' all imply a negative effect on reputation, directly contradicting the positive tone established by describing record-setting successes.', 'MEDIUM', 'English', 'Cloze Test — India''s Space Programme (W10)', 'ENG_CLOZE_TEST_W10', '[{"option_text": "damaged", "is_correct": false}, {"option_text": "boosted", "is_correct": true}, {"option_text": "reduced", "is_correct": false}, {"option_text": "questioned", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('66674bae-ca81-579f-9de9-ef0d0c97c4be', 'Blank (8): ''The Chandrayaan missions have __(8)__ valuable data about the Moon''s surface...''', NULL, 'C is correct. ''Yielded valuable data'' = produced or generated meaningful scientific data as a result of the missions. ''Yield'' = produce as a result. Trap: ''ignored'' and ''hidden'' contradict obtaining data; ''wasted'' contradicts ''valuable.'' Note: ''collected'' would also work conceptually, but ''yielded'' is the more precise scientific term for missions that generate findings.', 'HARD', 'English', 'Cloze Test — India''s Space Programme (W10)', 'ENG_CLOZE_TEST_W10', '[{"option_text": "ignored", "is_correct": false}, {"option_text": "hidden", "is_correct": false}, {"option_text": "yielded", "is_correct": true}, {"option_text": "wasted", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d15ffe06-e742-5e38-8cbe-fa63d3b881e4', 'Blank (9): ''Looking ahead, ISRO __(9)__ to launch Gaganyaan, India''s first manned spaceflight.''', NULL, 'B is correct. ''ISRO aims to launch'' = ISRO plans and intends to launch. ''Aim to + verb'' expresses a goal or aspiration. Trap: ''refuses to launch'' contradicts the stated ambition; ''fails to launch'' would mean the mission didn''t happen (contradicting future-tense ambition); ''hesitates'' implies uncertainty, while the passage''s tone is one of confident ambition.', 'HARD', 'English', 'Cloze Test — India''s Space Programme (W10)', 'ENG_CLOZE_TEST_W10', '[{"option_text": "refuses", "is_correct": false}, {"option_text": "aims", "is_correct": true}, {"option_text": "fails", "is_correct": false}, {"option_text": "hesitates", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e6cdec43-8966-5553-b6ec-80ed494edde5', 'Blank (10): ''Such ambitions clearly __(10)__ that India''s journey among the stars has only just begun.''', NULL, 'C is correct. ''Clearly indicate that'' = show clearly or make evident that. The ambitious plans signal (indicate) that India''s space story is far from finished. Trap: ''deny'' would mean the ambitions contradict the statement about an unfinished journey (illogical); ''mask'' and ''obscure'' mean to hide or conceal — the opposite of ''clearly'' making something evident.', 'HARD', 'English', 'Cloze Test — India''s Space Programme (W10)', 'ENG_CLOZE_TEST_W10', '[{"option_text": "deny", "is_correct": false}, {"option_text": "mask", "is_correct": false}, {"option_text": "indicate", "is_correct": true}, {"option_text": "obscure", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c9ed4a63-265b-5f76-ba6e-d61cb3693788', 'Passage: ''Social media has (1)___ an integral part of modern youth culture. While it (2)___ young people to connect with friends and (3)___ information effortlessly, its excessive use has raised (4)___ concerns among educators and mental health experts. Studies suggest that teenagers who (5)___ more than three hours daily on social media are more (6)___ to experience anxiety. The (7)___ portrayals of perfect lives often lead young users to make unfavourable (8)___ between themselves and others. Despite these drawbacks, social media also (9)___ as a powerful tool for social activism and (10)___ communication across geographical boundaries.''
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('33095529-9f4a-5f43-8138-0f809bedede8', 'Blank (2): While it ___ young people to connect with friends and share information effortlessly...', NULL, 'A is correct. ''Enables'' = gives the ability to. The sentence structure ''While it ___ young people to connect'' is a concession clause — it first acknowledges the positive aspect of social media (enabling connection) before the passage shifts to drawbacks. ''Disables'', ''prevents'', and ''discourages'' are all negative in meaning and contradict the sentence''s concessive function.', 'EASY', 'English', 'Cloze Test — Social Media and Youth (W10 B2)', 'ENG_CLOZE_TEST_W10_B2', '[{"option_text": "enables", "is_correct": true}, {"option_text": "disables", "is_correct": false}, {"option_text": "prevents", "is_correct": false}, {"option_text": "discourages", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5a8bebb3-9403-5701-9a01-364187e240b3', 'Blank (3): While it enables young people to connect with friends and ___ information effortlessly...', NULL, 'B is correct. ''Share information'' is the natural pairing — the passage discusses the positive aspect of social media (easy communication and information dissemination). ''Conceal'' and ''withhold'' are opposite to the free-flow of information implied; ''destroy'' is semantically inappropriate.', 'EASY', 'English', 'Cloze Test — Social Media and Youth (W10 B2)', 'ENG_CLOZE_TEST_W10_B2', '[{"option_text": "conceal", "is_correct": false}, {"option_text": "share", "is_correct": true}, {"option_text": "destroy", "is_correct": false}, {"option_text": "withhold", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('53d38ed9-19a2-5e84-9c6e-429d8a94bf31', 'Blank (4): Its excessive use has raised ___ concerns among educators and mental health experts.', NULL, 'C is correct. ''Raised serious concerns'' is a standard colocation meaning the worries are significant and noteworthy. The passage context (educators and mental health experts are worried) confirms severity. ''Trivial'', ''minimal'', and ''negligible'' all mean unimportant — opposite to what the experts'' involvement suggests.', 'MEDIUM', 'English', 'Cloze Test — Social Media and Youth (W10 B2)', 'ENG_CLOZE_TEST_W10_B2', '[{"option_text": "trivial", "is_correct": false}, {"option_text": "minimal", "is_correct": false}, {"option_text": "serious", "is_correct": true}, {"option_text": "negligible", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e9d5fc2d-e0ef-5caa-ac41-beb93c2d4cfe', 'Blank (5): Studies suggest that teenagers who ___ more than three hours daily on social media platforms are more likely to experience anxiety.', NULL, 'A is correct. ''Spend time'' is the standard neutral collocation for using/passing time. ''Waste'' implies judging the time as misspent — but the passage is presenting this as an objective finding from studies (neutral language). ''Invest'' implies productive return; ''exhaust'' means to use up completely and doesn''t collocate with ''hours daily''.', 'MEDIUM', 'English', 'Cloze Test — Social Media and Youth (W10 B2)', 'ENG_CLOZE_TEST_W10_B2', '[{"option_text": "spend", "is_correct": true}, {"option_text": "waste", "is_correct": false}, {"option_text": "invest", "is_correct": false}, {"option_text": "exhaust", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5f617aeb-8ac5-506c-b04e-8e317e870776', 'Blank (6): Teenagers who spend more than three hours daily on social media are more ___ to experience anxiety and depression.', NULL, 'C is correct. ''More likely to experience'' is the standard construction for expressing increased probability. ''Resistant'' and ''immune'' mean protected from (opposite meaning); ''reluctant'' means unwilling and changes the meaning entirely (experiencing anxiety is not something one is reluctant to do — it''s involuntary).', 'MEDIUM', 'English', 'Cloze Test — Social Media and Youth (W10 B2)', 'ENG_CLOZE_TEST_W10_B2', '[{"option_text": "resistant", "is_correct": false}, {"option_text": "immune", "is_correct": false}, {"option_text": "likely", "is_correct": true}, {"option_text": "reluctant", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('637724a9-0598-51ab-81dc-5352260f6cb5', 'Blank (7): The ___ portrayals of perfect lives and bodies on social media often lead young users to make unfavourable comparisons.', NULL, 'B is correct. ''Idealised portrayals'' = unrealistically perfect representations. The passage describes how these portrayals cause unfavourable comparisons — implying they are false or exaggerated ideals, not genuine. ''Realistic'', ''accurate'', and ''objective'' all imply truth, which would weaken the argument that social media causes harmful comparisons.', 'MEDIUM', 'English', 'Cloze Test — Social Media and Youth (W10 B2)', 'ENG_CLOZE_TEST_W10_B2', '[{"option_text": "realistic", "is_correct": false}, {"option_text": "idealised", "is_correct": true}, {"option_text": "accurate", "is_correct": false}, {"option_text": "objective", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('668bef72-bb9b-530d-a8ac-f8f6b387466c', 'Blank (8): The idealised portrayals often lead young users to make unfavourable ___ between themselves and others.', NULL, 'B is correct. ''Make unfavourable comparisons between X and Y'' is the exact idiom describing the act of measuring oneself against others and finding oneself lacking. ''Friendships'' doesn''t fit grammatically (you don''t make unfavourable friendships between yourself and others); ''compliments'' is opposite in tone (favourable, not unfavourable).', 'HARD', 'English', 'Cloze Test — Social Media and Youth (W10 B2)', 'ENG_CLOZE_TEST_W10_B2', '[{"option_text": "friendships", "is_correct": false}, {"option_text": "comparisons", "is_correct": true}, {"option_text": "arrangements", "is_correct": false}, {"option_text": "compliments", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f7ab7a03-764a-58ed-951d-80ac371e6069', 'Blank (9): Despite these drawbacks, social media also ___ as a powerful tool for social activism.', NULL, 'B is correct. ''Serves as'' = functions as or acts as. ''Social media serves as a tool'' is a standard formal construction. ''Despite these drawbacks'' signals that the sentence will now say something positive about social media. ''Fails'', ''declines'', and ''refuses'' all introduce negativity, which contradicts the ''despite'' concession.', 'HARD', 'English', 'Cloze Test — Social Media and Youth (W10 B2)', 'ENG_CLOZE_TEST_W10_B2', '[{"option_text": "fails", "is_correct": false}, {"option_text": "serves", "is_correct": true}, {"option_text": "declines", "is_correct": false}, {"option_text": "refuses", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('95ee9da7-331e-555f-9501-ecd69c595241', 'Blank (10): Social media also serves as a powerful tool for social activism and ___ communication across geographical boundaries.', NULL, 'C is correct. ''Facilitating communication'' = enabling or making it easier. The sentence continues the positive aspect (social media as a tool for activism and communication). ''Obstructing'', ''hindering'', and ''preventing'' all mean blocking communication — the exact opposite of what a communication tool does.', 'HARD', 'English', 'Cloze Test — Social Media and Youth (W10 B2)', 'ENG_CLOZE_TEST_W10_B2', '[{"option_text": "obstructing", "is_correct": false}, {"option_text": "hindering", "is_correct": false}, {"option_text": "facilitating", "is_correct": true}, {"option_text": "preventing", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3c39845a-2a56-5a3a-9810-93c2838514e0', 'Read the passage and choose the best word for each blank.
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5b222f3b-b464-5f64-a062-85a6e774fd19', 'Passage: "...It is home to an (2)___ variety of species, many of which remain unknown to science..."
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('060125ff-99fb-5c09-9f7b-702e1d815bc7', 'Passage: "...many of which remain (3)___ to science..."
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('383dc5bf-2360-531e-a024-231b737c523b', 'Passage: "...However, this (4)___ habitat is under serious threat from rampant deforestation..."
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ebb595fd-7548-5c74-b690-734cb1b6b1f6', 'Passage: "...Every year, millions of hectares of forest are (5)___ to make way for agriculture and logging..."
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('916ff80c-ecdc-50c4-9860-064c3ac11b94', 'Passage: "...The (6)___ of the rainforest has severe implications for the global climate..."
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('38616b3d-d39a-59b4-be84-9949c999af61', 'Passage: "...Forests naturally (7)___ carbon dioxide from the atmosphere, and their removal releases this stored carbon..."
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f6f30b86-a238-5b3c-992d-e87d17d94449', 'Passage: "...their removal releases this stored carbon, (8)___ global warming..."
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f6a3930b-784f-5e65-9388-a533578fb696', 'Passage: "...International bodies have urged governments to (9)___ strict conservation policies..."
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1c83bc33-0aa8-5d63-bd72-027dd00c9115', 'Passage: "...and actively (10)___ reforestation across degraded land."
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('74e8a00b-ec86-52be-a7fa-30fa31f3b603', 'Passage: ''Artificial intelligence is reshaping the labour market in ways both dramatic and subtle. Unlike previous waves of automation — which primarily displaced manual and clerical workers — AI has the capacity to perform complex cognitive tasks: analysing legal documents, diagnosing medical conditions, generating creative content and writing computer code. This has led some economists to predict that no profession is truly safe from technological disruption. Others, however, argue that AI will primarily augment human capabilities rather than replace workers entirely, creating new categories of employment we cannot yet imagine.'' — Which statement BEST reflects the passage''s view on AI''s impact?', NULL, 'C is correct. The passage presents TWO views: some economists predict no profession is safe (replacement threat), while OTHERS argue AI augments human capability and creates new jobs. C accurately captures this division. Trap: A = overstates by saying ''all jobs'' (passage says no profession is ''truly safe'', not eliminated); B = directly contradicts the passage (AI performs cognitive tasks beyond clerical work); D = passage says AI differs FROM previous automation by targeting cognitive tasks (implies it is potentially more disruptive, not less).', 'MEDIUM', 'English', 'Reading Comprehension — Artificial Intelligence & Labour Market (W13 B1)', 'ENG_COMPREHENSION_VII_W13_B1', '[{"option_text": "AI will cause mass unemployment by eliminating all jobs.", "is_correct": false}, {"option_text": "AI affects only manual and clerical workers, not professionals.", "is_correct": false}, {"option_text": "Economists are divided on whether AI replaces or augments human workers.", "is_correct": true}, {"option_text": "AI is a less disruptive force than previous waves of automation.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c02a7cf5-f51e-5b3f-a192-a3a4e107d9fa', '[Same passage] The word ''AUGMENT'' as used in the passage most closely means:', NULL, 'C is correct. AUGMENT = to make greater by adding to; to enhance or supplement. ''AI will augment human capabilities'' = AI will ADD TO and ENHANCE what humans can do, not replace them. Root: Latin augere = to increase. Trap: ''replace'' = the passage contrasts augmenting with replacing; ''suppress'' = opposite of augment; ''copy'' = mimic (different concept — augmenting means improving, not imitating).', 'EASY', 'English', 'Reading Comprehension — Artificial Intelligence & Labour Market (W13 B1)', 'ENG_COMPREHENSION_VII_W13_B1', '[{"option_text": "replace completely", "is_correct": false}, {"option_text": "suppress or limit", "is_correct": false}, {"option_text": "enhance or add to", "is_correct": true}, {"option_text": "copy or imitate", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6b9dcab0-a3bd-5633-aa1d-000ec6bd207f', '[Same passage] According to the passage, how does AI-driven automation DIFFER from previous waves of automation?', NULL, 'B is correct. The passage explicitly states: ''Unlike previous waves of automation — which primarily displaced manual and clerical workers — AI has the capacity to perform complex cognitive tasks.'' B captures this contrast precisely. Trap: A = no comparison of speed is made; C = no geographic distinction is mentioned; D = the passage presents both views on job creation without comparing them to previous automation''s job creation.', 'EASY', 'English', 'Reading Comprehension — Artificial Intelligence & Labour Market (W13 B1)', 'ENG_COMPREHENSION_VII_W13_B1', '[{"option_text": "Previous automation was faster and more efficient.", "is_correct": false}, {"option_text": "Previous automation displaced manual workers; AI targets cognitive tasks too.", "is_correct": true}, {"option_text": "AI only affects developing countries, unlike earlier automation.", "is_correct": false}, {"option_text": "Previous automation created more new jobs than AI is expected to.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1daadd4e-da78-52fa-a109-c600342a9ee6', '[Same passage] The phrase ''categories of employment we cannot yet imagine'' suggests the author believes:', NULL, 'B is correct. ''Categories of employment we cannot yet imagine'' = types of jobs that do not currently exist and are so novel that present-day thinkers cannot predict them. This suggests AI may create fundamentally new work categories. Trap: A = ''cannot yet imagine'' means UNLIKE current jobs (opposite); C = the passage doesn''t say economic prediction is impossible in general — only that future AI-created jobs are unpredictable; D = the author is not making a policy recommendation (just presenting the optimists'' view).', 'MEDIUM', 'English', 'Reading Comprehension — Artificial Intelligence & Labour Market (W13 B1)', 'ENG_COMPREHENSION_VII_W13_B1', '[{"option_text": "Future jobs will be very similar to current ones.", "is_correct": false}, {"option_text": "AI will create jobs that are entirely new and unprecedented.", "is_correct": true}, {"option_text": "It is impossible for humans to predict economic trends.", "is_correct": false}, {"option_text": "AI development should be slowed to protect existing jobs.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9b1631e6-a199-53b9-b272-e0ef86eea096', '[Same passage] The tone of the passage can best be described as:', NULL, 'C is correct. The author presents both alarm (no profession truly safe) and optimism (AI creates new jobs) without personally endorsing either view. This balanced presentation is analytical and academic in tone. Trap: alarmist = one-sided fear (passage also presents the optimistic view); dismissive = the opposite (passage takes AI''s impact very seriously); enthusiastically pro-AI = passage acknowledges disruption concerns too.', 'MEDIUM', 'English', 'Reading Comprehension — Artificial Intelligence & Labour Market (W13 B1)', 'ENG_COMPREHENSION_VII_W13_B1', '[{"option_text": "Alarmist and pessimistic", "is_correct": false}, {"option_text": "Dismissive of AI''s economic impact", "is_correct": false}, {"option_text": "Balanced and analytical", "is_correct": true}, {"option_text": "Enthusiastically pro-AI", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1ca73823-5338-5f74-a4a7-83c0bbf3bca0', 'Passage 2: ''The Indian education system has long been criticised for its emphasis on rote memorisation over critical thinking. While this approach may produce students who perform well in standardised examinations, it often fails to develop the problem-solving and communication skills that employers now demand. Education reformers increasingly advocate a shift towards competency-based learning — measuring students not by their ability to recall facts but by their demonstrated capacity to apply knowledge creatively and independently.'' — What is the MAIN critique of rote memorisation raised in the passage?', NULL, 'B is correct. The passage says rote learning ''produces students who perform well in standardised examinations'' but ''fails to develop the problem-solving and communication skills that employers now demand.'' The main critique = exam success but workforce skill deficiency. Trap: A = the passage says rote learning DOES help in exams (opposite); C = no comparison to other countries is made; D = ''once effective but now obsolete'' overstates — the passage says it produces exam performers but lacks other skills.', 'EASY', 'English', 'Reading Comprehension — Artificial Intelligence & Labour Market (W13 B1)', 'ENG_COMPREHENSION_VII_W13_B1', '[{"option_text": "It prevents students from performing well in examinations.", "is_correct": false}, {"option_text": "It prioritises exam performance over skills valued in the workforce.", "is_correct": true}, {"option_text": "It is practised only in India and not in other countries.", "is_correct": false}, {"option_text": "It was once effective but is now entirely obsolete.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('980b9632-b88f-5f62-a483-7de875c2b904', '[Same passage 2] What does ''COMPETENCY-BASED LEARNING'' prioritise according to the passage?', NULL, 'B is correct. The passage defines competency-based learning as ''measuring students not by their ability to recall facts but by their demonstrated capacity to apply knowledge creatively and independently.'' B is a direct paraphrase. Trap: A = recalling facts is what ROTE learning emphasises (the system being replaced); C and D = broad syllabus coverage and national exams are also associated with the old system, not competency-based reform.', 'EASY', 'English', 'Reading Comprehension — Artificial Intelligence & Labour Market (W13 B1)', 'ENG_COMPREHENSION_VII_W13_B1', '[{"option_text": "Recalling factual information quickly under pressure", "is_correct": false}, {"option_text": "Demonstrated ability to apply knowledge creatively and independently", "is_correct": true}, {"option_text": "Covering a wide syllabus across many subjects", "is_correct": false}, {"option_text": "Competitive examination performance at national level", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('21b46bb6-cc8a-5e6a-8a2b-6786ec634eaf', '[Same passage 2] The word ''ADVOCATE'' as used in ''Education reformers increasingly advocate a shift'' most closely means:', NULL, 'B is correct. ADVOCATE (verb) = to publicly recommend or support a policy or cause. ''Education reformers increasingly advocate a shift'' = they are recommending/promoting a change. Note: advocate (noun) = a lawyer or supporter. Trap: ''oppose'' = the opposite; ''implement'' = to actually carry out (advocacy is recommending, not necessarily implementing); ''study'' = research (advocates act, they don''t just study).', 'MEDIUM', 'English', 'Reading Comprehension — Artificial Intelligence & Labour Market (W13 B1)', 'ENG_COMPREHENSION_VII_W13_B1', '[{"option_text": "oppose or resist", "is_correct": false}, {"option_text": "publicly recommend or support", "is_correct": true}, {"option_text": "study or analyse in depth", "is_correct": false}, {"option_text": "implement or carry out", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1a8ec228-61c8-53f0-bfe0-f6f6f22a179a', '[Same passage 2] The passage implies that employers value which of the following MOST?', NULL, 'C is correct. The passage states rote learning ''fails to develop the problem-solving and communication skills that EMPLOYERS NOW DEMAND.'' Employers therefore value problem-solving and communication. Trap: exam scores and memorisation = what rote learning produces (which employers are said NOT to demand); breadth of subjects = traditional curriculum (not highlighted as what employers value).', 'MEDIUM', 'English', 'Reading Comprehension — Artificial Intelligence & Labour Market (W13 B1)', 'ENG_COMPREHENSION_VII_W13_B1', '[{"option_text": "Scores achieved in national-level examinations", "is_correct": false}, {"option_text": "The ability to memorise and reproduce information accurately", "is_correct": false}, {"option_text": "Problem-solving and communication abilities", "is_correct": true}, {"option_text": "The breadth of subjects studied in school", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('50944dcb-9a13-5010-be3d-32caa90d943c', '[Same passage 2] Which sentence would BEST continue the passage after its final sentence?', NULL, 'B is correct. The passage ends with advocacy for competency-based learning. The LOGICAL next step in such an argument is to address what IMPLEMENTING this reform would require — teacher retraining and redesigned assessments. This advances the argument naturally. Trap: A = contradicts the entire thrust of the passage (which criticises rote learning); C = extreme policy recommendation beyond the scope of what the passage advocates; D = directly contradicts the critique of rote learning made throughout the passage.', 'HARD', 'English', 'Reading Comprehension — Artificial Intelligence & Labour Market (W13 B1)', 'ENG_COMPREHENSION_VII_W13_B1', '[{"option_text": "However, rote memorisation remains the only effective teaching method.", "is_correct": false}, {"option_text": "Such reforms would require retraining teachers and redesigning assessments across the system.", "is_correct": true}, {"option_text": "India''s examination boards should stop conducting national tests altogether.", "is_correct": false}, {"option_text": "Students who memorise well inevitably become successful professionals.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
