INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d932fdec-979e-5727-851c-2263996f8314', 'Change to indirect speech: She said, ''I am happy.''', NULL, 'B is correct. Past reporting verb (''said'') → tense shifts: ''am'' → ''was''; pronoun ''I'' → ''she''. ''Tell'' requires an object, so ''told she'' is wrong.', 'EASY', 'English', 'Direct and Indirect Speech (W9)', 'ENG_DIRECT_INDIRECT_W9', '[{"option_text": "She said that she is happy.", "is_correct": false}, {"option_text": "She said that she was happy.", "is_correct": true}, {"option_text": "She said that I am happy.", "is_correct": false}, {"option_text": "She told she was happy.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bfa15858-de06-5c03-9cd0-e12801e08000', 'Change to indirect speech: He said, ''I will go tomorrow.''', NULL, 'A is correct. Tense shifts: ''will'' → ''would''; ''tomorrow'' → ''the next day''. ''Tell'' requires an object; ''told that'' is incorrect without an object before ''that''.', 'EASY', 'English', 'Direct and Indirect Speech (W9)', 'ENG_DIRECT_INDIRECT_W9', '[{"option_text": "He said that he would go the next day.", "is_correct": true}, {"option_text": "He said that he will go tomorrow.", "is_correct": false}, {"option_text": "He said he went the next day.", "is_correct": false}, {"option_text": "He told that he would go the next day.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8ac7f10c-8d44-5998-87eb-aa0f8646c6b0', 'Change to direct speech: She said that she was tired.', NULL, 'A is correct. Reverse the shift: ''was'' → ''am''; ''she'' → ''I''. Option D uses ''told'' without an object, which is incorrect.', 'EASY', 'English', 'Direct and Indirect Speech (W9)', 'ENG_DIRECT_INDIRECT_W9', '[{"option_text": "She said, ''I am tired.''", "is_correct": true}, {"option_text": "She said, ''I was tired.''", "is_correct": false}, {"option_text": "She said, ''She is tired.''", "is_correct": false}, {"option_text": "She told, ''I am tired.''", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('21c4ccde-f5ba-55d5-ba6f-a3c1f9b30af0', 'Change to indirect speech: The teacher said to the students, ''Be quiet.''', NULL, 'A is correct. Imperatives in indirect speech use ''told/asked/ordered + object + to + infinitive''.', 'MEDIUM', 'English', 'Direct and Indirect Speech (W9)', 'ENG_DIRECT_INDIRECT_W9', '[{"option_text": "The teacher told the students to be quiet.", "is_correct": true}, {"option_text": "The teacher said the students to be quiet.", "is_correct": false}, {"option_text": "The teacher asked the students that they be quiet.", "is_correct": false}, {"option_text": "The teacher told the students that be quiet.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('163b0cdf-c29d-56fd-b11f-ae73a93ddffd', 'Change to indirect speech: He said, ''Did you finish the work?''', NULL, 'A is correct. Yes/no questions → ''asked + if/whether + subject + verb''. Tense shifts: ''did finish'' → ''had finished''. ''That + if'' together is wrong.', 'MEDIUM', 'English', 'Direct and Indirect Speech (W9)', 'ENG_DIRECT_INDIRECT_W9', '[{"option_text": "He asked if I had finished the work.", "is_correct": true}, {"option_text": "He asked whether you finished the work.", "is_correct": false}, {"option_text": "He asked that if I had finished the work.", "is_correct": false}, {"option_text": "He said had I finished the work.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('47bd4cc7-71a5-5ab0-bdc1-f638979c320d', 'Change to indirect speech: She said, ''How beautiful the sunset is!''', NULL, 'A is correct. Exclamatory sentences → ''exclaimed that + assertive sentence (with appropriate tense shift and an adverb like very/quite)''. Option C lacks the declarative restructuring required.', 'MEDIUM', 'English', 'Direct and Indirect Speech (W9)', 'ENG_DIRECT_INDIRECT_W9', '[{"option_text": "She exclaimed that the sunset was very beautiful.", "is_correct": true}, {"option_text": "She said that the sunset is beautiful.", "is_correct": false}, {"option_text": "She exclaimed how beautiful the sunset was.", "is_correct": false}, {"option_text": "She told the sunset was beautiful.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4995ca1e-bf19-5b81-95ec-4f16ac71d430', 'Change to indirect speech: He said to me, ''Please help me.''', NULL, 'A is correct. ''Please'' in direct speech signals a polite request → ''requested + object + to + infinitive''.', 'MEDIUM', 'English', 'Direct and Indirect Speech (W9)', 'ENG_DIRECT_INDIRECT_W9', '[{"option_text": "He requested me to help him.", "is_correct": true}, {"option_text": "He said to me to help him.", "is_correct": false}, {"option_text": "He told me that please help him.", "is_correct": false}, {"option_text": "He asked me please to help him.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('16b06b5f-9652-54a2-8271-c673ae46e1a6', 'Change to indirect speech: She said, ''I have been working since morning.''', NULL, 'A is correct. Present perfect continuous → past perfect continuous: ''had been working''. ''Since morning'' stays as ''since morning'' (it marks a point, not a duration). ''From morning'' is incorrect for this context.', 'HARD', 'English', 'Direct and Indirect Speech (W9)', 'ENG_DIRECT_INDIRECT_W9', '[{"option_text": "She said that she had been working since morning.", "is_correct": true}, {"option_text": "She said she has been working since morning.", "is_correct": false}, {"option_text": "She said she was working since morning.", "is_correct": false}, {"option_text": "She told she had been working from morning.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('17572f8a-7e14-5684-b405-03cc490bcb5b', 'Change to direct speech: He asked whether she had come alone.', NULL, 'C is correct. Reverse tense shift: ''had come'' → ''Did...come'' (past simple question). The reporting verb ''asked'' signals a question; ''asked,'' with quotation marks is correct.', 'HARD', 'English', 'Direct and Indirect Speech (W9)', 'ENG_DIRECT_INDIRECT_W9', '[{"option_text": "He said, ''Had she come alone?''", "is_correct": false}, {"option_text": "He said, ''Did she come alone?''", "is_correct": false}, {"option_text": "He asked, ''Did she come alone?''", "is_correct": true}, {"option_text": "He asked, ''Has she come alone?''", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5616399b-df21-57d8-a8cd-513a60c50364', 'Change to indirect speech (optative): Mother said, ''May God bless you, my child!''', NULL, 'C is correct. Sentences with ''May'' expressing a blessing/prayer → indirect speech uses ''prayed that...might''. ''Wished'' is used for personal desires, not divine blessings.', 'HARD', 'English', 'Direct and Indirect Speech (W9)', 'ENG_DIRECT_INDIRECT_W9', '[{"option_text": "Mother wished that God might bless her child.", "is_correct": false}, {"option_text": "Mother said God should bless her child.", "is_correct": false}, {"option_text": "Mother prayed that God might bless her child.", "is_correct": true}, {"option_text": "Mother exclaimed that God bless her child.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a10f6f1e-5ebc-5284-9ec9-12a958c3cfd1', 'Fill in both blanks: ''The committee was ___ over the new proposal; the debate was quite ___.'' (A) unanimous / heated  (B) divided / heated  (C) united / calm  (D) divided / brief', NULL, 'B is correct. ''Divided over a proposal'' = split into opposing factions on the issue. ''Debate was heated'' = intense, passionate debate. Logically: a divided committee → a heated debate (they disagree vigorously). Trap: ''unanimous / heated'' = contradiction (unanimous = everyone agrees, so there''s nothing to debate heatedly); ''united / calm'' = possible but ''united'' is less idiomatic than ''unanimous'' for committees, and ''calm'' implies little disagreement; ''divided / brief'' = if divided, a brief debate implies quick resolution, which contradicts the division.', 'MEDIUM', 'English', 'Double-Blank Fill in the Blanks (W12 B1)', 'ENG_DOUBLE_BLANKS_W12_B1', '[{"option_text": "unanimous / heated", "is_correct": false}, {"option_text": "divided / heated", "is_correct": true}, {"option_text": "united / calm", "is_correct": false}, {"option_text": "divided / brief", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('acb74641-f3e5-5ce3-8b94-4a7393c55e8b', 'Fill in both blanks: ''The scientist was ___ in her approach, testing each ___ carefully before drawing any conclusions.'' (A) cautious / hypothesis  (B) reckless / result  (C) cautious / opinion  (D) hasty / hypothesis', NULL, 'A is correct. ''Cautious in approach'' matches ''testing carefully before drawing conclusions'' (both mean careful/methodical). Scientists test ''hypotheses'' (proposed explanations awaiting testing) — not ''opinions'' (which are personal views, not tested). Trap: ''cautious / opinion'' — ''opinion'' is wrong in scientific context; scientists test hypotheses; ''reckless / result'' — reckless and ''testing carefully'' contradict each other; ''hasty / hypothesis'' — ''hasty'' contradicts ''carefully before drawing conclusions''.', 'MEDIUM', 'English', 'Double-Blank Fill in the Blanks (W12 B1)', 'ENG_DOUBLE_BLANKS_W12_B1', '[{"option_text": "cautious / hypothesis", "is_correct": true}, {"option_text": "reckless / result", "is_correct": false}, {"option_text": "cautious / opinion", "is_correct": false}, {"option_text": "hasty / hypothesis", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d8a64a54-0213-5a30-b63d-9a16e81d743a', 'Fill in both blanks: ''A good leader should be ___ to criticism and willing to ___ their decisions when necessary.'' (A) averse / enforce  (B) open / revise  (C) immune / justify  (D) hostile / defend', NULL, 'B is correct. ''Open to criticism'' = receptive and willing to hear criticism. ''Willing to revise decisions'' = making changes when needed. Both reflect the quality of adaptability in leadership. Trap: ''averse to criticism'' = the opposite of what a good leader should be (averse = opposed to); ''immune to criticism'' = unaffected by it (also not a positive quality in a leader); ''hostile / defend'' = negative traits, contradicting ''good leader''.', 'EASY', 'English', 'Double-Blank Fill in the Blanks (W12 B1)', 'ENG_DOUBLE_BLANKS_W12_B1', '[{"option_text": "averse / enforce", "is_correct": false}, {"option_text": "open / revise", "is_correct": true}, {"option_text": "immune / justify", "is_correct": false}, {"option_text": "hostile / defend", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5c1d36ec-4198-5a67-8a1f-9a8b85d7b15a', 'Fill in both blanks: ''The merger was ___ by both boards and is expected to ___ shareholders'' profits significantly.'' (A) rejected / boost  (B) approved / boost  (C) approved / reduce  (D) delayed / improve', NULL, 'B is correct. ''Approved by both boards'' = both corporate boards agreed to the merger. ''Expected to boost profits'' = the expected positive outcome that justifies the approval. Logic: boards approve mergers expecting profit gains. Trap: ''rejected / boost'' = contradiction (rejected merger can''t be expected to boost profits); ''approved / reduce'' = contradiction (boards wouldn''t approve a merger expected to reduce profits); ''delayed / improve'' = ''delayed'' doesn''t match ''expected to... significantly'' in the same positive forward-looking tone.', 'EASY', 'English', 'Double-Blank Fill in the Blanks (W12 B1)', 'ENG_DOUBLE_BLANKS_W12_B1', '[{"option_text": "rejected / boost", "is_correct": false}, {"option_text": "approved / boost", "is_correct": true}, {"option_text": "approved / reduce", "is_correct": false}, {"option_text": "delayed / improve", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('13f4d4a7-3bf4-525f-b11c-cfd775737de7', 'Fill in both blanks: ''The athlete showed ___ perseverance despite ___ setbacks throughout the season.'' (A) remarkable / numerous  (B) little / few  (C) remarkable / few  (D) minimal / countless', NULL, 'A is correct. ''Remarkable perseverance'' (exceptional determination) is praised specifically because of ''numerous setbacks'' (many obstacles). The contrast between many setbacks and continued perseverance makes the perseverance remarkable. Trap: ''remarkable / few'' — if there were only a few setbacks, ''remarkable'' perseverance is harder to justify; ''little / few'' — ''little perseverance despite few setbacks'' is grammatically valid but doesn''t convey a praiseworthy statement; ''minimal / countless'' — ''minimal perseverance despite countless setbacks'' describes a failure, not praise.', 'MEDIUM', 'English', 'Double-Blank Fill in the Blanks (W12 B1)', 'ENG_DOUBLE_BLANKS_W12_B1', '[{"option_text": "remarkable / numerous", "is_correct": true}, {"option_text": "little / few", "is_correct": false}, {"option_text": "remarkable / few", "is_correct": false}, {"option_text": "minimal / countless", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('125fdc8b-21fe-5554-8ebb-9631a550c7da', 'Fill in both blanks: ''The government''s new policy is aimed at ___ corruption and ___ transparency in public institutions.'' (A) curbing / promoting  (B) promoting / discouraging  (C) curbing / reducing  (D) boosting / improving', NULL, 'A is correct. Anti-corruption policy aims to ''curb corruption'' (reduce/suppress it) and ''promote transparency'' (increase openness). The two goals are complementary and opposite in direction (reduce something bad, increase something good). Trap: ''curbing / reducing'' = redundant — both mean reducing, but the blank following ''transparency'' needs a positive verb (increase, promote); ''promoting / discouraging'' = promoting corruption? Contradicts the policy goal; ''boosting / improving'' = ''boosting corruption'' is wrong.', 'EASY', 'English', 'Double-Blank Fill in the Blanks (W12 B1)', 'ENG_DOUBLE_BLANKS_W12_B1', '[{"option_text": "curbing / promoting", "is_correct": true}, {"option_text": "promoting / discouraging", "is_correct": false}, {"option_text": "curbing / reducing", "is_correct": false}, {"option_text": "boosting / improving", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('140ff7a0-0200-5cb4-bbc9-c56c8f3dd6ce', 'Fill in both blanks: ''His speech was so ___ that it left the entire audience ___ in their seats.'' (A) boring / riveted  (B) captivating / riveted  (C) captivating / squirming  (D) tedious / inspired', NULL, 'B is correct. ''Captivating speech'' = enthralling, holding attention completely. ''Riveted in their seats'' = unable to move, completely absorbed. A captivating speech → audience riveted (engrossed). Trap: ''boring / riveted'' = contradiction (boring speech leaves audiences checking watches, not riveted); ''captivating / squirming'' = contradiction (squirming implies discomfort/boredom, not captivation); ''tedious / inspired'' = contradiction (tedious = boring, but inspired = positively moved — opposite reactions).', 'MEDIUM', 'English', 'Double-Blank Fill in the Blanks (W12 B1)', 'ENG_DOUBLE_BLANKS_W12_B1', '[{"option_text": "boring / riveted", "is_correct": false}, {"option_text": "captivating / riveted", "is_correct": true}, {"option_text": "captivating / squirming", "is_correct": false}, {"option_text": "tedious / inspired", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('76a56137-a9bc-580b-b135-86c2bfb04bb7', 'Fill in both blanks: ''Excessive screen time has been ___ to sleep quality and has led to a ___ in children''s concentration spans.'' (A) harmful / decline  (B) beneficial / rise  (C) detrimental / decrease  (D) harmful / increase', NULL, 'C is correct. ''Detrimental to sleep quality'' = harmful to/for sleep (note: ''detrimental TO'', not ''detrimental OF''). ''Led to a DECREASE in concentration spans'' = shorter attention spans. Both describe negative outcomes of excessive screen time. Trap: ''harmful / decline'' — ''harmful'' works but the second blank needs a noun: ''a decline in concentration'' is also correct; however, ''harmful'' should be followed by ''TO'' which is present in option A (''harmful to sleep quality'') — actually A uses the wrong preposition-check: ''harmful to'' is also correct. So both A and C could work grammatically. Key distinction: ''decline'' in A vs ''decrease'' in C for attention spans. ''Decline'' and ''decrease'' are both valid. But ''detrimental'' is the more precise and formal term for academic/government-style SSC passages. C is the better fit as the more formal pairing.', 'HARD', 'English', 'Double-Blank Fill in the Blanks (W12 B1)', 'ENG_DOUBLE_BLANKS_W12_B1', '[{"option_text": "harmful / decline", "is_correct": false}, {"option_text": "beneficial / rise", "is_correct": false}, {"option_text": "detrimental / decrease", "is_correct": true}, {"option_text": "harmful / increase", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bca52fd0-2552-5912-98f3-248f78cf453c', 'Fill in both blanks: ''The judge''s verdict was considered ___ by the defence team, who immediately filed an ___.'' (A) fair / appeal  (B) unjust / appeal  (C) lenient / acquittal  (D) unjust / inquiry', NULL, 'B is correct. The defence team found the verdict ''unjust'' (unfair to their client) and filed an ''appeal'' (legal application to a higher court to review the decision). The logic: unjust verdict → immediate appeal. Trap: ''fair / appeal'' — if the defence team considered the verdict fair, they would NOT immediately appeal; ''lenient / acquittal'' — an acquittal is not ''filed'', it''s delivered by the court; ''unjust / inquiry'' — an ''inquiry'' is an investigation, not what is filed after a verdict; ''appeal'' is the correct legal term.', 'MEDIUM', 'English', 'Double-Blank Fill in the Blanks (W12 B1)', 'ENG_DOUBLE_BLANKS_W12_B1', '[{"option_text": "fair / appeal", "is_correct": false}, {"option_text": "unjust / appeal", "is_correct": true}, {"option_text": "lenient / acquittal", "is_correct": false}, {"option_text": "unjust / inquiry", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ad047f8e-472c-5c4f-8bc9-7303fd1fbf2c', 'Fill in both blanks: ''She had a ___ understanding of quantum physics, having spent two ___ in the field.'' (A) basic / weeks  (B) profound / decades  (C) shallow / decades  (D) profound / hours', NULL, 'B is correct. ''Profound understanding'' (deep, thorough knowledge) is justified by ''two decades in the field'' (20 years of experience). Long experience → deep expertise. Trap: ''shallow / decades'' — two decades of experience would produce deep, not shallow knowledge; ''profound / hours'' — you can''t develop a profound understanding of quantum physics in just two hours; ''basic / weeks'' — basic is possible in weeks but the pairing is inconsistent with the sentence structure implying earned expertise.', 'EASY', 'English', 'Double-Blank Fill in the Blanks (W12 B1)', 'ENG_DOUBLE_BLANKS_W12_B1', '[{"option_text": "basic / weeks", "is_correct": false}, {"option_text": "profound / decades", "is_correct": true}, {"option_text": "shallow / decades", "is_correct": false}, {"option_text": "profound / hours", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
