INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('018d0198-4c0e-5636-8342-73c48879f368', 'Find the part with the grammatical error:
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7c32b9c8-eca9-5e1b-843d-2806ad2c15bf', 'Neither the manager nor the employees ______ aware of the new regulation.', NULL, 'B is correct. With ''Neither...nor'', the verb agrees with the subject closest to it (the nearer subject rule). ''Employees'' (plural) is closer to the verb. Therefore use ''were''. Rule: Neither X nor Y → verb agrees with Y. If Y is plural → plural verb. Trap: ''was'' = wrong (would apply if the singular subject ''manager'' were closer); ''is/are being'' = present tense is wrong for a past situation implied by ''aware of the new regulation'' requiring a simple state verb.', 'HARD', 'English', 'Fill in the Blanks — Advanced Grammar and Vocabulary (W11 B2)', 'ENG_FILL_BLANKS_ADV_W11_B2', '[{"option_text": "was", "is_correct": false}, {"option_text": "were", "is_correct": true}, {"option_text": "is", "is_correct": false}, {"option_text": "are being", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('047cacbf-be34-5b02-9ac0-7a7cc1639c86', 'He has been working in this company ______ five years.', NULL, 'C is correct. FOR + duration (a period of time): ''for five years'' = a span of time. SINCE + point in time: ''since 2019'' = a specific time marker. ''Five years'' is a duration, so FOR is correct. Trap: Since = correct with a specific starting point like ''since 2019'', not a duration like ''five years''; During = used with named periods like ''during the meeting''.', 'EASY', 'English', 'Fill in the Blanks — Advanced Grammar and Vocabulary (W11 B2)', 'ENG_FILL_BLANKS_ADV_W11_B2', '[{"option_text": "since", "is_correct": false}, {"option_text": "from", "is_correct": false}, {"option_text": "for", "is_correct": true}, {"option_text": "during", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d710b221-179b-5b39-9eaf-22c5a3b21051', 'The committee ______ reached a unanimous decision after three hours of deliberation.', NULL, 'B is correct. ''The committee'' is a collective noun. In standard British/SSC English, collective nouns are treated as singular when acting as a single unit: ''The committee has decided'' (acting together). The Present Perfect singular ''has reached'' is correct. Trap: ''have reached'' = used when committee members are acting individually (not as a unit); ''were'' = wrong tense and number; ''had been'' = Past Perfect (no context for a prior past action).', 'MEDIUM', 'English', 'Fill in the Blanks — Advanced Grammar and Vocabulary (W11 B2)', 'ENG_FILL_BLANKS_ADV_W11_B2', '[{"option_text": "have", "is_correct": false}, {"option_text": "has", "is_correct": true}, {"option_text": "had been", "is_correct": false}, {"option_text": "were", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('961f89b4-1340-52a1-87e6-917532268f19', 'She speaks English ______ her mother tongue.', NULL, 'B is correct. LIKE (preposition) = comparing nouns/pronouns. ''She speaks English like her mother tongue'' = comparing her English to (the way she speaks) her mother tongue. LIKE is followed by a noun phrase. AS (conjunction) = comparing clauses: ''She speaks English as she would speak her mother tongue'' (followed by subject+verb). LIKE + noun ✓ here. Trap: ''as if'' = used with a clause to suggest hypothetical comparison (''She speaks as if she were a native''); ''similar to'' = grammatically awkward here.', 'HARD', 'English', 'Fill in the Blanks — Advanced Grammar and Vocabulary (W11 B2)', 'ENG_FILL_BLANKS_ADV_W11_B2', '[{"option_text": "as if", "is_correct": false}, {"option_text": "like", "is_correct": true}, {"option_text": "as", "is_correct": false}, {"option_text": "similar to", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('59858cef-909f-5fbf-b400-78ee92ef5c91', 'The results of the experiment ______ published next month.', NULL, 'A is correct. ''Next month'' indicates a future action. The passive future tense ''will be published'' is correct for ''results that will be published''. WILL BE + past participle = Future Simple Passive. Trap: ''are being published'' = Present Continuous Passive (suggests it''s happening right now, not next month); ''has been published'' = Present Perfect Passive (already completed — contradicts ''next month''); ''were published'' = Simple Past Passive (already done).', 'EASY', 'English', 'Fill in the Blanks — Advanced Grammar and Vocabulary (W11 B2)', 'ENG_FILL_BLANKS_ADV_W11_B2', '[{"option_text": "will be", "is_correct": true}, {"option_text": "are being", "is_correct": false}, {"option_text": "has been", "is_correct": false}, {"option_text": "were", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2396ac4b-4c30-5524-927c-9fc37115c42b', 'The teacher, along with her students, ______ attending the science fair.', NULL, 'C is correct. When the subject is connected to additional nouns by phrases like ''along with'', ''together with'', ''as well as'', ''in addition to'' — the verb agrees with the MAIN subject (before the phrase), not the added nouns. Main subject = ''The teacher'' (singular) → singular verb ''is''. Trap: ''are'' = treats ''teacher + students'' as compound subject (wrong — ''along with'' is not ''and''); ''were'' = past tense, context seems present.', 'HARD', 'English', 'Fill in the Blanks — Advanced Grammar and Vocabulary (W11 B2)', 'ENG_FILL_BLANKS_ADV_W11_B2', '[{"option_text": "are", "is_correct": false}, {"option_text": "were", "is_correct": false}, {"option_text": "is", "is_correct": true}, {"option_text": "have been", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('998253db-02d6-53ee-af5b-04b16945cd67', 'He is one of those players who ______ always given their best.', NULL, 'B is correct. ''One of those + plural noun + who/that'' takes a plural verb. The relative clause ''who ______ always given their best'' refers to ''those players'' (plural). The antecedent of ''who'' is ''players'' (plural), so the verb must be plural: ''have''. Trap: ''has'' = common error where ''he'' is mistaken for the antecedent (but ''who'' refers to ''those players'', not ''he''); ''had'' = past perfect (no justification).', 'HARD', 'English', 'Fill in the Blanks — Advanced Grammar and Vocabulary (W11 B2)', 'ENG_FILL_BLANKS_ADV_W11_B2', '[{"option_text": "has", "is_correct": false}, {"option_text": "have", "is_correct": true}, {"option_text": "had", "is_correct": false}, {"option_text": "having", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('66d05220-380c-5c41-9dd7-61f426fd720f', 'The injured were immediately ______ to the nearest hospital.', NULL, 'B is correct. ''Rushed to hospital'' = the standard collocation when emergency transportation is implied (urgent, fast movement). ''Rushed to the nearest hospital'' is the precise idiomatic expression in medical emergency contexts. BROUGHT = taken (doesn''t carry urgency); CARRIED AWAY = idiom meaning ''to lose self-control'' or ''to remove something'' (wrong connotation); DRIVEN OFF = to chase away (wrong meaning entirely).', 'MEDIUM', 'English', 'Fill in the Blanks — Advanced Grammar and Vocabulary (W11 B2)', 'ENG_FILL_BLANKS_ADV_W11_B2', '[{"option_text": "brought", "is_correct": false}, {"option_text": "rushed", "is_correct": true}, {"option_text": "carried away", "is_correct": false}, {"option_text": "driven off", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a48fd320-27ff-5d62-8936-36a796f5e06f', '______ having studied hard, she could not clear the exam.', NULL, 'C is correct. DESPITE is a preposition followed by a noun/gerund phrase: ''Despite having studied hard''. It does NOT take a clause. Contrast: ALTHOUGH/EVEN THOUGH are conjunctions followed by a subject+verb clause: ''Although she studied hard...'' Here the blank is followed by ''having studied hard'' (a gerund phrase, no subject) → DESPITE is correct. Trap: ''Although/Even though'' = must be followed by a subject+verb; ''However'' = conjunctive adverb, doesn''t connect to a participle phrase.', 'MEDIUM', 'English', 'Fill in the Blanks — Advanced Grammar and Vocabulary (W11 B2)', 'ENG_FILL_BLANKS_ADV_W11_B2', '[{"option_text": "Even though", "is_correct": false}, {"option_text": "Although", "is_correct": false}, {"option_text": "Despite", "is_correct": true}, {"option_text": "However", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('07df2a4f-d549-573a-9d8c-f98e898eaac7', 'No sooner ______ the bell than the students rushed out.', NULL, 'C is correct. ''No sooner...than'' triggers inversion: ''No sooner + auxiliary + subject + verb''. Pattern: ''No sooner did + subject + V1 + than...''. ''No sooner did the bell ring than...'' ✓. Note: ''ring'' is correct (base form after auxiliary ''did''); ''rang'' would be used WITHOUT auxiliary: ''The bell had no sooner rung than...'' using ''No sooner had + subject + V3 + than''. Trap: ''did rang'' = wrong — can''t use both ''did'' and past tense ''rang''; ''had the bell rang'' = wrong past participle (''rang'' is simple past; past participle of ring = ''rung'').', 'HARD', 'English', 'Fill in the Blanks — Advanced Grammar and Vocabulary (W11 B2)', 'ENG_FILL_BLANKS_ADV_W11_B2', '[{"option_text": "did rang", "is_correct": false}, {"option_text": "rang", "is_correct": false}, {"option_text": "did the bell ring", "is_correct": true}, {"option_text": "had the bell rang", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5b5d0b89-74e8-59bc-af4b-cc650fcc0fc9', 'The minister''s speech was full of ___ promises that he had no ___ of keeping.', NULL, 'A is correct. ''Hollow promises'' = promises that are empty and insincere. ''No intention of keeping'' = not planning to fulfil. The pair (hollow + intention) is a natural, idiomatic collocations: ''hollow promises he had no intention of keeping'' — a complete, coherent negative assessment. Trap: ''sincere/plan'' — sincere promises + no plan = contradictory (sincere means genuine, which conflicts with ''no plan''); ''hollow/interest'' — idiomatically ''no interest in keeping'' sounds weak compared to ''no intention''; ''vague/possibility'' — vague promises + no possibility = different meaning (possibility relates to ability, not intent).', 'MEDIUM', 'English', 'Double Fill in the Blanks — Grammar and Vocabulary Combined (W13 B1)', 'ENG_FILL_BLANKS_DOUBLE_II_W13_B1', '[{"option_text": "hollow / intention", "is_correct": true}, {"option_text": "sincere / plan", "is_correct": false}, {"option_text": "vague / possibility", "is_correct": false}, {"option_text": "hollow / interest", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c57da492-2610-5b39-a48f-fbfcf0547f89', 'The scientist''s discovery was so ___ that it ___ the entire field of molecular biology.', NULL, 'B is correct. Both blanks must carry the same positive magnitude: a revolutionary discovery naturally transforms a field. ''Revolutionary + transformed'' = logically consistent and idiomatic. Trap: ''controversial/undermined'' = logical but negative (controversy undermines, doesn''t transform positively — the sentence context suggests a major advance); ''revolutionary/confused'' = revolutionary things clarify, not confuse; ''trivial/overlooked'' = a trivial thing gets overlooked, not because it transformed anything.', 'MEDIUM', 'English', 'Double Fill in the Blanks — Grammar and Vocabulary Combined (W13 B1)', 'ENG_FILL_BLANKS_DOUBLE_II_W13_B1', '[{"option_text": "trivial / overlooked", "is_correct": false}, {"option_text": "revolutionary / transformed", "is_correct": true}, {"option_text": "controversial / undermined", "is_correct": false}, {"option_text": "revolutionary / confused", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('293b2e3a-bf6b-5b23-b2a5-4160cebb05e4', 'She had such a ___ of talent that even her harshest critics could not ___ her performance.', NULL, 'C is correct. ''A wealth of talent'' = an abundance of talent (standard collocation). ''Could not fault her performance'' = could not find fault with it = could not criticise it. Both blanks reinforce the idea of exceptional, beyond-criticism talent. Trap: ''wealth/praise'' = ''could not praise'' means critics wouldn''t praise her (negative), but the sentence implies they COULDN''T criticise her (positive outcome despite harsh critics); ''surplus/criticise'' — ''surplus of talent'' is less idiomatic than ''wealth of talent''; ''lack/applaud'' = logically reversed (lack of talent + critics couldn''t applaud = consistent but misses the ''cannot criticise'' idiom).', 'MEDIUM', 'English', 'Double Fill in the Blanks — Grammar and Vocabulary Combined (W13 B1)', 'ENG_FILL_BLANKS_DOUBLE_II_W13_B1', '[{"option_text": "lack / applaud", "is_correct": false}, {"option_text": "surplus / criticise", "is_correct": false}, {"option_text": "wealth / fault", "is_correct": true}, {"option_text": "wealth / praise", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5ee6f7f4-6750-5018-a5d2-6f9016352b2a', 'The new policy was ___ to many small businesses, which could not ___ with the strict new requirements.', NULL, 'B is correct. ''Detrimental to small businesses'' = harmful to them. ''Could not comply with requirements'' = unable to meet/fulfil the rules. Both blanks together: harsh policy + inability to meet requirements = logical hardship narrative. Collocations: ''detrimental to'' ✓; ''comply with requirements'' ✓ (standard legal/regulatory language). Trap: ''helpful/struggle'' = ''struggle with requirements'' is grammatically acceptable but ''helpful'' contradicts ''strict new requirements'' causing hardship; ''detrimental/agree'' = ''agree with requirements'' is awkward (you comply, not agree, with regulations).', 'MEDIUM', 'English', 'Double Fill in the Blanks — Grammar and Vocabulary Combined (W13 B1)', 'ENG_FILL_BLANKS_DOUBLE_II_W13_B1', '[{"option_text": "beneficial / disagree", "is_correct": false}, {"option_text": "detrimental / comply", "is_correct": true}, {"option_text": "helpful / struggle", "is_correct": false}, {"option_text": "detrimental / agree", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fe40ba98-6d33-56a0-85dc-11d6bbed777f', 'The judge''s ruling was ___ unexpected that it left even the ___ legal experts in disbelief.', NULL, 'A is correct. Grammar: ''so + adjective + that'' is the correct intensifier structure. ''So unexpected that...'' ✓. The second blank: ''even the EXPERIENCED legal experts'' = the ruling shocked even those who should be unsurprisable. ''Even the experienced'' carries the implication of highest standard of surprise. Trap: ''such'' would require ''such an unexpected ruling that...'' (noun phrase, not adjective); ''novice'' = novices being surprised is expected (not impressive — the shock is more meaningful when it surprises EXPERIENCED experts); ''too unexpected that'' = ''too...that'' is not standard (too...to = correct form; too...that = non-standard).', 'MEDIUM', 'English', 'Double Fill in the Blanks — Grammar and Vocabulary Combined (W13 B1)', 'ENG_FILL_BLANKS_DOUBLE_II_W13_B1', '[{"option_text": "so / experienced", "is_correct": true}, {"option_text": "such / junior", "is_correct": false}, {"option_text": "so / novice", "is_correct": false}, {"option_text": "too / experienced", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('75b9c558-b0e2-5671-9c6b-56f9ab53f18b', 'His ___ to the board was well-received, but the committee remained ___ about the financial projections.', NULL, 'C is correct. ''Presentation to the board'' = a formal address (standard business collocation). ''Remained sceptical about'' = continued to doubt (financial projections are routinely treated with scepticism). ''Well-received'' (positive overall reception) CONTRASTED with ''remained sceptical about financials'' (specific doubt) = a nuanced, realistic outcome. Trap: ''convinced'' = ''the committee remained convinced'' = no longer doubting (contradicts the contrast implied by ''but''); ''proposal/optimistic'' = ''remained optimistic'' doesn''t express residual doubt that ''but'' implies; ''objection/enthusiastic'' = a well-received objection + enthusiastic committee = internally contradictory.', 'MEDIUM', 'English', 'Double Fill in the Blanks — Grammar and Vocabulary Combined (W13 B1)', 'ENG_FILL_BLANKS_DOUBLE_II_W13_B1', '[{"option_text": "proposal / optimistic", "is_correct": false}, {"option_text": "objection / enthusiastic", "is_correct": false}, {"option_text": "presentation / sceptical", "is_correct": true}, {"option_text": "presentation / convinced", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5fd6a609-1ab5-554f-8d4b-fa3988ac338b', 'Rather than ___ the issue further, the negotiators agreed to ___ their differences for the sake of progress.', NULL, 'B is correct. ''Rather than prolonging the issue'' = instead of extending the argument. ''Agreed to set aside their differences'' = agreed to temporarily ignore disagreements = idiomatically perfect (standard diplomatic phrase). The contrast ''rather than prolonging...agreed to set aside'' = logical diplomatic resolution. Trap: ''resolving/acknowledge'' = ''Rather than resolving...agreed to acknowledge'' = contradictory (resolving is good, you don''t prefer to NOT resolve); ''prolonging/heighten'' = ''agreed to heighten differences'' = opposite of peace; ''ignoring/exaggerate'' = ''rather than ignoring...agreed to exaggerate'' = both suggest worsening, not resolution.', 'HARD', 'English', 'Double Fill in the Blanks — Grammar and Vocabulary Combined (W13 B1)', 'ENG_FILL_BLANKS_DOUBLE_II_W13_B1', '[{"option_text": "resolving / acknowledge", "is_correct": false}, {"option_text": "prolonging / set aside", "is_correct": true}, {"option_text": "ignoring / exaggerate", "is_correct": false}, {"option_text": "prolonging / heighten", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('37e001cd-7bae-5066-a79f-49ab26a4eda8', 'The ___ of the CEO''s statement was that the company would ___ its international operations within the year.', NULL, 'B is correct. ''The gist of the statement'' = the main point or essential meaning. ''Would expand its international operations'' = a clear strategic direction announcement. A CEO would most likely announce expansion (positive news). ''Gist'' = the general meaning conveyed by the statement. Trap: ''implication/halt'' = halting operations is negative news (unusual for a CEO''s statement to imply halting without more context); ''irony/reduce'' = ''the irony was that they would reduce'' = irony requires a contradiction, which isn''t set up here; ''gist/deny'' = ''gist was that they would deny operations'' = awkward and contextually weak.', 'HARD', 'English', 'Double Fill in the Blanks — Grammar and Vocabulary Combined (W13 B1)', 'ENG_FILL_BLANKS_DOUBLE_II_W13_B1', '[{"option_text": "implication / halt", "is_correct": false}, {"option_text": "gist / expand", "is_correct": true}, {"option_text": "irony / reduce", "is_correct": false}, {"option_text": "gist / deny", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c8f86ff3-f5a4-51e9-884e-f2aaed1604a3', 'The village ___ dramatically after the new highway was built, as more investors were ___ by the improved connectivity.', NULL, 'C is correct. Highway → better connectivity → village prospered. Investors were attracted (drawn in) by improved connectivity. Both blanks carry the same positive direction: prosperity caused by investor attraction. ''Prospered + attracted'' = economically consistent causal chain. Trap: ''deterred'' = investors were put off (contradicts the highway''s positive connectivity); ''stagnated/attracted'' = investors came but the village stagnated? Internally inconsistent — if investors are attracted, the village should grow; ''declined/repelled'' = both negative — logically consistent but contradicts ''new highway'' as a positive development.', 'HARD', 'English', 'Double Fill in the Blanks — Grammar and Vocabulary Combined (W13 B1)', 'ENG_FILL_BLANKS_DOUBLE_II_W13_B1', '[{"option_text": "declined / repelled", "is_correct": false}, {"option_text": "stagnated / attracted", "is_correct": false}, {"option_text": "prospered / attracted", "is_correct": true}, {"option_text": "prospered / deterred", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4ede3467-134b-57e8-9609-cd0b8824af77', 'A ___ leader inspires through vision and example, whereas a ___ leader relies solely on formal authority and hierarchy.', NULL, 'A is correct. ''Charismatic leader'' = one who leads through personal magnetism, vision and personal example (management/leadership theory). ''Transactional leader'' = one who relies on formal authority, incentives, rules and hierarchy (transactional leadership theory). The contrast (vision/example vs. formal authority/hierarchy) maps precisely onto the charismatic vs. transactional distinction in leadership studies. Trap: ''dictatorial/democratic'' = a valid contrast but ''formal authority and hierarchy'' better describes transactional leadership than dictatorship; ''charismatic/visionary'' = both are similar positive styles (no contrast); ''passive/aggressive'' = personality terms, not leadership styles.', 'HARD', 'English', 'Double Fill in the Blanks — Grammar and Vocabulary Combined (W13 B1)', 'ENG_FILL_BLANKS_DOUBLE_II_W13_B1', '[{"option_text": "charismatic / transactional", "is_correct": true}, {"option_text": "dictatorial / democratic", "is_correct": false}, {"option_text": "charismatic / visionary", "is_correct": false}, {"option_text": "passive / aggressive", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d02ec19b-9509-5005-aeb2-edaa2d580878', 'The minister''s _______ speech moved everyone in the audience to tears.', NULL, 'A is correct. ELOQUENT = fluent and persuasive in speaking; expressing ideas powerfully and movingly. A speech that ''moves everyone to tears'' must be emotionally powerful and well-delivered = eloquent. VERBOSE = using too many words (wordy); does not imply emotional impact. INCOHERENT = unclear, disjointed speech (cannot move people to tears). MUNDANE = ordinary, everyday; opposite of moving.', 'MEDIUM', 'English', 'Fill in the Blanks — Single Blank (W11 B2)', 'ENG_FILL_BLANKS_SINGLE_W11_B2', '[{"option_text": "eloquent", "is_correct": true}, {"option_text": "verbose", "is_correct": false}, {"option_text": "incoherent", "is_correct": false}, {"option_text": "mundane", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('81bcced0-90d2-5582-a23e-b3452a3cd2c1', 'He apologised _______ for his rude behaviour at the dinner table.', NULL, 'A is correct. PROFUSELY = in large amounts; generously; with much expression. ''Apologised profusely'' = apologised repeatedly and at length (a genuine, heartfelt apology). RELUCTANTLY = unwillingly (contradicts a genuine apology — he wouldn''t apologise if reluctant usually). INDIGNANTLY = with indignation (feeling one has been treated unjustly — wouldn''t apologise while feeling righteous). CURTLY = briefly and abruptly (not a full apology). Trap: Reluctantly = possible but contradicts the context of genuine apology.', 'EASY', 'English', 'Fill in the Blanks — Single Blank (W11 B2)', 'ENG_FILL_BLANKS_SINGLE_W11_B2', '[{"option_text": "profusely", "is_correct": true}, {"option_text": "reluctantly", "is_correct": false}, {"option_text": "indignantly", "is_correct": false}, {"option_text": "curtly", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5e63427c-3ebf-5fcc-96de-44c170b32b21', 'The scientist made a _______ discovery that changed our understanding of the solar system.', NULL, 'C is correct. GROUNDBREAKING = innovative, pioneering; changing the way something is done or understood. A discovery that ''changed our understanding'' = groundbreaking. TRIVIAL = of little importance (opposite of a discovery that changes understanding). SPURIOUS = false, not genuine (a discovery must be valid). TENTATIVE = uncertain, not fully confirmed (contradicts ''changed understanding'').', 'EASY', 'English', 'Fill in the Blanks — Single Blank (W11 B2)', 'ENG_FILL_BLANKS_SINGLE_W11_B2', '[{"option_text": "trivial", "is_correct": false}, {"option_text": "spurious", "is_correct": false}, {"option_text": "groundbreaking", "is_correct": true}, {"option_text": "tentative", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c94a350f-7800-55c5-9ed4-830dbd21907b', 'The new employee was _______ about asking too many questions, fearing he would appear ignorant.', NULL, 'B is correct. HESITANT = slow to speak or act due to nervousness or indecision. The fear of appearing ignorant logically leads to hesitation. EAGER = enthusiastically willing (contradicts ''fearing he would appear ignorant''). CONFIDENT = sure of oneself (contradicts the fear). INDIFFERENT = not caring (if indifferent, he wouldn''t fear the consequence).', 'EASY', 'English', 'Fill in the Blanks — Single Blank (W11 B2)', 'ENG_FILL_BLANKS_SINGLE_W11_B2', '[{"option_text": "eager", "is_correct": false}, {"option_text": "hesitant", "is_correct": true}, {"option_text": "confident", "is_correct": false}, {"option_text": "indifferent", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7d89f436-1cd5-5a5b-8ffd-536bdf4fd42c', 'The committee''s decision was _______ by the managing director, who had the final authority.', NULL, 'A is correct. RATIFIED = formally approved or confirmed, especially by a higher authority. The MD ''had final authority'' and the decision was _______ by him = ratified (approved). REFUTED = disproved (the MD disproved the committee''s decision? — unlikely context for ''final authority''). REITERATED = repeated/restated (not about approval). RESCINDED = cancelled or revoked (opposite of approving). Trap: ''Rescinded'' could work in a different context where MD overrules, but ''final authority'' more naturally implies confirmation/approval.', 'MEDIUM', 'English', 'Fill in the Blanks — Single Blank (W11 B2)', 'ENG_FILL_BLANKS_SINGLE_W11_B2', '[{"option_text": "ratified", "is_correct": true}, {"option_text": "refuted", "is_correct": false}, {"option_text": "reiterated", "is_correct": false}, {"option_text": "rescinded", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('77e69a2b-6e7b-5306-baea-8a2adbd30c2e', 'The old man walked with _______, his joints aching with every step.', NULL, 'D is correct. Aching joints → the man walked with DIFFICULTY. AGILITY = ability to move quickly and easily (opposite of aching joints). ALACRITY = brisk eagerness (also implies ease of movement — contradicts aching joints). LANGUOR = physical weakness or tiredness (while this could fit, ''difficulty'' is more precise and direct for aching joints). DIFFICULTY = the most contextually precise word: aching joints directly cause difficulty in walking.', 'MEDIUM', 'English', 'Fill in the Blanks — Single Blank (W11 B2)', 'ENG_FILL_BLANKS_SINGLE_W11_B2', '[{"option_text": "agility", "is_correct": false}, {"option_text": "alacrity", "is_correct": false}, {"option_text": "languor", "is_correct": false}, {"option_text": "difficulty", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4c014c43-3935-58c2-b901-9de81a0f290c', 'The government launched a _______ campaign to educate citizens about the importance of hygiene.', NULL, 'B is correct. A government launching a campaign ''to educate citizens'' implies wide reach = NATIONWIDE (covering the entire nation). CLANDESTINE = secret, hidden (a government wouldn''t hide a hygiene campaign). COVERT = secret operations (same problem as clandestine). FUTILE = pointless, ineffective (a government wouldn''t launch a ''futile'' campaign — the context implies intention to succeed). Trap: ''Massive'' would also work but isn''t in the options; ''nationwide'' is the best fit.', 'EASY', 'English', 'Fill in the Blanks — Single Blank (W11 B2)', 'ENG_FILL_BLANKS_SINGLE_W11_B2', '[{"option_text": "clandestine", "is_correct": false}, {"option_text": "nationwide", "is_correct": true}, {"option_text": "covert", "is_correct": false}, {"option_text": "futile", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e90f120a-6d23-596b-9a21-ba45b797022f', 'After years of rivalry, the two neighbouring countries finally signed a _______ agreement.', NULL, 'D is correct. BILATERAL = involving two parties or countries. An agreement between two neighbouring countries = bilateral agreement. CONTENTIOUS = causing disagreement (an agreement cannot be contentious — it resolves disagreement). HOSTILE = unfriendly (an agreement marked hostility would not be a resolution). BELLIGERENT = aggressive, warlike (opposite of signing a peace/cooperative agreement). Trap: All three wrong options describe the years of RIVALRY, not the agreement that ends it.', 'MEDIUM', 'English', 'Fill in the Blanks — Single Blank (W11 B2)', 'ENG_FILL_BLANKS_SINGLE_W11_B2', '[{"option_text": "contentious", "is_correct": false}, {"option_text": "hostile", "is_correct": false}, {"option_text": "belligerent", "is_correct": false}, {"option_text": "bilateral", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('af438ab2-da35-5856-b287-0a6c67c17d20', 'The judge warned that any attempt to _______ with the witness would result in immediate arrest.', NULL, 'C is correct. TAMPER = to interfere with something in order to cause damage or unfairly influence it. ''Tamper with a witness'' = to intimidate, bribe, or otherwise improperly influence a witness (a serious legal offence). COORDINATE = to organise (neutral; not applicable). CONSULT = to seek advice from (legal, neutral). COLLABORATE = to work together (also legal). Only ''tamper'' carries the legal threat implied by ''immediate arrest''. Collocation: ''tamper with a witness'' is a fixed legal phrase.', 'MEDIUM', 'English', 'Fill in the Blanks — Single Blank (W11 B2)', 'ENG_FILL_BLANKS_SINGLE_W11_B2', '[{"option_text": "coordinate", "is_correct": false}, {"option_text": "consult", "is_correct": false}, {"option_text": "tamper", "is_correct": true}, {"option_text": "collaborate", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6e9ea17a-a52b-5241-8e48-d1ddea4bc64b', 'She was known for her _______ nature; she never wasted anything and always found a way to reuse.', NULL, 'B is correct. THRIFTY = using money and other resources carefully and not wastefully. ''Never wasted anything and always reused'' = thrifty. WASTEFUL = opposite (spending/using resources carelessly). EXTRAVAGANT = spending more than necessary (opposite). IMPULSIVE = acting without thinking (unrelated to resource use). Synonym note: thrifty ≈ frugal ≈ economical (positive connotations); miserly (negative — excess frugality).', 'EASY', 'English', 'Fill in the Blanks — Single Blank (W11 B2)', 'ENG_FILL_BLANKS_SINGLE_W11_B2', '[{"option_text": "wasteful", "is_correct": false}, {"option_text": "thrifty", "is_correct": true}, {"option_text": "extravagant", "is_correct": false}, {"option_text": "impulsive", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('602eab8f-9362-5e9b-a9bc-708713c09916', 'The sun rises _____ the east.', NULL, 'A is correct. We say ''in the east/west/north/south'' when referring to a direction as a region.', 'EASY', 'English', 'Fill in the Blanks (W9)', 'ENG_FILL_BLANKS_W9', '[{"option_text": "in", "is_correct": true}, {"option_text": "on", "is_correct": false}, {"option_text": "at", "is_correct": false}, {"option_text": "from", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0b0cd3a1-30cc-5572-a4b9-47a09a761fa5', 'He was so tired that he _____ asleep immediately.', NULL, 'A is correct. ''Fell asleep'' (simple past of ''fall asleep'') fits the past context. ''fallen'' needs an auxiliary (''had fallen''); ''fall'' is present tense.', 'EASY', 'English', 'Fill in the Blanks (W9)', 'ENG_FILL_BLANKS_W9', '[{"option_text": "fell", "is_correct": true}, {"option_text": "fallen", "is_correct": false}, {"option_text": "fall", "is_correct": false}, {"option_text": "feels", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('29547a38-9c3a-5b4f-9512-a86a879f0b7a', 'She is neither intelligent _____ hardworking.', NULL, 'B is correct. ''Neither...nor'' is the standard correlative conjunction pair. ''Neither...or'' is incorrect.', 'EASY', 'English', 'Fill in the Blanks (W9)', 'ENG_FILL_BLANKS_W9', '[{"option_text": "or", "is_correct": false}, {"option_text": "nor", "is_correct": true}, {"option_text": "and", "is_correct": false}, {"option_text": "but", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f68e2af0-7f5c-5df9-bcae-8adde897f3e9', 'The manager was _____ with the employee''s performance.', NULL, 'B is correct. ''Was satisfied'' (past passive adjective) fits. ''Satisfying'' describes what causes satisfaction; ''satisfactory'' is an adjective meaning adequate but wouldn''t follow ''was'' here in this context.', 'MEDIUM', 'English', 'Fill in the Blanks (W9)', 'ENG_FILL_BLANKS_W9', '[{"option_text": "satisfy", "is_correct": false}, {"option_text": "satisfied", "is_correct": true}, {"option_text": "satisfying", "is_correct": false}, {"option_text": "satisfactory", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ca525274-c31c-5387-81ee-a8f814e79b61', 'He could not _____ the temptation to eat the cake.', NULL, 'A is correct. ''Resist'' (bare infinitive) follows ''could not''. ''Resist to'' is incorrect — resist takes a direct object without ''to''.', 'MEDIUM', 'English', 'Fill in the Blanks (W9)', 'ENG_FILL_BLANKS_W9', '[{"option_text": "resist", "is_correct": true}, {"option_text": "resist to", "is_correct": false}, {"option_text": "resisting", "is_correct": false}, {"option_text": "resists", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('59a636cb-c1e2-5065-887e-5667d075ab78', 'The government has _____ new policies to boost the economy.', NULL, 'B is correct. ''Has implemented'' (present perfect) is correct. ''Has implement'' and ''has implements'' are grammatically wrong; ''has implementing'' needs a participle verb ''been''.', 'MEDIUM', 'English', 'Fill in the Blanks (W9)', 'ENG_FILL_BLANKS_W9', '[{"option_text": "implement", "is_correct": false}, {"option_text": "implemented", "is_correct": true}, {"option_text": "implementing", "is_correct": false}, {"option_text": "implements", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e718c38b-64be-5260-812a-89050fabaa3c', 'The team worked together to _____ the project on time.', NULL, 'A is correct. ''To complete'' (infinitive) follows ''to''. ''Completing'' needs a continuous marker; ''completed'' needs an auxiliary; ''completion'' is a noun.', 'MEDIUM', 'English', 'Fill in the Blanks (W9)', 'ENG_FILL_BLANKS_W9', '[{"option_text": "complete", "is_correct": true}, {"option_text": "completing", "is_correct": false}, {"option_text": "completed", "is_correct": false}, {"option_text": "completion", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('16dbcdb0-4a8c-5d8c-adc8-4b5c871e404d', 'The ruins of the ancient temple were a precious _____ of a once great civilisation.', NULL, 'D is correct. A ''relic'' is a surviving object or remains from an earlier time. ''Remnant'' refers to a leftover portion; ''memory'' is mental; ''sign'' is too vague.', 'MEDIUM', 'English', 'Fill in the Blanks (W9)', 'ENG_FILL_BLANKS_W9', '[{"option_text": "remnant", "is_correct": false}, {"option_text": "memory", "is_correct": false}, {"option_text": "sign", "is_correct": false}, {"option_text": "relic", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('86e3509f-1570-510f-97a4-d1baedbf5f12', 'Not only did he refuse to help, _____ he also criticised the entire effort.', NULL, 'B is correct. The correlative conjunction ''not only...but (also)'' is the standard structure. ''And'' could work loosely but ''but'' is the prescribed pair for ''not only''.', 'HARD', 'English', 'Fill in the Blanks (W9)', 'ENG_FILL_BLANKS_W9', '[{"option_text": "and", "is_correct": false}, {"option_text": "but", "is_correct": true}, {"option_text": "or", "is_correct": false}, {"option_text": "yet", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b129e35b-be7a-576b-be9f-30429567670b', 'Despite the heavy rain, the event proceeded _____ planned.', NULL, 'B is correct. ''As planned'' (conjunction + adjective/participle) is correct. ''Like'' is a preposition and cannot introduce a clause; ''how'' and ''that'' don''t fit grammatically here.', 'HARD', 'English', 'Fill in the Blanks (W9)', 'ENG_FILL_BLANKS_W9', '[{"option_text": "like", "is_correct": false}, {"option_text": "as", "is_correct": true}, {"option_text": "how", "is_correct": false}, {"option_text": "that", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9418e1fc-e57a-5768-aca7-240d24d33cba', 'The scientist made a ________ discovery that changed the course of medicine forever.', NULL, 'B is correct. ''Landmark'' means a significant, memorable achievement that marks an important stage. The sentence says the discovery ''changed the course of medicine'', implying historic importance. Trap: ''trivial'', ''casual'', and ''minor'' are all antonymous to the context — a discovery that changes medicine cannot be described with any of these words.', 'EASY', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10)', 'ENG_FILL_IN_BLANKS_W10', '[{"option_text": "trivial", "is_correct": false}, {"option_text": "landmark", "is_correct": true}, {"option_text": "casual", "is_correct": false}, {"option_text": "minor", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2a0566ac-339e-56b0-956f-3d95199c3f5a', 'Despite his ________ efforts, he managed to complete the ambitious project before the deadline.', NULL, 'C is correct. ''Despite his ... efforts'' followed by ''managed to complete'' implies the efforts were sustained and determined — ''persistent'' (continuing firmly despite difficulty) fits. Trap: ''lazy'' and ''careless'' contradict both ''efforts'' and the successful outcome; ''random'' does not describe a quality of effort relevant to task completion.', 'EASY', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10)', 'ENG_FILL_IN_BLANKS_W10', '[{"option_text": "lazy", "is_correct": false}, {"option_text": "careless", "is_correct": false}, {"option_text": "persistent", "is_correct": true}, {"option_text": "random", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0da51b59-a813-570e-a484-fefd30d9b88a', 'The ambassador''s speech was so ________ that it moved the entire audience to tears.', NULL, 'C is correct. ''Eloquent'' means fluent, persuasive, and powerfully expressive in speech. Moving an audience to tears indicates great emotional impact through words — eloquence. Trap: ''incoherent'' (unclear) and ''monotonous'' (boring) are opposite to something that moves people; ''repulsive'' (disgusting) would cause a very different reaction.', 'MEDIUM', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10)', 'ENG_FILL_IN_BLANKS_W10', '[{"option_text": "incoherent", "is_correct": false}, {"option_text": "monotonous", "is_correct": false}, {"option_text": "eloquent", "is_correct": true}, {"option_text": "repulsive", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('330fb0de-998a-5214-a35c-35e959b219b3', 'The government ________ a new policy to curb the rapidly rising inflation in the country.', NULL, 'D is correct. ''Implemented a new policy'' means the government put the policy into action — the correct collocation for introducing and enacting a policy. Trap: ''ignored'', ''avoided'', and ''neglected'' all suggest inaction, which contradicts the introduction of a new policy. Note: one cannot ''ignore a new policy'' — the government would be the policy maker, not the ignorer.', 'MEDIUM', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10)', 'ENG_FILL_IN_BLANKS_W10', '[{"option_text": "ignored", "is_correct": false}, {"option_text": "avoided", "is_correct": false}, {"option_text": "neglected", "is_correct": false}, {"option_text": "implemented", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9e1aac22-4397-5a41-8115-184569dbaad8', 'His argument was well-structured but lacked concrete ________ to support his claims.', NULL, 'C is correct. ''Concrete evidence'' is the standard expression for factual support behind an argument. The argument ''lacked'' something to ''support his claims'' — only ''evidence'' directly supports claims in formal reasoning. Trap: ''hypothesis'' is a proposed explanation (itself an unsupported claim); ''opinion'' is subjective and would weaken, not support, claims; ''suggestion'' is too informal for an argument''s supporting material.', 'MEDIUM', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10)', 'ENG_FILL_IN_BLANKS_W10', '[{"option_text": "hypothesis", "is_correct": false}, {"option_text": "opinion", "is_correct": false}, {"option_text": "evidence", "is_correct": true}, {"option_text": "suggestion", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ab6717f3-e17e-5c10-891e-4fb8f070b7f5', 'The athlete''s ________ performance at the Olympics earned her widespread acclaim.', NULL, 'B is correct. ''Stellar'' means outstanding or exceptionally brilliant — consistent with earning ''widespread acclaim'' at the Olympics. Trap: ''mediocre'' (only average), ''average'', and ''substandard'' (below average) would NOT earn widespread acclaim. This tests the student''s vocabulary: stellar literally means ''of or like a star'', hence ''star-quality.''', 'MEDIUM', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10)', 'ENG_FILL_IN_BLANKS_W10', '[{"option_text": "mediocre", "is_correct": false}, {"option_text": "stellar", "is_correct": true}, {"option_text": "average", "is_correct": false}, {"option_text": "substandard", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('eb6a8e2f-6cc4-55de-9aae-caeaf443d954', 'The committee was ________ to reach a consensus because its members held ________ views on the proposed reform.', NULL, 'A is correct. ''Unable to reach a consensus'' + ''divergent views'' creates perfect logical cohesion: divergent (moving in different directions) views explain why consensus was impossible. Trap: ''eager/similar'' contradicts the scenario (similar views would produce easy consensus); ''forced/unanimous'' implies agreement was achieved; ''unwilling/complementary'' is illogical — complementary views reinforce each other.', 'HARD', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10)', 'ENG_FILL_IN_BLANKS_W10', '[{"option_text": "unable / divergent", "is_correct": true}, {"option_text": "eager / similar", "is_correct": false}, {"option_text": "forced / unanimous", "is_correct": false}, {"option_text": "unwilling / complementary", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0c5b2b68-3b58-5151-b134-2c80e42d6c7c', 'Although the plan seemed ________ on paper, its actual implementation proved far more ________ than anyone had anticipated.', NULL, 'B is correct. The contrast is between appearance and reality: ''seemed ________ on paper'' (positive) vs. ''proved far more ________ '' (challenging). ''Feasible'' (achievable, workable) fits the positive initial assessment; ''complex'' (difficult, many-layered) fits the unexpectedly hard reality. Trap: ''practical/simple'' — if it seemed practical/simple, complexity would be a reasonable contrast, but ''practical on paper'' is weaker than ''feasible''; ''complicated/rewarding'' reverses the contrast direction.', 'HARD', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10)', 'ENG_FILL_IN_BLANKS_W10', '[{"option_text": "practical / simple", "is_correct": false}, {"option_text": "feasible / complex", "is_correct": true}, {"option_text": "abstract / easy", "is_correct": false}, {"option_text": "complicated / rewarding", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e92da087-cfbb-5d5f-a010-e639d0ba2cb0', 'The ________ of ancient manuscripts has helped historians construct a more ________ understanding of early civilizations.', NULL, 'C is correct. ''Preservation of manuscripts'' (keeping them safe through time) combined with ''comprehensive understanding'' (thorough, wide-ranging) is the most logically and lexically coherent pair. Preservation allows historians to study primary sources; primary source access broadens their understanding. Trap: ''destruction'' directly contradicts helping historians; ''translation/narrow'' is contradictory (translation broadens, not narrows); ''discovery/incomplete'' — ''discovery'' could work, but ''incomplete understanding'' is negatively framed, inconsistent with ''helped historians construct.''', 'HARD', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10)', 'ENG_FILL_IN_BLANKS_W10', '[{"option_text": "destruction / vague", "is_correct": false}, {"option_text": "translation / narrow", "is_correct": false}, {"option_text": "preservation / comprehensive", "is_correct": true}, {"option_text": "discovery / incomplete", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a21f44e5-3723-579f-9f1a-8a4615550f2b', 'The CEO''s unilateral decision to ________ the merger without consulting the board was widely regarded as an ________ of authority.', NULL, 'A is correct. ''Approve a merger unilaterally'' (without board consultation) constitutes an ''abuse of authority'' — using power improperly or beyond one''s sanctioned role. The word ''unilateral'' signals wrongful solo action. Trap: ''reject/exercise'' — one can exercise authority legitimately, but ''widely regarded as'' implies criticism, ruling out neutral ''exercise''; ''announce/extension'' — announcing a merger is not inherently an abuse; ''postpone/delegation'' has no logical link to ''widely criticized''.', 'HARD', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10)', 'ENG_FILL_IN_BLANKS_W10', '[{"option_text": "approve / abuse", "is_correct": true}, {"option_text": "reject / exercise", "is_correct": false}, {"option_text": "announce / extension", "is_correct": false}, {"option_text": "postpone / delegation", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d886d4e0-30d9-52a5-a6e2-84ebeb8d1252', 'The judge was known for his ___ and refused to accept any favours from either party during the trial.', NULL, 'A is correct. IMPARTIALITY = treating all parties equally without favouring one side. The context — a judge who ''refuses to accept favours'' — defines neutrality/fairness = impartiality. Trap: Partiality = the opposite (bias toward one side); Impudence = disrespectful boldness (unrelated); Indifference = lack of interest (a judge can be indifferent to favours but the word ''impartiality'' is more precise for a judicial context).', 'EASY', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10 B2)', 'ENG_FILL_IN_BLANKS_W10_B2', '[{"option_text": "impartiality", "is_correct": true}, {"option_text": "partiality", "is_correct": false}, {"option_text": "impudence", "is_correct": false}, {"option_text": "indifference", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a57fe044-a4b2-5d47-992a-84f964fe4b98', 'The new policy was ___ last month but will only come into ___ from the first of next year.', NULL, 'A is correct. ''Enacted'' = formally made into law (policies and legislation are enacted). ''Come into effect'' = become operational (standard legal phrase). Trap: ''Effected'' = caused/brought about (unusual usage, typically ''effected a change''); ''affect'' = to influence (a verb, cannot follow ''into''); ''affected'' = influenced (wrong form here). ''Into effect'' is a fixed idiom — never ''into affect''.', 'EASY', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10 B2)', 'ENG_FILL_IN_BLANKS_W10_B2', '[{"option_text": "enacted / effect", "is_correct": true}, {"option_text": "effected / affect", "is_correct": false}, {"option_text": "enacted / affect", "is_correct": false}, {"option_text": "affected / effect", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2d097445-8e83-5141-a4c2-05451d4564b9', 'Despite repeated warnings, the students continued to ___ in the library, disturbing others.', NULL, 'C is correct. ''Chatter'' = talk informally and incessantly in a way that disturbs others. The context (warnings, disturbing others, library) makes ''chatter'' the precise fit. Trap: ''Deliberate'' = consider carefully (unrelated to making noise); ''Congregate'' = gather together (describes location/grouping, not noise-making behaviour). The key contextual clue is ''disturbing others''.', 'EASY', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10 B2)', 'ENG_FILL_IN_BLANKS_W10_B2', '[{"option_text": "deliberate", "is_correct": false}, {"option_text": "congregate", "is_correct": false}, {"option_text": "chatter", "is_correct": true}, {"option_text": "deliberate", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b7f86ec9-b5a1-5d1e-8959-f5277e9c1173', 'The scientist''s hypothesis, though ___ at first, was later validated by three independent experiments.', NULL, 'D is correct. CONTROVERSIAL = giving rise to public disagreement; causing argument. The sentence structure ''though ___ at first, later validated'' signals the blank = something initially doubted or disputed. ''Controversial'' fits — the hypothesis was disputed before it was validated. Trap: Contentious (C) is close in meaning but ''controversial'' is more neutral and standard in scientific contexts; Proven = opposite of what is needed (it was eventually proven, not initially); Celebrated = positive (contradicts ''though'').', 'MEDIUM', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10 B2)', 'ENG_FILL_IN_BLANKS_W10_B2', '[{"option_text": "proven", "is_correct": false}, {"option_text": "celebrated", "is_correct": false}, {"option_text": "contentious", "is_correct": false}, {"option_text": "controversial", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f1bad144-f24d-5a9b-b5f0-00479850124d', 'After months of negotiations, both countries agreed to ___ their differences and sign a peace treaty.', NULL, 'C is correct. ''Set aside their differences'' = put disagreements behind them; agree to ignore prior disputes for a common goal. The context (negotiations, peace treaty) demands a phrase meaning to move past disagreements. Trap: Exacerbate and Aggravate both mean to make worse (opposite of signing a peace treaty); Magnify = make larger (also opposite of resolving differences).', 'MEDIUM', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10 B2)', 'ENG_FILL_IN_BLANKS_W10_B2', '[{"option_text": "exacerbate", "is_correct": false}, {"option_text": "aggravate", "is_correct": false}, {"option_text": "set aside", "is_correct": true}, {"option_text": "magnify", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('28bb8759-1398-5255-b710-f54837174a35', 'The film received ___ reviews — some critics found it profound while others dismissed it as pretentious.', NULL, 'B is correct. ''Mixed reviews'' = divided critical reception — some positive, some negative. The sentence explicitly shows the split: ''some found it profound'' vs ''others dismissed it''. Trap: Unanimous = all in agreement (contradicts the ''some vs others'' split); Glowing = very positive (contradicts ''others dismissed it''); Scathing = harshly critical (contradicts ''some found it profound'').', 'MEDIUM', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10 B2)', 'ENG_FILL_IN_BLANKS_W10_B2', '[{"option_text": "unanimous", "is_correct": false}, {"option_text": "mixed", "is_correct": true}, {"option_text": "glowing", "is_correct": false}, {"option_text": "scathing", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1faac39b-0341-5058-a97f-223d5b842d24', 'The minister''s remarks were so ___ that even his supporters found them difficult to defend.', NULL, 'A is correct. INDEFENSIBLE = not justifiable by argument; impossible to defend. The sentence shows even allies found the remarks hard to defend — the word in the blank must explain WHY: the remarks were indefensible. Trap: Commendable = praiseworthy (opposite); Innocuous = harmless (wouldn''t be ''difficult to defend''); Laudatory = expressing praise (opposite of what the context suggests).', 'MEDIUM', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10 B2)', 'ENG_FILL_IN_BLANKS_W10_B2', '[{"option_text": "indefensible", "is_correct": true}, {"option_text": "commendable", "is_correct": false}, {"option_text": "innocuous", "is_correct": false}, {"option_text": "laudatory", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a1c672e8-721c-5ebf-88fd-023017a223a2', 'The CEO''s decision to invest in renewable energy was both ___ and ___, benefiting the company financially while reducing its carbon footprint.', NULL, 'B is correct. The decision ''benefited the company financially'' = financially wise = PRUDENT. ''Reducing carbon footprint'' = environmentally responsible = COMMENDABLE. Both words in option B align with the dual benefit described. Trap: Hasty/Laudable — hasty implies rushed (negative connotation, contradicts the balanced positive outcome); Reckless/Praiseworthy — reckless = careless (contradicts ''benefiting financially'').', 'HARD', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10 B2)', 'ENG_FILL_IN_BLANKS_W10_B2', '[{"option_text": "impractical / unnecessary", "is_correct": false}, {"option_text": "prudent / commendable", "is_correct": true}, {"option_text": "hasty / laudable", "is_correct": false}, {"option_text": "reckless / praiseworthy", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2c82f7e1-caad-5fad-ad05-3b14d7e1a246', 'The new employee''s ___ attitude — always questioning authority and refusing to follow established procedures — made her difficult to manage.', NULL, 'C is correct. RECALCITRANT = having an obstinately uncooperative attitude toward authority or discipline. The context — ''questioning authority'', ''refusing to follow procedures'', ''difficult to manage'' — perfectly defines recalcitrant. Trap: Subservient, Acquiescent, Compliant are all synonyms of each other and opposites of recalcitrant — they all mean obedient or yielding. This word appears frequently in SSC Tier 2 reading comprehension and fill-in-the-blanks.', 'HARD', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10 B2)', 'ENG_FILL_IN_BLANKS_W10_B2', '[{"option_text": "subservient", "is_correct": false}, {"option_text": "acquiescent", "is_correct": false}, {"option_text": "recalcitrant", "is_correct": true}, {"option_text": "compliant", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d1eeef4a-6ec1-50f5-8de6-d85af717355f', 'The research team was ___ in their approach — they left no stone unturned and checked every variable multiple times before publishing their conclusions.', NULL, 'D is correct. METICULOUS = showing great attention to detail; very careful and precise. ''No stone unturned'' and ''checking every variable multiple times'' describe extreme thoroughness = meticulous. Trap: Perfunctory = carried out with minimal effort (opposite); Cursory = hasty and therefore insufficient (opposite); Methodical = following a logical order — close, but ''methodical'' implies systematic process, not necessarily extreme care. ''Meticulous'' captures the thoroughness better.', 'HARD', 'English', 'Fill in the Blanks — Vocabulary and Grammar in Context (W10 B2)', 'ENG_FILL_IN_BLANKS_W10_B2', '[{"option_text": "perfunctory", "is_correct": false}, {"option_text": "cursory", "is_correct": false}, {"option_text": "methodical", "is_correct": false}, {"option_text": "meticulous", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a0aed101-3dde-5170-aef2-7e87651c9296', 'Fill in the blank with the correct article: ''___ Himalayas are the highest mountain range in the world.''', NULL, 'C is correct. THE is used with: (1) unique geographical features — mountain ranges (the Himalayas, the Alps), rivers (the Ganga), deserts (the Sahara), oceans; (2) superlatives (''the highest''); (3) specific, known items. ''The Himalayas'' uses ''the'' because it''s a specific, unique mountain range. Trap: ''A'' = used for non-specific singular countable nouns (wrong — Himalayas is plural and specific); No article = used for general plural nouns (mountains in general), but ''the Himalayas'' is a specific proper name requiring ''the''.', 'EASY', 'English', 'Advanced Grammar — Articles, Modal Verbs, Conditionals and Collocations (W12 B1)', 'ENG_GRAMMAR_ADVANCED_W12_B1', '[{"option_text": "A", "is_correct": false}, {"option_text": "An", "is_correct": false}, {"option_text": "The", "is_correct": true}, {"option_text": "No article needed", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('458277d9-6951-5a46-beb2-6649f60c715c', 'Choose the correct modal verb: ''You ___ submit the form by Friday — it is compulsory and there are no exceptions.''', NULL, 'C is correct. MUST = expresses strong obligation or necessity (often from the speaker''s own authority or rules). ''It is compulsory and there are no exceptions'' confirms absolute obligation → ''must''. SHOULD = advice or weaker obligation (''you should submit'' = recommended but not absolute); MIGHT = remote possibility; COULD = ability or polite request (neither strong obligation). Key: must (absolute necessity) > should (strong advice) > might/could (weaker possibility).', 'EASY', 'English', 'Advanced Grammar — Articles, Modal Verbs, Conditionals and Collocations (W12 B1)', 'ENG_GRAMMAR_ADVANCED_W12_B1', '[{"option_text": "might", "is_correct": false}, {"option_text": "should", "is_correct": false}, {"option_text": "must", "is_correct": true}, {"option_text": "could", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0ef421c4-19f8-56fe-b90b-f67ca8305fbc', 'Choose the correct collocation: ''The manager decided to ___ action on the complaints.''', NULL, 'C is correct. ''Take action'' is the fixed collocation in English. TAKE collocates with: action, a decision, responsibility, a test, notes, a step. MAKE collocates with: a decision, progress, an effort, a mistake, an offer. DO collocates with: homework, the dishes, business, research. PUT collocates with: effort into, on hold. ''Take action'' (= act upon something) is the only natural expression here. Trap: ''make action'' and ''do action'' are common learner errors — neither is standard English.', 'EASY', 'English', 'Advanced Grammar — Articles, Modal Verbs, Conditionals and Collocations (W12 B1)', 'ENG_GRAMMAR_ADVANCED_W12_B1', '[{"option_text": "do", "is_correct": false}, {"option_text": "make", "is_correct": false}, {"option_text": "take", "is_correct": true}, {"option_text": "put", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e8dfb69a-ae20-5853-9237-1ffb682d353b', 'Choose the correct verb form: ''She would rather ___ at home than go to the party.''', NULL, 'C is correct. ''Would rather'' is followed by the BASE FORM (infinitive without ''to''). Structure: Subject + would rather + base verb + than + base verb. ''She would rather STAY at home than GO to the party.'' Both verbs after ''would rather...than'' are in base form. Trap: ''to stay'' = uses ''to infinitive'' (wrong — ''would rather'' doesn''t take ''to''); ''staying'' = gerund (wrong — ''would rather'' takes base form not gerund); ''stayed'' = past tense (wrong unless expressing preference about someone else: ''I''d rather she stayed home'').', 'MEDIUM', 'English', 'Advanced Grammar — Articles, Modal Verbs, Conditionals and Collocations (W12 B1)', 'ENG_GRAMMAR_ADVANCED_W12_B1', '[{"option_text": "staying", "is_correct": false}, {"option_text": "to stay", "is_correct": false}, {"option_text": "stay", "is_correct": true}, {"option_text": "stayed", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0652443a-11e0-5dcc-a0a1-2633ad860ec8', 'Identify the CORRECT sentence using a relative clause:', NULL, 'B is correct. Relative pronoun ''that'' replaces ''the book'' in the relative clause. Correct structure: ''The book [that I borrowed from the library]''. No pronoun repetition — ''it'' is dropped because ''that'' already stands for ''the book''. Trap: ''which I borrowed it'' = double subject (both ''which'' and ''it'' refer to the book — error); ''whom'' = used for PEOPLE not things (book is a thing → use ''which'' or ''that''); ''it was fascinating'' = extra ''it'' after the relative clause breaks the main clause continuity.', 'MEDIUM', 'English', 'Advanced Grammar — Articles, Modal Verbs, Conditionals and Collocations (W12 B1)', 'ENG_GRAMMAR_ADVANCED_W12_B1', '[{"option_text": "The book which I borrowed it from the library was fascinating.", "is_correct": false}, {"option_text": "The book that I borrowed from the library was fascinating.", "is_correct": true}, {"option_text": "The book whom I borrowed from the library was fascinating.", "is_correct": false}, {"option_text": "The book which I borrowed from the library it was fascinating.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('86665c8b-c995-546b-87a9-8fcb12aaac9a', 'Choose the correct conditional: ''If I ___ a bird, I would fly to you.''', NULL, 'C is correct. This is a second conditional (hypothetical/unreal present situation): ''If + Past Subjunctive, would + base verb.'' The past subjunctive of ''be'' for ALL persons is ''were'' (not ''was'') in formal grammar. ''If I WERE a bird'' = imaginary situation (I am not a bird). Trap: ''was'' = informal/conversational (some speakers use it, but SSC follows formal grammar requiring ''were'' in subjunctive after ''if I''); ''am'' = first conditional (real situation in present → wrong here since being a bird is not a real present situation); ''will be'' = future (wrong — condition uses past tense in second conditional).', 'MEDIUM', 'English', 'Advanced Grammar — Articles, Modal Verbs, Conditionals and Collocations (W12 B1)', 'ENG_GRAMMAR_ADVANCED_W12_B1', '[{"option_text": "am", "is_correct": false}, {"option_text": "will be", "is_correct": false}, {"option_text": "were", "is_correct": true}, {"option_text": "was", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('866eb8d2-c6c8-5f67-8905-2d56f8cef681', 'Choose the correct preposition: ''She has been waiting ___ the station ___ two hours.''', NULL, 'B is correct. AT = used for specific locations/points (at the station, at the corner, at the bus stop). FOR = used with a period/duration of time (for two hours, for three days). ''AT the station FOR two hours'' ✓. Trap: IN = used for enclosed spaces or larger areas (in the city, in the room — not typically ''in the station'' when waiting at a specific platform point); SINCE = used with a point in time, not a duration (''since 2 PM'' not ''since two hours'').', 'MEDIUM', 'English', 'Advanced Grammar — Articles, Modal Verbs, Conditionals and Collocations (W12 B1)', 'ENG_GRAMMAR_ADVANCED_W12_B1', '[{"option_text": "in / since", "is_correct": false}, {"option_text": "at / for", "is_correct": true}, {"option_text": "on / since", "is_correct": false}, {"option_text": "at / since", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('28323797-18eb-5fe1-b818-71288efcd643', 'Identify the CORRECTLY formed gerund phrase: ''She is looking forward to ___.''', NULL, 'A is correct. ''Look forward to'' uses ''to'' as a PREPOSITION, not part of an infinitive. After a preposition, use a GERUND (V+ing). ''Looking forward to MEETING'' = correct (meeting = gerund). Trap: ''to meet'' = treats ''to'' as part of an infinitive marker (wrong — here ''to'' is a preposition); ''will meet'' = future tense (cannot follow a preposition). This is SSC''s favourite ''to + gerund'' trap: ''look forward to'', ''object to'', ''used to'', ''in addition to'', ''when it comes to'' — all take gerunds, NOT infinitives.', 'MEDIUM', 'English', 'Advanced Grammar — Articles, Modal Verbs, Conditionals and Collocations (W12 B1)', 'ENG_GRAMMAR_ADVANCED_W12_B1', '[{"option_text": "meeting her old friends", "is_correct": true}, {"option_text": "meet her old friends", "is_correct": false}, {"option_text": "will meet her old friends", "is_correct": false}, {"option_text": "have met her old friends", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b4a36d97-c173-5faf-99e1-c49405d3f499', 'Choose the sentence with CORRECT agreement: ''Neither of the reports ___.''', NULL, 'B is correct. NEITHER (without a pairing ''nor'') refers to one or the other of two, but is grammatically SINGULAR when used alone with ''of''. ''Neither of the reports'' = singular subject → singular verb ''was''. Similarly: ''either of them IS going'' (singular). Contrast: ''Neither the manager nor the officers were present'' (neither...nor → proximity rule → plural). Trap: ''were'' = plural (wrong — ''neither of + plural noun'' still takes singular verb in formal grammar); ''have been'' = plural auxiliary (same error).', 'HARD', 'English', 'Advanced Grammar — Articles, Modal Verbs, Conditionals and Collocations (W12 B1)', 'ENG_GRAMMAR_ADVANCED_W12_B1', '[{"option_text": "were submitted on time", "is_correct": false}, {"option_text": "was submitted on time", "is_correct": true}, {"option_text": "have been submitted on time", "is_correct": false}, {"option_text": "are submitted on time", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0717adc4-4929-56e3-9b8c-b5017adf0fc7', 'Choose the CORRECT use of the participle: ''Having finished the exam, ___.''', NULL, 'B is correct. Participial phrase ''Having finished the exam'' must logically attach to the subject of the main clause. The students finished the exam → ''the students felt relieved.'' Subject = ''the students'' = the same people who finished. Trap: ''the results were announced'' = results didn''t finish the exam (dangling modifier — grammatically wrong); ''the paper was kept aside by us'' = the paper didn''t finish the exam (another dangling modifier, though ''us'' could logically have finished — passive construction makes the paper the grammatical subject, which is wrong); ''the clock was checked by the invigilator'' = the invigilator, not the clock, would finish the exam.', 'HARD', 'English', 'Advanced Grammar — Articles, Modal Verbs, Conditionals and Collocations (W12 B1)', 'ENG_GRAMMAR_ADVANCED_W12_B1', '[{"option_text": "the results were announced.", "is_correct": false}, {"option_text": "the students felt relieved.", "is_correct": true}, {"option_text": "the paper was kept aside by us.", "is_correct": false}, {"option_text": "the clock was checked by the invigilator.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('62be2f75-04f0-5882-93f7-0a5e45f5edb7', 'Choose the correctly spelled word:', NULL, 'Conscientious (governed by conscience). Common errors: confusing -ient and -ience spellings. Related: conscience, conscious, unconscious.', 'MEDIUM', 'English', 'Grammar — Mixed', 'ENG_FILLERS', '[{"option_text": "Conscientious", "is_correct": true}, {"option_text": "Consientious", "is_correct": false}, {"option_text": "Consciencious", "is_correct": false}, {"option_text": "Conscientous", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('61144f19-1417-568b-9ac0-b2d12fbe4657', 'A ''malapropism'' is:', NULL, 'Malapropism (from Mrs. Malaprop, Sheridan''s character): ''He is the very pineapple of politeness'' (should be ''pinnacle''). Common exam vocabulary topic.', 'HARD', 'English', 'Grammar — Mixed', 'ENG_FILLERS', '[{"option_text": "The mistaken use of a word in place of a similar-sounding word (e.g., ''dance a flamingo'' instead of ''flamenco'')", "is_correct": true}, {"option_text": "Excessive use of metaphors", "is_correct": false}, {"option_text": "Speaking too loudly", "is_correct": false}, {"option_text": "Using overly formal language", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('eaaccdca-6f4a-519e-b102-dc922670159d', 'Change to passive voice: ''The committee will announce the results tomorrow.''', NULL, 'A is correct. Active: ''will announce'' (future simple active). Passive: ''will be + past participle'' → ''will be announced''. Structure: Object (The results) + will be + past participle (announced) + by + Subject (the committee) + time (tomorrow). Trap: ''will have been announced'' = future perfect passive (wrong tense — used for future perfect active ''will have announced'', not simple future); ''shall be announced'' = ''shall'' is for first person (I/We), not third person (the committee); present tense passive = wrong tense.', 'MEDIUM', 'English', 'Grammar Usage — Active/Passive, Reported Speech, Conditionals, Modals and Subjunctive (W13 B1)', 'ENG_GRAMMAR_USAGE_W13_B1', '[{"option_text": "The results will be announced by the committee tomorrow.", "is_correct": true}, {"option_text": "The results will have been announced by the committee tomorrow.", "is_correct": false}, {"option_text": "The results shall be announced by the committee tomorrow.", "is_correct": false}, {"option_text": "The results are announced by the committee tomorrow.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('606484c1-ff47-5161-9900-af7863f8de58', 'Change to active voice: ''The letter was being written by her when I arrived.''', NULL, 'B is correct. Passive: ''was being written'' = past continuous passive. Active equivalent: ''was + verb-ing'' = past continuous active = ''was writing''. The continuous aspect (''being written'') shows an ongoing action interrupted by my arrival. ''She was writing the letter when I arrived'' ✓. Trap: ''wrote'' = past simple (drops the continuous aspect — implies completion, but ''was being written'' implies an action in progress); ''has written'' = present perfect (wrong tense).', 'MEDIUM', 'English', 'Grammar Usage — Active/Passive, Reported Speech, Conditionals, Modals and Subjunctive (W13 B1)', 'ENG_GRAMMAR_USAGE_W13_B1', '[{"option_text": "She has written the letter when I arrived.", "is_correct": false}, {"option_text": "She was writing the letter when I arrived.", "is_correct": true}, {"option_text": "She wrote the letter when I arrived.", "is_correct": false}, {"option_text": "She had written the letter when I arrived.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c1b63037-6e35-574d-b0c1-0f924edaf68e', 'Convert to reported speech: She said, ''I am preparing for the exam now.''', NULL, 'B is correct. Rules for reported speech (past reporting verb ''said''): (1) Present continuous → Past continuous: ''am preparing'' → ''was preparing''. (2) ''now'' → ''then''. (3) First person ''I'' → third person ''she''. Result: ''She said that she was preparing for the exam then.'' Trap: ''is preparing'' = keeps present tense (wrong — must backshift when reporting verb is past); ''had prepared'' = past perfect (past perfect is used for simple past in direct speech: ''I prepared'' → ''she had prepared''; here the original is continuous, not simple past).', 'MEDIUM', 'English', 'Grammar Usage — Active/Passive, Reported Speech, Conditionals, Modals and Subjunctive (W13 B1)', 'ENG_GRAMMAR_USAGE_W13_B1', '[{"option_text": "She said that she is preparing for the exam then.", "is_correct": false}, {"option_text": "She said that she was preparing for the exam then.", "is_correct": true}, {"option_text": "She said that she had prepared for the exam now.", "is_correct": false}, {"option_text": "She said that she would prepare for the exam then.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8ed1446d-de55-5e25-b73c-d0d8cb53a4fd', 'Convert to reported speech: He asked me, ''Have you submitted your application?''', NULL, 'A is correct. Rules: (1) Yes/No question → use ''if/whether''. (2) Backshift: present perfect ''have submitted'' → past perfect ''had submitted''. (3) ''you'' → ''I'' (perspective shift). (4) Remove question word order: ''Have you'' → ''I had''. Result: ''He asked me IF I HAD SUBMITTED my application'' ✓. Trap: ''have submitted'' = no backshift (wrong when reporting verb is past); ''have I submitted'' = keeps question inversion (wrong in reported speech — must use statement word order); ''that had I'' = ''that'' is used for statements, ''if/whether'' for yes/no questions.', 'MEDIUM', 'English', 'Grammar Usage — Active/Passive, Reported Speech, Conditionals, Modals and Subjunctive (W13 B1)', 'ENG_GRAMMAR_USAGE_W13_B1', '[{"option_text": "He asked me if I had submitted my application.", "is_correct": true}, {"option_text": "He asked me if I have submitted my application.", "is_correct": false}, {"option_text": "He asked me have I submitted my application.", "is_correct": false}, {"option_text": "He asked me that had I submitted my application.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dd564ec4-2388-50fb-9057-b0364329961b', 'Which sentence correctly uses the TYPE 2 CONDITIONAL?', NULL, 'C is correct. TYPE 2 CONDITIONAL = hypothetical/unreal present situation: ''If + past tense + would/could + base verb''. ''If I WERE the principal'' (note: ''were'' used for all subjects in subjunctive Type 2 — not ''was''), ''I WOULD CHANGE...'' ✓ = imagining yourself in a position you are not in. Trap: A = Type 1 (real/possible future: ''if + present simple + will''); B and D = Type 3 (unreal past: ''if + past perfect + would have + past participle''). Type 2 is for unreal PRESENT; Type 3 is for unreal PAST.', 'MEDIUM', 'English', 'Grammar Usage — Active/Passive, Reported Speech, Conditionals, Modals and Subjunctive (W13 B1)', 'ENG_GRAMMAR_USAGE_W13_B1', '[{"option_text": "If it rains tomorrow, we will cancel the picnic.", "is_correct": false}, {"option_text": "If I had known earlier, I would have informed you.", "is_correct": false}, {"option_text": "If I were the principal, I would change the dress code.", "is_correct": true}, {"option_text": "If she had worked harder, she would have passed.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bb952f27-361f-5350-9240-08842421f968', 'Which sentence uses MUST correctly in the sense of CERTAINTY (deduction), not obligation?', NULL, 'C is correct. MUST has two main uses: (1) OBLIGATION (''You must submit...'', ''must wear'', ''must leave'') = a rule or requirement; (2) LOGICAL CERTAINTY/DEDUCTION (''She must be tired'' = I''m confident she is tired, based on the evidence of working since dawn). C uses ''must'' for DEDUCTION based on evidence — a logical inference. Trap: A, B, D = all use ''must'' for obligation (rules and requirements). The deduction use is identifiable by the presence of evidence in the context: ''she has been working since dawn'' = evidence → ''must be tired'' = deduction.', 'MEDIUM', 'English', 'Grammar Usage — Active/Passive, Reported Speech, Conditionals, Modals and Subjunctive (W13 B1)', 'ENG_GRAMMAR_USAGE_W13_B1', '[{"option_text": "You must submit your form by Friday.", "is_correct": false}, {"option_text": "Students must wear uniforms in school.", "is_correct": false}, {"option_text": "She must be tired; she has been working since dawn.", "is_correct": true}, {"option_text": "We must leave before the storm arrives.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cbeff1ad-7df6-5bae-85aa-13ff37ac3fe3', 'Choose the correct question tag: ''He hardly goes out, ___?''', NULL, 'A is correct. HARDLY is a negative adverb (''hardly goes'' = almost never goes = a negative meaning). RULE: When the main clause contains a negative word (hardly, scarcely, never, seldom, rarely, no, nobody), the question tag must be POSITIVE. ''He hardly goes out'' → tag = ''DOES he?'' (positive tag). ''Hardly goes'' = present simple → auxiliary ''does''. Trap: ''doesn''t he'' = DOUBLE NEGATIVE: ''hardly'' (negative) + ''doesn''t'' (negative) = two negatives together = wrong. The tag after negative adverbs is always positive.', 'HARD', 'English', 'Grammar Usage — Active/Passive, Reported Speech, Conditionals, Modals and Subjunctive (W13 B1)', 'ENG_GRAMMAR_USAGE_W13_B1', '[{"option_text": "does he", "is_correct": true}, {"option_text": "doesn''t he", "is_correct": false}, {"option_text": "is he", "is_correct": false}, {"option_text": "isn''t he", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8c23b409-ca6d-56c6-ba67-83e56d8c9101', 'Which sentence uses the GERUND correctly where an infinitive would be WRONG?', NULL, 'C is correct. ''LOOK FORWARD TO + gerund (-ing)'' is a fixed phrase where ''to'' is a PREPOSITION, not part of the infinitive. Therefore: ''looking forward to MEETING'' (gerund) ✓. NOT ''looking forward to MEET'' (infinitive). Trap: A: ''hope'' takes INFINITIVE not gerund → ''hopes TO PLAY''; B: ''decide'' takes INFINITIVE → ''decided TO QUIT''; D: ''want'' takes INFINITIVE → ''wants TO PLAY''. Key: when ''to'' is a preposition (look forward TO, object TO, in addition TO, accustomed TO), use GERUND, not infinitive.', 'HARD', 'English', 'Grammar Usage — Active/Passive, Reported Speech, Conditionals, Modals and Subjunctive (W13 B1)', 'ENG_GRAMMAR_USAGE_W13_B1', '[{"option_text": "She hopes playing for the national team one day.", "is_correct": false}, {"option_text": "She decided quitting her job immediately.", "is_correct": false}, {"option_text": "She is looking forward to meeting the director.", "is_correct": true}, {"option_text": "She wants playing tennis every morning.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('30929d0e-7888-5188-86e3-72301f01765e', 'Which sentence correctly uses the SUBJUNCTIVE mood?', NULL, 'B is correct. SUBJUNCTIVE MOOD: Used after verbs of recommendation, suggestion, demand, insistence etc. (suggest, recommend, demand, insist, propose, order, request). Structure: that + subject + BASE FORM of verb (no -s, no -ed, no auxiliary). ''Suggested that he REST'' (base form, no ''s'') ✓. Trap: ''rests'' = adds -s for third person (wrong in subjunctive — no -s in base form); ''rested'' = past tense (wrong in mandative subjunctive); ''should rests'' = ''should + bare infinitive'' is acceptable (alternative to subjunctive) but ''should rests'' has the wrong verb form (must be ''should rest'').', 'HARD', 'English', 'Grammar Usage — Active/Passive, Reported Speech, Conditionals, Modals and Subjunctive (W13 B1)', 'ENG_GRAMMAR_USAGE_W13_B1', '[{"option_text": "The doctor suggested that he rests for a week.", "is_correct": false}, {"option_text": "The doctor suggested that he rest for a week.", "is_correct": true}, {"option_text": "The doctor suggested that he should rests for a week.", "is_correct": false}, {"option_text": "The doctor suggested that he rested for a week.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cbe24f57-5b6f-5b53-b352-d19bab97f54a', 'Which sentence contains an ABSOLUTE PHRASE (a phrase not grammatically connected to the main clause)?', NULL, 'B is correct. An ABSOLUTE PHRASE = a phrase that modifies the entire sentence but has its own SUBJECT (different from the main clause subject). B: ''Her work completed'' — subject of this phrase is ''her work'' (different from main clause subject ''she''). Absolute phrase structure: noun/pronoun + past participle (or present participle). ''Her work completed, she left'' = once her work was completed, she left. Trap: A = ''Running down the stairs'' = participial phrase (subject = ''he'', same as main clause = NOT absolute); C = ''After finishing'' = subordinate clause/participial phrase, not absolute; D = ''To complete'' = infinitive phrase, not absolute.', 'HARD', 'English', 'Grammar Usage — Active/Passive, Reported Speech, Conditionals, Modals and Subjunctive (W13 B1)', 'ENG_GRAMMAR_USAGE_W13_B1', '[{"option_text": "Running down the stairs, he tripped and fell.", "is_correct": false}, {"option_text": "Her work completed, she left the office.", "is_correct": true}, {"option_text": "After finishing his meal, he went for a walk.", "is_correct": false}, {"option_text": "To complete the project, she worked through the night.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('49e667ce-52ba-5401-8d87-5913beb5af84', 'The idiom ''to turn a blind eye'' means:', NULL, 'To deliberately ignore wrongdoing or something inconvenient. Origin is often attributed to Admiral Nelson, who reportedly put his telescope to his blind eye at the Battle of Copenhagen (1801) to ignore a signal to withdraw. Example — ''The manager turned a blind eye to the employees'' lateness.''', 'MEDIUM', 'English', 'Idioms — daily use — mixed tiers', 'ENG_VOCAB_IDIOMS', '[{"option_text": "To look very carefully at something", "is_correct": false}, {"option_text": "To pretend not to notice something", "is_correct": true}, {"option_text": "To become physically blind", "is_correct": false}, {"option_text": "To look in the wrong direction", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1da2cb9c-a475-52d4-be01-e1cb6b16ecca', 'Choose the sentence in which ''BEAT AROUND THE BUSH'' is used correctly.', NULL, 'B is correct. ''Beat around the bush'' = to avoid coming to the main point; to talk around an issue without addressing it directly. The idiom is used figuratively, not literally. B captures this perfectly: ''she kept beating around the bush'' = she avoided giving a direct answer. Trap: A, C, D use the phrase in its literal sense (bushes in sport or gardening) — SSC tests whether students know idioms are never literal.', 'EASY', 'English', 'Idioms and Phrases — Meaning in Context and Correct Usage (W13 B1)', 'ENG_IDIOMS_IN_CONTEXT_W13_B1', '[{"option_text": "He beat around the bush while playing cricket.", "is_correct": false}, {"option_text": "Instead of answering directly, she kept beating around the bush.", "is_correct": true}, {"option_text": "The gardener beat around the bush to trim it.", "is_correct": false}, {"option_text": "They beat around the bush during the marathon.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2ebf8970-091c-5769-8b58-3aaad8bfeb10', 'What does ''SPILL THE BEANS'' mean?', NULL, 'B is correct. ''Spill the beans'' = to accidentally or prematurely reveal information that was supposed to be kept secret; to let confidential information slip. Use: ''Don''t spill the beans — the surprise party is on Saturday!'' Origin: possibly from ancient Greek voting using beans placed in jars. Trap: ''waste resources'' = ''spill resources'' (different meaning); ''nervous'' = cold feet (different idiom).', 'EASY', 'English', 'Idioms and Phrases — Meaning in Context and Correct Usage (W13 B1)', 'ENG_IDIOMS_IN_CONTEXT_W13_B1', '[{"option_text": "To waste resources carelessly", "is_correct": false}, {"option_text": "To reveal a secret or surprise unintentionally", "is_correct": true}, {"option_text": "To create a mess in the kitchen", "is_correct": false}, {"option_text": "To become nervous before an event", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8d7ee592-7a93-5936-9fbe-591381e90f4b', '''The project seemed straightforward, but it turned out to be a CAN OF WORMS.'' What does this mean?', NULL, 'B is correct. ''A can of worms'' = a complex, troublesome, or unpleasant situation, especially one that becomes even more complicated when examined. Opening a can of worms releases something problematic and hard to contain. Use: ''Auditing those accounts opened a real can of worms.'' The project ''turned out to be a can of worms'' = what seemed simple created numerous unexpected problems. Trap: ''worthless'' = scrap or trash (different idiom); ''biology'' = literal misreading.', 'EASY', 'English', 'Idioms and Phrases — Meaning in Context and Correct Usage (W13 B1)', 'ENG_IDIOMS_IN_CONTEXT_W13_B1', '[{"option_text": "The project involved biology experiments", "is_correct": false}, {"option_text": "The project generated unexpected complications", "is_correct": true}, {"option_text": "The project was completely worthless", "is_correct": false}, {"option_text": "The project was completed successfully", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b7ffee78-1958-5db6-a448-17ef2a5f2fc6', '''He was barking up the wrong tree when he blamed his assistant.'' What does ''barking up the wrong tree'' mean?', NULL, 'B is correct. ''Barking up the wrong tree'' = directing effort, blame, or attention toward the wrong person or thing; pursuing a false lead. Origin: hunting dogs would bark at the base of a tree if they thought prey had climbed it — but could bark at the wrong tree. Use: ''If you think I''m behind the leak, you''re barking up the wrong tree.'' Trap: ''loud complaints'' = raising one''s voice/blowing one''s trumpet (different idiom); ''afraid of dogs'' = literal misreading.', 'MEDIUM', 'English', 'Idioms and Phrases — Meaning in Context and Correct Usage (W13 B1)', 'ENG_IDIOMS_IN_CONTEXT_W13_B1', '[{"option_text": "Making loud complaints unnecessarily", "is_correct": false}, {"option_text": "Pursuing a mistaken or misguided course of action", "is_correct": true}, {"option_text": "Blaming someone who is afraid of dogs", "is_correct": false}, {"option_text": "Being unreasonably harsh in criticism", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f71360fa-cd17-58b2-992e-adba4bf524ac', 'What does ''BITE OFF MORE THAN YOU CAN CHEW'' mean?', NULL, 'B is correct. ''Bite off more than you can chew'' = to take on a task or commitment that is too large or complex for one to manage; to overestimate one''s own capacity. Use: ''He bit off more than he could chew by promising to deliver the entire project in one week.'' Trap: ''bold decision'' = bite the bullet (different idiom — that means proceeding despite pain); ''greedy with food'' = literal misreading (this is figurative).', 'MEDIUM', 'English', 'Idioms and Phrases — Meaning in Context and Correct Usage (W13 B1)', 'ENG_IDIOMS_IN_CONTEXT_W13_B1', '[{"option_text": "To eat very fast without manners", "is_correct": false}, {"option_text": "To take on more responsibilities than you can handle", "is_correct": true}, {"option_text": "To be greedy with food at a party", "is_correct": false}, {"option_text": "To make a bold decision without thinking", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2ed365ac-7fca-53ec-9a02-1758b48419f6', '''After months of dispute, the two companies finally buried the hatchet.'' What happened?', NULL, 'C is correct. ''Bury the hatchet'' = to make peace; to cease hostilities and end a conflict or argument. Origin: Native American tradition of burying a tomahawk (hatchet) as a symbol of peace when warring tribes reached an agreement. Use: ''The siblings buried the hatchet after their father''s intervention.'' Trap: ''legal settlement'' = involves courts (bury the hatchet is about informal reconciliation); ''buried evidence'' = literal misreading of ''buried''.', 'MEDIUM', 'English', 'Idioms and Phrases — Meaning in Context and Correct Usage (W13 B1)', 'ENG_IDIOMS_IN_CONTEXT_W13_B1', '[{"option_text": "One company went bankrupt", "is_correct": false}, {"option_text": "They reached a settlement through legal means", "is_correct": false}, {"option_text": "They made peace and ended their conflict", "is_correct": true}, {"option_text": "They buried evidence of financial wrongdoing", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b1ff1e9f-6c2c-5f07-888c-2737a7b9c05a', 'What does ''PULL SOMEONE''S LEG'' mean?', NULL, 'C is correct. ''Pull someone''s leg'' = to tease someone with a joke or untruth in a light-hearted way; to playfully deceive someone. Use: ''I''m just pulling your leg — your presentation was actually excellent!'' Trap: ''physical harm'' = literal reading; ''unfair advantage'' = foul play (different concept); ''convince to work harder'' = unrelated.', 'MEDIUM', 'English', 'Idioms and Phrases — Meaning in Context and Correct Usage (W13 B1)', 'ENG_IDIOMS_IN_CONTEXT_W13_B1', '[{"option_text": "To physically harm someone", "is_correct": false}, {"option_text": "To seek unfair advantage in a competition", "is_correct": false}, {"option_text": "To tease or joke with someone playfully", "is_correct": true}, {"option_text": "To convince someone to work harder", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d8345451-3353-5434-a88b-a5e096b9f649', '''The investigation hit a BRICK WALL when all the witnesses refused to testify.'' What does this mean?', NULL, 'C is correct. ''Hit a brick wall'' = to reach a point where progress is completely blocked; to encounter an insurmountable obstacle. A brick wall is solid and cannot easily be broken through. Use: ''The peace talks hit a brick wall when neither side would compromise.'' Trap: ''concluded successfully'' = opposite; ''violent'' = literal misreading of ''hit''.', 'HARD', 'English', 'Idioms and Phrases — Meaning in Context and Correct Usage (W13 B1)', 'ENG_IDIOMS_IN_CONTEXT_W13_B1', '[{"option_text": "The investigation was conducted inside a building", "is_correct": false}, {"option_text": "The investigators became violent", "is_correct": false}, {"option_text": "The investigation reached an obstacle it could not get past", "is_correct": true}, {"option_text": "The investigation concluded successfully", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d0130737-adfe-5d64-9281-89af0eeaa34d', '''By sending that message to the entire company instead of just the manager, she let the CAT OUT OF THE BAG.'' This means she:', NULL, 'B is correct. ''Let the cat out of the bag'' = to accidentally reveal a secret or surprise. Origin: marketplace fraud where a piglet was hidden in a bag (sack); if the cat was let out, the swindle was exposed. Similar to ''spill the beans''. Use: ''Someone let the cat out of the bag about the merger before the official announcement.'' Trap: ''caused panic'' = raise an alarm/blow the whistle (different idiom); ''startled colleagues'' = only partly related — the core meaning is REVEALING A SECRET.', 'HARD', 'English', 'Idioms and Phrases — Meaning in Context and Correct Usage (W13 B1)', 'ENG_IDIOMS_IN_CONTEXT_W13_B1', '[{"option_text": "Startled her colleagues", "is_correct": false}, {"option_text": "Accidentally revealed something that was meant to be secret", "is_correct": true}, {"option_text": "Released a pet cat from a bag", "is_correct": false}, {"option_text": "Caused unnecessary panic at work", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5458524a-eb48-59b1-9d28-4ee58d6c2ad3', 'Choose the sentence that correctly uses ''ON THE FENCE'':', NULL, 'B is correct. ''On the fence'' = undecided between two options; not committed to either side; neutral. Use: ''He stayed on the fence during the debate, refusing to endorse either candidate.'' B uses it correctly to mean undecided about a job offer. Trap: A, C, D use it literally (sitting/playing/climbing on a physical fence). SSC tests: idioms used correctly vs. literally — the correct use is ALWAYS figurative.', 'HARD', 'English', 'Idioms and Phrases — Meaning in Context and Correct Usage (W13 B1)', 'ENG_IDIOMS_IN_CONTEXT_W13_B1', '[{"option_text": "The farmer sat on the fence to rest after a long day.", "is_correct": false}, {"option_text": "She was on the fence about whether to accept the job offer.", "is_correct": true}, {"option_text": "The children played on the fence in the backyard.", "is_correct": false}, {"option_text": "The politician climbed on the fence to address the crowd.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ee1c9f66-2bc3-5733-949a-3fea0621fd9d', '''ONCE IN A BLUE MOON'' means:', NULL, 'Once in a blue moon = extremely rarely. A ''blue moon'' is a second full moon in a calendar month (a rare event). Also, literal blue-looking moons are very rare (from atmospheric particulates).', 'EASY', 'English', 'Idioms & phrases — mixed tiers', 'ENG_VOCAB_IDIOMS', '[{"option_text": "Very frequently", "is_correct": false}, {"option_text": "Very rarely", "is_correct": true}, {"option_text": "On a specific date", "is_correct": false}, {"option_text": "In the past", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bd466394-8b4f-5610-ab1c-173b6ef7f861', 'What does the idiom ''BITE THE BULLET'' mean?', NULL, 'B is correct. ''Bite the bullet'' = to endure a painful or difficult situation with courage and stoicism. Origin: soldiers bit on a bullet during surgery before anaesthesia to bear the pain. Example: ''Just bite the bullet and apologise to your boss.'' Trap: ''make a rash decision'' = ''shoot from the hip''; ''avoid confrontation'' = ''turn the other cheek''.', 'MEDIUM', 'English', 'Idioms and Phrases — Meaning Identification (W11 B1)', 'ENG_IDIOMS_PHRASES_W11_B1', '[{"option_text": "To eat hastily without care", "is_correct": false}, {"option_text": "To endure a painful situation bravely", "is_correct": true}, {"option_text": "To make a rash decision", "is_correct": false}, {"option_text": "To avoid a confrontation", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ff67711d-05ec-5b5d-aeb4-520564ed5770', 'What does the idiom ''BURN THE MIDNIGHT OIL'' mean?', NULL, 'C is correct. ''Burn the midnight oil'' = to work or study until very late at night. Origin: before electricity, people burned oil lamps to read/work at night. Example: ''She burned the midnight oil preparing for the board exam.'' Trap: ''waste resources recklessly'' = ''burn a hole in one''s pocket''; ''celebrate late'' = ''paint the town red''.', 'EASY', 'English', 'Idioms and Phrases — Meaning Identification (W11 B1)', 'ENG_IDIOMS_PHRASES_W11_B1', '[{"option_text": "To start a fire at night for warmth", "is_correct": false}, {"option_text": "To waste resources recklessly", "is_correct": false}, {"option_text": "To work or study late into the night", "is_correct": true}, {"option_text": "To celebrate into the early hours", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2b066465-8459-569d-b5ce-29cda4611933', 'What does the idiom ''A DOUBLE-EDGED SWORD'' mean?', NULL, 'B is correct. ''A double-edged sword'' = something that can be beneficial and harmful at the same time; having two sides — both positive and negative. Example: ''Social media is a double-edged sword: it connects people but also spreads misinformation.'' Trap: ''a very effective argument'' = one-sided interpretation (ignores the negative edge); ''a difficult choice'' = ''between the devil and the deep blue sea'' / ''a Hobson''s choice''.', 'HARD', 'English', 'Idioms and Phrases — Meaning Identification (W11 B1)', 'ENG_IDIOMS_PHRASES_W11_B1', '[{"option_text": "A very effective weapon or argument", "is_correct": false}, {"option_text": "Something that has both advantages and disadvantages", "is_correct": true}, {"option_text": "A situation requiring a very difficult choice", "is_correct": false}, {"option_text": "An aggressive and confrontational manner", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('be4eff4a-6f61-5201-8eb6-c72106917fb1', 'What does the phrase ''KICK THE BUCKET'' mean?', NULL, 'B is correct. ''Kick the bucket'' = to die (informal, often humorous). This is one of the most commonly tested SSC English idioms. Example: ''The old miser kicked the bucket before he could enjoy his wealth.'' Trap: ''abandon a project'' = ''throw in the towel''; ''resign from a job'' = ''hand in one''s notice''; ''make a foolish mistake'' = ''put one''s foot in one''s mouth''.', 'EASY', 'English', 'Idioms and Phrases — Meaning Identification (W11 B1)', 'ENG_IDIOMS_PHRASES_W11_B1', '[{"option_text": "To abandon a project midway", "is_correct": false}, {"option_text": "To die", "is_correct": true}, {"option_text": "To resign from a job", "is_correct": false}, {"option_text": "To make a foolish mistake", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9a8189d3-48de-5c38-b311-716590f7212d', 'What does the idiom ''IN THE SAME BOAT'' mean?', NULL, 'B is correct. ''In the same boat'' = in the same difficult or unfortunate situation as others. Example: ''We are all in the same boat — the project delay has affected everyone''s bonus.'' The idiom emphasises shared adversity, not merely being together. Trap: ''equal rank'' = ''on the same footing''; ''same skill level'' = ''on par with''.', 'EASY', 'English', 'Idioms and Phrases — Meaning Identification (W11 B1)', 'ENG_IDIOMS_PHRASES_W11_B1', '[{"option_text": "Travelling together to the same destination", "is_correct": false}, {"option_text": "Sharing the same difficult situation", "is_correct": true}, {"option_text": "Being in a position of equal rank", "is_correct": false}, {"option_text": "Having the same skill level", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('781f8197-c8bf-502c-9633-67f835d8458c', 'What does the idiom ''BEAT AROUND THE BUSH'' mean?', NULL, 'C is correct. ''Beat around the bush'' = to avoid discussing the main topic directly; to talk around a subject without addressing it. Example: ''Stop beating around the bush and tell me what the problem is.'' Trap: ''search carefully'' = literal misinterpretation of ''beat'' (to search) and ''bush''; ''prepare thoroughly'' = ''leave no stone unturned''.', 'MEDIUM', 'English', 'Idioms and Phrases — Meaning Identification (W11 B1)', 'ENG_IDIOMS_PHRASES_W11_B1', '[{"option_text": "To be physically active outdoors", "is_correct": false}, {"option_text": "To search for something carefully", "is_correct": false}, {"option_text": "To avoid coming to the main point", "is_correct": true}, {"option_text": "To prepare thoroughly before an event", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1b5630c6-6877-51bb-a2ed-8da0d2e5aab9', 'What does the phrase ''ONCE IN A BLUE MOON'' mean?', NULL, 'B is correct. ''Once in a blue moon'' = something that happens very infrequently or rarely. Example: ''She only visits us once in a blue moon.'' A ''blue moon'' is the rare occurrence of a second full moon in one calendar month — hence the idiom for rarity. Trap: ''at an unexpected moment'' = ''out of the blue''; ''in sadness'' = ''feeling blue'' (different idiom).', 'EASY', 'English', 'Idioms and Phrases — Meaning Identification (W11 B1)', 'ENG_IDIOMS_PHRASES_W11_B1', '[{"option_text": "During a rare astronomical event", "is_correct": false}, {"option_text": "Very rarely", "is_correct": true}, {"option_text": "At an unexpected moment", "is_correct": false}, {"option_text": "In a state of sadness", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0d994e2f-7193-55c4-9896-ca632e602618', 'What does the idiom ''A BLESSING IN DISGUISE'' mean?', NULL, 'B is correct. ''A blessing in disguise'' = something that seems bad or unfortunate at first but turns out to be beneficial. Example: ''Losing his job was a blessing in disguise — it led him to start his own business.'' Trap: ''hidden danger'' = ''a wolf in sheep''s clothing'' (opposite — something harmful that appears good); ''unexpected gift'' = literal misreading.', 'MEDIUM', 'English', 'Idioms and Phrases — Meaning Identification (W11 B1)', 'ENG_IDIOMS_PHRASES_W11_B1', '[{"option_text": "A hidden danger that appears harmless", "is_correct": false}, {"option_text": "A good thing that initially seemed bad", "is_correct": true}, {"option_text": "An unexpected gift from a stranger", "is_correct": false}, {"option_text": "A plan that needs to be kept secret", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('92d22010-ac79-5bd0-995c-ee9076134403', 'What does the idiom ''SPILL THE BEANS'' mean?', NULL, 'C is correct. ''Spill the beans'' = to accidentally reveal secret or private information. Example: ''Don''t spill the beans about the surprise party!'' Trap: ''make a careless mistake'' = ''drop the ball''; ''get into confusion'' = ''get into a muddle''. The idiom specifically implies revealing information (often accidentally) that was meant to be kept secret.', 'EASY', 'English', 'Idioms and Phrases — Meaning Identification (W11 B1)', 'ENG_IDIOMS_PHRASES_W11_B1', '[{"option_text": "To make a careless mistake", "is_correct": false}, {"option_text": "To cause an accident in the kitchen", "is_correct": false}, {"option_text": "To reveal a secret", "is_correct": true}, {"option_text": "To get into a confusing situation", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1f3a6e4e-2866-5f77-90a2-47402aab00bb', 'What does the idiom ''BITE THE HAND THAT FEEDS YOU'' mean?', NULL, 'A is correct. ''Bite the hand that feeds you'' = to act with ingratitude towards someone who supports you, especially by harming or criticising them. Example: ''Criticising the sponsor publicly is biting the hand that feeds you.'' Trap: ''take advantage of a generous person'' = close but misses the key element of INGRATITUDE/HARM — the idiom implies actively working against your benefactor; ''compete with an ally'' = ''turn on one''s friends''.', 'HARD', 'English', 'Idioms and Phrases — Meaning Identification (W11 B1)', 'ENG_IDIOMS_PHRASES_W11_B1', '[{"option_text": "To be ungrateful to those who support you", "is_correct": true}, {"option_text": "To eat greedily without sharing", "is_correct": false}, {"option_text": "To take advantage of a generous person", "is_correct": false}, {"option_text": "To compete with your own ally", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('884b8f0b-0a8b-57c8-9d78-b81b44bd8bf8', 'What does the idiom ''Once in a blue moon'' mean?', NULL, 'A is correct. ''Once in a blue moon'' = very rarely. A blue moon (second full moon in one calendar month) is uncommon, hence the idiom.', 'EASY', 'English', 'Idioms and Phrases (W9)', 'ENG_IDIOMS_W9', '[{"option_text": "Very rarely", "is_correct": true}, {"option_text": "Once every month", "is_correct": false}, {"option_text": "Only at night", "is_correct": false}, {"option_text": "Very frequently", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5cdf039a-03c3-5b7f-8ee2-e4efd4ccafbf', 'What does the idiom ''Break the ice'' mean?', NULL, 'B is correct. ''Break the ice'' means to do or say something to relieve tension and start a conversation, especially among strangers.', 'EASY', 'English', 'Idioms and Phrases (W9)', 'ENG_IDIOMS_W9', '[{"option_text": "Destroy something valuable", "is_correct": false}, {"option_text": "Start a conversation in an awkward situation", "is_correct": true}, {"option_text": "Bring everything to a standstill", "is_correct": false}, {"option_text": "Stop a fight", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b0c715a6-3e3d-52a9-a0e6-ebc1ab4a8a80', 'What does ''Beat around the bush'' mean?', NULL, 'A is correct. ''Beat around the bush'' = to avoid directly addressing the point; to talk in circles without getting to the main issue.', 'EASY', 'English', 'Idioms and Phrases (W9)', 'ENG_IDIOMS_W9', '[{"option_text": "Avoid the main topic", "is_correct": true}, {"option_text": "Search in a forest", "is_correct": false}, {"option_text": "Speak too loudly", "is_correct": false}, {"option_text": "Make a physical attack", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('27e3e283-bb92-503f-9b8f-64d4fd93826f', 'What does ''Bite the bullet'' mean?', NULL, 'B is correct. ''Bite the bullet'' = to stoically endure a painful or difficult situation. It originates from giving soldiers a bullet to bite on during surgery before anaesthesia.', 'MEDIUM', 'English', 'Idioms and Phrases (W9)', 'ENG_IDIOMS_W9', '[{"option_text": "Eat something unpleasant", "is_correct": false}, {"option_text": "Endure a painful situation with courage", "is_correct": true}, {"option_text": "Fire a weapon", "is_correct": false}, {"option_text": "Accept defeat completely", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5c1ee0e1-86e3-5b01-a9bb-893ca732133a', 'What does ''Let the cat out of the bag'' mean?', NULL, 'B is correct. ''Let the cat out of the bag'' = to accidentally disclose a secret or surprise.', 'MEDIUM', 'English', 'Idioms and Phrases (W9)', 'ENG_IDIOMS_W9', '[{"option_text": "Release a trapped animal", "is_correct": false}, {"option_text": "Accidentally reveal a secret", "is_correct": true}, {"option_text": "Create disorder", "is_correct": false}, {"option_text": "Tell an obvious lie", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('06bc575a-6728-55b8-bec1-9e4764ded839', 'What does ''Hit the nail on the head'' mean?', NULL, 'B is correct. ''Hit the nail on the head'' = to be precisely correct in describing or identifying something.', 'MEDIUM', 'English', 'Idioms and Phrases (W9)', 'ENG_IDIOMS_W9', '[{"option_text": "Cause physical damage", "is_correct": false}, {"option_text": "Describe something exactly correctly", "is_correct": true}, {"option_text": "Begin construction", "is_correct": false}, {"option_text": "Solve an engineering problem", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3715ead3-5f1d-5bc1-a23d-eabb10fcb565', 'What does ''Burn the midnight oil'' mean?', NULL, 'C is correct. ''Burn the midnight oil'' = to work very late, referring to the days when oil lamps were used for late-night work.', 'MEDIUM', 'English', 'Idioms and Phrases (W9)', 'ENG_IDIOMS_W9', '[{"option_text": "Waste valuable resources", "is_correct": false}, {"option_text": "Celebrate with fireworks", "is_correct": false}, {"option_text": "Work or study very late into the night", "is_correct": true}, {"option_text": "Destroy evidence", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e0ac8901-8155-5b92-a625-6c1429adf9df', 'What does ''Spill the beans'' mean?', NULL, 'C is correct. ''Spill the beans'' = to reveal secret information, often unintentionally.', 'MEDIUM', 'English', 'Idioms and Phrases (W9)', 'ENG_IDIOMS_W9', '[{"option_text": "Make a mess in the kitchen", "is_correct": false}, {"option_text": "Cook a meal carelessly", "is_correct": false}, {"option_text": "Reveal secret or confidential information", "is_correct": true}, {"option_text": "Cause unnecessary confusion", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7aa136d9-5310-5dba-b7a6-c645e7cac935', 'What does ''A penny for your thoughts'' mean?', NULL, 'B is correct. ''A penny for your thoughts'' = used to ask what someone is thinking about, especially when they seem distracted or quiet.', 'HARD', 'English', 'Idioms and Phrases (W9)', 'ENG_IDIOMS_W9', '[{"option_text": "Offer to buy someone''s idea", "is_correct": false}, {"option_text": "Ask what someone is thinking about", "is_correct": true}, {"option_text": "Say something is worthless", "is_correct": false}, {"option_text": "Make a small wish", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('07d79e29-8b5e-5724-91f1-344645495d69', 'What does ''Kill two birds with one stone'' mean?', NULL, 'B is correct. ''Kill two birds with one stone'' = to solve two problems or achieve two goals with a single effort or action.', 'HARD', 'English', 'Idioms and Phrases (W9)', 'ENG_IDIOMS_W9', '[{"option_text": "Hunt animals for food", "is_correct": false}, {"option_text": "Accomplish two things with a single action", "is_correct": true}, {"option_text": "Be cruel to animals", "is_correct": false}, {"option_text": "Cause twice the damage", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
