INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fc9514e3-24e8-51be-be2a-a69e9fcf89c1', 'A person who cannot read or write.', NULL, 'A is correct. ''Illiterate'' specifically means unable to read or write. Trap: ''Ignorant'' means lacking knowledge in general (not specifically literacy); ''Naive'' means simple or innocent; ''Introvert'' describes a shy or inward person — none of these relate specifically to reading/writing ability.', 'EASY', 'English', 'One Word Substitution — Meanings and Definitions (W10)', 'ENG_ONE_WORD_SUBSTITUTION_W10', '[{"option_text": "Illiterate", "is_correct": true}, {"option_text": "Ignorant", "is_correct": false}, {"option_text": "Naive", "is_correct": false}, {"option_text": "Introvert", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2ae5b091-1357-5bab-b97e-68e49366340c', 'The art of beautiful handwriting.', NULL, 'A is correct. ''Calligraphy'' comes from Greek kallos (beauty) + graphia (writing) — the art of producing decorative, beautiful handwriting. Trap: ''Typography'' is the art of arranging printed type (not handwriting); ''Lithography'' is a printing technique; ''Photography'' records images with light.', 'EASY', 'English', 'One Word Substitution — Meanings and Definitions (W10)', 'ENG_ONE_WORD_SUBSTITUTION_W10', '[{"option_text": "Calligraphy", "is_correct": true}, {"option_text": "Photography", "is_correct": false}, {"option_text": "Typography", "is_correct": false}, {"option_text": "Lithography", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('12eb4ff6-271c-5000-bb3c-b57621096c6f', 'A speech delivered without prior preparation or notes.', NULL, 'C is correct. ''Extempore'' (from Latin ex tempore = out of the moment) means spoken without preparation, on the spur of the moment. Trap: ''Eulogy'' is a speech in praise of someone (often a funeral speech); ''Soliloquy'' is a theatrical device where a character speaks thoughts aloud; ''Monologue'' is a long speech by one person but may be prepared.', 'MEDIUM', 'English', 'One Word Substitution — Meanings and Definitions (W10)', 'ENG_ONE_WORD_SUBSTITUTION_W10', '[{"option_text": "Eulogy", "is_correct": false}, {"option_text": "Soliloquy", "is_correct": false}, {"option_text": "Extempore", "is_correct": true}, {"option_text": "Monologue", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0ba4fb5a-662d-55f4-ae49-0b47d2e7eade', 'An abnormal fear of heights.', NULL, 'B is correct. ''Acrophobia'' = fear of heights (acro- = peak/top). Trap: ''Claustrophobia'' = fear of enclosed spaces; ''Agoraphobia'' = fear of open or crowded public spaces; ''Hydrophobia'' = fear of water (also a symptom of rabies). SSC regularly tests the phobia vocabulary — acro/claustro/agora/hydro are the four most tested.', 'MEDIUM', 'English', 'One Word Substitution — Meanings and Definitions (W10)', 'ENG_ONE_WORD_SUBSTITUTION_W10', '[{"option_text": "Claustrophobia", "is_correct": false}, {"option_text": "Acrophobia", "is_correct": true}, {"option_text": "Agoraphobia", "is_correct": false}, {"option_text": "Hydrophobia", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('69bc0a4d-27c0-5f7a-933d-19657ae17fcd', 'An animal that eats both plants and other animals.', NULL, 'C is correct. ''Omnivore'' = eats both plant and animal matter (omni- = all). Trap: ''Carnivore'' = eats only meat; ''Herbivore'' = eats only plants; ''Insectivore'' = eats insects. Humans are omnivores; lions are carnivores; cows are herbivores.', 'MEDIUM', 'English', 'One Word Substitution — Meanings and Definitions (W10)', 'ENG_ONE_WORD_SUBSTITUTION_W10', '[{"option_text": "Carnivore", "is_correct": false}, {"option_text": "Herbivore", "is_correct": false}, {"option_text": "Omnivore", "is_correct": true}, {"option_text": "Insectivore", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8ff7174c-8122-5301-adc4-6f6fe8d77213', 'The branch of linguistics concerned with the origin and historical development of words.', NULL, 'C is correct. ''Etymology'' studies the origin and historical development of words (etymon = true sense of a word, in Greek). Trap: ''Phonology'' studies the sound systems of language; ''Lexicology'' studies vocabulary and word meaning (synchronic, not historical); ''Morphology'' studies word structure and forms (prefixes, roots, suffixes).', 'MEDIUM', 'English', 'One Word Substitution — Meanings and Definitions (W10)', 'ENG_ONE_WORD_SUBSTITUTION_W10', '[{"option_text": "Phonology", "is_correct": false}, {"option_text": "Lexicology", "is_correct": false}, {"option_text": "Etymology", "is_correct": true}, {"option_text": "Morphology", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e38c3716-0540-5f8a-a57c-d457eb98d089', 'A person who pretends to have religious virtues or moral beliefs that they do not actually possess.', NULL, 'B is correct. ''Hypocrite'' = one who feigns virtue or moral correctness while privately behaving otherwise. Trap: ''Agnostic'' = one who believes nothing can be known about God''s existence (no moral pretence implied); ''Atheist'' = one who disbelieves in God (openly, not pretending); ''Apostate'' = one who abandons their religion (an act of leaving, not pretending).', 'HARD', 'English', 'One Word Substitution — Meanings and Definitions (W10)', 'ENG_ONE_WORD_SUBSTITUTION_W10', '[{"option_text": "Agnostic", "is_correct": false}, {"option_text": "Hypocrite", "is_correct": true}, {"option_text": "Atheist", "is_correct": false}, {"option_text": "Apostate", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9d3df2d5-08bd-5d62-9002-4f2ca8312cea', 'A remedy or solution believed to cure all diseases or solve all problems.', NULL, 'C is correct. ''Panacea'' = a universal remedy for all ills (from Greek pan = all + akeia = remedy; also the name of the goddess of healing). Trap: ''Antidote'' counteracts a specific poison; ''Placebo'' is an inert substance that produces psychological improvement; ''Vaccine'' prevents specific diseases through immunity — none are universal solutions.', 'HARD', 'English', 'One Word Substitution — Meanings and Definitions (W10)', 'ENG_ONE_WORD_SUBSTITUTION_W10', '[{"option_text": "Antidote", "is_correct": false}, {"option_text": "Placebo", "is_correct": false}, {"option_text": "Panacea", "is_correct": true}, {"option_text": "Vaccine", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('11b6aa23-b311-52f3-9005-cfd0ab8f2fd4', 'The act of killing one''s own father.', NULL, 'B is correct. ''Patricide'' = killing of one''s father (pater = father). Trap: ''Parricide'' is broader — killing of either parent or a close relative; ''Matricide'' = killing of one''s mother (mater); ''Fratricide'' = killing of one''s brother (frater). SSC tests the -cide words frequently: patricide/matricide/fratricide/infanticide/homicide/regicide.', 'HARD', 'English', 'One Word Substitution — Meanings and Definitions (W10)', 'ENG_ONE_WORD_SUBSTITUTION_W10', '[{"option_text": "Parricide", "is_correct": false}, {"option_text": "Patricide", "is_correct": true}, {"option_text": "Matricide", "is_correct": false}, {"option_text": "Fratricide", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e2901567-4350-52ba-a71b-b173a8092be4', 'The policy of extending a nation''s power and influence through military force, colonization, or economic domination over other territories.', NULL, 'C is correct. ''Imperialism'' = the policy of extending a country''s power over others through conquest or dominance (empire-building). Trap: ''Nationalism'' = devotion to one''s own nation (internal pride, not expansion); ''Socialism'' = collective ownership of production (economic philosophy); ''Federalism'' = division of power between central and regional governments (structural governance).', 'HARD', 'English', 'One Word Substitution — Meanings and Definitions (W10)', 'ENG_ONE_WORD_SUBSTITUTION_W10', '[{"option_text": "Nationalism", "is_correct": false}, {"option_text": "Socialism", "is_correct": false}, {"option_text": "Imperialism", "is_correct": true}, {"option_text": "Federalism", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('94b6ffc5-0369-510f-baa0-8ab013d82a3c', 'One who is able to use both hands with equal ease:', NULL, 'B is correct. AMBIDEXTROUS = able to use both hands equally well (ambi = both, dexter = right hand/skillful). Trap: Ambiguous = having two possible meanings (ambi = both, agere = to drive); Ambivalent = having mixed feelings about something; Amphibious = able to live/operate on land and water.', 'EASY', 'English', 'One Word Substitution — Advanced Set (W11 B1)', 'ENG_ONE_WORD_SUBSTITUTION_W11_B1', '[{"option_text": "Ambiguous", "is_correct": false}, {"option_text": "Ambidextrous", "is_correct": true}, {"option_text": "Ambivalent", "is_correct": false}, {"option_text": "Amphibious", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0233426a-951f-59ad-8ab6-862c23ced160', 'A person who speaks many languages:', NULL, 'C is correct. POLYGLOT = a person who knows and uses many languages (Greek: poly = many, glotta = tongue/language). Trap: Multilingual = adjective describing someone who knows multiple languages; Bilingual = someone who knows two languages specifically; Linguist = a person who studies language or is skilled in languages (but not specifically ''many''). ''Polyglot'' is the precise one-word substitution for ''many languages''.', 'MEDIUM', 'English', 'One Word Substitution — Advanced Set (W11 B1)', 'ENG_ONE_WORD_SUBSTITUTION_W11_B1', '[{"option_text": "Multilingual", "is_correct": false}, {"option_text": "Bilingual", "is_correct": false}, {"option_text": "Polyglot", "is_correct": true}, {"option_text": "Linguist", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('794277e1-136a-5f8e-ba17-f22772f52451', 'A place where bees are kept:', NULL, 'C is correct. APIARY = a place where bees are kept (Latin: apis = bee). Trap: Aquarium = place where aquatic animals are kept; Aviary = a large enclosure for keeping birds (avis = bird); Sanctuary = a place of refuge for animals generally. Note: The beekeeper is called an APIARIST.', 'MEDIUM', 'English', 'One Word Substitution — Advanced Set (W11 B1)', 'ENG_ONE_WORD_SUBSTITUTION_W11_B1', '[{"option_text": "Aquarium", "is_correct": false}, {"option_text": "Aviary", "is_correct": false}, {"option_text": "Apiary", "is_correct": true}, {"option_text": "Sanctuary", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4ecbdae8-c5d6-51ec-b15e-1e47dcfdb2a8', 'One who is recovering from illness:', NULL, 'B is correct. CONVALESCENT = a person who is recovering from illness. Convalescence = the period of recovery. Trap: Hypochondriac = a person who is excessively worried about being ill; Recuperative = adjective (recuperative powers) not a noun for person; Ambulatory = able to walk about, not specifically about recovering from illness.', 'MEDIUM', 'English', 'One Word Substitution — Advanced Set (W11 B1)', 'ENG_ONE_WORD_SUBSTITUTION_W11_B1', '[{"option_text": "Hypochondriac", "is_correct": false}, {"option_text": "Convalescent", "is_correct": true}, {"option_text": "Recuperative", "is_correct": false}, {"option_text": "Ambulatory", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0959e94e-45a9-52c9-b626-eeaf0ee39661', 'Something that cannot be seen through; not transparent:', NULL, 'C is correct. OPAQUE = not able to be seen through; not transparent. Trap: Translucent = allowing light to pass through but not fully clear (between transparent and opaque); Opalescent = showing changing colours like an opal (shimmery); Imperceptible = unable to be perceived by the senses (different sense: hearing/feeling not visibility).', 'EASY', 'English', 'One Word Substitution — Advanced Set (W11 B1)', 'ENG_ONE_WORD_SUBSTITUTION_W11_B1', '[{"option_text": "Translucent", "is_correct": false}, {"option_text": "Opalescent", "is_correct": false}, {"option_text": "Opaque", "is_correct": true}, {"option_text": "Imperceptible", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3a2e47e9-d1db-58af-bcca-4acf0e89affd', 'Murder of a king:', NULL, 'C is correct. REGICIDE = the killing of a king (Latin: rex/regis = king, caedere = to kill). Trap: Homicide = killing of a human being; Patricide = killing of one''s father; Fratricide = killing of one''s brother. Other ''-cide'' words: Infanticide (killing of infant), Suicide (killing of self/sui), Genocide (killing of a racial group/genos), Deicide (killing of a god), Uxoricide (killing of one''s wife/uxor).', 'HARD', 'English', 'One Word Substitution — Advanced Set (W11 B1)', 'ENG_ONE_WORD_SUBSTITUTION_W11_B1', '[{"option_text": "Homicide", "is_correct": false}, {"option_text": "Patricide", "is_correct": false}, {"option_text": "Regicide", "is_correct": true}, {"option_text": "Fratricide", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6c898911-1ff7-5852-a076-922225db9055', 'A person who is indifferent to pleasure and pain; one who endures hardship without complaint:', NULL, 'B is correct. STOIC = a person who endures pain or hardship without complaint or shows indifference to pleasure/pain. From the Stoic philosophical school of ancient Greece. Trap: Cynic = a person who believes that people are motivated purely by self-interest; Hedonist = a person who believes pleasure is the highest good (opposite — seeks pleasure); Ascetic = a person who practises severe self-discipline and abstains from pleasure (related but focuses on self-denial, not indifference).', 'HARD', 'English', 'One Word Substitution — Advanced Set (W11 B1)', 'ENG_ONE_WORD_SUBSTITUTION_W11_B1', '[{"option_text": "Cynic", "is_correct": false}, {"option_text": "Stoic", "is_correct": true}, {"option_text": "Hedonist", "is_correct": false}, {"option_text": "Ascetic", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('23cdfb49-6759-5fb7-b096-b407d15bc33f', 'A collection of poems:', NULL, 'A is correct. ANTHOLOGY = a published collection of poems or other pieces of writing (originally: a ''gathering of flowers''). Trap: Bibliography = a list of books or articles on a subject; Epitaph = a short text written on a tombstone or in memory of a dead person; Elegy = a mournful poem for a dead person (one poem, not a collection).', 'EASY', 'English', 'One Word Substitution — Advanced Set (W11 B1)', 'ENG_ONE_WORD_SUBSTITUTION_W11_B1', '[{"option_text": "Anthology", "is_correct": true}, {"option_text": "Bibliography", "is_correct": false}, {"option_text": "Epitaph", "is_correct": false}, {"option_text": "Elegy", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('708047a6-4ebb-5b7c-8d2d-a67c1b5235b3', 'One who walks in sleep:', NULL, 'C is correct. SOMNAMBULIST = one who walks in sleep; sleepwalker (Latin: somnus = sleep, ambulare = to walk). The condition = somnambulism. Trap: Insomniac = a person who is unable to sleep; Narcissist = a person with excessive admiration for oneself; Hypochondriac = one who excessively worries about being ill. Other ''somn-'' words: Somnolent (drowsy), Insomnia (inability to sleep).', 'HARD', 'English', 'One Word Substitution — Advanced Set (W11 B1)', 'ENG_ONE_WORD_SUBSTITUTION_W11_B1', '[{"option_text": "Insomniac", "is_correct": false}, {"option_text": "Narcissist", "is_correct": false}, {"option_text": "Somnambulist", "is_correct": true}, {"option_text": "Hypochondriac", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6ac8c3d7-52ab-51b8-8748-8caf4b2564cd', 'A government run by the representatives of the people:', NULL, 'D is correct. DEMOCRACY = government by the people or their elected representatives (Greek: demos = people, kratos = rule). Trap: Aristocracy = government by a privileged class/nobility (aristos = best); Autocracy = government by a single person with absolute power (autos = self); Theocracy = government by religious leaders or priests claiming divine guidance (theos = god).', 'EASY', 'English', 'One Word Substitution — Advanced Set (W11 B1)', 'ENG_ONE_WORD_SUBSTITUTION_W11_B1', '[{"option_text": "Aristocracy", "is_correct": false}, {"option_text": "Autocracy", "is_correct": false}, {"option_text": "Theocracy", "is_correct": false}, {"option_text": "Democracy", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('03f4c081-0878-5491-81c5-a043c204ff58', 'A person who has a strong hatred of and contempt for the human race is called a ___.', NULL, 'C is correct. MISANTHROPE = a person who dislikes or distrusts humankind in general (from Greek misein = hate + anthropos = human being). Famous literary misanthropes: Ebenezer Scrooge, Sherlock Holmes (somewhat). Trap: misogynist = hatred specifically of women (miso + gyne); philanthropist = lover of humanity (the opposite of misanthrope); pessimist = one who expects the worst (not the same as hating people).', 'EASY', 'English', 'One-Word Substitution in Context — SSC CGL Tested Vocabulary (W12 B1)', 'ENG_ONE_WORD_SUBS_CONTEXT_W12_B1', '[{"option_text": "misogynist", "is_correct": false}, {"option_text": "philanthropist", "is_correct": false}, {"option_text": "misanthrope", "is_correct": true}, {"option_text": "pessimist", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('85147274-27e7-5498-b27a-fea9ec1c8a81', 'The psychiatrist noted the patient''s intense and irrational fear of water. This condition is known as ___.', NULL, 'B is correct. HYDROPHOBIA = morbid fear of water (Greek hydro = water + phobia = fear). Also a symptom of rabies in advanced stages. Trap: acrophobia = fear of heights (acro = heights); claustrophobia = fear of confined spaces (claustro = enclosed); agoraphobia = fear of open or crowded spaces (agora = marketplace/open area). Memory tip: HYDRO = water (hydraulic, hydrant, dehydration).', 'MEDIUM', 'English', 'One-Word Substitution in Context — SSC CGL Tested Vocabulary (W12 B1)', 'ENG_ONE_WORD_SUBS_CONTEXT_W12_B1', '[{"option_text": "acrophobia", "is_correct": false}, {"option_text": "hydrophobia", "is_correct": true}, {"option_text": "claustrophobia", "is_correct": false}, {"option_text": "agoraphobia", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0aa364a6-02dc-5c20-8523-972d2da409e3', 'A system of government in which the supreme power lies with the people, exercised directly or through elected representatives, is called ___.', NULL, 'D is correct. DEMOCRACY = government by the people (Greek demos = people + kratos = rule/power). Lincoln: ''government of the people, by the people, for the people.'' Trap: oligarchy = rule by a small group of powerful people; theocracy = rule by religious authority or God''s law; autocracy = rule by one person with absolute power (auto = self). All end in ''-cracy'' (rule) but have different prefix meanings.', 'EASY', 'English', 'One-Word Substitution in Context — SSC CGL Tested Vocabulary (W12 B1)', 'ENG_ONE_WORD_SUBS_CONTEXT_W12_B1', '[{"option_text": "oligarchy", "is_correct": false}, {"option_text": "theocracy", "is_correct": false}, {"option_text": "autocracy", "is_correct": false}, {"option_text": "democracy", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e2061ff4-0428-5e7f-b27d-2862fd8fe266', 'The zoo''s new facility, where birds of various species live in a large enclosed space, is called an ___.', NULL, 'B is correct. AVIARY = a large enclosure for keeping birds in captivity (Latin avis = bird). Trap: apiary = a place where bees are kept (Latin apis = bee); aquarium = where fish/aquatic animals are kept (Latin aqua = water); herbarium = a collection of dried, pressed plants (Latin herba = plant/grass). Key root: AVI = bird (aviation, aviator — both involve flying, like birds).', 'MEDIUM', 'English', 'One-Word Substitution in Context — SSC CGL Tested Vocabulary (W12 B1)', 'ENG_ONE_WORD_SUBS_CONTEXT_W12_B1', '[{"option_text": "apiary", "is_correct": false}, {"option_text": "aviary", "is_correct": true}, {"option_text": "aquarium", "is_correct": false}, {"option_text": "herbarium", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('69df1ce1-b8c4-5f76-badf-5902ff3df597', 'The doctor found the patient walking around the hospital corridors with eyes open but completely unconscious, a condition called ___.', NULL, 'C is correct. SOMNAMBULISM = the condition of walking and sometimes performing other actions while asleep; sleepwalking (Latin somnus = sleep + ambulare = to walk). Trap: insomnia = inability to sleep (Latin in- = not + somnus = sleep); hypnosis = induced sleep-like trance (for suggestion); narcolepsy = uncontrollable attacks of deep sleep during the day. Mnemonic: SOMN = sleep (somnolent = drowsy), AMBLE = walk (ambulance = vehicle that carries).', 'MEDIUM', 'English', 'One-Word Substitution in Context — SSC CGL Tested Vocabulary (W12 B1)', 'ENG_ONE_WORD_SUBS_CONTEXT_W12_B1', '[{"option_text": "insomnia", "is_correct": false}, {"option_text": "hypnosis", "is_correct": false}, {"option_text": "somnambulism", "is_correct": true}, {"option_text": "narcolepsy", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c3656e5a-5220-580b-8ffa-64f5e1898b57', 'His grandfather collected ancient Roman coins and medals, a hobby known as ___.', NULL, 'B is correct. NUMISMATICS = the study or collection of coins, paper money, and medals (Latin numisma = coin, from Greek nomisma = current coin). Trap: philately = the collection and study of postage stamps (Greek philos = loving + ateleia = tax-free, referring to prepaid postage); cartophily = collection of cigarette cards; ''numismatology'' = not a real standard English word (numismatics is the accepted term). SSC PYQ favourite: philately (stamps) vs numismatics (coins).', 'MEDIUM', 'English', 'One-Word Substitution in Context — SSC CGL Tested Vocabulary (W12 B1)', 'ENG_ONE_WORD_SUBS_CONTEXT_W12_B1', '[{"option_text": "philately", "is_correct": false}, {"option_text": "numismatics", "is_correct": true}, {"option_text": "numismatology", "is_correct": false}, {"option_text": "cartophily", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('51a9044e-5e5e-51fd-bab9-635824d3ab26', 'The manager suspected that the employee was pretending to be sick to avoid a difficult assignment — a behaviour described as ___.', NULL, 'A is correct. MALINGERING = deliberately feigning or exaggerating illness or incapacity to avoid duty or work, especially in a military or employment context (origin uncertain, possibly from French malingre = weakly sickly). One who does it: a malingerer. Trap: hypochondria = genuinely believing oneself to be ill when one is not (the hypochondriac is sincere, not faking); feigning = pretending in general (a verb, not a noun label for the specific behaviour); shirking = avoiding work but not specifically by faking illness — the one-word substitution that most precisely fits is malingering.', 'HARD', 'English', 'One-Word Substitution in Context — SSC CGL Tested Vocabulary (W12 B1)', 'ENG_ONE_WORD_SUBS_CONTEXT_W12_B1', '[{"option_text": "malingering", "is_correct": true}, {"option_text": "hypochondria", "is_correct": false}, {"option_text": "feigning", "is_correct": false}, {"option_text": "shirking", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ded58a36-c661-56f3-b510-0c34fcdf28c5', 'The minister delivered a brilliant speech on education policy without any notes or prior preparation. Such a speech is described as ___.', NULL, 'C is correct. IMPROMPTU = done without being planned or rehearsed; on the spur of the moment (Latin in promptu = in readiness, but used to mean without preparation). Also: extempore = spoken without preparation (from the same idea). Trap: verbose = using more words than necessary (the opposite quality from what''s described — the speech was brilliant); eloquent = fluent and persuasive speaking (quality of delivery, not preparation status); rehearsed = the opposite of impromptu.', 'MEDIUM', 'English', 'One-Word Substitution in Context — SSC CGL Tested Vocabulary (W12 B1)', 'ENG_ONE_WORD_SUBS_CONTEXT_W12_B1', '[{"option_text": "verbose", "is_correct": false}, {"option_text": "eloquent", "is_correct": false}, {"option_text": "impromptu", "is_correct": true}, {"option_text": "rehearsed", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('98ab25b9-7d48-5e28-9e34-0386c1444de2', 'Despite every setback, she always believed things would turn out well. Her friends called her an incurable ___.', NULL, 'A is correct. OPTIMIST = a person who tends to take a hopeful or positive view of future outcomes (from Latin optimus = best). Antonym: pessimist (expects the worst). Trap: realist = one who accepts situations as they actually are (neither optimistic nor pessimistic); altruist = one who selflessly considers others'' welfare before their own (about actions, not worldview); narcissist = one who is excessively self-admiring (personality trait, not related to outlook on events).', 'EASY', 'English', 'One-Word Substitution in Context — SSC CGL Tested Vocabulary (W12 B1)', 'ENG_ONE_WORD_SUBS_CONTEXT_W12_B1', '[{"option_text": "optimist", "is_correct": true}, {"option_text": "realist", "is_correct": false}, {"option_text": "altruist", "is_correct": false}, {"option_text": "narcissist", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5309ae96-4984-58db-a918-35df6abcc92f', 'Professor Mehta is an authority on the study and collection of national flags of various countries. His area of expertise is called ___.', NULL, 'D is correct. VEXILLOLOGY = the study of flags, their history, symbolism and usage (from Latin vexillum = small sail/flag + Greek -logia = study). Coined in 1959 by Whitney Smith. Trap: heraldry = the study of coats of arms and armorial bearings (shields, family crests — not flags per se); cartography = making and studying maps (Latin charta = paper/map); numismatics = study of coins and medals (Q6). SSC occasionally tests rare -ology words: vexillology (flags), seismology (earthquakes), ornithology (birds), entomology (insects).', 'HARD', 'English', 'One-Word Substitution in Context — SSC CGL Tested Vocabulary (W12 B1)', 'ENG_ONE_WORD_SUBS_CONTEXT_W12_B1', '[{"option_text": "heraldry", "is_correct": false}, {"option_text": "numismatics", "is_correct": false}, {"option_text": "cartography", "is_correct": false}, {"option_text": "vexillology", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a651ff4c-2115-5d2f-9dfe-a7b7d126bb69', 'One who has no faith in the existence of God.', NULL, 'B is correct. An atheist denies the existence of God. An agnostic believes it is unknowable; a theist believes in God.', 'EASY', 'English', 'One Word Substitution (W9)', 'ENG_ONE_WORD_W9', '[{"option_text": "Agnostic", "is_correct": false}, {"option_text": "Atheist", "is_correct": true}, {"option_text": "Theist", "is_correct": false}, {"option_text": "Pessimist", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('baa3aeff-34c7-58db-9b91-8958aa00d36c', 'A person who travels to a holy place as an act of devotion.', NULL, 'C is correct. A pilgrim travels to a sacred place for religious reasons. A nomad/vagrant moves without a fixed destination.', 'EASY', 'English', 'One Word Substitution (W9)', 'ENG_ONE_WORD_W9', '[{"option_text": "Nomad", "is_correct": false}, {"option_text": "Vagrant", "is_correct": false}, {"option_text": "Pilgrim", "is_correct": true}, {"option_text": "Wanderer", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9f7e434a-5fb0-5d5b-a4f5-401357b482f6', 'A speech delivered without any prior preparation.', NULL, 'C is correct. Extempore (or impromptu) means delivered without preparation. A soliloquy is a character''s thoughts spoken aloud; a monologue is a long solo speech.', 'EASY', 'English', 'One Word Substitution (W9)', 'ENG_ONE_WORD_W9', '[{"option_text": "Manuscript", "is_correct": false}, {"option_text": "Soliloquy", "is_correct": false}, {"option_text": "Extempore", "is_correct": true}, {"option_text": "Monologue", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3ba73323-5700-59b4-8cbb-2aa45d69a1ba', 'One who eats both plants and animals.', NULL, 'C is correct. Omnivore (Latin: omni = all). Herbivore = plants only; Carnivore = flesh only; Insectivore = insects.', 'MEDIUM', 'English', 'One Word Substitution (W9)', 'ENG_ONE_WORD_W9', '[{"option_text": "Herbivore", "is_correct": false}, {"option_text": "Carnivore", "is_correct": false}, {"option_text": "Omnivore", "is_correct": true}, {"option_text": "Insectivore", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1129c8d2-0b34-5ab6-a88d-1d39d2597402', 'A place where bees are kept.', NULL, 'B is correct. Apiary (Latin: apis = bee). Aviary = birds; Aquarium = fish; Sanatorium = recovering patients.', 'MEDIUM', 'English', 'One Word Substitution (W9)', 'ENG_ONE_WORD_W9', '[{"option_text": "Aviary", "is_correct": false}, {"option_text": "Apiary", "is_correct": true}, {"option_text": "Aquarium", "is_correct": false}, {"option_text": "Sanatorium", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('918af5d1-3c8f-52df-af79-71332cc4dc11', 'The scientific study of coins and medals.', NULL, 'B is correct. Numismatics = study of coins. Philately = stamp collecting; Heraldry = coats of arms; Genealogy = family history.', 'MEDIUM', 'English', 'One Word Substitution (W9)', 'ENG_ONE_WORD_W9', '[{"option_text": "Philately", "is_correct": false}, {"option_text": "Numismatics", "is_correct": true}, {"option_text": "Heraldry", "is_correct": false}, {"option_text": "Genealogy", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('00e5d13c-c5ad-593e-ad6d-3fe968d1716f', 'One who believes in or practises self-discipline and abstains from pleasure.', NULL, 'B is correct. An ascetic deliberately avoids sensual pleasures. A stoic endures pain without complaint; a hedonist pursues pleasure; a cynic distrusts human sincerity.', 'MEDIUM', 'English', 'One Word Substitution (W9)', 'ENG_ONE_WORD_W9', '[{"option_text": "Cynic", "is_correct": false}, {"option_text": "Ascetic", "is_correct": true}, {"option_text": "Stoic", "is_correct": false}, {"option_text": "Hedonist", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('86da9ac8-a848-50ca-8e17-559ce41116f0', 'A doctor who specialises in the diagnosis and treatment of mental disorders.', NULL, 'C is correct. A psychiatrist is a medical doctor who treats mental illness. A psychologist studies behaviour but is not a medical doctor; a neurologist treats brain/nerve disorders.', 'MEDIUM', 'English', 'One Word Substitution (W9)', 'ENG_ONE_WORD_W9', '[{"option_text": "Psychologist", "is_correct": false}, {"option_text": "Neurologist", "is_correct": false}, {"option_text": "Psychiatrist", "is_correct": true}, {"option_text": "Physiologist", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5f1c0ccc-2c45-5928-9af9-89ed51c51d03', 'Government by the mob or the undisciplined masses.', NULL, 'C is correct. Mobocracy = rule by a mob. Theocracy = rule by clergy; Oligarchy = rule by a few; Plutocracy = rule by the wealthy.', 'HARD', 'English', 'One Word Substitution (W9)', 'ENG_ONE_WORD_W9', '[{"option_text": "Theocracy", "is_correct": false}, {"option_text": "Oligarchy", "is_correct": false}, {"option_text": "Mobocracy", "is_correct": true}, {"option_text": "Plutocracy", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2706b2c0-22e0-5062-aa2b-79d55a891621', 'An extreme or irrational fear of being in enclosed spaces.', NULL, 'B is correct. Claustrophobia = fear of confined spaces (Latin: claustrum = enclosed). Agoraphobia = fear of open/public places; Xenophobia = fear of foreigners; Hydrophobia = fear of water.', 'HARD', 'English', 'One Word Substitution (W9)', 'ENG_ONE_WORD_W9', '[{"option_text": "Agoraphobia", "is_correct": false}, {"option_text": "Claustrophobia", "is_correct": true}, {"option_text": "Xenophobia", "is_correct": false}, {"option_text": "Hydrophobia", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b6cc2f6f-312a-56e2-adc0-1b069f7613e6', 'Choose the sentence that best completes the paragraph:
