INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('86d6d813-d42a-50db-bb15-24cc5242ba85', 'Choose the best sentence to fill the BLANK in the paragraph:
