INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8f443603-b28e-5295-a605-7ab15b2f4b04', 'Choose the sentence that best completes the paragraph:
