INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5bbfe109-113b-531d-a130-27f42e46b627', 'Improve the underlined part: ''He is one of the best __student__ in the class.''', NULL, 'A is correct. ''One of the best'' is always followed by a plural noun. ''Students'' is the correct form.', 'EASY', 'English', 'Sentence Improvement (W9)', 'ENG_SENTENCE_IMPROVEMENT_W9', '[{"option_text": "students", "is_correct": true}, {"option_text": "student''s", "is_correct": false}, {"option_text": "best student", "is_correct": false}, {"option_text": "No improvement", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5d75fe07-fc42-5e0b-8b71-eb8d4ec2d9b5', 'Improve the underlined part: ''I have been living here __since__ five years.''', NULL, 'A is correct. ''For'' is used with a period/duration of time (''five years''). ''Since'' is used with a point in time (''since 2019'').', 'EASY', 'English', 'Sentence Improvement (W9)', 'ENG_SENTENCE_IMPROVEMENT_W9', '[{"option_text": "for", "is_correct": true}, {"option_text": "from", "is_correct": false}, {"option_text": "within", "is_correct": false}, {"option_text": "No improvement", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ddcb1a3e-a0f4-52a6-b87d-dd82b15703ae', 'Improve the underlined part: ''She is more beautiful than __any girl__ in her class.''', NULL, 'A is correct. When comparing a member to others in the same group, ''other'' is needed: ''any other girl'' (to exclude herself). Without ''other'' she would be compared to herself, creating a contradiction.', 'EASY', 'English', 'Sentence Improvement (W9)', 'ENG_SENTENCE_IMPROVEMENT_W9', '[{"option_text": "any other girl", "is_correct": true}, {"option_text": "some girl", "is_correct": false}, {"option_text": "any other girls", "is_correct": false}, {"option_text": "No improvement", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6a2ecbdb-44a1-5848-b00b-53fed1892c4a', 'Improve the underlined part: ''The teacher as well as the students __were__ tired.''', NULL, 'A is correct. ''As well as'' does not compound the subject. The verb agrees with ''teacher'' (singular) → ''was''. (Unlike ''and'', ''as well as'' makes the second noun parenthetical.)', 'MEDIUM', 'English', 'Sentence Improvement (W9)', 'ENG_SENTENCE_IMPROVEMENT_W9', '[{"option_text": "was", "is_correct": true}, {"option_text": "are", "is_correct": false}, {"option_text": "have been", "is_correct": false}, {"option_text": "No improvement", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f6a27f84-4fa0-5364-a2b8-011cafb7457b', 'Improve the underlined part: ''She prefers tea __than__ coffee.''', NULL, 'A is correct. ''Prefer...to'' is the standard structure. ''Prefer...than'' is incorrect in formal grammar.', 'MEDIUM', 'English', 'Sentence Improvement (W9)', 'ENG_SENTENCE_IMPROVEMENT_W9', '[{"option_text": "to", "is_correct": true}, {"option_text": "over", "is_correct": false}, {"option_text": "from", "is_correct": false}, {"option_text": "No improvement", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ff966049-162e-5d7a-8fc3-4171aaa85788', 'Improve the underlined part: ''__Having finished the work__, the room was left.''', NULL, 'A is correct. The original has a dangling modifier — the implied subject of ''having finished'' must match the main clause subject. ''He left the room'' fixes this.', 'MEDIUM', 'English', 'Sentence Improvement (W9)', 'ENG_SENTENCE_IMPROVEMENT_W9', '[{"option_text": "Having finished the work, he left the room", "is_correct": true}, {"option_text": "After finishing the work, the room was vacated", "is_correct": false}, {"option_text": "Having done the work, the room was left", "is_correct": false}, {"option_text": "No improvement", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a611da9d-3174-54d5-808d-fbcc450567ba', 'Improve the underlined part: ''He is senior __than__ me by three years.''', NULL, 'A is correct. Senior, junior, superior, inferior, prior, anterior are Latin comparatives and always take ''to'', never ''than''.', 'MEDIUM', 'English', 'Sentence Improvement (W9)', 'ENG_SENTENCE_IMPROVEMENT_W9', '[{"option_text": "to", "is_correct": true}, {"option_text": "than to", "is_correct": false}, {"option_text": "of", "is_correct": false}, {"option_text": "No improvement", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0d41b70f-0a6b-5494-afa5-bb638afff231', 'Improve the underlined part: ''__If I would have known__, I would have helped him.''', NULL, 'A is correct. Third conditional (unreal past): ''If + past perfect, would + have + past participle''. ''Would have'' cannot appear in the if-clause.', 'HARD', 'English', 'Sentence Improvement (W9)', 'ENG_SENTENCE_IMPROVEMENT_W9', '[{"option_text": "If I had known", "is_correct": true}, {"option_text": "If I would know", "is_correct": false}, {"option_text": "Had I have known", "is_correct": false}, {"option_text": "No improvement", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('00126cf6-61fd-5576-bd2a-8c2b181c2e9a', 'Improve the underlined part: ''He denied __to have taken__ the money.''', NULL, 'A is correct. ''Deny'' is followed by a gerund, not an infinitive: ''denied having taken''. ''Denied to have taken'' is incorrect.', 'HARD', 'English', 'Sentence Improvement (W9)', 'ENG_SENTENCE_IMPROVEMENT_W9', '[{"option_text": "having taken", "is_correct": true}, {"option_text": "to take", "is_correct": false}, {"option_text": "of taking", "is_correct": false}, {"option_text": "No improvement", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5d21bcc4-e38a-568c-a60d-f5f489cd79c5', 'Improve the underlined part: ''The jury __have given__ their verdict.''', NULL, 'A is correct. In formal/examination English, collective nouns like ''jury'' acting as a single unit take a singular verb (''has'') and singular pronoun (''its''). Full correction: ''has given its verdict''.', 'HARD', 'English', 'Sentence Improvement (W9)', 'ENG_SENTENCE_IMPROVEMENT_W9', '[{"option_text": "has given its", "is_correct": true}, {"option_text": "has given their", "is_correct": false}, {"option_text": "have given its", "is_correct": false}, {"option_text": "No improvement", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('35413af7-b267-59c3-ac35-5a8afe24e22d', 'Rearrange the following sentences (P, Q, R, S) to form a coherent paragraph. Choose the correct order.
