INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('915e2d23-74d7-5e49-9810-1eabb584963e', 'Choose the sentence that does NOT fit logically in the paragraph below:
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('889c5810-e681-5ec3-9fce-4469470f2757', 'Arrange P, Q, R, S into a coherent paragraph: P: This was largely because of improvements in sanitation, vaccination programmes and better nutrition. Q: The 20th century witnessed a dramatic increase in human life expectancy across the globe. R: By the end of the century, the average person in many countries could expect to live well past seventy. S: In 1900, average life expectancy in much of the world was below forty years.', NULL, 'A (QSPR) is correct. Q introduces the topic (''20th century, dramatic increase in life expectancy''). S provides the starting baseline (''In 1900, below forty years'' — a contrast to the dramatic increase). P explains the reason (''This was largely because of...'' — ''This'' refers back to the increase). R gives the outcome/evidence (''by end of century, past seventy'' — confirming the dramatic increase). QSPR: Topic→Baseline→Reason→Outcome. Signal: ''This'' in P refers to the improvement mentioned in context of S and Q.', 'EASY', 'English', 'Sentence Rearrangement — Para Jumbles with Signal Words (W12 B1)', 'ENG_SENTENCE_REARRANGEMENT_W12_B1', '[{"option_text": "QSPR", "is_correct": true}, {"option_text": "SQPR", "is_correct": false}, {"option_text": "QRSP", "is_correct": false}, {"option_text": "SQRP", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('865d642c-de03-530c-bf47-e057c3f33b6d', 'In the arrangement QSPR (Q1), which sentence comes LAST?', NULL, 'D is correct. In QSPR: 1st=Q, 2nd=S, 3rd=P, 4th/last=R. R (''By the end of the century, the average person could expect to live well past seventy'') serves as the concluding evidence confirming the dramatic increase mentioned in Q. It provides the final statistic that completes the argument.', 'EASY', 'English', 'Sentence Rearrangement — Para Jumbles with Signal Words (W12 B1)', 'ENG_SENTENCE_REARRANGEMENT_W12_B1', '[{"option_text": "Q", "is_correct": false}, {"option_text": "S", "is_correct": false}, {"option_text": "P", "is_correct": false}, {"option_text": "R", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('89d599f4-2527-5a01-b198-ca2dad2f6127', 'Arrange P, Q, R, S into a coherent paragraph: P: In fact, scientists estimate that billions of neurons fire simultaneously during the process of dreaming. Q: For centuries, humans have been fascinated by the mysterious nature of dreams. R: Modern neuroscience has begun to shed light on what happens in the brain during sleep. S: Dreams involve far more complex brain activity than was previously believed.', NULL, 'A (QRSP) is correct. Q introduces the general topic (humans fascinated by dreams historically). R transitions to modern science (''modern neuroscience has begun to shed light on what happens during sleep''). S makes a specific claim (''dreams involve far more complex activity than previously believed'') — ''previously believed'' links back to the historical view in Q, now updated by R. P provides supporting evidence (''In fact, scientists estimate billions of neurons fire simultaneously'') — ''In fact'' signals concrete support for S''s claim. Order: QRSP = General→Modern Science→Claim→Evidence.', 'MEDIUM', 'English', 'Sentence Rearrangement — Para Jumbles with Signal Words (W12 B1)', 'ENG_SENTENCE_REARRANGEMENT_W12_B1', '[{"option_text": "QRSP", "is_correct": true}, {"option_text": "QRPS", "is_correct": false}, {"option_text": "SRQP", "is_correct": false}, {"option_text": "RQSP", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c8e9a8f5-3559-55cd-bd93-49077c8fae84', 'Arrange P, Q, R, S: P: However, with increasing globalisation, English has become the dominant language of international commerce, science and diplomacy. Q: Throughout history, different languages have served as global lingua francas. R: Latin once served this role in medieval Europe, while Arabic was dominant in the medieval Islamic world. S: Whether this is a blessing or a cultural loss is debated by linguists worldwide.', NULL, 'A (QRPS) is correct. Q introduces the historical theme (different lingua francas throughout history). R gives examples (Latin in medieval Europe, Arabic in Islamic world) — ''once served this role'' references Q''s ''served as global lingua francas''. P introduces the contrast with modern times (''However, with globalisation, English has become dominant'') — ''However'' signals a turn from historical examples to the present. S concludes with the debate this situation generates. QRPS: Historical claim→Examples→Modern contrast→Current debate.', 'MEDIUM', 'English', 'Sentence Rearrangement — Para Jumbles with Signal Words (W12 B1)', 'ENG_SENTENCE_REARRANGEMENT_W12_B1', '[{"option_text": "QRPS", "is_correct": true}, {"option_text": "PQRS", "is_correct": false}, {"option_text": "QPRS", "is_correct": false}, {"option_text": "RQPS", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0b3b8a78-7f0b-5d46-882a-4248069f9cc3', 'Identify which sentence would be the BEST OPENING sentence for a paragraph about climate adaptation: (A) Unfortunately, mitigation efforts have so far been insufficient. (B) Many coastal cities are already constructing seawalls and redesigning drainage systems. (C) Climate change adaptation refers to adjustments in human systems to reduce harm from climate change. (D) In 2023 alone, record-breaking heatwaves caused thousands of deaths worldwide.', NULL, 'C is correct. An opening sentence for a paragraph about a concept should DEFINE or INTRODUCE the concept clearly. C provides the definition of ''climate change adaptation'' — establishing what the paragraph is about before giving examples or evidence. Trap: B gives a specific example (seawalls) — too specific for an opening that hasn''t defined the topic yet; D gives a statistic — more suited as supporting evidence than an opening; A discusses mitigation (a related but different concept) — would confuse readers as an opener for an adaptation paragraph.', 'MEDIUM', 'English', 'Sentence Rearrangement — Para Jumbles with Signal Words (W12 B1)', 'ENG_SENTENCE_REARRANGEMENT_W12_B1', '[{"option_text": "Unfortunately, mitigation efforts have so far been insufficient.", "is_correct": false}, {"option_text": "Many coastal cities are already constructing seawalls and redesigning drainage systems.", "is_correct": false}, {"option_text": "Climate change adaptation refers to adjustments in human systems to reduce harm from climate change.", "is_correct": true}, {"option_text": "In 2023 alone, record-breaking heatwaves caused thousands of deaths worldwide.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('85c9c077-efba-51ad-8862-a1c8e5132cad', 'Arrange P, Q, R, S: P: As a result, many people are turning to mindfulness meditation as a tool for managing daily stress. Q: Modern life, with its constant connectivity and relentless pace, has created unprecedented levels of psychological stress. R: Research now confirms that regular mindfulness practice reduces cortisol levels, the body''s primary stress hormone. S: Furthermore, practitioners report improvements in focus, sleep quality and emotional regulation.', NULL, 'A (QPRS) is correct. Q introduces the problem (modern life creates stress). P draws the conclusion from Q (''As a result, many are turning to mindfulness'') — ''As a result'' directly links to the stress described in Q. R provides scientific support (''Research confirms...'' — evidence for mindfulness effectiveness). S adds further benefits (''Furthermore, practitioners report...'') — ''Furthermore'' signals addition to R''s evidence. QPRS: Problem→Response→Evidence→Additional benefits. Signal words: ''As a result'' (P), ''Furthermore'' (S) are strong ordering clues.', 'MEDIUM', 'English', 'Sentence Rearrangement — Para Jumbles with Signal Words (W12 B1)', 'ENG_SENTENCE_REARRANGEMENT_W12_B1', '[{"option_text": "QPRS", "is_correct": true}, {"option_text": "PQRS", "is_correct": false}, {"option_text": "QRSP", "is_correct": false}, {"option_text": "RSPQ", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5ed91d21-a3f0-537f-bbeb-0fd415e7d7c1', 'Arrange P, Q, R, S: P: This was famously demonstrated by Copernicus, who showed the Earth revolves around the Sun, not vice versa. Q: Scientific revolutions often overturn long-held beliefs that seemed self-evidently true. R: Similarly, Darwin''s theory of evolution challenged the idea of fixed, unchanging species. S: Today, we accept these revolutionary ideas as basic scientific fact, yet both faced fierce resistance in their time.', NULL, 'A (QPRS) is correct. Q opens with the general claim (scientific revolutions overturn beliefs). P gives the first specific example (''This was famously demonstrated by Copernicus'') — ''This'' refers to the overturning described in Q. R gives a second parallel example (''Similarly, Darwin''s theory'') — ''Similarly'' signals parallel to P''s Copernicus example. S concludes by noting current acceptance despite historical resistance — ''both'' refers to Copernicus and Darwin from P and R. QPRS: Claim→Example 1→Example 2→Conclusion.', 'MEDIUM', 'English', 'Sentence Rearrangement — Para Jumbles with Signal Words (W12 B1)', 'ENG_SENTENCE_REARRANGEMENT_W12_B1', '[{"option_text": "QPRS", "is_correct": true}, {"option_text": "QRPS", "is_correct": false}, {"option_text": "PQRS", "is_correct": false}, {"option_text": "QRSP", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4722fe12-e063-5201-8650-7338a4f1dd11', 'Choose the BEST sentence to CONCLUDE this paragraph: ''Artificial intelligence is transforming industries at an unprecedented pace. From healthcare to finance, AI systems are performing tasks that once required human expertise. Companies that fail to adopt AI risk falling behind competitors who leverage its efficiency. _______________.''', NULL, 'B is correct. The paragraph ends after noting the competitive pressure to adopt AI. A strong concluding sentence should either (a) call for action, (b) identify a key challenge, or (c) provide a nuanced perspective. B (''ethical implications demand careful attention'') provides a nuanced caveat — acknowledging that despite the adoption pressure, ethics cannot be ignored. This balances the paragraph. Trap: A (Turing in the 1950s) = historical background belonging at the START, not the conclusion; C (employees enjoy AI) = too narrow and unsupported; D (''AI is a type of computer science'') = a tautological definition entirely inappropriate as a conclusion.', 'HARD', 'English', 'Sentence Rearrangement — Para Jumbles with Signal Words (W12 B1)', 'ENG_SENTENCE_REARRANGEMENT_W12_B1', '[{"option_text": "However, AI was first conceptualised in the 1950s by pioneers like Alan Turing.", "is_correct": false}, {"option_text": "The ethical implications of widespread AI adoption, however, demand careful and ongoing attention.", "is_correct": true}, {"option_text": "Many employees enjoy working alongside AI systems in modern workplaces.", "is_correct": false}, {"option_text": "In conclusion, artificial intelligence is a type of computer science.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6559cc21-87e9-5d3f-9396-525e2fe22633', 'Arrange P, Q, R, S, T into correct order: P: Moreover, excessive use of social media has been linked to anxiety, depression and lowered self-esteem, particularly in adolescents. Q: Social media platforms have revolutionised how humans communicate and share information. R: Consequently, mental health experts are calling for stricter regulation of social media algorithms that promote addictive behaviour. S: Nevertheless, these platforms present significant psychological risks when used without self-regulation. T: On the positive side, they enable instant global connectivity, support for communities and rapid information exchange.', NULL, 'A (QTSPR) is correct. Q introduces social media (''revolutionised how humans communicate''). T gives positive aspects (''On the positive side, global connectivity'') — ''on the positive side'' directly follows an introduction before introducing negatives. S signals the turn (''Nevertheless, significant psychological risks'') — ''Nevertheless'' introduces the counter-argument to T. P gives specific evidence (''Moreover, linked to anxiety'') — ''Moreover'' adds to the negatives in S. R provides the conclusion (''Consequently, experts calling for regulation'') — ''Consequently'' draws the logical outcome from P+S. QTSPR: Intro→Positive→Pivot→Evidence→Conclusion.', 'HARD', 'English', 'Sentence Rearrangement — Para Jumbles with Signal Words (W12 B1)', 'ENG_SENTENCE_REARRANGEMENT_W12_B1', '[{"option_text": "QTSPR", "is_correct": true}, {"option_text": "QSTPR", "is_correct": false}, {"option_text": "TQSPR", "is_correct": false}, {"option_text": "QTPSR", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('22d50631-612f-58e3-9d31-1879e6132320', 'Which sentence is MISPLACED in the following paragraph? ''Water scarcity is one of the defining challenges of the 21st century. [A] Melting glaciers due to climate change are reducing freshwater availability. [B] The global film industry produced over 10,000 films in 2022. [C] Agricultural irrigation accounts for approximately 70% of global freshwater use. [D] Urbanisation and population growth are placing further pressure on water resources.''', NULL, 'B is correct. The paragraph is about water scarcity. Sentences A (glaciers reducing freshwater), C (agriculture using 70% freshwater) and D (urbanisation pressuring water resources) all directly relate to water scarcity. Sentence B (''The global film industry produced over 10,000 films in 2022'') has absolutely no connection to water scarcity or freshwater resources — it is an intruder from an unrelated topic. Such ''odd sentence out'' in a passage = a misplaced sentence question type frequently seen in SSC English.', 'HARD', 'English', 'Sentence Rearrangement — Para Jumbles with Signal Words (W12 B1)', 'ENG_SENTENCE_REARRANGEMENT_W12_B1', '[{"option_text": "Sentence A (Melting glaciers)", "is_correct": false}, {"option_text": "Sentence B (Global film industry)", "is_correct": true}, {"option_text": "Sentence C (Agricultural irrigation)", "is_correct": false}, {"option_text": "Sentence D (Urbanisation)", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0e568027-b277-5bf6-994f-09b42e65df83', 'Choose the correctly spelled word:', NULL, 'B is correct: ACCOMMODATION. Memory aid: double-c (two c''s) + double-m (two m''s) + -ation. The word ''accommodate'' has double letters: acCOMModate. Trap: ''Accomodation'' (single m) and ''Acomodation'' (single c) are the most common errors.', 'EASY', 'English', 'Spelling — Commonly Misspelled Words (W10)', 'ENG_SPELLING_W10', '[{"option_text": "Accomodation", "is_correct": false}, {"option_text": "Accommodation", "is_correct": true}, {"option_text": "Acomodation", "is_correct": false}, {"option_text": "Accomadation", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('790d80f5-b798-5971-9ef9-8f106fc4f6a5', 'Choose the correctly spelled word:', NULL, 'B is correct: RECEIVE. Rule: ''i before e, except after c.'' After the letter ''c'', use ''ei'' not ''ie''. Re-C-EIVE: the c comes before ei. Other words following this rule: deceive, perceive, conceive, ceiling. Trap: ''Recieve'' is the most common misspelling — reversing ''ei'' to ''ie'' after ''c''.', 'EASY', 'English', 'Spelling — Commonly Misspelled Words (W10)', 'ENG_SPELLING_W10', '[{"option_text": "Recieve", "is_correct": false}, {"option_text": "Receive", "is_correct": true}, {"option_text": "Receve", "is_correct": false}, {"option_text": "Receeve", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c51f7c24-fcc3-52df-b6cb-54507812bec3', 'Choose the correctly spelled word:', NULL, 'A is correct: MISCHIEVOUS. It has 3 syllables: mis-chie-vous (NOT mis-chie-vi-ous). The word contains ''mischief'' + ''-ous'' (not mischief + ''-ious''). Trap: ''Mischievious'' (4 syllables) is incorrect — the extra ''i'' is often inserted due to mispronunciation; ''Mischeivous'' misspells the ''ief'' → ''eiv'' sequence.', 'MEDIUM', 'English', 'Spelling — Commonly Misspelled Words (W10)', 'ENG_SPELLING_W10', '[{"option_text": "Mischievous", "is_correct": true}, {"option_text": "Mischeivous", "is_correct": false}, {"option_text": "Mischevious", "is_correct": false}, {"option_text": "Mischievious", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('96b680d8-a89c-5c63-9330-b5c0ce47d786', 'Choose the correctly spelled word:', NULL, 'B is correct: OCCURRENCE. Double-c + double-r + -ence: oc-CUR-RENCE. Memory aid: the word occurs from ''occur'' (which doubles the ''r'' when adding a suffix starting with a vowel in British English). Trap: ''Occurence'' (single r), ''Occurrance'' (wrong suffix -rance), and ''Ocurrence'' (single c) are common errors.', 'MEDIUM', 'English', 'Spelling — Commonly Misspelled Words (W10)', 'ENG_SPELLING_W10', '[{"option_text": "Occurence", "is_correct": false}, {"option_text": "Occurrence", "is_correct": true}, {"option_text": "Occurrance", "is_correct": false}, {"option_text": "Ocurrence", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bf1b1046-7bf1-5221-a6ed-47b0f7a66c16', 'Choose the correctly spelled word:', NULL, 'B is correct: ASSASSINATION. Memory trick: ASS + ASS + IN + ATION (two ''ass'' + nation). The word contains two consecutive ''ss'' pairs: ASSASSIN + -ATION. Trap: ''Assasination'' has only one ''ss'' in the middle; ''Asassination'' has only one ''s'' at the start.', 'MEDIUM', 'English', 'Spelling — Commonly Misspelled Words (W10)', 'ENG_SPELLING_W10', '[{"option_text": "Assasination", "is_correct": false}, {"option_text": "Assassination", "is_correct": true}, {"option_text": "Assasinnation", "is_correct": false}, {"option_text": "Asassination", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('acb6ed29-0d87-5069-aeca-cc70d7c1a944', 'Choose the correctly spelled word:', NULL, 'A is correct: CONSCIENTIOUS (con-sci-en-tious). It contains ''SCIENCE'' inside: con-SCIEN-tious. Memory aid: a conscientious person has ''science'' in their work ethic. Trap: ''Concientious'' drops the ''s''; ''Consciencious'' inserts an extra ''c'' from confusing it with ''conscience''; ''Consientious'' drops the ''c'' after ''con''.', 'MEDIUM', 'English', 'Spelling — Commonly Misspelled Words (W10)', 'ENG_SPELLING_W10', '[{"option_text": "Conscientious", "is_correct": true}, {"option_text": "Consientious", "is_correct": false}, {"option_text": "Concientious", "is_correct": false}, {"option_text": "Consciencious", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8d682e02-9d76-55e8-a1df-f21ffae4be89', 'Choose the correctly spelled word:', NULL, 'B is correct: MILLENNIUM. Root: Latin mille (thousand) + annum (year) = thousand years. The double ''l'' comes from ''mille'' and the double ''n'' from ''annum''. Memory aid: MILL + ENN + IUM. Trap: ''Millenium'' (double l, single n) is the most common error — students double the ''l'' correctly but forget the double ''n''.', 'HARD', 'English', 'Spelling — Commonly Misspelled Words (W10)', 'ENG_SPELLING_W10', '[{"option_text": "Millenium", "is_correct": false}, {"option_text": "Millennium", "is_correct": true}, {"option_text": "Milennium", "is_correct": false}, {"option_text": "Milenneum", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c67f77d9-d010-5ac8-9598-6b79e8507971', 'Choose the correctly spelled word:', NULL, 'B is correct: PHARAOH. The unusual spelling comes from Ancient Egyptian through Greek. Note the vowel sequence: a-a-o-h (PH-A-R-A-O-H). Memory aid: Pharaoh has no ''r'' before the second ''a'' — PHAR + AOH. Trap: ''Pharoah'' (most common error) puts ''o'' before ''a''; the correct order is ''a'' + ''o'' + ''h''.', 'HARD', 'English', 'Spelling — Commonly Misspelled Words (W10)', 'ENG_SPELLING_W10', '[{"option_text": "Pharoah", "is_correct": false}, {"option_text": "Pharaoh", "is_correct": true}, {"option_text": "Pharoah", "is_correct": false}, {"option_text": "Phaaroah", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1030897c-9f82-55ab-b7f9-65ef889abe20', 'Choose the correctly spelled word:', NULL, 'A is correct: BUREAUCRACY. From French ''bureau'' (office/desk) + Greek ''-cracy'' (rule/government) = rule by offices. Spelling breakdown: BUR + EAU + CRA + CY. Note ''eau'' not ''eau'' reversed. Trap: ''Beaurocracy'' inserts an extra ''e'' after ''beau'' (likely confusing with the French word ''beau''); ''Burocracy'' drops the ''eau'' entirely.', 'HARD', 'English', 'Spelling — Commonly Misspelled Words (W10)', 'ENG_SPELLING_W10', '[{"option_text": "Bureaucracy", "is_correct": true}, {"option_text": "Burocracy", "is_correct": false}, {"option_text": "Beaurocracy", "is_correct": false}, {"option_text": "Beurocracy", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9dbd265d-9e8a-5dd2-9e54-51b5e5b75104', 'Choose the correctly spelled word:', NULL, 'C is correct: MAINTENANCE. Note: the root is ''maintain'' but the noun shifts to ''maint-EN-ance'' (not maintainance). Breakdown: MAIN + TEN + ANCE. The vowel changes: maintain → maintenance (the ''ai'' in maintain becomes ''e'' in maintenance). Trap: ''Maintainance'' keeps the ''ai'' from ''maintain'' (wrong — the vowel shifts in the noun form); ''Maintenence'' uses ''-ence'' instead of ''-ance''.', 'HARD', 'English', 'Spelling — Commonly Misspelled Words (W10)', 'ENG_SPELLING_W10', '[{"option_text": "Maintainance", "is_correct": false}, {"option_text": "Maintenence", "is_correct": false}, {"option_text": "Maintenance", "is_correct": true}, {"option_text": "Maintenence", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0fb7e944-bb94-5b20-ba9c-1c892b801468', 'Choose the correctly spelled word:', NULL, 'B is correct. Accommodation has double ''c'' and double ''m'' (ac-com-mo-da-tion). A common error is using only one ''c'' or one ''m''.', 'EASY', 'English', 'Spelling — Correct/Incorrect (W9)', 'ENG_SPELLING_W9', '[{"option_text": "Accomodation", "is_correct": false}, {"option_text": "Accommodation", "is_correct": true}, {"option_text": "Acommodation", "is_correct": false}, {"option_text": "Acomodation", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9c86c521-de17-53e6-9e7a-b928a33de916', 'Choose the correctly spelled word:', NULL, 'B is correct. Occurrence = double ''c'' and double ''r'' (oc-cur-rence). The root is ''occur'' (double r when suffix added to short-vowel monosyllable).', 'EASY', 'English', 'Spelling — Correct/Incorrect (W9)', 'ENG_SPELLING_W9', '[{"option_text": "Occurence", "is_correct": false}, {"option_text": "Occurrence", "is_correct": true}, {"option_text": "Ocurrence", "is_correct": false}, {"option_text": "Occurrance", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('80ccac8a-6d1d-5c12-8c5e-9f2d895d8349', 'Choose the correctly spelled word:', NULL, 'B is correct. Assassination = two ''s'' after ''a'', then ''ss'' again (as-sas-si-na-tion). Four s''s in total.', 'EASY', 'English', 'Spelling — Correct/Incorrect (W9)', 'ENG_SPELLING_W9', '[{"option_text": "Assasination", "is_correct": false}, {"option_text": "Assassination", "is_correct": true}, {"option_text": "Assasinaton", "is_correct": false}, {"option_text": "Assasintion", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9bb16d0c-e99b-5a88-9f30-f6909e7d39b5', 'Choose the correctly spelled word:', NULL, 'C is correct. Inadvertent = in-ad-vert-ent. Only one ''n'' at the start; ends in ''-ent'', not ''-ant''.', 'MEDIUM', 'English', 'Spelling — Correct/Incorrect (W9)', 'ENG_SPELLING_W9', '[{"option_text": "Inadvertant", "is_correct": false}, {"option_text": "Innadvertent", "is_correct": false}, {"option_text": "Inadvertent", "is_correct": true}, {"option_text": "Inadvertentt", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bd866f84-b1c5-5e23-b69e-26485529373b', 'Choose the correctly spelled word:', NULL, 'C is correct. Entrepreneur (French origin) = en-tre-pre-neur. Common errors: reversing ''eu'' to ''ue'', or inserting an extra ''e'' after ''pr''.', 'MEDIUM', 'English', 'Spelling — Correct/Incorrect (W9)', 'ENG_SPELLING_W9', '[{"option_text": "Entreprenuer", "is_correct": false}, {"option_text": "Entrepeneur", "is_correct": false}, {"option_text": "Entrepreneur", "is_correct": true}, {"option_text": "Entreprenueur", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e5aac1bb-50f7-5636-9b69-6c3974ce368d', 'Choose the correctly spelled word:', NULL, 'B is correct. Description = de-scrip-tion. Stem is ''describe'' → ''descri-'' not ''discri-''. Ends ''-ption'', not ''-pion''.', 'MEDIUM', 'English', 'Spelling — Correct/Incorrect (W9)', 'ENG_SPELLING_W9', '[{"option_text": "Discription", "is_correct": false}, {"option_text": "Description", "is_correct": true}, {"option_text": "Descrption", "is_correct": false}, {"option_text": "Discriptin", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7be975be-5b27-5de9-bf22-c328bded306e', 'Choose the correctly spelled word:', NULL, 'B is correct. Believe = be-lieve. ''i'' before ''e'' except after ''c'' applies here: bel-ie-ve.', 'MEDIUM', 'English', 'Spelling — Correct/Incorrect (W9)', 'ENG_SPELLING_W9', '[{"option_text": "Beleive", "is_correct": false}, {"option_text": "Believe", "is_correct": true}, {"option_text": "Belive", "is_correct": false}, {"option_text": "Beileve", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0769e147-d7a2-5832-bb95-475f9d90374e', 'Choose the correctly spelled word:', NULL, 'C is correct. Necessary = one ''c'', double ''s'' (nec-es-sar-y). A useful mnemonic: one collar, two socks (1 ''c'', 2 ''s'').', 'MEDIUM', 'English', 'Spelling — Correct/Incorrect (W9)', 'ENG_SPELLING_W9', '[{"option_text": "Necassary", "is_correct": false}, {"option_text": "Neccesary", "is_correct": false}, {"option_text": "Necessary", "is_correct": true}, {"option_text": "Nessecary", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('77778293-ceef-59e4-a963-477574ea8442', 'Choose the correctly spelled word:', NULL, 'C is correct. Mischievous = mis-chie-vous (3 syllables, not 4). No extra ''i'' — ''mischievious'' is a very common misspelling.', 'HARD', 'English', 'Spelling — Correct/Incorrect (W9)', 'ENG_SPELLING_W9', '[{"option_text": "Mischievious", "is_correct": false}, {"option_text": "Mischeivous", "is_correct": false}, {"option_text": "Mischievous", "is_correct": true}, {"option_text": "Mischevious", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3e067b00-fe0a-5aaa-baab-0ff4093c067e', 'Choose the correctly spelled word:', NULL, 'A is correct. Conscientious = con-sci-en-tious. The root is ''science''; the ''sc'' before ''i'' makes a ''sh'' sound. Ends ''-tious'', not ''-cious''.', 'HARD', 'English', 'Spelling — Correct/Incorrect (W9)', 'ENG_SPELLING_W9', '[{"option_text": "Conscientious", "is_correct": true}, {"option_text": "Consciencious", "is_correct": false}, {"option_text": "Conscienscious", "is_correct": false}, {"option_text": "Consceintious", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
