INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8fb7b222-b4a6-5e78-adc9-454841030c55', 'Each of the students in the classroom (A) / have submitted (B) / their assignment on time (C). / No error (D).', NULL, 'B is correct. Error in Part B: ''have submitted'' should be ''has submitted''. RULE: ''Each of'' + plural noun still takes a SINGULAR verb because ''Each'' is the head pronoun and it is singular. Compare: ''Each of the boys HAS done his work.'' Similarly, ''their'' in part C should ideally be ''his/her'' (though SSC increasingly accepts ''their'' for singular reference). Primary error = B. TRAP: Students see ''students'' (plural) immediately before the verb and write ''have''. The trick is to identify the REAL subject = ''Each'' (singular).', 'MEDIUM', 'English', 'Spotting Errors VI — Subject-Verb Agreement, Tense, Modifiers and Idioms (W13 B1)', 'ENG_SPOTTING_ERRORS_VI_W13_B1', '[{"option_text": "A", "is_correct": false}, {"option_text": "B", "is_correct": true}, {"option_text": "C", "is_correct": false}, {"option_text": "D", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f38e24ca-cb3c-5ec5-bc84-d6e775c80c1d', 'She has been working (A) / on this project (B) / since three years (C). / No error (D).', NULL, 'C is correct. Error in Part C: ''since three years'' should be ''for three years''. RULE: SINCE = used with a specific POINT in time (''since 2020'', ''since Monday'', ''since morning''). FOR = used with a PERIOD/DURATION of time (''for three years'', ''for two hours'', ''for a long time''). ''Three years'' is a duration, not a point → use ''for''. Correct: ''She has been working on this project FOR three years.'' TRAP: ''since'' and ''for'' are both time prepositions and often confused. SSC tests this distinction repeatedly.', 'MEDIUM', 'English', 'Spotting Errors VI — Subject-Verb Agreement, Tense, Modifiers and Idioms (W13 B1)', 'ENG_SPOTTING_ERRORS_VI_W13_B1', '[{"option_text": "A", "is_correct": false}, {"option_text": "B", "is_correct": false}, {"option_text": "C", "is_correct": true}, {"option_text": "D", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c3e7dca1-255c-5fec-b8aa-7cbe20f6e67b', 'The news that (A) / the prime minister had resigned (B) / have shocked everyone in the country (C). / No error (D).', NULL, 'C is correct. Error in Part C: ''have shocked'' should be ''has shocked''. RULE: The subject of this sentence is ''The news'' (singular/uncountable noun — treated as singular in grammar). The clause ''that the prime minister had resigned'' is a NOUN CLAUSE modifying ''news'', not the subject. The verb must agree with ''news'' (singular) → ''has shocked''. Correct: ''...has shocked everyone.'' TRAP: Students jump from ''resigned'' to ''have'' thinking the subject is ''prime minister'', but by that point we are already back to the main clause where subject = ''The news''.', 'MEDIUM', 'English', 'Spotting Errors VI — Subject-Verb Agreement, Tense, Modifiers and Idioms (W13 B1)', 'ENG_SPOTTING_ERRORS_VI_W13_B1', '[{"option_text": "A", "is_correct": false}, {"option_text": "B", "is_correct": false}, {"option_text": "C", "is_correct": true}, {"option_text": "D", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('774ee157-e95e-518b-a9b5-d343c1386703', 'He is too weak (A) / to not lift (B) / even a light bag (C). / No error (D).', NULL, 'B is correct. Error in Part B: ''to not lift'' should be ''to lift''. RULE: ''Too + adjective + to + infinitive'' already carries a NEGATIVE meaning (''too weak to lift'' = so weak that he CANNOT lift). Adding ''not'' creates an ungrammatical double negative: ''too weak to NOT lift'' would paradoxically mean he is NOT able to NOT lift (i.e., he CAN lift). Correct: ''He is too weak TO LIFT even a light bag.'' TRAP: Students hear the negative meaning and insert ''not'', not realising ''too...to'' is inherently negative.', 'MEDIUM', 'English', 'Spotting Errors VI — Subject-Verb Agreement, Tense, Modifiers and Idioms (W13 B1)', 'ENG_SPOTTING_ERRORS_VI_W13_B1', '[{"option_text": "A", "is_correct": false}, {"option_text": "B", "is_correct": true}, {"option_text": "C", "is_correct": false}, {"option_text": "D", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6cc17223-d73a-5b29-b549-dff5bd31cd78', 'Either the principal (A) / or the teachers (B) / is responsible for this decision (C). / No error (D).', NULL, 'C is correct. Error in Part C: ''is responsible'' should be ''are responsible''. RULE: With ''Either...or'' / ''Neither...nor'', the verb agrees with the subject NEAREST to it (proximity rule). Here, the nearest subject = ''the teachers'' (plural) → verb must be plural = ''are responsible''. Correct: ''Either the principal or the teachers ARE responsible...'' Contrast: ''Either the teachers or the principal IS responsible'' (nearest = ''the principal'' = singular → ''is''). TRAP: Students see ''either...or'' and assume singular subject → wrong.', 'MEDIUM', 'English', 'Spotting Errors VI — Subject-Verb Agreement, Tense, Modifiers and Idioms (W13 B1)', 'ENG_SPOTTING_ERRORS_VI_W13_B1', '[{"option_text": "A", "is_correct": false}, {"option_text": "B", "is_correct": false}, {"option_text": "C", "is_correct": true}, {"option_text": "D", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f2131c7d-b8d3-527a-bfc5-39ab4b4e0a99', 'Hardly had she arrived (A) / at the station (B) / than the train left (C). / No error (D).', NULL, 'C is correct. Error in Part C: ''than'' should be ''when''. RULE: ''Hardly/Scarcely...WHEN'' and ''Barely...WHEN'' — these negative adverbs require ''when'' to introduce the following clause, NOT ''than''. ''No sooner...THAN'' is the only pair that uses ''than''. Confusing the pairs is the classic SSC trap. Correct: ''Hardly had she arrived at the station WHEN the train left.'' Note also: ''Hardly had she arrived'' = correct inversion after ''hardly'' at the start of a sentence. TRAP: ''No sooner + than'' and ''Hardly + when'' are swapped by students under exam pressure.', 'MEDIUM', 'English', 'Spotting Errors VI — Subject-Verb Agreement, Tense, Modifiers and Idioms (W13 B1)', 'ENG_SPOTTING_ERRORS_VI_W13_B1', '[{"option_text": "A", "is_correct": false}, {"option_text": "B", "is_correct": false}, {"option_text": "C", "is_correct": true}, {"option_text": "D", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6146152b-7258-52f4-9fe0-22b07b83cdcf', 'The accused denied (A) / that he had stole (B) / the money from the safe (C). / No error (D).', NULL, 'B is correct. Error in Part B: ''stole'' should be ''stolen''. RULE: ''Had + PAST PARTICIPLE'' forms the past perfect tense. The past participle of ''steal'' is ''STOLEN'' (steal → stole → stolen). ''stole'' is the simple past, not the past participle. Correct: ''...that he had STOLEN the money...'' Common irregular verbs SSC tests: steal-stole-stolen; break-broke-broken; freeze-froze-frozen; speak-spoke-spoken; wake-woke-woken. TRAP: Students confuse simple past (stole) with past participle (stolen); they are different forms for irregular verbs.', 'HARD', 'English', 'Spotting Errors VI — Subject-Verb Agreement, Tense, Modifiers and Idioms (W13 B1)', 'ENG_SPOTTING_ERRORS_VI_W13_B1', '[{"option_text": "A", "is_correct": false}, {"option_text": "B", "is_correct": true}, {"option_text": "C", "is_correct": false}, {"option_text": "D", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('08c36b53-267e-5ee0-980e-bb8d895f6157', 'Being a rainy day, (A) / the manager decided (B) / to cancel the outdoor meeting (C). / No error (D).', NULL, 'A is correct. Error in Part A: ''Being a rainy day'' is a DANGLING MODIFIER. RULE: A participial phrase at the beginning of a sentence must logically refer to the subject of the main clause. The main clause subject = ''the manager''. So ''Being a rainy day'' implies the MANAGER is a rainy day — which is absurd. Correct forms: ''It being a rainy day, the manager...'' OR ''Since it was a rainy day, the manager...'' Dangling modifiers are a recurrent high-difficulty error type in SSC CGL Tier 2 spotting errors. TRAP: The rest of the sentence sounds logical; the error is structural (modifier-subject mismatch), not lexical.', 'HARD', 'English', 'Spotting Errors VI — Subject-Verb Agreement, Tense, Modifiers and Idioms (W13 B1)', 'ENG_SPOTTING_ERRORS_VI_W13_B1', '[{"option_text": "A", "is_correct": true}, {"option_text": "B", "is_correct": false}, {"option_text": "C", "is_correct": false}, {"option_text": "D", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('84b21759-9a6c-52b1-977c-8e4de41866ee', 'He is one of those officers (A) / who always gives priority (B) / to the welfare of his subordinates (C). / No error (D).', NULL, 'B is correct. Error in Part B: ''gives'' should be ''give''. RULE: In ''one of those + plural noun + who'', the relative pronoun ''who'' refers to the PLURAL noun (''officers''), not to ''one''. Therefore the verb after ''who'' must be PLURAL: ''who always GIVE priority''. Compare: ''He is THE ONE officer who always GIVES priority'' (here ''one officer'' is singular → ''gives''). The phrase ''one of those X who'' = ''who'' → X (plural) → plural verb. TRAP: Students focus on ''He is one'' (singular) and use ''gives'' without realising ''who'' modifies ''those officers'' (plural).', 'HARD', 'English', 'Spotting Errors VI — Subject-Verb Agreement, Tense, Modifiers and Idioms (W13 B1)', 'ENG_SPOTTING_ERRORS_VI_W13_B1', '[{"option_text": "A", "is_correct": false}, {"option_text": "B", "is_correct": true}, {"option_text": "C", "is_correct": false}, {"option_text": "D", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7ad7f8d1-f530-51ba-9426-6074160af8df', 'The committee has been deliberating (A) / the matter since yesterday (B) / and have not yet reached a decision (C). / No error (D).', NULL, 'C is correct. Error in Part C: ''have not yet reached'' should be ''has not yet reached''. RULE: Within a SINGLE sentence, the same collective noun subject must keep the same number agreement throughout. Part A uses ''The committee HAS been deliberating'' (treating committee as singular) → Part C must also use ''HAS not yet reached'' to remain consistent. Switching from ''has'' (Part A) to ''have'' (Part C) is an internal inconsistency. Correct: ''...and HAS not yet reached a decision.'' TRAP: The long intervening phrase causes students to forget the original verb number used in Part A. Consistency within a sentence is a crucial Tier 2 rule.', 'HARD', 'English', 'Spotting Errors VI — Subject-Verb Agreement, Tense, Modifiers and Idioms (W13 B1)', 'ENG_SPOTTING_ERRORS_VI_W13_B1', '[{"option_text": "A", "is_correct": false}, {"option_text": "B", "is_correct": false}, {"option_text": "C", "is_correct": true}, {"option_text": "D", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5827fde1-8acd-58d6-829f-a15c24637e52', 'Find the error: (A) A number of students / (B) was absent / (C) yesterday due to / (D) the heavy rains', NULL, 'B is correct. ''A number of + plural noun'' takes a PLURAL verb. ''A number of students'' = several students → plural → ''WERE absent''. Contrast: ''The number of students was...'' (here ''the number'' is the subject = singular). Rule: A number of = many/several (plural); The number of = the count (singular). Trap: students often use ''was'' because ''a number'' seems singular — but the noun phrase acts like ''many''.', 'EASY', 'English', 'Spotting Errors — Agreement, Preposition, Tense and Idiom Rules (W12 B1)', 'ENG_SPOTTING_ERRORS_V_W12_B1', '[{"option_text": "(A) A number of students", "is_correct": false}, {"option_text": "(B) was absent", "is_correct": true}, {"option_text": "(C) yesterday due to", "is_correct": false}, {"option_text": "(D) the heavy rains", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ade9f41a-cd66-5f3f-bf95-4c23af66fbe3', 'Find the error: (A) She suggested me / (B) to apply for the job / (C) before the deadline / (D) No error', NULL, 'A is correct. The verb SUGGEST does not take a direct personal object followed by an infinitive. ''Suggested me to apply'' is wrong. Correct patterns: ''She suggested THAT I apply'' or ''She suggested applying''. Compare: ''advised me TO apply'' is correct (ADVISE takes person + infinitive). Trap: students write ''suggested me to'' on the analogy of ''told me to'', ''asked me to'', ''advised me to'' — but ''suggest'' does not follow this pattern.', 'EASY', 'English', 'Spotting Errors — Agreement, Preposition, Tense and Idiom Rules (W12 B1)', 'ENG_SPOTTING_ERRORS_V_W12_B1', '[{"option_text": "(A) She suggested me", "is_correct": true}, {"option_text": "(B) to apply for the job", "is_correct": false}, {"option_text": "(C) before the deadline", "is_correct": false}, {"option_text": "(D) No error", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8dd9ba55-bafd-5cb7-9a98-091981f4ec7d', 'Find the error: (A) If I / (B) will go there, / (C) I will meet him / (D) for sure', NULL, 'B is correct. In conditional sentences with ''if'', the if-clause uses Simple Present (not future). Correct: ''If I GO there, I will meet him.'' The future meaning is implied by context, but the grammar rule demands Simple Present in the if-clause. Same for: when/after/before/until/as soon as + Simple Present (not future). Trap: ''If I will go'' sounds natural to Hindi-medium speakers (Hindi allows future in the if-clause) but is wrong in English.', 'EASY', 'English', 'Spotting Errors — Agreement, Preposition, Tense and Idiom Rules (W12 B1)', 'ENG_SPOTTING_ERRORS_V_W12_B1', '[{"option_text": "(A) If I", "is_correct": false}, {"option_text": "(B) will go there,", "is_correct": true}, {"option_text": "(C) I will meet him", "is_correct": false}, {"option_text": "(D) for sure", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b726e19f-b11a-5a1c-a4b0-28672147032e', 'Find the error: (A) She is senior / (B) than me / (C) in this organisation / (D) No error', NULL, 'B is correct. Latin-origin comparatives (senior, junior, superior, inferior, major, minor, prior, anterior, posterior) take the preposition TO, not ''than''. Correct: ''She is senior TO me.'' SSC favourite rule: senior/junior/superior/inferior/major/minor + TO (never ''than''). Trap: students use ''than'' by analogy with ''older than'', ''taller than'' — but these native-English comparatives use ''than''; Latin-origin ones use ''to''.', 'MEDIUM', 'English', 'Spotting Errors — Agreement, Preposition, Tense and Idiom Rules (W12 B1)', 'ENG_SPOTTING_ERRORS_V_W12_B1', '[{"option_text": "(A) She is senior", "is_correct": false}, {"option_text": "(B) than me", "is_correct": true}, {"option_text": "(C) in this organisation", "is_correct": false}, {"option_text": "(D) No error", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6123d445-2d3c-564b-977e-d05d8c6cb1a7', 'Find the error: (A) He has been working / (B) in this company / (C) since five years / (D) No error', NULL, 'C is correct. SINCE = used with a point in time (since 2020, since Monday, since morning). FOR = used with a period/duration of time (for five years, for two hours). ''5 years'' is a DURATION, so it takes ''FOR''. Correct: ''He has been working in this company FOR five years.'' Trap: since/for confusion is very common; students mistakenly use ''since'' for durations in translations from Hindi (Hindi uses ''se'' for both).', 'MEDIUM', 'English', 'Spotting Errors — Agreement, Preposition, Tense and Idiom Rules (W12 B1)', 'ENG_SPOTTING_ERRORS_V_W12_B1', '[{"option_text": "(A) He has been working", "is_correct": false}, {"option_text": "(B) in this company", "is_correct": false}, {"option_text": "(C) since five years", "is_correct": true}, {"option_text": "(D) No error", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c2f5660e-414d-52c5-b969-08386e2378f9', 'Find the error: (A) He is / (B) the taller / (C) of the three / (D) brothers', NULL, 'B is correct. Rule: Comparative degree (''taller'', ''-er'') is used when comparing TWO things; Superlative (''tallest'', ''-est'') is used when comparing THREE or more. Here we''re comparing among three brothers → use ''tallest''. Correct: ''He is the TALLEST of the three brothers.'' Trap: students use ''taller'' because it sounds more modest — but the grammatical rule demands superlative when the comparison set has 3+ members.', 'MEDIUM', 'English', 'Spotting Errors — Agreement, Preposition, Tense and Idiom Rules (W12 B1)', 'ENG_SPOTTING_ERRORS_V_W12_B1', '[{"option_text": "(A) He is", "is_correct": false}, {"option_text": "(B) the taller", "is_correct": true}, {"option_text": "(C) of the three", "is_correct": false}, {"option_text": "(D) brothers", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('459d26b5-8498-5880-860b-00760da1671e', 'Find the error: (A) Being a rainy day, / (B) we decided / (C) to stay / (D) indoors', NULL, 'A is correct. DANGLING MODIFIER: ''Being a rainy day'' is a participial phrase that should modify the subject of the main clause. The main subject is ''we'' — but ''we'' cannot be a rainy day. The phrase dangles without a proper subject. Correct: ''As it was a rainy day, we decided to stay indoors.'' Trap: the sentence sounds natural but is grammatically incorrect — the implied subject of ''Being a rainy day'' must match ''we'', which is logically impossible.', 'MEDIUM', 'English', 'Spotting Errors — Agreement, Preposition, Tense and Idiom Rules (W12 B1)', 'ENG_SPOTTING_ERRORS_V_W12_B1', '[{"option_text": "(A) Being a rainy day,", "is_correct": true}, {"option_text": "(B) we decided", "is_correct": false}, {"option_text": "(C) to stay", "is_correct": false}, {"option_text": "(D) indoors", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3602d9e5-5334-544a-8421-5cea0b34f315', 'Find the error: (A) Scarcely had I / (B) entered the room / (C) when the phone / (D) ringed', NULL, 'D is correct. The verb ''ring'' has an irregular past tense: ring → rang → rung. ''Ringed'' is incorrect (as if ''ring'' were a regular verb). Correct: ''the phone RANG''. Note: ''scarcely...when'' is the correct idiomatic construction (not ''scarcely...than'') — so A,B,C are all correct. Trap: ''scarcely...when'' is sometimes confused with ''no sooner...than'' — but ''scarcely/hardly/barely'' always take ''when/before'', not ''than''.', 'MEDIUM', 'English', 'Spotting Errors — Agreement, Preposition, Tense and Idiom Rules (W12 B1)', 'ENG_SPOTTING_ERRORS_V_W12_B1', '[{"option_text": "(A) Scarcely had I", "is_correct": false}, {"option_text": "(B) entered the room", "is_correct": false}, {"option_text": "(C) when the phone", "is_correct": false}, {"option_text": "(D) ringed", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('404a0c99-0595-537f-9733-d2e48eb74523', 'Find the error: (A) Had I known / (B) the answer, / (C) I would / (D) answered it', NULL, 'D is correct. Third conditional structure: ''If/Had + Past Perfect, would have + Past Participle.'' Result clause needs ''WOULD HAVE answered'' — not just ''would answered''. Correct: ''I would HAVE answered it.'' The inverted form ''Had I known'' = ''If I had known'' (both correct). Trap: ''would answered'' is a common error where students use the base form after ''would'' (correct in 2nd conditional: ''I would answer''), but in 3rd conditional the auxiliary ''have'' is required.', 'HARD', 'English', 'Spotting Errors — Agreement, Preposition, Tense and Idiom Rules (W12 B1)', 'ENG_SPOTTING_ERRORS_V_W12_B1', '[{"option_text": "(A) Had I known", "is_correct": false}, {"option_text": "(B) the answer,", "is_correct": false}, {"option_text": "(C) I would", "is_correct": false}, {"option_text": "(D) answered it", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('83489783-4750-52e6-b4de-cf3e7b71211d', 'Find the error: (A) The committee of doctors / (B) have decided / (C) to go on strike / (D) from Monday', NULL, 'B is correct. ''The committee'' = a collective noun. When a collective noun acts as a single body taking a unified decision, it takes a SINGULAR verb. ''The committee... have decided'' → should be ''HAS decided'' (the committee as a single body made one decision). Correct: ''The committee of doctors HAS decided.'' Contrast: if the committee is divided and members act individually, plural verb is used — but ''decided to go on strike'' implies collective unified action. Trap: ''doctors'' is plural, tempting students to use ''have''; but the grammatical subject is ''the committee'' (singular).', 'HARD', 'English', 'Spotting Errors — Agreement, Preposition, Tense and Idiom Rules (W12 B1)', 'ENG_SPOTTING_ERRORS_V_W12_B1', '[{"option_text": "(A) The committee of doctors", "is_correct": false}, {"option_text": "(B) have decided", "is_correct": true}, {"option_text": "(C) to go on strike", "is_correct": false}, {"option_text": "(D) from Monday", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('86b84df4-c697-582b-bd32-1d3174327ccd', 'Choose the synonym of ANGRY:', NULL, 'A is correct. Furious is a synonym of angry (both denote strong displeasure). Calm is the antonym.', 'EASY', 'English', 'Synonyms (W9)', 'ENG_SYNONYMS_W9', '[{"option_text": "Furious", "is_correct": true}, {"option_text": "Calm", "is_correct": false}, {"option_text": "Happy", "is_correct": false}, {"option_text": "Sorrowful", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('55df5127-e2d7-5bd4-a5d9-afb8b00093b7', 'Choose the synonym of BRAVE:', NULL, 'C is correct. Courageous = brave. Options A, B and D are antonyms.', 'EASY', 'English', 'Synonyms (W9)', 'ENG_SYNONYMS_W9', '[{"option_text": "Cowardly", "is_correct": false}, {"option_text": "Timid", "is_correct": false}, {"option_text": "Courageous", "is_correct": true}, {"option_text": "Fearful", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ef4a4f07-59f4-555f-a73d-2e8a72335f97', 'Choose the synonym of BEAUTIFUL:', NULL, 'B is correct. Gorgeous means very beautiful. Ugly is the antonym; plain/ordinary mean unremarkable.', 'EASY', 'English', 'Synonyms (W9)', 'ENG_SYNONYMS_W9', '[{"option_text": "Ugly", "is_correct": false}, {"option_text": "Gorgeous", "is_correct": true}, {"option_text": "Plain", "is_correct": false}, {"option_text": "Ordinary", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e5a9d3b9-f36a-5d63-a435-e0247c03e8f3', 'Choose the synonym of ENIGMA:', NULL, 'C is correct. An enigma is something mysterious or puzzling. Solution and clarity are near-antonyms.', 'MEDIUM', 'English', 'Synonyms (W9)', 'ENG_SYNONYMS_W9', '[{"option_text": "Solution", "is_correct": false}, {"option_text": "Answer", "is_correct": false}, {"option_text": "Mystery", "is_correct": true}, {"option_text": "Clarity", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cce895ce-8ba4-5a04-ab7e-c8da21f10e0a', 'Choose the synonym of FRUGAL:', NULL, 'C is correct. Frugal = thrifty (careful with money, avoiding waste). Wasteful and extravagant are antonyms.', 'MEDIUM', 'English', 'Synonyms (W9)', 'ENG_SYNONYMS_W9', '[{"option_text": "Wasteful", "is_correct": false}, {"option_text": "Generous", "is_correct": false}, {"option_text": "Thrifty", "is_correct": true}, {"option_text": "Extravagant", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0f134d92-fd6e-5d04-863e-c231e0eab557', 'Choose the synonym of CANDID:', NULL, 'B is correct. Candid = frank (truthful and straightforward). Deceptive and secretive are antonyms.', 'MEDIUM', 'English', 'Synonyms (W9)', 'ENG_SYNONYMS_W9', '[{"option_text": "Deceptive", "is_correct": false}, {"option_text": "Frank", "is_correct": true}, {"option_text": "Secretive", "is_correct": false}, {"option_text": "Flattering", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('67afaaed-23a8-5491-9cf0-e35ac4fce3ec', 'Choose the synonym of OBSOLETE:', NULL, 'C is correct. Obsolete = no longer in use; outdated. Modern and current are antonyms.', 'MEDIUM', 'English', 'Synonyms (W9)', 'ENG_SYNONYMS_W9', '[{"option_text": "Modern", "is_correct": false}, {"option_text": "Current", "is_correct": false}, {"option_text": "Outdated", "is_correct": true}, {"option_text": "Relevant", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('12a1ccc3-898d-5110-b947-2d12abda482f', 'Choose the synonym of BENEVOLENT:', NULL, 'B is correct. Benevolent = well-meaning and kind; charitable. Cruel and selfish are antonyms.', 'MEDIUM', 'English', 'Synonyms (W9)', 'ENG_SYNONYMS_W9', '[{"option_text": "Cruel", "is_correct": false}, {"option_text": "Charitable", "is_correct": true}, {"option_text": "Selfish", "is_correct": false}, {"option_text": "Indifferent", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3beba32d-582c-50c8-9720-d14c17b9f154', 'Choose the synonym of LACONIC:', NULL, 'C is correct. Laconic = using very few words; concise. (From Laconia/Sparta, where people were famously brief.) Verbose and talkative are antonyms.', 'HARD', 'English', 'Synonyms (W9)', 'ENG_SYNONYMS_W9', '[{"option_text": "Verbose", "is_correct": false}, {"option_text": "Talkative", "is_correct": false}, {"option_text": "Concise", "is_correct": true}, {"option_text": "Elaborate", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('66ddb511-58cb-506c-b38e-83e985b97ea1', 'Choose the synonym of PHLEGMATIC:', NULL, 'D is correct. Phlegmatic = having a calm, unemotional temperament; not easily excited. Excitable, passionate and agitated are all antonyms.', 'HARD', 'English', 'Synonyms (W9)', 'ENG_SYNONYMS_W9', '[{"option_text": "Excitable", "is_correct": false}, {"option_text": "Passionate", "is_correct": false}, {"option_text": "Agitated", "is_correct": false}, {"option_text": "Calm and unemotional", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('13269cd0-9cef-54e3-83bd-d227df26bb82', 'Choose the correct tense form:
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('323d8bc9-5532-5b94-9d94-c3522b686dbd', 'Choose the correct form:
