INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('25eb02e6-8e7a-5e40-9a4c-c54ae2a17041', 'A train 300 m long passes a pole in 15 seconds. What is its speed in km/h?', NULL, 'Speed = 300/15 = 20 m/s = 20×18/5 = 72 km/h.
