INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('17ccbabc-ea72-54a5-9b55-49665963be34', 'Doctor : Hospital :: Teacher : ?', NULL, 'A Doctor works at a Hospital; a Teacher works at a School. The relationship is: person → place of work. Both ''school'' and ''college'' are educational institutions but the primary and most direct workplace of a teacher (especially in Indian exam context) is a school.', 'EASY', 'Reasoning', 'Analogy — 4th batch', 'RSN_ANALOGY', '[{"option_text": "Office", "is_correct": false}, {"option_text": "Library", "is_correct": false}, {"option_text": "School", "is_correct": true}, {"option_text": "College", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e5747d5b-a591-5d18-99e4-6cda4654335f', 'DOCTOR : HOSPITAL :: TEACHER : ?', NULL, 'Doctor works in a hospital → Teacher works in a school. Place-of-work analogy.', 'EASY', 'Reasoning', 'Analogies — mixed tiers', 'RSN_ANALOGY', '[{"option_text": "Pupils", "is_correct": false}, {"option_text": "School", "is_correct": true}, {"option_text": "Books", "is_correct": false}, {"option_text": "Profession", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('96d08eaa-bb7a-5d56-a796-07e2febc2e0f', 'Prison : Criminal :: Hospital : ?', NULL, 'A prison houses criminals; a hospital houses patients. Relationship: institution → person who stays there.', 'EASY', 'Reasoning', 'Analogy', 'RSN_ANALOGY', '["Doctor", "Patient", "Nurse", "Medicine"]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7cf98867-f5a6-5dff-8c95-67051dfe328a', '4 : 16 :: 9 : ?', NULL, '4² = 16; 9² = 81. Relationship: n → n².', 'EASY', 'Reasoning', 'Analogy', 'RSN_ANALOGY', '["27", "36", "72", "81"]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9a9ef640-8313-5369-9f4e-9a393a14115e', 'Carpenter : Wood :: Blacksmith : ?', NULL, 'A carpenter works primarily with wood; a blacksmith works primarily with iron. Relationship: craftsperson → primary material.', 'MEDIUM', 'Reasoning', 'Analogy', 'RSN_ANALOGY', '["Silver", "Iron", "Gold", "Copper"]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b9d3c0df-1b20-5542-93a1-095a41db6724', 'Acrophobia : Heights :: Claustrophobia : ?', NULL, 'Acrophobia is an irrational fear of heights; claustrophobia is an irrational fear of enclosed or confined spaces.', 'MEDIUM', 'Reasoning', 'Analogy', 'RSN_ANALOGY', '["Darkness", "Crowds", "Enclosed spaces", "Open water"]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b9be44e3-317f-57d0-ba02-a01adadc737e', 'Lion : Pride :: Fish : ?', NULL, 'A group of lions is called a pride. A group of fish is called a shoal (or school). (Flock = birds; Pack = wolves; Herd = cattle.)', 'EASY', 'Reasoning', 'Analogy', 'RSN_ANALOGY', '["Flock", "Pack", "Shoal", "Herd"]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('81b72de3-e67f-5cd1-b31f-290216afb5b6', 'Pointing to a photograph of a boy, Suresh said, ''He is the son of the only son of my mother.'' How is Suresh related to that boy?', NULL, 'WHY IT IS CORRECT: Let''s break down the sentence backward:
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f725b4d7-0f56-596d-b7d6-3dd26d8c821e', 'If CAT is coded as DBU, then DOG is coded as:', NULL, 'TYPE 1 — uniform +1 shift. C→D, A→B, T→U, all +1. Apply to DOG: D→E, O→P, G→H → EPH.', 'EASY', 'Reasoning', 'Coding-Decoding', 'RSN_CODING', '[{"option_text": "EPH", "is_correct": true}, {"option_text": "CPF", "is_correct": false}, {"option_text": "EQH", "is_correct": false}, {"option_text": "EOG", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d10279dd-ee60-532b-8324-8461a0450818', 'Find the missing number: 2, 6, 12, 20, 30, ?', NULL, 'Differences: 4, 6, 8, 10 (arithmetic progression). Next difference = 12. So 30 + 12 = 42. Equivalently each term = n(n+1) for n = 1, 2, 3, 4, 5 → 2, 6, 12, 20, 30; next n=6 gives 42. Distractor 36 = 6². Distractor 40 = 30 + 10 (uses last difference instead of next). Distractor 48 = 30 + 18 (jumped two steps in difference).', 'EASY', 'Reasoning', 'Number puzzles — mixed tiers', 'RSN_MATH_OPS', '[{"option_text": "36", "is_correct": false}, {"option_text": "42", "is_correct": true}, {"option_text": "40", "is_correct": false}, {"option_text": "48", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e9ee4247-6aa2-5d30-9082-2e8d3b2e16d6', 'Which is the odd one out?', NULL, '17, 23, 41 are prime numbers (only divisible by 1 and themselves). 35 = 5 × 7, a composite number. Verification — 35 / 5 = 7 (clean), while 17, 23, 41 have no divisor besides 1 and themselves. The category is ''primeness''.', 'MEDIUM', 'Reasoning', 'Odd one out — mixed tiers', 'RSN_CLASSIFY', '[{"option_text": "17", "is_correct": false}, {"option_text": "23", "is_correct": false}, {"option_text": "35", "is_correct": true}, {"option_text": "41", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f0bf498a-1476-57cc-8ee8-e3e2e98e6a46', 'Find the next term: 1, 8, 27, 64, 125, ?', NULL, 'Perfect cubes: 1³, 2³, 3³, 4³, 5³, next is 6³ = 216.', 'EASY', 'Reasoning', 'Series (Number & Letter)', 'RSN_SERIES', '[{"option_text": "196", "is_correct": false}, {"option_text": "216", "is_correct": true}, {"option_text": "225", "is_correct": false}, {"option_text": "210", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e35cd428-dcbb-5515-b629-c4ca1346065d', 'Find the next term: 1, 4, 9, 16, 25, ?', NULL, 'Perfect squares: 1², 2², 3², 4², 5², 6² = 36.', 'EASY', 'Reasoning', 'Number & alphabet series — mixed tiers', 'RSN_SERIES', '[{"option_text": "30", "is_correct": false}, {"option_text": "36", "is_correct": true}, {"option_text": "49", "is_correct": false}, {"option_text": "35", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
