INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('71a25b78-c6bf-55b5-9189-7e8e211ce475', 'Find the next term in the series: A1, C3, E5, G7, ?', NULL, 'B is correct. Letters: A, C, E, G — every other letter (+2 each time). Next = I. Numbers: 1, 3, 5, 7 — odd numbers (+2 each time). Next = 9. Answer = I9. Trap: J9 uses +3 skip (wrong); H8 = next consecutive letter with even number (wrong pattern); I10 = even number (breaks odd-number pattern).', 'EASY', 'Reasoning', 'Alphanumeric Series — Mixed Letter and Number Patterns (W10 B2)', 'RSN_ALPHANUMERIC_SERIES_W10_B2', '[{"option_text": "H8", "is_correct": false}, {"option_text": "I9", "is_correct": true}, {"option_text": "J9", "is_correct": false}, {"option_text": "I10", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c5800297-01e5-50e9-ad46-793d4b0787ec', 'Find the missing term: Z1, Y4, X9, W16, ?', NULL, 'B is correct. Letters: Z, Y, X, W — reverse alphabetical order (−1 each). Next = V. Numbers: 1, 4, 9, 16 = 1², 2², 3², 4² — perfect squares. Next = 5² = 25. Answer = V25. Trap: U25 = goes back two letters (wrong); V24 = 4×6 (not a perfect square); V20 = 16+4 (arithmetic not geometric pattern).', 'EASY', 'Reasoning', 'Alphanumeric Series — Mixed Letter and Number Patterns (W10 B2)', 'RSN_ALPHANUMERIC_SERIES_W10_B2', '[{"option_text": "V20", "is_correct": false}, {"option_text": "V25", "is_correct": true}, {"option_text": "U25", "is_correct": false}, {"option_text": "V24", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cf96afb2-403e-54ea-9141-e7ff6bed5bef', 'Find the next term: B2, D4, F8, H16, ?', NULL, 'C is correct. Letters: B, D, F, H — skip one letter (+2): B→D→F→H→J. Numbers: 2, 4, 8, 16 — doubling (×2): 2→4→8→16→32. Answer = J32. Trap: I32 = consecutive letter (wrong, should skip one); J24 = 16+8=24 (arithmetic not geometric); K32 = skips two letters.', 'EASY', 'Reasoning', 'Alphanumeric Series — Mixed Letter and Number Patterns (W10 B2)', 'RSN_ALPHANUMERIC_SERIES_W10_B2', '[{"option_text": "I32", "is_correct": false}, {"option_text": "J24", "is_correct": false}, {"option_text": "J32", "is_correct": true}, {"option_text": "K32", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d84d04ac-9382-567f-8af9-cdeb99f0d10a', 'Which term is wrong in the series? P3, R6, T9, V12, X16', NULL, 'C is correct. Letters: P, R, T, V, X — skip one letter each (+2). Numbers: 3, 6, 9, 12, ? — arithmetic +3. After V12, should be X15 (not X16). X16 is wrong — it should be X15. Trap: T9 looks suspicious (9=3×3 vs 3+3+3) but the letter T is correct (+2 from R) and the number 9 = 3+3+3 = correct (+3 from R6); 16 breaks the +3 pattern (should be 15).', 'MEDIUM', 'Reasoning', 'Alphanumeric Series — Mixed Letter and Number Patterns (W10 B2)', 'RSN_ALPHANUMERIC_SERIES_W10_B2', '[{"option_text": "T9", "is_correct": false}, {"option_text": "V12", "is_correct": false}, {"option_text": "X16", "is_correct": true}, {"option_text": "R6", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6be02e9f-252a-5d31-833f-a91b7c76e8c3', 'Find the next term: AZ, BY, CX, DW, ?', NULL, 'A is correct. First letters: A, B, C, D — move forward (+1): next = E. Second letters: Z, Y, X, W — move backward (−1): next = V. Answer = EV. Trap: EU = second letter goes back two positions (wrong); FV = first letter skips one (wrong); EW = second letter doesn''t change (wrong).', 'MEDIUM', 'Reasoning', 'Alphanumeric Series — Mixed Letter and Number Patterns (W10 B2)', 'RSN_ALPHANUMERIC_SERIES_W10_B2', '[{"option_text": "EV", "is_correct": true}, {"option_text": "EU", "is_correct": false}, {"option_text": "FV", "is_correct": false}, {"option_text": "EW", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d27c0534-598e-5d07-bbe2-648ed61b540c', 'Find the next term in the series: 2A, 4D, 6G, 8J, ?', NULL, 'B is correct. Numbers: 2, 4, 6, 8 — even numbers (+2). Next = 10. Letters: A, D, G, J — every third letter (+3 each): A(1)→D(4)→G(7)→J(10)→M(13). Answer = 10M. Trap: 10L = next letter is L (12th position), but the gap between J(10) and L(12) is only +2 not +3; 12M = wrong number; 10N = N is 14th position (+4 from J).', 'MEDIUM', 'Reasoning', 'Alphanumeric Series — Mixed Letter and Number Patterns (W10 B2)', 'RSN_ALPHANUMERIC_SERIES_W10_B2', '[{"option_text": "10L", "is_correct": false}, {"option_text": "10M", "is_correct": true}, {"option_text": "12M", "is_correct": false}, {"option_text": "10N", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7318848c-af1f-5c08-958f-f052e915a6c4', 'Complete the series: 3F, 6J, 9N, 12R, ?', NULL, 'C is correct. Numbers: 3, 6, 9, 12 (+3 each). Next = 15. Letters: F(6), J(10), N(14), R(18) — positions increase by 4 each. Next = 18+4 = 22nd letter = V. Answer = 15V. Trap: 15T = T is 20th letter (+2 from R); 16V = wrong number; 14T = both wrong. Alphabet positions: A=1, F=6, J=10, N=14, R=18, V=22.', 'MEDIUM', 'Reasoning', 'Alphanumeric Series — Mixed Letter and Number Patterns (W10 B2)', 'RSN_ALPHANUMERIC_SERIES_W10_B2', '[{"option_text": "14T", "is_correct": false}, {"option_text": "15T", "is_correct": false}, {"option_text": "15V", "is_correct": true}, {"option_text": "16V", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('95c79950-d522-5673-be91-1ec17b981cf5', 'In the series: M5N, P8Q, S11T, V14W, ?, what is the next term?', NULL, 'B is correct. First letters: M(13), P(16), S(19), V(22) — +3 each. Next = Y(25). Numbers: 5, 8, 11, 14 — +3 each. Next = 17. Last letters: N(14), Q(17), T(20), W(23) — +3 each. Next = Z(26). Answer = Y17Z. Trap: X17Y = X is 24th letter (+2 from V, wrong skip); Y18Z = 14+4=18 (wrong +4 instead of +3); Z17A = Z is 26th = +4 from V (wrong).', 'HARD', 'Reasoning', 'Alphanumeric Series — Mixed Letter and Number Patterns (W10 B2)', 'RSN_ALPHANUMERIC_SERIES_W10_B2', '[{"option_text": "X17Y", "is_correct": false}, {"option_text": "Y17Z", "is_correct": true}, {"option_text": "Y18Z", "is_correct": false}, {"option_text": "Z17A", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d6744de0-0687-59a4-9ee6-489387c242c1', 'Find the missing term: A1Z, C4X, E9V, G16T, ?', NULL, 'B is correct. First letters: A, C, E, G (+2 each). Next = I. Numbers: 1, 4, 9, 16 = 1², 2², 3², 4². Next = 5² = 25. Last letters: Z(26), X(24), V(22), T(20) (−2 each). Next = R(18). Answer = I25R. Trap: I24R = 16+8=24 (arithmetic pattern instead of squares); J25R = J is the wrong next letter (+3 from G); I25S = S(19) is one position too late.', 'HARD', 'Reasoning', 'Alphanumeric Series — Mixed Letter and Number Patterns (W10 B2)', 'RSN_ALPHANUMERIC_SERIES_W10_B2', '[{"option_text": "I24R", "is_correct": false}, {"option_text": "I25R", "is_correct": true}, {"option_text": "J25R", "is_correct": false}, {"option_text": "I25S", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9db1bacc-d788-55b3-973e-5b9c0c09ade1', 'What replaces the ''?'' in: B2E, D6H, F12K, H20N, ?', NULL, 'B is correct. First letters: B, D, F, H (+2 each). Next = J. Numbers: 2, 6, 12, 20 — differences are 4, 6, 8 (increasing by 2). Next difference = 10. 20+10 = 30. Last letters: E(5), H(8), K(11), N(14) (+3 each). Next = Q(17). Answer = J30Q. Trap: J28Q = 20+8=28 (wrong — repeats previous difference instead of increasing); K30Q = K is +3 from H (wrong — should be +2); J30R = R(18) is +4 from N (wrong).', 'HARD', 'Reasoning', 'Alphanumeric Series — Mixed Letter and Number Patterns (W10 B2)', 'RSN_ALPHANUMERIC_SERIES_W10_B2', '[{"option_text": "J28Q", "is_correct": false}, {"option_text": "J30Q", "is_correct": true}, {"option_text": "K30Q", "is_correct": false}, {"option_text": "J30R", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0f269e92-f73e-54f0-af38-8cfc64f305ce', 'Find the missing term: A1, C3, E5, G7, ?', NULL, 'B is correct. Letters: A, C, E, G — every alternate letter (skip one): A→C→E→G→I. Numbers: 1, 3, 5, 7 — odd numbers increasing by 2: next = 9. Next term = I9. Trap: J9 = advances letter by 3 (wrong); H8 = moves to the very next letter with next even number; I10 = uses correct letter but wrong number (10 is even, pattern uses odd numbers).', 'EASY', 'Reasoning', 'Alphanumeric Series — Pattern Identification (W11 B2)', 'RSN_ALPHANUMERIC_SERIES_W11_B2', '[{"option_text": "H8", "is_correct": false}, {"option_text": "I9", "is_correct": true}, {"option_text": "J9", "is_correct": false}, {"option_text": "I10", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7674440a-de82-58af-bbc0-5035493cd435', 'Find the missing term: Z1, X4, V9, T16, ?', NULL, 'A is correct. Letters: Z, X, V, T — going backward, skipping one letter each time: Z→X(skip Y)→V(skip W)→T(skip U)→R(skip S). Numbers: 1, 4, 9, 16 = 1², 2², 3², 4² → next = 5² = 25. Next term = R25. Trap: S25 = S is only one letter back from T (wrong; should skip one letter to get R); P25 = skips two letters instead of one.', 'MEDIUM', 'Reasoning', 'Alphanumeric Series — Pattern Identification (W11 B2)', 'RSN_ALPHANUMERIC_SERIES_W11_B2', '[{"option_text": "R25", "is_correct": true}, {"option_text": "S25", "is_correct": false}, {"option_text": "R24", "is_correct": false}, {"option_text": "P25", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0b8cd82c-fb5b-5c51-b70a-6966e6dea685', 'In the series: B2E, D4G, F6I, H8K, what comes next?', NULL, 'B is correct. Analyse each term: B(2)2E(5), D(4)4G(7), F(6)6I(9), H(8)8K(11). First letter: B,D,F,H → +2 each time → next = J(10). Number: 2,4,6,8 → +2 each time → next = 10. Last letter: E,G,I,K → +2 each time → next = M(13). Next term = J10M. Trap: J10L = L is only +1 from K (wrong; pattern is +2); K10M = K is wrong first letter (+1 from H instead of +2).', 'HARD', 'Reasoning', 'Alphanumeric Series — Pattern Identification (W11 B2)', 'RSN_ALPHANUMERIC_SERIES_W11_B2', '[{"option_text": "J10L", "is_correct": false}, {"option_text": "J10M", "is_correct": true}, {"option_text": "K10M", "is_correct": false}, {"option_text": "J12M", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0efc0a4b-3292-5c29-9dd6-e33b04335d48', 'Study the sequence: 2B4, 4D8, 6F12, 8H16, ?
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8dc3d7a0-0879-5e91-89ba-45cc5ce4623e', 'Find the odd one out in this alphanumeric series: P3Q, R5S, T7U, V8W, X11Y', NULL, 'C is correct. Pattern: each group is (letter)(prime number)(next consecutive letter). Numbers: 3, 5, 7, ?, 11. The primes in sequence are 3, 5, 7, 11 (skipping 9 which is not prime). The next prime after 7 is 11 — but V8W uses 8, which is NOT prime (8 = 2³). V8W breaks the prime-number pattern. Letters: P→Q (consecutive), R→S, T→U, V→W, X→Y — all consecutive letter pairs ✓. The flaw is the number 8 in V8W. Trap: X11Y uses 11 (prime) ✓; R5S uses 5 (prime) ✓.', 'HARD', 'Reasoning', 'Alphanumeric Series — Pattern Identification (W11 B2)', 'RSN_ALPHANUMERIC_SERIES_W11_B2', '[{"option_text": "P3Q", "is_correct": false}, {"option_text": "R5S", "is_correct": false}, {"option_text": "V8W", "is_correct": true}, {"option_text": "X11Y", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ce6d3bab-4f74-5854-827b-c712945e5bec', 'If the series A=1, B=2, C=3... Z=26, what is the value of CAB + BAC?', NULL, 'A is correct. Decode each letter using its alphabetical position: C=3, A=1, B=2. CAB = sum of its letters = C+A+B = 3+1+2 = 6. BAC = B+A+C = 2+1+3 = 6. CAB + BAC = 6+6 = 12. Trap: 18 = common wrong answer when students add A=1,B=2,C=3,D=4... and confuse position with value; 15 = result of some non-standard letter coding.', 'MEDIUM', 'Reasoning', 'Alphanumeric Series — Pattern Identification (W11 B2)', 'RSN_ALPHANUMERIC_SERIES_W11_B2', '[{"option_text": "12", "is_correct": true}, {"option_text": "15", "is_correct": false}, {"option_text": "18", "is_correct": false}, {"option_text": "21", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a7b754f6-84e2-550b-93f6-e01fcea7f3cd', 'In the series: M5N, O7P, Q9R, S11T, what is the next term?', NULL, 'B is correct. Pattern: each term = (letter)(number)(next consecutive letter). First letters: M(13), O(15), Q(17), S(19) → +2 each time → next = U(21). Numbers: 5, 7, 9, 11 → +2 each time → next = 13. Last letter = first letter + 1: M→N, O→P, Q→R, S→T → next = U→V. Next term = U13V. Trap: U12V = wrong number (12 not in odd-number pattern); V13W = wrong first letter (+3 from S instead of +2).', 'MEDIUM', 'Reasoning', 'Alphanumeric Series — Pattern Identification (W11 B2)', 'RSN_ALPHANUMERIC_SERIES_W11_B2', '[{"option_text": "U12V", "is_correct": false}, {"option_text": "U13V", "is_correct": true}, {"option_text": "V13W", "is_correct": false}, {"option_text": "U14V", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bb5d206c-4392-5571-aa5f-8f6c9183d69f', 'If PEN = 35 (P=16, E=5, N=14 → 16+5+14=35), what is the value of CAT?', NULL, 'B is correct. Using A=1, B=2, ... Z=26: C=3, A=1, T=20. CAT = 3+1+20 = 24. Verify: PEN = P(16)+E(5)+N(14) = 35 ✓ (confirms the coding). Trap: 20 = only T''s value; 28 = 3+5+20 (uses E''s value instead of A''s); 30 = 3+7+20 (wrong middle value).', 'EASY', 'Reasoning', 'Alphanumeric Series — Pattern Identification (W11 B2)', 'RSN_ALPHANUMERIC_SERIES_W11_B2', '[{"option_text": "20", "is_correct": false}, {"option_text": "24", "is_correct": true}, {"option_text": "28", "is_correct": false}, {"option_text": "30", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b4c7a49b-f945-5f31-a373-2b7bf3cd52f4', 'Find the missing term: 3A, 5C, 9E, 15G, ?', NULL, 'B is correct. Numbers: 3, 5, 9, 15 — differences: 2, 4, 6. Second differences are +2. Next difference = 8. Next number = 15+8 = 23. Letters: A, C, E, G — every alternate letter (+2 each): next = I. Next term = 23I. Trap: 21I = 15+6 (repeats the previous difference instead of increasing by 2); 23J = wrong letter (J is not +2 from G; I is).', 'HARD', 'Reasoning', 'Alphanumeric Series — Pattern Identification (W11 B2)', 'RSN_ALPHANUMERIC_SERIES_W11_B2', '[{"option_text": "21I", "is_correct": false}, {"option_text": "23I", "is_correct": true}, {"option_text": "21H", "is_correct": false}, {"option_text": "23J", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a7878ab9-778d-5905-b88c-cbb387248ef0', 'In a certain code: A=2, B=4, C=6... (each letter = 2 × position number). What is the code for DOG?', NULL, 'A is correct. Rule: each letter = 2 × position. D is 4th → 2×4=8; O is 15th → 2×15=30; G is 7th → 2×7=14. DOG = 8+30+14 = 52. Verify with the given code: A=2(1st)=2, B=2(2nd)=4, C=2(3rd)=6 ✓. Trap: 64 = uses O=32 (wrong; 15th → 30, not 32); 26 = uses raw position values D=4,O=15,G=7 → 4+15+7=26 (omits the ×2 multiplier).', 'MEDIUM', 'Reasoning', 'Alphanumeric Series — Pattern Identification (W11 B2)', 'RSN_ALPHANUMERIC_SERIES_W11_B2', '[{"option_text": "52", "is_correct": true}, {"option_text": "64", "is_correct": false}, {"option_text": "26", "is_correct": false}, {"option_text": "48", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('34b0536e-56d9-5444-aa97-fea6a0376175', 'Find the next term: A1, B2, C3, D4, ?', NULL, 'A is correct. Letter advances by 1 (A,B,C,D,E); number advances by 1 (1,2,3,4,5). Next = E5.', 'EASY', 'Reasoning', 'Alpha-Numeric Series (W9)', 'RSN_ALPHA_NUMERIC_W9', '[{"option_text": "E5", "is_correct": true}, {"option_text": "F5", "is_correct": false}, {"option_text": "E6", "is_correct": false}, {"option_text": "F6", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7333e444-49c4-5b68-b181-81d700e7ea72', 'Find the next term: 2A, 4B, 6C, 8D, ?', NULL, 'B is correct. Numbers: 2,4,6,8 (+2 each) → next = 10. Letters: A,B,C,D (+1) → next = E. Answer = 10E.', 'EASY', 'Reasoning', 'Alpha-Numeric Series (W9)', 'RSN_ALPHA_NUMERIC_W9', '[{"option_text": "9E", "is_correct": false}, {"option_text": "10E", "is_correct": true}, {"option_text": "10F", "is_correct": false}, {"option_text": "12E", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c0626f1d-3eae-52f6-af09-8121e3271a11', 'Find the next term: Z1, Y4, X9, W16, ?', NULL, 'A is correct. Letters go backwards: Z,Y,X,W → next = V. Numbers are perfect squares: 1,4,9,16 → next = 25. Answer = V25.', 'EASY', 'Reasoning', 'Alpha-Numeric Series (W9)', 'RSN_ALPHA_NUMERIC_W9', '[{"option_text": "V25", "is_correct": true}, {"option_text": "U25", "is_correct": false}, {"option_text": "V36", "is_correct": false}, {"option_text": "U36", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('210b46c0-c03e-58ae-8c8a-f139f12b7e64', 'Find the next term: A1B2, C3D4, E5F6, ?', NULL, 'A is correct. Each group has two letter-number pairs. Letters continue A,B,C,D,E,F → G,H. Numbers continue 1,2,3,4,5,6 → 7,8. Next group = G7H8.', 'MEDIUM', 'Reasoning', 'Alpha-Numeric Series (W9)', 'RSN_ALPHA_NUMERIC_W9', '[{"option_text": "G7H8", "is_correct": true}, {"option_text": "G8H7", "is_correct": false}, {"option_text": "H7G8", "is_correct": false}, {"option_text": "G7H9", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ee3baed2-24b2-55b3-b6ee-385ea2c0bcde', 'Find the next term: A2B, B4C, C6D, ?', NULL, 'B is correct. First letter: A,B,C,D (+1). Number: 2,4,6,8 (+2). Last letter is one after the first: B,C,D,E (+1). Next term = D8E.', 'MEDIUM', 'Reasoning', 'Alpha-Numeric Series (W9)', 'RSN_ALPHA_NUMERIC_W9', '[{"option_text": "D7E", "is_correct": false}, {"option_text": "D8E", "is_correct": true}, {"option_text": "E8F", "is_correct": false}, {"option_text": "D8F", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('725b3485-fea0-56d1-8156-49bfedba4bd0', 'Find the next term: 3B, 5D, 7F, 9H, ?', NULL, 'B is correct. Numbers: 3,5,7,9 (+2) → next = 11. Letters: B(2),D(4),F(6),H(8) (+2 positions) → next = J(10). Answer = 11J.', 'MEDIUM', 'Reasoning', 'Alpha-Numeric Series (W9)', 'RSN_ALPHA_NUMERIC_W9', '[{"option_text": "10J", "is_correct": false}, {"option_text": "11J", "is_correct": true}, {"option_text": "11K", "is_correct": false}, {"option_text": "10K", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6ec031a6-d96d-54eb-b058-3b2c6d7791d4', 'Find the next term: P2Q, Q3R, R4S, S5T, ?', NULL, 'A is correct. First letter: P,Q,R,S,T (+1). Number: 2,3,4,5,6 (+1). Last letter is one after the first: Q,R,S,T,U (+1). Next = T6U.', 'MEDIUM', 'Reasoning', 'Alpha-Numeric Series (W9)', 'RSN_ALPHA_NUMERIC_W9', '[{"option_text": "T6U", "is_correct": true}, {"option_text": "U6T", "is_correct": false}, {"option_text": "T5U", "is_correct": false}, {"option_text": "S6T", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('96ac7602-21a3-5a28-96e3-29b6a644dcef', 'Find the next term: A4, C9, E16, G25, ?', NULL, 'A is correct. Letters: A(1st),C(3rd),E(5th),G(7th) — alternate odd-positioned letters → next = I(9th). Numbers: 4=2²,9=3²,16=4²,25=5² → next = 6²=36. Answer = I36.', 'MEDIUM', 'Reasoning', 'Alpha-Numeric Series (W9)', 'RSN_ALPHA_NUMERIC_W9', '[{"option_text": "I36", "is_correct": true}, {"option_text": "H36", "is_correct": false}, {"option_text": "I49", "is_correct": false}, {"option_text": "H49", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4218cbb3-49fa-5a0e-afff-0fe2f8a0bd5b', 'Find the next term: A1Z, B4Y, C9X, D16W, ?', NULL, 'A is correct. First letter: A,B,C,D,E (+1). Middle number: 1,4,9,16,25 (perfect squares 1²,2²,3²,4²,5²). Last letter: Z,Y,X,W,V (retreating from Z). Next = E25V.', 'HARD', 'Reasoning', 'Alpha-Numeric Series (W9)', 'RSN_ALPHA_NUMERIC_W9', '[{"option_text": "E25V", "is_correct": true}, {"option_text": "E36V", "is_correct": false}, {"option_text": "F25V", "is_correct": false}, {"option_text": "E25U", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c652d4b4-6315-5f98-ad1c-fe171b2f2646', 'Find the next group: A2B4C, B4C8D, C8D16E, ?', NULL, 'A is correct. Each group: starting letter +1 (A→B→C→D); first number doubles (2→4→8→16); middle letters follow (+1 each); second number doubles (4→8→16→32); last letter +1 (C→D→E→F). Next group = D16E32F.', 'HARD', 'Reasoning', 'Alpha-Numeric Series (W9)', 'RSN_ALPHA_NUMERIC_W9', '[{"option_text": "D16E32F", "is_correct": true}, {"option_text": "D8E16F", "is_correct": false}, {"option_text": "E16F32G", "is_correct": false}, {"option_text": "D16E16F", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b435441d-6912-54ca-87d9-4403da6928d1', 'Find the next term: A, C, E, G, ?', NULL, 'B is correct. Alternate letters (skipping one each time): A, C, E, G → next = I.', 'EASY', 'Reasoning', 'Alphabetical Series (W9)', 'RSN_ALPHA_SERIES_W9', '[{"option_text": "H", "is_correct": false}, {"option_text": "I", "is_correct": true}, {"option_text": "J", "is_correct": false}, {"option_text": "K", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c96ad580-ab5f-5b1f-bcd2-115d74991adb', 'Find the next pair: AB, DE, GH, JK, ?', NULL, 'B is correct. Each pair skips two letters: AB→(skip CD)→DE→(skip EF)→GH→(skip IJ)→JK→(skip KL)→MN.', 'EASY', 'Reasoning', 'Alphabetical Series (W9)', 'RSN_ALPHA_SERIES_W9', '[{"option_text": "LM", "is_correct": false}, {"option_text": "MN", "is_correct": true}, {"option_text": "NO", "is_correct": false}, {"option_text": "LN", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('23f06fe8-d9fe-56eb-af2c-869765245295', 'Find the next pair: AZ, BY, CX, ?', NULL, 'A is correct. First letter advances (A,B,C,D); second letter retreats from Z (Z,Y,X,W). Pattern: each pair has letters that sum to 27 (A+Z=1+26). Next pair = DW.', 'EASY', 'Reasoning', 'Alphabetical Series (W9)', 'RSN_ALPHA_SERIES_W9', '[{"option_text": "DW", "is_correct": true}, {"option_text": "DX", "is_correct": false}, {"option_text": "EW", "is_correct": false}, {"option_text": "DV", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7041ed3f-a383-5d11-a92f-a67d1c086489', 'Find the next term: ABB, CDC, EFE, ?', NULL, 'B is correct. Pattern: X(2n−1)Y(2n)X(2n−1) → A(1)B(2)A(1)=ABB? Wait: ABB=A,B,B. Actually: A,B,B; C,D,C; E,F,E → the 1st and 3rd letter of each triple match, and are consecutive odd-positional letters; the 2nd letter is consecutive even. G,H,G → GHG.', 'MEDIUM', 'Reasoning', 'Alphabetical Series (W9)', 'RSN_ALPHA_SERIES_W9', '[{"option_text": "GGH", "is_correct": false}, {"option_text": "GHG", "is_correct": true}, {"option_text": "HGH", "is_correct": false}, {"option_text": "GHH", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d225862e-13a0-553a-a5b8-fc6ab7e20a7f', 'Find the next term in the series: A, B, D, G, K, ?', NULL, 'C is correct. Differences in positions: B−A=1, D−B=2, G−D=3, K−G=4. Next difference = 5: K(11)+5 = P(16).', 'MEDIUM', 'Reasoning', 'Alphabetical Series (W9)', 'RSN_ALPHA_SERIES_W9', '[{"option_text": "N", "is_correct": false}, {"option_text": "O", "is_correct": false}, {"option_text": "P", "is_correct": true}, {"option_text": "Q", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('03d1e73a-9804-5e5c-b9dd-e25d612fd1ce', 'Find the next term: Z, X, V, T, R, ?', NULL, 'C is correct. Each letter decreases by 2 positions: Z(26),X(24),V(22),T(20),R(18) → P(16).', 'MEDIUM', 'Reasoning', 'Alphabetical Series (W9)', 'RSN_ALPHA_SERIES_W9', '[{"option_text": "N", "is_correct": false}, {"option_text": "O", "is_correct": false}, {"option_text": "P", "is_correct": true}, {"option_text": "Q", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b8412a5c-c34f-5b3b-8d77-4d7966cc52d2', 'Find the next group: ACE, FHJ, KMO, ?', NULL, 'B is correct. Each group has alternate letters starting at +5 from previous group''s start: A(1),C(3),E(5); F(6),H(8),J(10); K(11),M(13),O(15); P(16),R(18),T(20) → PRT.', 'MEDIUM', 'Reasoning', 'Alphabetical Series (W9)', 'RSN_ALPHA_SERIES_W9', '[{"option_text": "PQR", "is_correct": false}, {"option_text": "PRT", "is_correct": true}, {"option_text": "QSU", "is_correct": false}, {"option_text": "PRU", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8dc38c70-07d2-578c-8b17-59c42a0624eb', 'Find the next pair: AE, BF, CG, ?', NULL, 'A is correct. First letter: A,B,C,D (+1 each). Second letter is first letter +4: A+4=E, B+4=F, C+4=G, D+4=H. Next pair = DH.', 'MEDIUM', 'Reasoning', 'Alphabetical Series (W9)', 'RSN_ALPHA_SERIES_W9', '[{"option_text": "DH", "is_correct": true}, {"option_text": "DI", "is_correct": false}, {"option_text": "EH", "is_correct": false}, {"option_text": "DG", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e5732f50-4301-58f4-bc67-dbe9e08eeb31', 'Find the next pair: AZ, CX, EV, GT, ?', NULL, 'A is correct. First letters: A(1),C(3),E(5),G(7) → next = I(9). Second letters: Z(26),X(24),V(22),T(20) → next = R(18). Each pair sums to 27 in positions. Next pair = IR.', 'HARD', 'Reasoning', 'Alphabetical Series (W9)', 'RSN_ALPHA_SERIES_W9', '[{"option_text": "IR", "is_correct": true}, {"option_text": "IS", "is_correct": false}, {"option_text": "HR", "is_correct": false}, {"option_text": "IQ", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cae28912-406c-5811-8887-db0972bc00c6', 'Find the next term: B2E, D4G, F6I, H8K, ?', NULL, 'A is correct. First letter: B,D,F,H (+2 each) → next = J. Number: 2,4,6,8 (+2 each) → next = 10. Third letter is first letter +3: B→E, D→G, F→I, H→K, J→M. Next term = J10M.', 'HARD', 'Reasoning', 'Alphabetical Series (W9)', 'RSN_ALPHA_SERIES_W9', '[{"option_text": "J10M", "is_correct": true}, {"option_text": "J10N", "is_correct": false}, {"option_text": "K10M", "is_correct": false}, {"option_text": "J8M", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2deef610-1287-50d9-816f-c8ddeb40106b', '3 : 9 :: 5 : ?', NULL, 'C is correct. Relationship: each number squared. 3² = 9. Apply to 5: 5² = 25. Verify: 3→9 (×3 or 3²=9); checking ×3: 5×3=15 (wrong option). Correct pattern is 3²=9, confirming square pattern (3×3=9, 5×5=25). Trap: 15 = uses ×3 relationship (wrong — 3²=9 is the squaring pattern, not ×3 because 5×3=15 but 5²=25).', 'EASY', 'Reasoning', 'Analogy — Number, Letter and Semantic Pairs (W12 B1)', 'RSN_ANALOGY_ADVANCED_W12_B1', '[{"option_text": "10", "is_correct": false}, {"option_text": "15", "is_correct": false}, {"option_text": "25", "is_correct": true}, {"option_text": "30", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b8ff7b99-2a7c-5192-98d4-096fb2939e06', 'ACE : BDF :: MOQ : ?', NULL, 'B is correct. Each letter in ACE is shifted +1 to form BDF. A+1=B ✓; C+1=D ✓; E+1=F ✓. Apply to MOQ: M+1=N; O+1=P; Q+1=R. Code = NPR. Verify: M(13)→N(14); O(15)→P(16); Q(17)→R(18) ✓. Trap: NOP = shifts M+1=N, O+0=O (wrong, O should shift too), P=? inconsistent; LNP = shifts by −1 (wrong direction).', 'EASY', 'Reasoning', 'Analogy — Number, Letter and Semantic Pairs (W12 B1)', 'RSN_ANALOGY_ADVANCED_W12_B1', '[{"option_text": "NOP", "is_correct": false}, {"option_text": "NPR", "is_correct": true}, {"option_text": "LNP", "is_correct": false}, {"option_text": "NPS", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('949ae920-476a-53df-a0df-968f2d69faae', 'Dog : Kennel :: Cow : ?', NULL, 'B is correct. Relationship: animal and its dwelling. Dog lives in a Kennel. Cow lives in a Stable (also called a Byre). Trap: Burrow = rabbit/badger dwelling; Sty = pig dwelling; Den = lion''s dwelling. Classic SSC animal-home set: Dog→Kennel; Horse→Stable; Pig→Sty; Rabbit→Burrow; Lion→Den; Fox→Earth; Bee→Hive; Bird→Nest; Cow→Stable/Shed.', 'EASY', 'Reasoning', 'Analogy — Number, Letter and Semantic Pairs (W12 B1)', 'RSN_ANALOGY_ADVANCED_W12_B1', '[{"option_text": "Burrow", "is_correct": false}, {"option_text": "Stable", "is_correct": true}, {"option_text": "Sty", "is_correct": false}, {"option_text": "Den", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6df965e5-d86e-512e-bb0f-8af9921d3655', 'ABCD : DCBA :: EFGH : ?', NULL, 'B is correct. Relationship: the letter group is reversed. ABCD reversed = DCBA ✓ (D-C-B-A). Apply to EFGH: reversed = H-G-F-E = HGFE. Verify: E(1st)→E(4th position in HGFE); F(2nd)→F(3rd); G(3rd)→G(2nd); H(4th)→H(1st) ✓. Trap: GHEF = not a reversal (rearrangement only); HEFG = only partial reversal.', 'MEDIUM', 'Reasoning', 'Analogy — Number, Letter and Semantic Pairs (W12 B1)', 'RSN_ANALOGY_ADVANCED_W12_B1', '[{"option_text": "GHEF", "is_correct": false}, {"option_text": "HGFE", "is_correct": true}, {"option_text": "HEFG", "is_correct": false}, {"option_text": "FGHE", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('03d243cd-b245-5541-b735-612498e8b87d', '12 : 21 :: 45 : ?', NULL, 'C is correct. Relationship: reverse the digits of the number. 12 reversed = 21 ✓. Apply to 45: reversed = 54. Verify: 4 and 5 → reversed = 54 ✓. Trap: 55 = sums the digits then doubles (4+5=9→?); 50 = adds 5 to 45 (arithmetic, not the digit-reversal pattern).', 'MEDIUM', 'Reasoning', 'Analogy — Number, Letter and Semantic Pairs (W12 B1)', 'RSN_ANALOGY_ADVANCED_W12_B1', '[{"option_text": "44", "is_correct": false}, {"option_text": "50", "is_correct": false}, {"option_text": "54", "is_correct": true}, {"option_text": "55", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('61cd5414-6645-50e1-8d3f-f2573b548333', '4 : 64 :: 6 : ?', NULL, 'C is correct. Relationship: each number is cubed. 4³ = 64 ✓. Apply to 6: 6³ = 216. Verify: 6×6×6=216 ✓. Trap: 256 = 4⁴ or 2⁸ (fourth power, not cube); 196 = 14² (perfect square, not cube); 108 = 6²×3 (wrong formula).', 'MEDIUM', 'Reasoning', 'Analogy — Number, Letter and Semantic Pairs (W12 B1)', 'RSN_ANALOGY_ADVANCED_W12_B1', '[{"option_text": "108", "is_correct": false}, {"option_text": "196", "is_correct": false}, {"option_text": "216", "is_correct": true}, {"option_text": "256", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ff8a94f9-7e60-55b9-a45f-4463c4e92ecb', 'COLD : WARM :: DRY : ?', NULL, 'C is correct. Relationship: ANTONYM pairs. COLD is the opposite of WARM. DRY (having no or little moisture) is the opposite of WET (covered or saturated with water). Trap: HOT = antonym of cold (but that would be using cold''s antonym, not applying the COLD:WARM pair pattern to DRY); DAMP = near-synonym of wet or moist, but ''moist'' and ''damp'' are intermediate states; WET is the direct antonym of DRY.', 'MEDIUM', 'Reasoning', 'Analogy — Number, Letter and Semantic Pairs (W12 B1)', 'RSN_ANALOGY_ADVANCED_W12_B1', '[{"option_text": "Hot", "is_correct": false}, {"option_text": "Moist", "is_correct": false}, {"option_text": "Wet", "is_correct": true}, {"option_text": "Damp", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('955a5c15-0f5d-56da-9050-57572d2e4ffb', 'Surgeon : Scalpel :: Carpenter : ?', NULL, 'B is correct. Relationship: WORKER : PRIMARY CUTTING TOOL. A surgeon''s primary cutting instrument is a scalpel. A carpenter''s primary cutting instrument is a saw. Trap: Anvil = blacksmith''s tool (used with a hammer for metal shaping); Palette = painter''s tool (for mixing colours); Brick = building material (mason''s material, not a tool). Carpenter uses: saw (cutting), hammer (nailing), plane (smoothing), chisel (carving) — saw is the most distinctive cutting tool.', 'MEDIUM', 'Reasoning', 'Analogy — Number, Letter and Semantic Pairs (W12 B1)', 'RSN_ANALOGY_ADVANCED_W12_B1', '[{"option_text": "Brick", "is_correct": false}, {"option_text": "Saw", "is_correct": true}, {"option_text": "Anvil", "is_correct": false}, {"option_text": "Palette", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ef93b994-6df3-5e4f-83b9-41aa2b0090dd', '7 : 56 :: 9 : ?', NULL, 'C is correct. 7 : 56 → 7 × (7+1) = 7 × 8 = 56 ✓. Pattern: n × (n+1). Apply to 9: 9 × (9+1) = 9 × 10 = 90. Verify: 7×8=56 ✓; 9×10=90 ✓. Trap: 81 = 9² (square); 72 = 9×8 (uses 9×(9-1) instead of 9×(9+1)); 63 = 9×7 (wrong multiplier). The key is spotting that 56=7×8 = n×(n+1), not 7²=49.', 'HARD', 'Reasoning', 'Analogy — Number, Letter and Semantic Pairs (W12 B1)', 'RSN_ANALOGY_ADVANCED_W12_B1', '[{"option_text": "81", "is_correct": false}, {"option_text": "72", "is_correct": false}, {"option_text": "90", "is_correct": true}, {"option_text": "63", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('759d5c95-bc40-5ea0-ba4a-697b76153cd6', 'AZ : BY :: CX : ?', NULL, 'C is correct. Pattern: each pair consists of one letter from the start of the alphabet and one from the end, paired so that both positions from their respective ends sum to 27. A(1)+Z(26)=27; B(2)+Y(25)=27; C(3)+X(24)=27; D(4)+W(23)=27. CX → next pair = DW. Alternatively: each first letter increases by 1 (A→B→C→D); each second letter decreases by 1 (Z→Y→X→W). Trap: DV = W=23 in alphabet (V=22, wrong); DU = U=21 (wrong, skipped a position); EW = first letter skips C→E.', 'HARD', 'Reasoning', 'Analogy — Number, Letter and Semantic Pairs (W12 B1)', 'RSN_ANALOGY_ADVANCED_W12_B1', '[{"option_text": "DU", "is_correct": false}, {"option_text": "DV", "is_correct": false}, {"option_text": "DW", "is_correct": true}, {"option_text": "EW", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('05fe5b20-90c0-5074-a5fb-279ca4d2ead3', 'DOCTOR : STETHOSCOPE :: CARPENTER : ?', NULL, 'B is correct. The relationship is: professional → primary tool. Doctor uses a stethoscope; Carpenter uses a saw. Trap: Scalpel = a surgeon''s tool (not stethoscope user''s different tool — the analogy is about the profession:tool pair, not same professional different tool); Microscope and Thermometer are other medical tools (wrong profession).', 'EASY', 'Reasoning', 'Analogy — Advanced Word and Number Relationships (W11 B1)', 'RSN_ANALOGY_ADV_W11_B1', '[{"option_text": "Microscope", "is_correct": false}, {"option_text": "Saw", "is_correct": true}, {"option_text": "Scalpel", "is_correct": false}, {"option_text": "Thermometer", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cea83072-033d-57a4-8a90-51d955f5f3b4', 'LION : DEN :: BEE : ?', NULL, 'C is correct. Relationship: animal → its home/dwelling. Lion lives in a den; Bee lives in a hive. Trap: Nest = home of birds (not bees); Burrow = underground home of rabbits/foxes; Web = where spiders live (not bees).', 'EASY', 'Reasoning', 'Analogy — Advanced Word and Number Relationships (W11 B1)', 'RSN_ANALOGY_ADV_W11_B1', '[{"option_text": "Nest", "is_correct": false}, {"option_text": "Burrow", "is_correct": false}, {"option_text": "Hive", "is_correct": true}, {"option_text": "Web", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bb50fdb3-1fdf-593c-8da0-2d5b6f4f29f7', 'ACROPHOBIA : HEIGHTS :: CLAUSTROPHOBIA : ?', NULL, 'C is correct. Relationship: phobia → feared thing. Acrophobia = fear of heights. Claustrophobia = fear of confined/enclosed spaces. Root: ''claustro'' = enclosed. Trap: Open spaces = agoraphobia (fear of open/public spaces — the opposite of claustrophobia); Darkness = nyctophobia/scotophobia; Water = aquaphobia/hydrophobia.', 'MEDIUM', 'Reasoning', 'Analogy — Advanced Word and Number Relationships (W11 B1)', 'RSN_ANALOGY_ADV_W11_B1', '[{"option_text": "Open spaces", "is_correct": false}, {"option_text": "Darkness", "is_correct": false}, {"option_text": "Confined spaces", "is_correct": true}, {"option_text": "Water", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a30437de-57cd-5ecc-bd83-3768f97886e1', 'PARLIAMENT : INDIA :: CONGRESS : ?', NULL, 'D is correct. Relationship: legislative body → country. Parliament is India''s legislature. Congress is the United States'' legislature (comprising the Senate and House of Representatives). Trap: Russia = State Duma/Federation Council; France = Parlement; UK = Parliament too (but the given body is ''Congress'' which is specifically the US legislature).', 'MEDIUM', 'Reasoning', 'Analogy — Advanced Word and Number Relationships (W11 B1)', 'RSN_ANALOGY_ADV_W11_B1', '[{"option_text": "Russia", "is_correct": false}, {"option_text": "France", "is_correct": false}, {"option_text": "UK", "is_correct": false}, {"option_text": "USA", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fba17676-c685-5359-8a20-41e0f0052565', '4 : 64 :: 5 : ?', NULL, 'B is correct. Relationship: n : n³. 4³ = 64. 5³ = 125. Trap: 100 = 5² × 4 (wrong operation); 150 = 5×30 (arbitrary); 175 = some wrong computation. Simple rule: cube the number.', 'EASY', 'Reasoning', 'Analogy — Advanced Word and Number Relationships (W11 B1)', 'RSN_ANALOGY_ADV_W11_B1', '[{"option_text": "100", "is_correct": false}, {"option_text": "125", "is_correct": true}, {"option_text": "150", "is_correct": false}, {"option_text": "175", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5bbb5ac6-94b2-5fd1-9cb3-7215652e5d62', 'ABODE : RESIDENCE :: MENDACIOUS : ?', NULL, 'C is correct. Relationship: word → its synonym. Abode = Residence (both mean a place where one lives). Mendacious = Untruthful (both mean lying/dishonest). Root: ''mendax'' (Latin) = lying. Trap: Truthful = antonym of mendacious; Polite = completely unrelated; Virtuous = morally good (unrelated to the lying/truth dimension).', 'HARD', 'Reasoning', 'Analogy — Advanced Word and Number Relationships (W11 B1)', 'RSN_ANALOGY_ADV_W11_B1', '[{"option_text": "Truthful", "is_correct": false}, {"option_text": "Polite", "is_correct": false}, {"option_text": "Untruthful", "is_correct": true}, {"option_text": "Virtuous", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('aa6b4e14-5473-5b43-8b6b-04261f56d4f6', 'MANGO : FRUIT :: COBRA : ?', NULL, 'C is correct. Relationship: specific species → its broader category. Mango is a fruit. Cobra is a reptile (snake = reptile). Trap: Animal = too broad (mango is also technically a living thing/plant — the analogy uses the specific immediate category, not the broadest); Venom = what cobra produces (not its category); Amphibian = frogs/salamanders (reptiles and amphibians are distinct classes).', 'MEDIUM', 'Reasoning', 'Analogy — Advanced Word and Number Relationships (W11 B1)', 'RSN_ANALOGY_ADV_W11_B1', '[{"option_text": "Animal", "is_correct": false}, {"option_text": "Venom", "is_correct": false}, {"option_text": "Reptile", "is_correct": true}, {"option_text": "Amphibian", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('392477be-96b3-5e03-becb-2fa1ba79f077', 'CELSIUS : TEMPERATURE :: DECIBEL : ?', NULL, 'B is correct. Relationship: unit of measurement → what it measures. Celsius measures temperature. Decibel measures sound intensity/loudness. Trap: Weight = measured in kg/Newton (not decibel); Light = measured in lux/candela; Pressure = measured in Pascal/bar.', 'MEDIUM', 'Reasoning', 'Analogy — Advanced Word and Number Relationships (W11 B1)', 'RSN_ANALOGY_ADV_W11_B1', '[{"option_text": "Weight", "is_correct": false}, {"option_text": "Sound intensity", "is_correct": true}, {"option_text": "Light", "is_correct": false}, {"option_text": "Pressure", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a1ddca43-902c-53e7-9e66-0ca61ea8a632', '14 : 9 :: 26 : ?', NULL, 'B is correct. Relationship: 14→9. 14−5=9. Or: 14 = 2×7, 9 = 2×7−5? Let me try: 14−9=5. 26−?=5? → ?=21. Let me verify: 26−21=5 ✓. So the relationship is: second number = first number − 5. 14−5=9 ✓. 26−5=21 ✓. Trap: 19 = 26−7 (wrong difference); 23 = 26−3; 25 = 26−1.', 'HARD', 'Reasoning', 'Analogy — Advanced Word and Number Relationships (W11 B1)', 'RSN_ANALOGY_ADV_W11_B1', '[{"option_text": "19", "is_correct": false}, {"option_text": "21", "is_correct": true}, {"option_text": "23", "is_correct": false}, {"option_text": "25", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0556fec8-b165-5cfd-9bfd-2873b85f8827', 'OPHTHALMOLOGY : EYES :: NEPHROLOGY : ?', NULL, 'C is correct. Relationship: medical specialty → organ/system it deals with. Ophthalmology = study and treatment of eyes. Nephrology = study and treatment of kidneys (root: ''nephros'' = Greek for kidney). Trap: Lungs = pulmonology; Brain = neurology; Bones = orthopedics/osteology. Other nephrology-root words: nephritis (kidney inflammation), nephrectomy (kidney removal).', 'HARD', 'Reasoning', 'Analogy — Advanced Word and Number Relationships (W11 B1)', 'RSN_ANALOGY_ADV_W11_B1', '[{"option_text": "Lungs", "is_correct": false}, {"option_text": "Brain", "is_correct": false}, {"option_text": "Kidneys", "is_correct": true}, {"option_text": "Bones", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('41f6a2f8-9df1-56bc-99fb-9d68711601e6', 'Pen : Writing :: Stethoscope : ?', NULL, 'C is correct. The relationship is Tool : Function (what the tool is used for). A Pen is used for Writing; a Stethoscope is used for Diagnosis. Trap: ''Doctor'' is the user of the stethoscope, not its function; ''Medicine'' is the broader field.', 'EASY', 'Reasoning', 'Analogy — Objects, Science, Letters and Numbers (W10)', 'RSN_ANALOGY_W10', '[{"option_text": "Medicine", "is_correct": false}, {"option_text": "Doctor", "is_correct": false}, {"option_text": "Diagnosis", "is_correct": true}, {"option_text": "Hospital", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('af15c189-f5cd-594e-8cbe-415a8c7479ed', 'Cat : Kitten :: Horse : ?', NULL, 'C is correct. The relationship is Animal : Young one. The young of a Cat is a Kitten; the young of a Horse is a Foal. Trap: Pony is a small breed of horse (not a young one); Colt is specifically a young male horse; Fawn is the young of a Deer.', 'EASY', 'Reasoning', 'Analogy — Objects, Science, Letters and Numbers (W10)', 'RSN_ANALOGY_W10', '[{"option_text": "Pony", "is_correct": false}, {"option_text": "Colt", "is_correct": false}, {"option_text": "Foal", "is_correct": true}, {"option_text": "Fawn", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9c654e8f-7592-537a-8cac-9a336ccb3c9b', 'Dozen : 12 :: Score : ?', NULL, 'C is correct. The relationship is Collective term : Its numerical value. Dozen = 12; Score = 20. Other standard terms: Gross = 144; Baker''s dozen = 13; Fortnight = 14 days. Trap: 15 is a common wrong answer for ''Score'' due to the word''s non-numerical everyday use.', 'EASY', 'Reasoning', 'Analogy — Objects, Science, Letters and Numbers (W10)', 'RSN_ANALOGY_W10', '[{"option_text": "15", "is_correct": false}, {"option_text": "18", "is_correct": false}, {"option_text": "20", "is_correct": true}, {"option_text": "25", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dd742f92-675e-50a4-9c83-bd5bf160ef7e', 'Geology : Earth :: Ornithology : ?', NULL, 'B is correct. The relationship is Branch of science : Subject studied. Geology studies the Earth; Ornithology studies Birds. Other sciences: Entomology = insects; Astronomy = stars/celestial bodies; Botany = plants. Trap: Entomology sounds similar to Ornithology — both end in ''-ology'' and are animal sciences.', 'MEDIUM', 'Reasoning', 'Analogy — Objects, Science, Letters and Numbers (W10)', 'RSN_ANALOGY_W10', '[{"option_text": "Plants", "is_correct": false}, {"option_text": "Birds", "is_correct": true}, {"option_text": "Stars", "is_correct": false}, {"option_text": "Insects", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c3258ba4-7f3b-533d-8260-cf81ddf358a1', 'India : Rupee :: Japan : ?', NULL, 'C is correct. The relationship is Country : Currency. India uses the Rupee; Japan uses the Yen. Trap: Dollar (USA/Australia); Won (South Korea); Yuan (China). Won and Yen both relate to East Asian economies — students often confuse them.', 'MEDIUM', 'Reasoning', 'Analogy — Objects, Science, Letters and Numbers (W10)', 'RSN_ANALOGY_W10', '[{"option_text": "Dollar", "is_correct": false}, {"option_text": "Won", "is_correct": false}, {"option_text": "Yen", "is_correct": true}, {"option_text": "Yuan", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0cf7c587-db2a-52cc-95a9-a8e7c4098014', 'ABCD : ZYXW :: EFGH : ?', NULL, 'A is correct. Each letter is paired with its ''mirror'' in the alphabet (A↔Z, B↔Y, C↔X, D↔W using position sum = 27). So E(5)↔V(22), F(6)↔U(21), G(7)↔T(20), H(8)↔S(19) → VUTS. Trap: WVUT reverses the last four letters of the alphabet rather than applying the complementary-position rule to EFGH.', 'MEDIUM', 'Reasoning', 'Analogy — Objects, Science, Letters and Numbers (W10)', 'RSN_ANALOGY_W10', '[{"option_text": "VUTS", "is_correct": true}, {"option_text": "WVUT", "is_correct": false}, {"option_text": "UVWX", "is_correct": false}, {"option_text": "STUV", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('34df546d-d6b0-5ccb-afba-fb3ea7caf9e2', 'Carpenter : Saw :: Surgeon : ?', NULL, 'C is correct. The relationship is Professional : Primary precision cutting tool. A Carpenter''s primary cutting tool is a Saw; a Surgeon''s primary cutting tool is a Scalpel. Trap: Stethoscope is a diagnostic tool used by physicians, not by surgeons during operations; Hospital is the workplace, not the tool.', 'MEDIUM', 'Reasoning', 'Analogy — Objects, Science, Letters and Numbers (W10)', 'RSN_ANALOGY_W10', '[{"option_text": "Hospital", "is_correct": false}, {"option_text": "Medicine", "is_correct": false}, {"option_text": "Scalpel", "is_correct": true}, {"option_text": "Stethoscope", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ec651f68-d883-55aa-8196-da9d7faf41bd', '4 : 18 :: 6 : ?', NULL, 'C is correct. Rule: n → n² + 2. Verify: 4² + 2 = 16 + 2 = 18 ✓. Apply: 6² + 2 = 36 + 2 = 38. Trap: 36 = 6² (forgetting the +2); 40 = 6² + 4 (using +4 instead of +2); 37 = 6² + 1 (off-by-one error).', 'HARD', 'Reasoning', 'Analogy — Objects, Science, Letters and Numbers (W10)', 'RSN_ANALOGY_W10', '[{"option_text": "36", "is_correct": false}, {"option_text": "37", "is_correct": false}, {"option_text": "38", "is_correct": true}, {"option_text": "40", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8813092d-a9b5-558e-b623-7cd0ef844012', 'Nitrogen : 7 :: Calcium : ?', NULL, 'B is correct. The relationship is Element : Atomic number. Nitrogen has atomic number 7; Calcium has atomic number 20. Trap: 18 is Argon (Ar); 26 is Iron (Fe); 30 is Zinc (Zn). This tests periodic table recall — a frequent SSC CGL science analogy.', 'HARD', 'Reasoning', 'Analogy — Objects, Science, Letters and Numbers (W10)', 'RSN_ANALOGY_W10', '[{"option_text": "18", "is_correct": false}, {"option_text": "20", "is_correct": true}, {"option_text": "26", "is_correct": false}, {"option_text": "30", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('789ad5a4-057d-5ad1-8787-00c8e12dc788', '7 : 343 :: 4 : ?', NULL, 'C is correct. Rule: n → n³ (cube). 7³ = 343 ✓. Apply: 4³ = 64. Trap: 16 = 4² (students try square instead of cube); 256 = 4⁴ (over-applying powers); 48 = 4 × 12 (no valid rule). SSC often uses perfect cubes in number analogies alongside squares.', 'HARD', 'Reasoning', 'Analogy — Objects, Science, Letters and Numbers (W10)', 'RSN_ANALOGY_W10', '[{"option_text": "16", "is_correct": false}, {"option_text": "48", "is_correct": false}, {"option_text": "64", "is_correct": true}, {"option_text": "256", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('36940206-93e9-5fa2-986e-2e8305164a77', 'Doctor : Scalpel :: Sculptor : ?', NULL, 'B is correct. Relationship: Professional : Primary precision cutting tool. A doctor uses a scalpel to cut precisely during surgery; a sculptor uses a chisel to cut and shape stone or wood precisely. Trap: Clay is the material a sculptor works with (not the tool); Canvas is a painter''s medium; Museum is where sculptures are displayed.', 'EASY', 'Reasoning', 'Analogy — Science, Literature and Letter Patterns (W10 B2)', 'RSN_ANALOGY_W10_B2', '[{"option_text": "Clay", "is_correct": false}, {"option_text": "Chisel", "is_correct": true}, {"option_text": "Canvas", "is_correct": false}, {"option_text": "Museum", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('76c53b08-df60-54ca-bce7-e0fe1bb8cdd1', 'Seismograph : Earthquakes :: Barometer : ?', NULL, 'D is correct. Relationship: Instrument : What it measures. A seismograph measures the intensity of earthquakes; a barometer measures atmospheric pressure. Trap: Wind speed is measured by an anemometer; temperature by a thermometer; rainfall by a rain gauge.', 'EASY', 'Reasoning', 'Analogy — Science, Literature and Letter Patterns (W10 B2)', 'RSN_ANALOGY_W10_B2', '[{"option_text": "Wind speed", "is_correct": false}, {"option_text": "Temperature", "is_correct": false}, {"option_text": "Rainfall", "is_correct": false}, {"option_text": "Atmospheric pressure", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('95809f88-a271-5bc7-aecd-b17267e43ead', 'Eye : Ophthalmology :: Skin : ?', NULL, 'B is correct. Relationship: Body part : Medical branch that studies it. Ophthalmology studies the eye; Dermatology studies the skin. Trap: Neurology = nerves/nervous system; Cardiology = heart; Oncology = cancer. SSC frequently tests medical branches as analogies.', 'MEDIUM', 'Reasoning', 'Analogy — Science, Literature and Letter Patterns (W10 B2)', 'RSN_ANALOGY_W10_B2', '[{"option_text": "Neurology", "is_correct": false}, {"option_text": "Dermatology", "is_correct": true}, {"option_text": "Cardiology", "is_correct": false}, {"option_text": "Oncology", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('04ca9ca1-e47c-5140-8ac0-bc4e975d331b', 'Elegy : Death :: Satire : ?', NULL, 'C is correct. Relationship: Literary form : Its primary subject/purpose. An elegy is a poem of mourning written for the dead; a satire is a literary form that ridicules human folly, vice, or institutions. Trap: love poetry is a ''lyric'' or ''sonnet''; nature poetry is ''pastoral''; religious poetry is a ''hymn'' or ''psalm''.', 'MEDIUM', 'Reasoning', 'Analogy — Science, Literature and Letter Patterns (W10 B2)', 'RSN_ANALOGY_W10_B2', '[{"option_text": "Love and romance", "is_correct": false}, {"option_text": "Natural scenery", "is_correct": false}, {"option_text": "Human folly and vice", "is_correct": true}, {"option_text": "Religious devotion", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e8ef3462-c1d9-5c3c-bfc1-2de4e87dca8c', 'Ignorance : Knowledge :: Chaos : ?', NULL, 'C is correct. Relationship: Word : Its direct antonym. Ignorance ↔ Knowledge (absence of knowledge vs. presence of knowledge). Chaos ↔ Order (complete disorder vs. organised structure). Trap: Disorder and Confusion are synonyms of Chaos; Anarchy is a type of chaos (specifically political), not its antonym.', 'MEDIUM', 'Reasoning', 'Analogy — Science, Literature and Letter Patterns (W10 B2)', 'RSN_ANALOGY_W10_B2', '[{"option_text": "Disorder", "is_correct": false}, {"option_text": "Anarchy", "is_correct": false}, {"option_text": "Order", "is_correct": true}, {"option_text": "Confusion", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2e891c61-dec9-50f1-88f6-3d5614008c90', '3 : 24 :: 4 : ?', NULL, 'C is correct. Rule: n → n×(n²−1). For n=3: 3×(9−1) = 3×8 = 24 ✓. For n=4: 4×(16−1) = 4×15 = 60. Alternative view: n×(n−1)×(n+1) = product of three consecutive integers starting from n−1. 3: 2×3×4=24; 4: 3×4×5=60. Trap: 48=4×12 (uses n²−4 incorrectly); 64=4³ (cubing instead).', 'HARD', 'Reasoning', 'Analogy — Science, Literature and Letter Patterns (W10 B2)', 'RSN_ANALOGY_W10_B2', '[{"option_text": "48", "is_correct": false}, {"option_text": "56", "is_correct": false}, {"option_text": "60", "is_correct": true}, {"option_text": "64", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bb386485-47c0-5bf4-8e51-a21a3d633c8f', 'ACEG : BDFH :: IKMO : ?', NULL, 'A is correct. Relationship: Each letter in the second group is exactly one position ahead of the corresponding letter in the first group. A→B, C→D, E→F, G→H. Apply same rule: I→J, K→L, M→N, O→P → JLNP. Trap: JLMP replaces only 3 of 4 letters correctly (M→N changes to M); IKMQ shifts only the last letter.', 'HARD', 'Reasoning', 'Analogy — Science, Literature and Letter Patterns (W10 B2)', 'RSN_ANALOGY_W10_B2', '[{"option_text": "JLNP", "is_correct": true}, {"option_text": "JLMP", "is_correct": false}, {"option_text": "IKMQ", "is_correct": false}, {"option_text": "JKNP", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('25c95959-f1f5-5d52-9edf-3941ddf9e56f', 'MNOP : RSTU :: VWXY : ?', NULL, 'A is correct. Gap between groups: M(13) to R(18) — Q is skipped (1 letter gap). P to R: from end of first group P(16) to start of second group R(18) skips Q(17). Similarly, from end of VWXY = Y(25) to start of next group, skip Z(26), giving A(1), B(2), C(3), D(4) → ABCD. Trap: ZABC includes Z which should be skipped; BCDE starts one too far.', 'HARD', 'Reasoning', 'Analogy — Science, Literature and Letter Patterns (W10 B2)', 'RSN_ANALOGY_W10_B2', '[{"option_text": "ABCD", "is_correct": true}, {"option_text": "ZABC", "is_correct": false}, {"option_text": "BCDE", "is_correct": false}, {"option_text": "WXYZ", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e5b7de33-8ab9-570e-9889-62532c70a011', 'Light : Photon :: Sound : ?', NULL, 'B is correct. Relationship: Wave phenomenon : Its quantum unit. A photon is the quantum (smallest discrete unit) of electromagnetic radiation including light. A phonon is the quantum of sound energy (acoustic vibration in a solid). This is a physics analogy appearing in SSC Tier 2 General Science sections. Trap: electron is a particle of matter (not a quantum of sound); ''wave only'' and ''vibration only'' describe classical (non-quantum) models of sound.', 'HARD', 'Reasoning', 'Analogy — Science, Literature and Letter Patterns (W10 B2)', 'RSN_ANALOGY_W10_B2', '[{"option_text": "Electron", "is_correct": false}, {"option_text": "Phonon", "is_correct": true}, {"option_text": "Wave only", "is_correct": false}, {"option_text": "Vibration only", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0c3b5089-fd11-502e-912b-f32092c31488', 'Herbivore : Grass :: Piscivore : ?', NULL, 'C is correct. Relationship: Diet type : Primary food eaten. A herbivore eats grass/plants; a piscivore eats fish (''piscis'' = fish in Latin, same root as Pisces). Trap: Insects are eaten by insectivores; Fruits by frugivores; Carrion (dead flesh) by scavengers/vultures. Piscivore vocabulary tests the -vore suffix family: herbivore, carnivore, omnivore, insectivore, piscivore.', 'HARD', 'Reasoning', 'Analogy — Science, Literature and Letter Patterns (W10 B2)', 'RSN_ANALOGY_W10_B2', '[{"option_text": "Insects", "is_correct": false}, {"option_text": "Fruits", "is_correct": false}, {"option_text": "Fish", "is_correct": true}, {"option_text": "Carrion", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('33ae17f1-43b5-5996-bd59-a3d18ac6177b', 'Marathon : Running :: Regatta : ?', NULL, 'D is correct. Relationship: Sporting event : the sport involved. A marathon is a long-distance running event. A regatta is a series of boat races (rowing or sailing events). This is a PYQ-favourite niche word — REGATTA = organised boat race competition.', 'MEDIUM', 'Reasoning', 'Analogies — Pair Relationships (Set W7)', 'RSN_ANALOGY_W7', '[{"option_text": "Swimming", "is_correct": false}, {"option_text": "Cycling", "is_correct": false}, {"option_text": "Wrestling", "is_correct": false}, {"option_text": "Boat racing", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('134b53a3-0fd8-53e4-9ceb-2da8b6f3029a', 'Pen : Write :: Knife : ?', NULL, 'B is correct. A pen is used to write; a knife is used to cut. Relationship: tool → primary function.', 'EASY', 'Reasoning', 'Analogies (W9)', 'RSN_ANALOGY_W9', '[{"option_text": "Sharpen", "is_correct": false}, {"option_text": "Cut", "is_correct": true}, {"option_text": "Stab", "is_correct": false}, {"option_text": "Cook", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bdd36036-8305-523a-b78a-599bf6f1b151', 'Doctor : Hospital :: Teacher : ?', NULL, 'C is correct. A doctor works in a hospital; a teacher works in a school. Relationship: professional → workplace.', 'EASY', 'Reasoning', 'Analogies (W9)', 'RSN_ANALOGY_W9', '[{"option_text": "College", "is_correct": false}, {"option_text": "Clinic", "is_correct": false}, {"option_text": "School", "is_correct": true}, {"option_text": "Library", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6beb3198-19df-5729-82c6-cad8b1b73545', 'Fish : Swim :: Bird : ?', NULL, 'B is correct. Fish move by swimming; birds move by flying. Relationship: creature → mode of locomotion.', 'EASY', 'Reasoning', 'Analogies (W9)', 'RSN_ANALOGY_W9', '[{"option_text": "Nest", "is_correct": false}, {"option_text": "Fly", "is_correct": true}, {"option_text": "Chirp", "is_correct": false}, {"option_text": "Wing", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('da01cbc4-0e4c-5951-8ee6-8772892ee298', 'Book : Author :: Film : ?', NULL, 'C is correct. A book is created by an author; a film is directed (and creatively led) by a director. Relationship: creative work → primary creator.', 'MEDIUM', 'Reasoning', 'Analogies (W9)', 'RSN_ANALOGY_W9', '[{"option_text": "Actor", "is_correct": false}, {"option_text": "Producer", "is_correct": false}, {"option_text": "Director", "is_correct": true}, {"option_text": "Cameraman", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9bec67dc-d041-556a-b578-67b882ca171c', 'Sculptor : Statue :: Poet : ?', NULL, 'A is correct. A sculptor creates a statue; a poet creates a poem. Relationship: artist → work produced.', 'MEDIUM', 'Reasoning', 'Analogies (W9)', 'RSN_ANALOGY_W9', '[{"option_text": "Poem", "is_correct": true}, {"option_text": "Verse", "is_correct": false}, {"option_text": "Novel", "is_correct": false}, {"option_text": "Song", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('068ea781-c8cf-577d-96e1-9ddfe22005fd', 'Ocean : Submarine :: Sky : ?', NULL, 'C is correct. A submarine travels through the ocean; an aeroplane travels through the sky. Relationship: medium → vehicle that travels within it.', 'MEDIUM', 'Reasoning', 'Analogies (W9)', 'RSN_ANALOGY_W9', '[{"option_text": "Rocket", "is_correct": false}, {"option_text": "Kite", "is_correct": false}, {"option_text": "Aeroplane", "is_correct": true}, {"option_text": "Satellite", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6c4beb01-ed53-554f-9793-39f6b07e5606', 'Fever : Symptom :: Crime : ?', NULL, 'C is correct. Fever is a symptom of disease; crime is a symptom/indicator of lawlessness. Relationship: observable sign → underlying condition it indicates.', 'MEDIUM', 'Reasoning', 'Analogies (W9)', 'RSN_ANALOGY_W9', '[{"option_text": "Police", "is_correct": false}, {"option_text": "Punishment", "is_correct": false}, {"option_text": "Lawlessness", "is_correct": true}, {"option_text": "Jail", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c5a824a6-c693-5814-889d-1afa49d92afb', 'Marathon : Race :: Symphony : ?', NULL, 'C is correct. A marathon is a type of race; a symphony is a type of musical composition. Relationship: specific → general category.', 'MEDIUM', 'Reasoning', 'Analogies (W9)', 'RSN_ANALOGY_W9', '[{"option_text": "Musician", "is_correct": false}, {"option_text": "Music", "is_correct": false}, {"option_text": "Composition", "is_correct": true}, {"option_text": "Orchestra", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4050e0a8-643c-599a-8b1b-8ad5e3c8afa2', 'ACEG : IKMO :: BDFH : ?', NULL, 'A is correct. ACEG = positions 1,3,5,7 (odd). IKMO = positions 9,11,13,15 (next four odds). Similarly, BDFH = positions 2,4,6,8 (even). The next four evens = J(10),L(12),N(14),P(16) → JLNP.', 'HARD', 'Reasoning', 'Analogies (W9)', 'RSN_ANALOGY_W9', '[{"option_text": "JLNP", "is_correct": true}, {"option_text": "JKLN", "is_correct": false}, {"option_text": "ILNP", "is_correct": false}, {"option_text": "JMNP", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7cd84a8b-d28c-5647-9a93-c86fcf584cdf', 'Nitrogen : Atmosphere :: Iron : ?', NULL, 'C is correct. Nitrogen is the most abundant element in the atmosphere (~78%); iron is the most abundant element in Earth''s core. Relationship: dominant element → the sphere/layer where it is most abundant.', 'HARD', 'Reasoning', 'Analogies (W9)', 'RSN_ANALOGY_W9', '[{"option_text": "Earth", "is_correct": false}, {"option_text": "Crust", "is_correct": false}, {"option_text": "Core", "is_correct": true}, {"option_text": "Mantle", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('57c51062-905f-56a9-a3d0-ade720d38001', 'A and E are a married couple. B and C are their children. D is C''s daughter. How is E related to D?', NULL, 'B is correct. A+E are parents of B and C. D is C''s daughter = A and E''s grandchild. E → C (parent) → D (grandchild). E is D''s grandmother.', 'MEDIUM', 'Reasoning', 'Blood Relations Advanced — Multi-Generation, Pointing Photo and Coded Relations (W13 B1)', 'RSN_BLOOD_RELATIONS_ADV_W13_B1', '[{"option_text": "Mother", "is_correct": false}, {"option_text": "Grandmother", "is_correct": true}, {"option_text": "Aunt", "is_correct": false}, {"option_text": "Great-grandmother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5ad096d7-b130-500f-befa-761708e9ca78', 'A is the mother of both B and C (who are siblings). D is the husband of C. How is A related to D?', NULL, 'C is correct. A is C''s mother. D is C''s husband. A is the mother of D''s wife → A is D''s mother-in-law.', 'MEDIUM', 'Reasoning', 'Blood Relations Advanced — Multi-Generation, Pointing Photo and Coded Relations (W13 B1)', 'RSN_BLOOD_RELATIONS_ADV_W13_B1', '[{"option_text": "Mother", "is_correct": false}, {"option_text": "Aunt", "is_correct": false}, {"option_text": "Mother-in-law", "is_correct": true}, {"option_text": "Grandmother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1407d634-f522-5ec4-81e6-0f733cef434d', 'Pointing to a photograph, Arjun says: ''This man''s son is my son''s uncle.'' Who is the man in the photograph to Arjun?', NULL, 'B is correct. My son''s uncle = my brother. So: this man''s son = Arjun''s brother. This man = father of Arjun''s brother = Arjun''s own father. Verify: photo man → his son = Arjun''s brother → they share the same father = photo man = Arjun''s father ✓.', 'MEDIUM', 'Reasoning', 'Blood Relations Advanced — Multi-Generation, Pointing Photo and Coded Relations (W13 B1)', 'RSN_BLOOD_RELATIONS_ADV_W13_B1', '[{"option_text": "Brother", "is_correct": false}, {"option_text": "Father", "is_correct": true}, {"option_text": "Uncle", "is_correct": false}, {"option_text": "Grandfather", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('96e6e216-a4de-5d88-999e-adc9ad3e542a', 'Pointing to a girl, a man says: ''She is the daughter of the only child of my father.'' How is the girl related to the man?', NULL, 'C is correct. ''Only child of my father'' = the man himself (self-reference). Girl''s parent = the man. Girl is the man''s daughter. Verify: my father''s only child = me. Girl''s father = me → she is my daughter ✓. PAPER-SETTER TRAP: Students look for a third person but ''only child'' points back to the speaker.', 'MEDIUM', 'Reasoning', 'Blood Relations Advanced — Multi-Generation, Pointing Photo and Coded Relations (W13 B1)', 'RSN_BLOOD_RELATIONS_ADV_W13_B1', '[{"option_text": "Niece", "is_correct": false}, {"option_text": "Sister", "is_correct": false}, {"option_text": "Daughter", "is_correct": true}, {"option_text": "Cousin", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('adcef291-0d6f-5910-98e0-185ddfdc1429', 'Introducing a boy, a girl says: ''He is the son of the daughter of the father of my uncle.'' How is the boy related to the girl?', NULL, 'D is correct. Trace: ''father of my uncle'' = grandfather (uncle''s father = grandfather). ''Daughter of grandfather'' = my aunt (grandfather''s daughter = my father''s sister). ''Son of aunt'' = my cousin. Verify: grandfather → daughter (aunt) → boy (son). Boy is girl''s cousin ✓.', 'HARD', 'Reasoning', 'Blood Relations Advanced — Multi-Generation, Pointing Photo and Coded Relations (W13 B1)', 'RSN_BLOOD_RELATIONS_ADV_W13_B1', '[{"option_text": "Brother", "is_correct": false}, {"option_text": "Son", "is_correct": false}, {"option_text": "Nephew", "is_correct": false}, {"option_text": "Cousin", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6ae0b247-147b-5ee7-a952-0cf3b9d7fa08', 'A is the son of B. C is B''s sister. D is C''s mother. E is D''s husband. How is E related to A?', NULL, 'C is correct. C is B''s sister → D is both B''s and C''s mother (same parents). E is D''s husband = B''s father. A is B''s son → E is A''s paternal grandfather (E → B → A). Verify: E to B = father-son, B to A = father-son. E is two generations above A = grandfather ✓.', 'MEDIUM', 'Reasoning', 'Blood Relations Advanced — Multi-Generation, Pointing Photo and Coded Relations (W13 B1)', 'RSN_BLOOD_RELATIONS_ADV_W13_B1', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Uncle", "is_correct": false}, {"option_text": "Grandfather", "is_correct": true}, {"option_text": "Great-grandfather", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('61872ae5-be63-519e-90ed-442ddd0585d5', 'P''s father is Q''s son. M is P''s mother and N is Q''s wife. How is N related to M?', NULL, 'C is correct. Let P''s father = R. Q''s son = R → N (Q''s wife) is R''s mother. M is P''s mother → M is married to R (P''s father). N is mother of R; M is wife of R. N is M''s mother-in-law. Verify: N → R (mother-son), R married M. N = M''s mother-in-law ✓.', 'HARD', 'Reasoning', 'Blood Relations Advanced — Multi-Generation, Pointing Photo and Coded Relations (W13 B1)', 'RSN_BLOOD_RELATIONS_ADV_W13_B1', '[{"option_text": "Sister", "is_correct": false}, {"option_text": "Daughter-in-law", "is_correct": false}, {"option_text": "Mother-in-law", "is_correct": true}, {"option_text": "Grandmother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7a1be005-b650-50f3-b544-cadf8d2de2c9', 'X is the father of Y. Y is the brother of Z. W is the wife of Z. V is the son of W and Z. How is X related to V?', NULL, 'C is correct. X = father of Y. Z = Y''s brother → X = father of both Y and Z (siblings). V = son of Z → V is X''s grandson. Verify: X → Z (father-son), Z → V (father-son). X is two generations above V = grandfather ✓.', 'MEDIUM', 'Reasoning', 'Blood Relations Advanced — Multi-Generation, Pointing Photo and Coded Relations (W13 B1)', 'RSN_BLOOD_RELATIONS_ADV_W13_B1', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Uncle", "is_correct": false}, {"option_text": "Grandfather", "is_correct": true}, {"option_text": "Brother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bce4fd31-5d37-577c-aad5-5f323795daf0', 'P is the father of Q. Q is the sister of R. S is R''s husband. T is the son of S and R. How is P related to T?', NULL, 'C is correct. P = father of Q and R (siblings). R married S. T = son of R and S → T is P''s grandson. Verify: P → R (grandfather''s child), R → T (parent-child). P is maternal grandfather of T ✓. Trap: Father-in-law = P is father-in-law of S (S''s wife R is P''s daughter), but the question asks P''s relation to T, not to S.', 'MEDIUM', 'Reasoning', 'Blood Relations Advanced — Multi-Generation, Pointing Photo and Coded Relations (W13 B1)', 'RSN_BLOOD_RELATIONS_ADV_W13_B1', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Uncle", "is_correct": false}, {"option_text": "Grandfather", "is_correct": true}, {"option_text": "Father-in-law", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8b4bec03-6acc-5bd7-9c36-0930c7d70dc0', 'Rohit says: ''My mother''s mother''s son''s daughter is Priya.'' How is Priya related to Rohit?', NULL, 'B is correct. Trace: ''Mother''s mother'' = Rohit''s maternal grandmother. ''Maternal grandmother''s son'' = Rohit''s maternal uncle (grandmother''s son = mother''s brother = uncle). ''Maternal uncle''s daughter'' = Rohit''s cousin. Verify: grandmother → son (uncle) → daughter (Priya). Priya is Rohit''s maternal cousin ✓. PAPER-SETTER TRAP: Students confuse ''grandmother''s son'' with ''grandmother''s daughter'' (which would be Rohit''s mother or aunt). The son of the grandmother = Rohit''s maternal uncle; uncle''s daughter = cousin.', 'HARD', 'Reasoning', 'Blood Relations Advanced — Multi-Generation, Pointing Photo and Coded Relations (W13 B1)', 'RSN_BLOOD_RELATIONS_ADV_W13_B1', '[{"option_text": "Sister", "is_correct": false}, {"option_text": "Cousin", "is_correct": true}, {"option_text": "Niece", "is_correct": false}, {"option_text": "Aunt", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bcdc02ec-99e9-50e1-930b-4a938947609a', 'Pointing to a boy, Reena says ''He is the son of my grandfather''s only son.'' How is the boy related to Reena?', NULL, 'C is correct. My grandfather''s only son = my father (assuming no other male siblings of the father are implied). The boy is the son of my father = my brother. Trap: Cousin = son of grandfather''s other son (but the problem specifies ''only son'', leaving only the father); Uncle = if grandfather had a son who was not Reena''s father (ruled out by ''only son'').', 'EASY', 'Reasoning', 'Blood Relations — Family Tree Deductions and Relationship Chains (W12 B1)', 'RSN_BLOOD_RELATIONS_III_W12_B1', '[{"option_text": "Uncle", "is_correct": false}, {"option_text": "Cousin", "is_correct": false}, {"option_text": "Brother", "is_correct": true}, {"option_text": "Father", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('70947c2d-7c0f-5be3-8ecc-bf2e32e7ec5d', 'A is the mother of B. C is the son of B. How is A related to C?', NULL, 'C is correct. A is B''s mother. C is B''s son. Relationship chain: A→(mother)→B→(son)→C. A is B''s mother and B is C''s parent → A is C''s grandmother. Verify: A(grandmother)→B(parent)→C(grandchild) ✓. Trap: Mother = A is B''s mother, but not C''s mother (one generation higher); Aunt = no sibling relationship established.', 'EASY', 'Reasoning', 'Blood Relations — Family Tree Deductions and Relationship Chains (W12 B1)', 'RSN_BLOOD_RELATIONS_III_W12_B1', '[{"option_text": "Mother", "is_correct": false}, {"option_text": "Aunt", "is_correct": false}, {"option_text": "Grandmother", "is_correct": true}, {"option_text": "Sister", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('84cee845-5557-52f6-a615-c2012bdd729f', 'How is a man''s sister''s husband''s sister related to the man?', NULL, 'C is correct. Chain: Man''s sister''s husband = brother-in-law. Brother-in-law''s sister = sister-in-law of the man (the sister of the person who married into the family). The man''s sister married someone; that person''s sister is now related to the man through his sister''s marriage → sister-in-law. Verify: If Man''s sister → married → Husband A. Husband A''s sister = a woman related by marriage to the man = his sister-in-law. Trap: Cousin = requires a common grandparent; Niece = daughter of sibling (not the case here).', 'EASY', 'Reasoning', 'Blood Relations — Family Tree Deductions and Relationship Chains (W12 B1)', 'RSN_BLOOD_RELATIONS_III_W12_B1', '[{"option_text": "Cousin", "is_correct": false}, {"option_text": "Niece", "is_correct": false}, {"option_text": "Sister-in-law", "is_correct": true}, {"option_text": "Aunt", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('829cac6e-db21-5d18-9702-a0efa0ee57b3', 'X is Y''s father''s nephew. Y''s brother is Z. How is X related to Z?', NULL, 'C is correct. X = Y''s father''s nephew. Father''s nephew = cousin of Y (child of father''s sibling). So X is Y''s cousin. Z is Y''s brother. Since X is cousin of Y, and Z is Y''s brother (same generation, same parents), X is also cousin of Z. Trap: Uncle = if X were father''s generation (not nephew); Brother = would require same parents (not the case).', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Tree Deductions and Relationship Chains (W12 B1)', 'RSN_BLOOD_RELATIONS_III_W12_B1', '[{"option_text": "Uncle", "is_correct": false}, {"option_text": "Nephew", "is_correct": false}, {"option_text": "Cousin", "is_correct": true}, {"option_text": "Brother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('793a1088-a65e-5de0-bf74-1a8dc756804b', 'Looking at a photograph, a woman says ''This man''s son is the only brother of my daughter.'' How is the man related to the woman?', NULL, 'B is correct. ''This man''s son is the only brother of my daughter.'' The only brother of the woman''s daughter = the woman''s son (she has one son). So: the man''s son = woman''s son. If a man''s son is also the woman''s son → the man and woman share the same son → the man is the woman''s husband. Verify: husband and wife have the same children ✓. Trap: Father = would mean the man is the woman''s own father (not her son''s father); Brother = sibling relationship, not marital.', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Tree Deductions and Relationship Chains (W12 B1)', 'RSN_BLOOD_RELATIONS_III_W12_B1', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Husband", "is_correct": true}, {"option_text": "Brother", "is_correct": false}, {"option_text": "Uncle", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('108f39ac-edb4-51ff-ac26-f43b2a5478a6', 'A is the father of B. C is the mother of D. B and D are sisters. How is A related to C?', NULL, 'B is correct. B and D are sisters → same parents. A is B''s father → A is also D''s father. C is D''s mother → C is also B''s mother. A (father) and C (mother) of the same children (B and D) → A is C''s husband. Verify: A and C are parents of both B and D ✓. Trap: Brother = sibling (no sibling clue given between A and C).', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Tree Deductions and Relationship Chains (W12 B1)', 'RSN_BLOOD_RELATIONS_III_W12_B1', '[{"option_text": "Brother", "is_correct": false}, {"option_text": "Husband", "is_correct": true}, {"option_text": "Father", "is_correct": false}, {"option_text": "Uncle", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3d13fca9-bcef-5741-b054-f3c5ce26874f', 'M is married to N. P is M''s brother. Q is P''s father. R is Q''s son (R ≠ M and R ≠ P). How is R related to N?', NULL, 'C is correct. Q is the father of P and M (siblings). R is another son of Q → R is also a brother of M (and P). N married M → N''s brothers-in-law are M''s siblings (P and R). R is M''s brother → R is N''s brother-in-law. Verify: N''s spouse is M; M''s sibling R = N''s brother-in-law ✓. Trap: Son = N has no son established; Cousin = R is a full sibling of M (not cousin, since same father Q).', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Tree Deductions and Relationship Chains (W12 B1)', 'RSN_BLOOD_RELATIONS_III_W12_B1', '[{"option_text": "Son", "is_correct": false}, {"option_text": "Father", "is_correct": false}, {"option_text": "Brother-in-law", "is_correct": true}, {"option_text": "Cousin", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2be23277-5c41-5b01-8794-3a2e32a5ae2f', 'A man introduces a woman as ''The mother of the only child of my only sister.'' How is the woman related to the man?', NULL, 'C is correct. ''My only sister'' has one child. ''The mother of that child'' = the one who gave birth to the sister''s child = the sister herself (if it''s the sister''s biological child). The woman introduced = the man''s sister. Verify: sister has one child; sister is the mother of that child; man is introducing his sister ✓. Trap: Sister-in-law = wife of the man''s brother (not the case here); Niece = daughter of the man''s sibling (the woman here IS the sibling, not her daughter).', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Tree Deductions and Relationship Chains (W12 B1)', 'RSN_BLOOD_RELATIONS_III_W12_B1', '[{"option_text": "Niece", "is_correct": false}, {"option_text": "Mother", "is_correct": false}, {"option_text": "Sister", "is_correct": true}, {"option_text": "Sister-in-law", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('715c1096-cbec-5664-b44e-87473cc3ec82', 'P''s mother is Q''s daughter. R is P''s sister. How is Q related to R?', NULL, 'C is correct. P''s mother = Q''s daughter. So Q is the mother of P''s mother → Q is P''s maternal grandmother. R is P''s sister (same parents) → R''s mother is also Q''s daughter → Q is also R''s maternal grandmother. Chain: Q→(daughter)→P''s mother→(children)→P and R. Q is grandmother of both P and R. Verify: Q(grandmother)→daughter→R(grandchild) ✓. Trap: Mother = Q is P''s mother''s mother (grandmother, not mother); Aunt = would require Q to be a sibling of R''s parent.', 'HARD', 'Reasoning', 'Blood Relations — Family Tree Deductions and Relationship Chains (W12 B1)', 'RSN_BLOOD_RELATIONS_III_W12_B1', '[{"option_text": "Mother", "is_correct": false}, {"option_text": "Aunt", "is_correct": false}, {"option_text": "Grandmother", "is_correct": true}, {"option_text": "Sister", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e4d92c22-5b8a-5b1e-8b24-588bcc78b2a9', 'A woman points to a man and says, ''His mother is the only daughter of my mother.'' How is the woman related to the man?', NULL, 'C is correct. ''His mother is the only daughter of MY mother.'' The only daughter of the woman''s mother = the woman herself. So the man''s mother = the woman. The woman IS the man''s mother. Chain: woman''s mother → only daughter = woman → man (the woman''s son). Verify: woman''s mother''s only daughter = woman (she is the only daughter); man''s mother = woman ✓. Trap: Grandmother = the woman''s mother is the man''s grandmother (one generation above the woman, who IS the mother); Aunt = would require the man''s mother to be the woman''s sibling (but she IS the woman).', 'HARD', 'Reasoning', 'Blood Relations — Family Tree Deductions and Relationship Chains (W12 B1)', 'RSN_BLOOD_RELATIONS_III_W12_B1', '[{"option_text": "Grandmother", "is_correct": false}, {"option_text": "Daughter", "is_correct": false}, {"option_text": "Mother", "is_correct": true}, {"option_text": "Aunt", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('43982317-babd-59ae-ae82-56c2bb8b402c', 'Pointing to a photograph, Rahul says ''She is the daughter of my grandfather''s only son''. How is the woman in the photograph related to Rahul?', NULL, 'C is correct. Chain: Rahul''s grandfather''s only son = Rahul''s father (since grandfather has only one son). The woman is the daughter of Rahul''s father = Rahul''s sister. Verify: Grandfather → Father (only son) → Woman (daughter). So Woman = Rahul''s sister ✓. Trap: Aunt = if it were grandfather''s son = uncle; Cousin = if grandfather had another son (but ''only son'' eliminates this).', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Tree Problems (W11 B2)', 'RSN_BLOOD_RELATIONS_II_W11_B2', '[{"option_text": "Mother", "is_correct": false}, {"option_text": "Aunt", "is_correct": false}, {"option_text": "Sister", "is_correct": true}, {"option_text": "Cousin", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('524383b2-ff3c-553d-8b6e-d80a8cfeae63', 'A is the father of B. B is the sister of C. C is the mother of D. How is A related to D?', NULL, 'C is correct. Chain: A is father of B. B is sister of C → A is also father of C. C is mother of D → A is grandfather of D. Verify: A → B (child), B sister of C → A → C (child), C → D (grandchild). So A = grandfather of D ✓. Trap: Uncle = A is a male relative but two generations above D, not one; Father = only one generation above D, but A is two generations above.', 'EASY', 'Reasoning', 'Blood Relations — Family Tree Problems (W11 B2)', 'RSN_BLOOD_RELATIONS_II_W11_B2', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Uncle", "is_correct": false}, {"option_text": "Grandfather", "is_correct": true}, {"option_text": "Great-grandfather", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c35ee08a-6fc2-5e9d-ad55-e9f13d11e67b', 'Introducing a man, a woman says ''His mother is the only daughter of my mother.'' How is the man related to the woman?', NULL, 'B is correct. ''Only daughter of my mother'' = the woman herself (she is the only daughter of her mother). So the man''s mother = the woman. Therefore the man = the woman''s son. Verify: Woman''s mother → Woman (only daughter). Man''s mother = Woman. Man = Son of Woman ✓. Trap: Nephew = the man''s mother would need to be the woman''s sister, but the woman IS the man''s mother here; Cousin = requires a sibling of a parent.', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Tree Problems (W11 B2)', 'RSN_BLOOD_RELATIONS_II_W11_B2', '[{"option_text": "Brother", "is_correct": false}, {"option_text": "Son", "is_correct": true}, {"option_text": "Nephew", "is_correct": false}, {"option_text": "Cousin", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('057cc622-61b3-59fa-8e39-b0c51ea1f606', 'P is the brother of Q. Q is the mother of R. S is the father of P. How is S related to R?', NULL, 'B is correct. S is father of P. P is brother of Q → S is also father of Q (since P and Q have the same father S). Q is mother of R → S is grandfather of R. Chain: S → P (son), Q (daughter); Q → R (child). S = Q''s father = R''s grandfather ✓. Trap: Uncle = S is not R''s parent''s sibling but R''s parent''s parent; Father = S is two generations above R.', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Tree Problems (W11 B2)', 'RSN_BLOOD_RELATIONS_II_W11_B2', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Grandfather", "is_correct": true}, {"option_text": "Uncle", "is_correct": false}, {"option_text": "Brother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e39a01a8-8db0-5928-831d-fe658789cfb4', 'Looking at a portrait, Meena says ''The person in the portrait is the son of the only son of my grandmother.'' Who is the person in the portrait?', NULL, 'A is correct. Meena''s grandmother → only son = Meena''s father. The portrait person = son of Meena''s father = Meena''s brother. Chain: Grandmother → Father (only son) → Portrait person (son). Portrait person = Meena''s brother ✓. Trap: Cousin = requires grandmother to have another child with a son; Nephew = portrait would be Meena''s sibling''s son; Son = portrait would be Meena''s own child (not her father''s child).', 'HARD', 'Reasoning', 'Blood Relations — Family Tree Problems (W11 B2)', 'RSN_BLOOD_RELATIONS_II_W11_B2', '[{"option_text": "Meena''s brother", "is_correct": true}, {"option_text": "Meena''s nephew", "is_correct": false}, {"option_text": "Meena''s cousin", "is_correct": false}, {"option_text": "Meena''s son", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a4d31493-736b-5742-b9e6-ef7a2a480d53', 'X is the father of Y. Y is the husband of Z. Z is the sister of W. W is the daughter of V. How is X related to V?', NULL, 'B is correct. X is father of Y. Y is husband of Z. Z and W are sisters, both daughters of V. So Z is V''s daughter → Y is V''s son-in-law. X is Y''s father → X is the father-in-law of Z. Since V is Z''s father, and X is Z''s husband''s father (father-in-law), X is V''s co-father-in-law (the other child''s parent). In family terms: V''s daughter Z married Y, whose father is X. So X is father-in-law of Z, and V is father-in-law of Y. X''s relation to V = X is V''s daughter''s father-in-law. In common Indian usage, X is the ''samdhī'' of V = ''father-in-law'' from V''s perspective for V''s daughter''s husband''s father. SSC typically asks X''s relation to V: X is V''s daughter Z''s husband Y''s father = X is the father-in-law of V''s daughter = X is V''s son-in-law? No. Let''s be precise: X is the father of Z''s husband. SSC answer = father-in-law of Z = B.', 'HARD', 'Reasoning', 'Blood Relations — Family Tree Problems (W11 B2)', 'RSN_BLOOD_RELATIONS_II_W11_B2', '[{"option_text": "Son-in-law", "is_correct": false}, {"option_text": "Father-in-law", "is_correct": true}, {"option_text": "Brother-in-law", "is_correct": false}, {"option_text": "Uncle", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1919dfd5-c9b9-55d0-8a19-0a622e5fa4ac', 'A man points to a woman and says ''Her brother is the only son of my parents.'' How is the woman related to the man?', NULL, 'C is correct. ''Only son of my parents'' = the man himself (he is the only son). So the woman''s brother = the man. Therefore, the woman = the man''s sister. Verify: Man''s parents → Man (only son). Woman''s brother = Man. Woman = Man''s sister ✓. Trap: Daughter = the man''s daughter''s brother would be the man''s son, not himself; Wife = no indication she married him.', 'EASY', 'Reasoning', 'Blood Relations — Family Tree Problems (W11 B2)', 'RSN_BLOOD_RELATIONS_II_W11_B2', '[{"option_text": "Daughter", "is_correct": false}, {"option_text": "Mother", "is_correct": false}, {"option_text": "Sister", "is_correct": true}, {"option_text": "Wife", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b396dd51-910d-57ea-b506-d1ce46b921e0', 'If A + B means ''A is the father of B'', A − B means ''A is the mother of B'', A × B means ''A is the brother of B'', and A ÷ B means ''A is the sister of B'', then what does P − Q + R × S mean?', NULL, 'C is correct. Parse: P−Q = P is MOTHER of Q. Q+R = Q is FATHER of R. R×S = R is BROTHER of S. Chain: Q is father of both R and S (brothers). P is mother of Q. Therefore P is the mother of S''s father (Q) = PATERNAL grandmother of S. ''Paternal grandmother'' = father''s mother. Here father=Q, Q''s mother=P → P is paternal grandmother ✓. Trap: ''Maternal grandmother'' = mother''s mother; since Q is S''s FATHER (not mother), P = paternal (not maternal) grandmother.', 'HARD', 'Reasoning', 'Blood Relations — Family Tree Problems (W11 B2)', 'RSN_BLOOD_RELATIONS_II_W11_B2', '[{"option_text": "P is the grandmother of S", "is_correct": false}, {"option_text": "P is the maternal grandmother of S", "is_correct": false}, {"option_text": "P is the paternal grandmother of S", "is_correct": true}, {"option_text": "P is the aunt of S", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bcfa463d-021d-5fea-bc37-24e7a9674186', 'In a family, there are six members: A, B, C, D, E, F. A and B are a married couple. C is A''s daughter. D is C''s husband. E is D''s father. F is B''s father. How is E related to F?', NULL, 'B is correct. A and B are married. C is A''s daughter. D is C''s husband → D married into A''s family. E is D''s father. F is B''s father → F is A''s father-in-law. C (daughter of A and B) married D (son of E). So E = father of the man who married A+B''s daughter. F = father of B = maternal grandfather of C. E is D''s father; D married C (A+B''s daughter). So E and F are co-parents-in-law (the fathers of the married couple D and C). In SSC terms they are ''co-fathers-in-law'' or samdhī. Answer = B.', 'HARD', 'Reasoning', 'Blood Relations — Family Tree Problems (W11 B2)', 'RSN_BLOOD_RELATIONS_II_W11_B2', '[{"option_text": "Son-in-law", "is_correct": false}, {"option_text": "Co-father-in-law (Samdhī)", "is_correct": true}, {"option_text": "Brother-in-law", "is_correct": false}, {"option_text": "Uncle", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8a3b1266-6c75-5628-a2f2-c0fb0b61528b', 'Rajesh has a brother Anil. Anil''s mother is Geeta. Geeta is the wife of Harish. What is Harish''s relation to Rajesh?', NULL, 'C is correct. Rajesh''s brother = Anil. Anil''s mother = Geeta → Geeta is also Rajesh''s mother (since Anil and Rajesh are brothers). Geeta is wife of Harish → Harish = Geeta''s husband = Rajesh''s father. Verify: Harish + Geeta are parents; their sons are Anil and Rajesh. Harish = Rajesh''s father ✓. Trap: Uncle = a parent''s sibling, not the parent himself; Grandfather = would require one more generation up.', 'EASY', 'Reasoning', 'Blood Relations — Family Tree Problems (W11 B2)', 'RSN_BLOOD_RELATIONS_II_W11_B2', '[{"option_text": "Uncle", "is_correct": false}, {"option_text": "Grandfather", "is_correct": false}, {"option_text": "Father", "is_correct": true}, {"option_text": "Brother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('950daab1-7d15-5513-bd0c-7e1fb9602588', 'A woman introduces a man by saying, ''He is the son of the woman who is the mother of my husband.'' How is the man related to the woman?', NULL, 'B is correct. Mother of my husband = my mother-in-law. Son of my mother-in-law = my husband''s brother = my brother-in-law. Trap: ''Son'' would require the man to be her own child, not her husband''s sibling; ''Uncle'' would require a generational gap not present here.', 'EASY', 'Reasoning', 'Blood Relations — Family Deductions (W10)', 'RSN_BLOOD_RELATIONS_W10', '[{"option_text": "Son", "is_correct": false}, {"option_text": "Brother-in-law", "is_correct": true}, {"option_text": "Uncle", "is_correct": false}, {"option_text": "Father-in-law", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0afabaed-59fb-592a-9d5a-7e53c1779d80', 'Pointing to a photograph, a man says, ''She is the daughter of my grandfather''s only son.'' How is the woman in the photograph related to the man?', NULL, 'C is correct. My grandfather''s only son = my father (assuming the man himself is from this lineage). Daughter of my father = my sister. Trap: ''Cousin'' would apply if grandfather had multiple sons; ''Niece'' would require the man to be one generation above; ''Daughter'' would require the woman to be his child.', 'EASY', 'Reasoning', 'Blood Relations — Family Deductions (W10)', 'RSN_BLOOD_RELATIONS_W10', '[{"option_text": "Daughter", "is_correct": false}, {"option_text": "Niece", "is_correct": false}, {"option_text": "Sister", "is_correct": true}, {"option_text": "Cousin", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fd8520aa-9488-5acd-86d7-e5fe8e1734c5', 'P is the father of Q. Q is the brother of R. R is the mother of S. What is P''s relationship to S?', NULL, 'C is correct. P → Q (father). Q and R are siblings (Q = brother of R). Therefore P is also R''s father. R → S (mother). So P is the father of R (who is S''s mother) → P is S''s maternal grandfather. Trap: ''Uncle'' confuses the step where P is deduced to be R''s father; ''Father'' skips a generation.', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Deductions (W10)', 'RSN_BLOOD_RELATIONS_W10', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Uncle", "is_correct": false}, {"option_text": "Grandfather", "is_correct": true}, {"option_text": "Great-grandfather", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c0f65ea2-70b7-51fa-b236-3e91adf193cb', 'Introducing a woman to a guest, a man says, ''She is the wife of the only son of my mother.'' How is the woman related to the man?', NULL, 'C is correct. Only son of my mother = me (the man himself, assuming he is the only son). Wife of me = my wife. Trap: ''Sister-in-law'' would apply if his mother had more than one son; ''Sister'' is incorrect since the woman is a wife, not a sibling.', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Deductions (W10)', 'RSN_BLOOD_RELATIONS_W10', '[{"option_text": "Mother", "is_correct": false}, {"option_text": "Sister", "is_correct": false}, {"option_text": "Wife", "is_correct": true}, {"option_text": "Sister-in-law", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e911ac05-5ad6-55ea-adfc-80ee119bfdf3', 'A says to B, ''Your father''s sister is my mother.'' How is A related to B?', NULL, 'B is correct. B''s father''s sister = B''s aunt. A''s mother is B''s father''s sister. So A''s mother is B''s aunt → A is B''s aunt''s child = B''s cousin. Trap: ''Brother'' would require A and B to share the same parents; ''Nephew'' reverses the generational relationship.', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Deductions (W10)', 'RSN_BLOOD_RELATIONS_W10', '[{"option_text": "Brother", "is_correct": false}, {"option_text": "Cousin", "is_correct": true}, {"option_text": "Nephew", "is_correct": false}, {"option_text": "Uncle", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('096b4d5c-4ff5-5060-8bae-10ffc5f00747', 'In a code: A × B means ''A is the mother of B''; A + B means ''A is the father of B''; A − B means ''A is the brother of B''. In the expression P × Q + R, what is P''s relationship to R?', NULL, 'B is correct. P × Q: P is the mother of Q. Q + R: Q is the father of R. So P is Q''s mother and Q is R''s father. Therefore P is R''s paternal grandmother. Trap: ''Mother'' skips a generation; ''Aunt'' would require P to be a sibling of R''s parent, not a parent herself.', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Deductions (W10)', 'RSN_BLOOD_RELATIONS_W10', '[{"option_text": "Mother", "is_correct": false}, {"option_text": "Grandmother", "is_correct": true}, {"option_text": "Aunt", "is_correct": false}, {"option_text": "Sister", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('afee129b-2271-5351-9fed-f7adbceafe66', 'M is the son of N. N is the daughter of O. O is the father of P. How is P related to M?', NULL, 'C is correct. N is O''s daughter and M is N''s son. O is also P''s father (O is the father of P). So N and P are both O''s children → N and P are siblings. Since N is M''s mother, P is M''s maternal uncle (if P is male) or maternal aunt (if P is female). The relationship is Uncle or Aunt. Trap: ''Grandfather'' would require O to be M''s grandfather, but O is P''s father (one generation above P, and P is M''s uncle/aunt — so O is M''s grandfather ✓). Wait — rechecking: O is N''s father (so O is M''s maternal grandfather ✓) and O is P''s father (so P is N''s sibling = M''s uncle/aunt ✓). Answer: C (Uncle or Aunt) is correct for P''s relationship to M.', 'HARD', 'Reasoning', 'Blood Relations — Family Deductions (W10)', 'RSN_BLOOD_RELATIONS_W10', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Brother", "is_correct": false}, {"option_text": "Uncle or Aunt", "is_correct": true}, {"option_text": "Grandfather", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8163dca8-b948-5bf4-b33c-c519d524a796', 'Pointing to a man in a photograph, a woman says, ''His mother is the only daughter of my mother.'' How is the man related to the woman?', NULL, 'C is correct. Only daughter of my mother = myself (the woman is the only daughter of her mother). So the man''s mother is the woman herself. The man is the woman''s son. Trap: ''Nephew'' would apply if the woman''s only daughter is her sister''s daughter; ''Brother'' misidentifies the gender/generation relationship.', 'HARD', 'Reasoning', 'Blood Relations — Family Deductions (W10)', 'RSN_BLOOD_RELATIONS_W10', '[{"option_text": "Brother", "is_correct": false}, {"option_text": "Nephew", "is_correct": false}, {"option_text": "Son", "is_correct": true}, {"option_text": "Father", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9ea0058e-5442-5a09-91dd-bdacaa17458f', 'In a code: A ÷ B means ''A is the father of B''; A − B means ''A is the wife of B''; A × B means ''A is the brother of B''. In the expression P ÷ R − Q, how is Q related to P?', NULL, 'C is correct. P ÷ R: P is the father of R. R − Q: R is the wife of Q. So P is R''s father, and R is Q''s wife. Therefore P is Q''s father-in-law, and Q is P''s son-in-law. Trap: ''Daughter-in-law'' confuses who married whom — Q is male (R is Q''s wife), so Q is P''s son-in-law, not daughter-in-law.', 'HARD', 'Reasoning', 'Blood Relations — Family Deductions (W10)', 'RSN_BLOOD_RELATIONS_W10', '[{"option_text": "Son", "is_correct": false}, {"option_text": "Daughter-in-law", "is_correct": false}, {"option_text": "Son-in-law", "is_correct": true}, {"option_text": "Brother-in-law", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6d18f20b-cb35-5454-85c8-0f8833567712', 'X has two children — Y (son) and Z (daughter). Y is married to W and has a son V. Z is married to U and has a daughter T. How is T related to V?', NULL, 'C is correct. V is Y''s son → V is X''s grandson. T is Z''s daughter → T is X''s granddaughter. Y and Z are siblings (both children of X). Since V''s father (Y) and T''s mother (Z) are siblings, V and T are cousins. Trap: ''Sister'' would require same parents; ''Niece'' would require V to be one generation above T''s parent (he is not — V and T are the same generation).', 'HARD', 'Reasoning', 'Blood Relations — Family Deductions (W10)', 'RSN_BLOOD_RELATIONS_W10', '[{"option_text": "Sister", "is_correct": false}, {"option_text": "Niece", "is_correct": false}, {"option_text": "Cousin", "is_correct": true}, {"option_text": "Aunt", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c5933310-142a-59cb-8b30-7d767047b0a8', 'A is the father of B. B is the sister of C. C is the mother of D. What is A''s relation to D?', NULL, 'C is correct. A is father of B → A is B''s father. B is sister of C → B and C are siblings, so A is also C''s father. C is mother of D → A is C''s father = D''s grandfather. Chain: A (father) → C (through sibling B) → D. So A is D''s Grandfather.', 'EASY', 'Reasoning', 'Blood Relations — Family Tree Puzzles (W10 B2)', 'RSN_BLOOD_RELATIONS_W10_B2', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Uncle", "is_correct": false}, {"option_text": "Grandfather", "is_correct": true}, {"option_text": "Grand uncle", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9b8ffdb3-ee2b-5297-a4f2-8a9f51c67971', 'Pointing to a photograph, Ravi says, ''She is the daughter of my grandfather''s only son.'' How is the person in the photograph related to Ravi?', NULL, 'B is correct. Ravi''s grandfather''s only son = Ravi''s father. The daughter of Ravi''s father = Ravi''s sister. Trap: ''Cousin'' — only if it were the son of an uncle/aunt; ''Aunt'' — would be the father''s sister; ''Niece'' — would be Ravi''s sibling''s daughter.', 'EASY', 'Reasoning', 'Blood Relations — Family Tree Puzzles (W10 B2)', 'RSN_BLOOD_RELATIONS_W10_B2', '[{"option_text": "Aunt", "is_correct": false}, {"option_text": "Sister", "is_correct": true}, {"option_text": "Cousin", "is_correct": false}, {"option_text": "Niece", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9661ec69-e1a6-559b-8cce-316c35b41f36', 'X is Y''s brother. Y is Z''s sister. Z is Q''s father. What is X''s relation to Q?', NULL, 'B is correct. X is Y''s brother. Y is Z''s sister → X, Y, Z are all siblings (same generation). Z is Q''s father → Z is male. X (sibling of Z) is Q''s uncle. Trap: ''Father'' confuses X and Z''s roles; ''Brother'' would be if X were in the same generation as Q; ''Grandfather'' would require one more generation.', 'EASY', 'Reasoning', 'Blood Relations — Family Tree Puzzles (W10 B2)', 'RSN_BLOOD_RELATIONS_W10_B2', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Uncle", "is_correct": true}, {"option_text": "Brother", "is_correct": false}, {"option_text": "Grandfather", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('63482b32-6f96-55dd-9c36-a03580672c0b', 'Seema is the wife of Aman. Aman''s mother is Kiran. Kiran''s father is Suresh. What is Seema''s relation to Suresh?', NULL, 'A is correct. Suresh is Kiran''s father → Kiran is Suresh''s daughter. Kiran is Aman''s mother → Aman is Suresh''s grandson. Seema is Aman''s wife → Seema is Suresh''s granddaughter-in-law. Trap: ''Daughter-in-law'' would be Seema''s relation to Kiran (one generation difference), not Suresh (two generations).', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Tree Puzzles (W10 B2)', 'RSN_BLOOD_RELATIONS_W10_B2', '[{"option_text": "Granddaughter-in-law", "is_correct": true}, {"option_text": "Daughter-in-law", "is_correct": false}, {"option_text": "Granddaughter", "is_correct": false}, {"option_text": "Sister-in-law", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('681ea719-aae4-59c7-a955-b2d082ef18c4', 'A man says to a woman, ''Your mother''s husband''s sister is my aunt.'' How is the woman related to the man?', NULL, 'B is correct. ''Your mother''s husband'' = woman''s father. ''Woman''s father''s sister'' = woman''s aunt. The man says this woman''s aunt is his aunt too. Since they share the same aunt (father''s sister), they share the same father → they are siblings. So the woman is the man''s sister. Trap: ''Cousin'' = if it were mother''s brother''s daughter; ''Niece'' = would be man''s sibling''s daughter (not the woman herself).', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Tree Puzzles (W10 B2)', 'RSN_BLOOD_RELATIONS_W10_B2', '[{"option_text": "Daughter", "is_correct": false}, {"option_text": "Sister", "is_correct": true}, {"option_text": "Niece", "is_correct": false}, {"option_text": "Cousin", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ef6dbbda-f7ea-5338-abbd-bcaac4ac77ea', 'P is the son of Q. R is Q''s sister. S is R''s mother. T is S''s husband. How is T related to P?', NULL, 'B is correct. T is S''s husband. S is R''s mother → T is R''s father. R is Q''s sister → T is Q''s grandfather (one more generation up: T→S→Q). P is Q''s son → T is P''s great-grandfather. Chain: P (son of Q) → Q (R''s sibling) → R (S''s child) → S (T''s wife). T is 3 generations above P = great-grandfather. Trap: ''Grandfather'' is T''s relation to Q, not P.', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Tree Puzzles (W10 B2)', 'RSN_BLOOD_RELATIONS_W10_B2', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Great-grandfather", "is_correct": true}, {"option_text": "Grandfather", "is_correct": false}, {"option_text": "Uncle", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bce5c47f-202e-5e7b-8e06-a24bfd4b5c68', 'Introducing a boy, a girl says, ''He is the son of my mother''s only brother.'' What is the boy''s relation to the girl''s father?', NULL, 'B is correct. The boy''s father = girl''s mother''s only brother = girl''s maternal uncle. The boy''s father and the girl''s father are brothers-in-law (married to sisters). The boy is the son of a man who is NOT related by blood to the girl''s father. But the question asks boy''s relation to girl''s father: the boy''s father is the girl''s mother''s brother → the boy''s father is the girl''s father''s brother-in-law. The boy is the son of his father, so the boy is the girl''s father''s nephew (his wife''s brother''s son = nephew-in-law, but by common usage = nephew). Trap: ''Son'' would imply the girl''s father is the boy''s grandfather.', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Tree Puzzles (W10 B2)', 'RSN_BLOOD_RELATIONS_W10_B2', '[{"option_text": "Son", "is_correct": false}, {"option_text": "Nephew", "is_correct": true}, {"option_text": "Brother", "is_correct": false}, {"option_text": "Cousin", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e3547b43-da3a-5873-9e40-1c1639fd8bd6', 'In a family: A and B are a married couple. C is A''s sister. D is C''s husband. E is B''s father. How is D related to E?', NULL, 'C is correct. A and B are married. C is A''s sister. D is C''s husband → D is A''s brother-in-law. E is B''s father → E is A''s father-in-law. D (A''s brother-in-law) and E (A''s father-in-law) have no defined blood or marriage relationship to each other — they are connected only through A. By standard relationship terminology, D and E have no direct family relation. Trap: Students often try to force a connection; in codified blood-relation questions, ''no direct relation'' is a valid and frequently correct answer.', 'HARD', 'Reasoning', 'Blood Relations — Family Tree Puzzles (W10 B2)', 'RSN_BLOOD_RELATIONS_W10_B2', '[{"option_text": "Son-in-law", "is_correct": false}, {"option_text": "Brother-in-law", "is_correct": false}, {"option_text": "No direct relation", "is_correct": true}, {"option_text": "Son", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1010c730-f679-5606-b836-2e29f1051577', 'If ''P × Q'' means P is father of Q, ''P + Q'' means P is mother of Q, ''P − Q'' means P is brother of Q, ''P ÷ Q'' means P is sister of Q, then what is the relationship of M to K in: M × N + L − K?', NULL, 'A is correct. Decode left to right: M × N = M is father of N. N + L = N is mother of L. L − K = L is brother of K. So: M (father) → N (mother of L) → L (brother of K). M is N''s father, N is K''s mother → M is K''s grandfather. Trap: ''Uncle'' would require M to be a sibling of K''s parent, not the parent''s parent. Operator-coded blood relations are high-frequency SSC Tier 1 questions.', 'HARD', 'Reasoning', 'Blood Relations — Family Tree Puzzles (W10 B2)', 'RSN_BLOOD_RELATIONS_W10_B2', '[{"option_text": "Grandfather", "is_correct": true}, {"option_text": "Uncle", "is_correct": false}, {"option_text": "Father", "is_correct": false}, {"option_text": "Great-grandfather", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('09fd9e22-8f69-534c-b3f4-294e64bba5cb', 'Using the same codes as Q9 (× = father, + = mother, − = brother, ÷ = sister), decode: A ÷ B × C + D. What is A''s relation to D?', NULL, 'C is correct. A ÷ B = A is sister of B. B × C = B is father of C. C + D = C is mother of D. Chain: A is B''s sister. B is C''s father → A is C''s aunt (father''s sister). C is D''s mother → A is D''s grand-aunt (aunt of D''s mother = great-aunt to D). Trap: ''Grandmother'' = B''s mother, not A; ''Aunt'' = A''s relation to C, not D; ''Mother'' = C''s relation to D. Students must carefully track each generation shift.', 'HARD', 'Reasoning', 'Blood Relations — Family Tree Puzzles (W10 B2)', 'RSN_BLOOD_RELATIONS_W10_B2', '[{"option_text": "Aunt", "is_correct": false}, {"option_text": "Grandmother", "is_correct": false}, {"option_text": "Grand-aunt (great-aunt)", "is_correct": true}, {"option_text": "Mother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6f542704-940f-5fad-89bc-3da612828669', 'A is the brother of B. B is the sister of C. C is the son of D. How is A related to D?', NULL, 'A is correct. A is the brother of B → A is male. B is the sister of C → B and C are siblings; B is female. C is the son of D → C is male and D''s child. Since A is B''s brother and B is C''s sister, A, B, and C are siblings. C is D''s son → all three are D''s children. A is D''s Son. Trap: Nephew = wrong generation — A is D''s child, not the child of D''s sibling.', 'EASY', 'Reasoning', 'Blood Relations — Family Tree and Coded Relation Puzzles (W11 B1)', 'RSN_BLOOD_RELATIONS_W11_B1', '[{"option_text": "Son", "is_correct": true}, {"option_text": "Daughter", "is_correct": false}, {"option_text": "Nephew", "is_correct": false}, {"option_text": "Cannot be determined", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b98cc075-3fd0-55bf-bad3-f7966500fe82', 'Pointing to a photograph, a woman said, ''His mother is the only daughter of my mother.'' How is the woman related to the man in the photograph?', NULL, 'C is correct. ''His mother is the only daughter of my mother.'' The only daughter of the woman''s mother = the woman herself. So ''his mother'' = the woman. The woman is the Mother of the man. Trap: Grandmother = confuses two generations; Aunt = would apply if the woman''s sister were his mother.', 'EASY', 'Reasoning', 'Blood Relations — Family Tree and Coded Relation Puzzles (W11 B1)', 'RSN_BLOOD_RELATIONS_W11_B1', '[{"option_text": "Aunt", "is_correct": false}, {"option_text": "Grandmother", "is_correct": false}, {"option_text": "Mother", "is_correct": true}, {"option_text": "Sister", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b528a819-8a5c-5aa3-9274-d0af4c5fff72', 'If P × Q means ''P is the father of Q'', P + Q means ''P is the mother of Q'', and P ÷ Q means ''P is the sister of Q'', what is the relation of P to R in the expression: P × Q + R?', NULL, 'B is correct. P × Q = P is the father of Q (Q is P''s child). Q + R = Q is the mother of R (R is Q''s child). Chaining: P is the father of Q; Q is the mother of R. Therefore P is the father of R''s mother = P is R''s grandfather. P → Q (parent) → R (grandchild). Trap: Father = one generation difference (here it''s two generations); Uncle = P would need to be a sibling of R''s parent.', 'HARD', 'Reasoning', 'Blood Relations — Family Tree and Coded Relation Puzzles (W11 B1)', 'RSN_BLOOD_RELATIONS_W11_B1', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Grandfather", "is_correct": true}, {"option_text": "Uncle", "is_correct": false}, {"option_text": "Brother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3afe30b1-b20a-5878-9b5a-39680b7c051f', 'Introducing a man, a woman said, ''He is the only son of my father''s only son.'' How is the woman related to the man?', NULL, 'B is correct. ''My father''s only son'' = the woman''s brother (since her father has only one son). ''He is the only son of my father''s only son'' = He is the son of the woman''s brother = He is her nephew. The woman is His Aunt. Trap: Mother = would apply if the woman herself were his parent; Sister = would make them the same generation as siblings.', 'HARD', 'Reasoning', 'Blood Relations — Family Tree and Coded Relation Puzzles (W11 B1)', 'RSN_BLOOD_RELATIONS_W11_B1', '[{"option_text": "Sister", "is_correct": false}, {"option_text": "Aunt", "is_correct": true}, {"option_text": "Mother", "is_correct": false}, {"option_text": "Grandmother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e22eed7c-8a0d-54ce-83e0-94fcd76987e3', 'A man said to a woman, ''Your mother''s husband''s sister is my aunt.'' How is the woman related to the man?', NULL, 'B is correct. ''Your mother''s husband'' = the woman''s father. ''Your mother''s husband''s sister'' = the woman''s father''s sister = the woman''s paternal aunt. The man says ''is my aunt''. So the woman''s paternal aunt is also the man''s aunt. They share the same paternal aunt → they share the same father. The woman and the man are siblings. The woman is the man''s Sister. Trap: Niece = would require a generation difference.', 'HARD', 'Reasoning', 'Blood Relations — Family Tree and Coded Relation Puzzles (W11 B1)', 'RSN_BLOOD_RELATIONS_W11_B1', '[{"option_text": "Daughter", "is_correct": false}, {"option_text": "Sister", "is_correct": true}, {"option_text": "Niece", "is_correct": false}, {"option_text": "Mother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0ea47684-1297-5dd9-89c8-ea994d493cb2', 'P is the father of Q. Q is the sister of R. S is the husband of R. T is the son of S. How is P related to T?', NULL, 'B is correct. P is the father of Q. Q is the sister of R → P is also R''s father (Q and R are siblings). R married S. T is the son of S and R. T is P''s grandchild (through R). P is the Grandfather of T. Trap: Uncle = P would be T''s uncle if P and R were siblings (but P is R''s parent); Great-grandfather = one generation too many.', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Tree and Coded Relation Puzzles (W11 B1)', 'RSN_BLOOD_RELATIONS_W11_B1', '[{"option_text": "Uncle", "is_correct": false}, {"option_text": "Grandfather", "is_correct": true}, {"option_text": "Father", "is_correct": false}, {"option_text": "Great-grandfather", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cc5cf116-e773-50be-a357-1ded01295465', 'Looking at the portrait of a man, Asha said, ''He is the son of my father''s only son.'' The man in the portrait is Asha''s:', NULL, 'B is correct. ''My father''s only son'' = Asha''s brother (Asha''s father has only one son). ''He is the son of Asha''s brother'' = Asha''s nephew. The portrait shows Asha''s Nephew. Trap: Son = Asha''s own son would require ''the son of myself/me'' (she can''t be her own brother); Brother = is her father''s son but not the son OF her brother.', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Tree and Coded Relation Puzzles (W11 B1)', 'RSN_BLOOD_RELATIONS_W11_B1', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Nephew", "is_correct": true}, {"option_text": "Son", "is_correct": false}, {"option_text": "Brother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6039a1d2-74f2-5898-a550-f486fd0a17a1', 'A and B are brothers. C and D are sisters. A''s son is D''s brother. How is B related to C?', NULL, 'C is correct. A and B are brothers. C and D are sisters. A''s son is D''s brother → A''s son and D are siblings → A is their parent → A is the father of D (and C, since C and D are sisters). So A is the father of C. B is the brother of A. Therefore B is the uncle of C (brother of C''s father). Trap: Father = A is C''s father, not B; Brother = different generations here.', 'HARD', 'Reasoning', 'Blood Relations — Family Tree and Coded Relation Puzzles (W11 B1)', 'RSN_BLOOD_RELATIONS_W11_B1', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Brother", "is_correct": false}, {"option_text": "Uncle", "is_correct": true}, {"option_text": "Grandfather", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('493aff02-4bb8-5940-ad4e-e0973392b9b2', 'Ram said to Shyam, ''Your father''s father is my father''s son.'' Assuming Ram has no brother, how is Ram related to Shyam?', NULL, 'A is correct. ''My father''s son'' (Ram speaking) = Ram himself (since Ram has no brother). So ''Shyam''s father''s father = Ram''. Shyam''s father''s father = Shyam''s grandfather (paternal). Therefore Shyam''s grandfather = Ram. Ram is Shyam''s Grandfather. Trap: Father = Ram would need to be Shyam''s father''s father''s son — one generation difference, not two; Uncle = lateral, not vertical lineage.', 'HARD', 'Reasoning', 'Blood Relations — Family Tree and Coded Relation Puzzles (W11 B1)', 'RSN_BLOOD_RELATIONS_W11_B1', '[{"option_text": "Grandfather", "is_correct": true}, {"option_text": "Father", "is_correct": false}, {"option_text": "Uncle", "is_correct": false}, {"option_text": "Great-grandfather", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9e027c9c-a21f-56db-a47c-f2dad1e28a95', 'Neha''s father has only one son. That son has one daughter. How many granddaughters does Neha''s grandfather have (counting only through Neha''s father''s family)?', NULL, 'B is correct. Neha''s father has one son = Neha''s brother. Neha''s brother has one daughter = Neha''s niece. Neha''s grandfather''s granddaughters (through Neha''s father): (1) Neha herself — she is the daughter of Neha''s father (who is Neha''s grandfather''s son); (2) Neha''s niece — she is the daughter of Neha''s brother (who is Neha''s grandfather''s grandson). Total = 2 granddaughters. Trap: One = counts only Neha and ignores her niece; Three = overcounts; Cannot be determined = all necessary information is provided.', 'MEDIUM', 'Reasoning', 'Blood Relations — Family Tree and Coded Relation Puzzles (W11 B1)', 'RSN_BLOOD_RELATIONS_W11_B1', '[{"option_text": "One", "is_correct": false}, {"option_text": "Two", "is_correct": true}, {"option_text": "Three", "is_correct": false}, {"option_text": "Cannot be determined", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bf3f3307-e023-5581-abdd-3de83e745990', 'A is the father of B. B is the sister of C. D is the mother of A. How is D related to C?', NULL, 'C is correct. D is A''s mother; A is the father of B and C. So D is the grandmother of both B and C.', 'EASY', 'Reasoning', 'Blood Relations (W9)', 'RSN_BLOOD_RELATIONS_W9', '[{"option_text": "Mother", "is_correct": false}, {"option_text": "Aunt", "is_correct": false}, {"option_text": "Grandmother", "is_correct": true}, {"option_text": "Sister", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fb85594a-fb01-5241-8311-1127f9376563', 'Pointing to a photo, Ravi says ''She is the daughter of my grandfather''s only son.'' How is the girl related to Ravi?', NULL, 'D is correct. Ravi''s grandfather''s only son = Ravi''s father. The girl is the daughter of Ravi''s father = Ravi''s sister.', 'EASY', 'Reasoning', 'Blood Relations (W9)', 'RSN_BLOOD_RELATIONS_W9', '[{"option_text": "Mother", "is_correct": false}, {"option_text": "Aunt", "is_correct": false}, {"option_text": "Cousin", "is_correct": false}, {"option_text": "Sister", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c6f11e19-5fbd-5e75-975c-c969de5fd5d0', 'Neha is the sister of Ravi. Ravi''s father is Ram. Ram''s mother is Sita. How is Neha related to Sita?', NULL, 'C is correct. Sita → Ram (son) → Neha (granddaughter). Neha is Sita''s granddaughter.', 'EASY', 'Reasoning', 'Blood Relations (W9)', 'RSN_BLOOD_RELATIONS_W9', '[{"option_text": "Daughter", "is_correct": false}, {"option_text": "Niece", "is_correct": false}, {"option_text": "Granddaughter", "is_correct": true}, {"option_text": "Daughter-in-law", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('be16fa5a-3b0b-5222-b918-8ad62a934f7d', 'Introducing a man, a woman says ''He is the only son of my mother''s mother.'' How is the man related to the woman?', NULL, 'B is correct. Mother''s mother = grandmother. Grandmother''s only son = the woman''s maternal uncle.', 'MEDIUM', 'Reasoning', 'Blood Relations (W9)', 'RSN_BLOOD_RELATIONS_W9', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Uncle", "is_correct": true}, {"option_text": "Grandfather", "is_correct": false}, {"option_text": "Brother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('09e779d2-d05e-5a5a-ab90-239d5f717e6e', 'A woman says of a photo ''The person is the only son of the father of my brother.'' How is the person in the photo related to her?', NULL, 'C is correct. Father of my brother = her father. Her father''s only son = her brother. So the person in the photo is her brother. (She is his sister.)', 'MEDIUM', 'Reasoning', 'Blood Relations (W9)', 'RSN_BLOOD_RELATIONS_W9', '[{"option_text": "Mother", "is_correct": false}, {"option_text": "Daughter", "is_correct": false}, {"option_text": "Brother", "is_correct": true}, {"option_text": "Niece", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('950910d7-124b-5ed1-92d4-aa0652c7862e', 'Mrs. Sharma says of a girl ''She is the daughter of the only son of my father.'' What is the girl to Mrs. Sharma?', NULL, 'B is correct. Mrs. Sharma''s father''s only son = Mrs. Sharma''s brother. The girl is the daughter of Mrs. Sharma''s brother = Mrs. Sharma''s niece.', 'MEDIUM', 'Reasoning', 'Blood Relations (W9)', 'RSN_BLOOD_RELATIONS_W9', '[{"option_text": "Sister", "is_correct": false}, {"option_text": "Niece", "is_correct": true}, {"option_text": "Daughter", "is_correct": false}, {"option_text": "Cousin", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b29a309a-7470-59d3-a605-4c68e2f2ffae', 'P is Q''s son. R is the brother of P. S is the mother of Q. How is R related to S?', NULL, 'B is correct. S is Q''s mother. Q is P''s parent. R is P''s brother, so R is also Q''s child. Therefore R is S''s grandson (S is the mother of Q who is the parent of P and R).', 'MEDIUM', 'Reasoning', 'Blood Relations (W9)', 'RSN_BLOOD_RELATIONS_W9', '[{"option_text": "Son", "is_correct": false}, {"option_text": "Grandson", "is_correct": true}, {"option_text": "Nephew", "is_correct": false}, {"option_text": "Grandfather", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('29176167-bf02-53be-87c2-07f27331974c', 'If P''s father Q is the brother of R, and R''s mother S is the wife of T, how is T related to P?', NULL, 'C is correct. S (wife of T) is R''s mother → T is R''s father. Q (P''s father) is R''s brother → Q and R have the same parents → T is Q''s father → T is P''s grandfather.', 'HARD', 'Reasoning', 'Blood Relations (W9)', 'RSN_BLOOD_RELATIONS_W9', '[{"option_text": "Uncle", "is_correct": false}, {"option_text": "Father", "is_correct": false}, {"option_text": "Grandfather", "is_correct": true}, {"option_text": "Brother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3a285b6b-c9ea-5433-8370-9dff256e85e0', 'A woman looking at a portrait says ''This man''s mother''s only daughter-in-law is my maternal grandmother.'' Who is the man in the portrait?', NULL, 'B is correct. ''This man''s mother''s only daughter-in-law'' = the only person who married into the man''s mother''s family = the man''s wife. The man''s wife = the woman''s maternal grandmother → the man = the woman''s maternal grandfather.', 'HARD', 'Reasoning', 'Blood Relations (W9)', 'RSN_BLOOD_RELATIONS_W9', '[{"option_text": "My father", "is_correct": false}, {"option_text": "My grandfather", "is_correct": true}, {"option_text": "My uncle", "is_correct": false}, {"option_text": "My brother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('808a1370-c26e-5cf4-bc24-81dd3f0a0034', 'A is the son of B. C is the daughter of A. D is the husband of C. E is the son of D. How is E related to B?', NULL, 'A is correct. B → A (son) → C (daughter) → D (husband of C) → E (son). So E is B''s great-grandson. The chain: B is A''s parent, A is C''s parent, C is E''s parent (through D) — three generations down from B.', 'HARD', 'Reasoning', 'Blood Relations (W9)', 'RSN_BLOOD_RELATIONS_W9', '[{"option_text": "Great-grandson", "is_correct": true}, {"option_text": "Grandson", "is_correct": false}, {"option_text": "Nephew", "is_correct": false}, {"option_text": "Son", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('47518147-5d89-5fdb-8b62-55154946edc5', '1st January 2023 was a Sunday. What day of the week was 1st March 2023?', NULL, 'C is correct. Count days from Jan 1 to Mar 1: January has 31 days (Jan 1 to Feb 1 = 31 days), February 2023 has 28 days (2023 is NOT a leap year — not divisible by 4). Jan 1 to Mar 1 = 31+28 = 59 days. 59 ÷ 7 = 8 weeks + 3 remainder days. Sunday + 3 days = Wednesday. Note: 2023 is odd (not ÷4), so Feb has 28 days. Trap: If you mistakenly treat 2023 as a leap year (adding 29 days for Feb), you get Sunday + (31+29=60) = 60÷7=8R4 → Thursday (wrong).', 'MEDIUM', 'Reasoning', 'Calendar and Day Calculations — Odd Days Method, Day Finding and Century Rules (W13 B1)', 'RSN_CALENDAR_DAYS_W13_B1', '[{"option_text": "Monday", "is_correct": false}, {"option_text": "Tuesday", "is_correct": false}, {"option_text": "Wednesday", "is_correct": true}, {"option_text": "Thursday", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('40fe538e-6490-5506-bc64-7dbfbe9343fc', '1st January 2024 was a Monday. What day was 1st January 2025?', NULL, 'B is correct. 2024 is a LEAP year (divisible by 4; and 2024÷4=506). A leap year has 366 days = 52 weeks + 2 days = 2 odd days. The day shifts forward by 2: Monday + 2 = Wednesday. RULE: Ordinary year → day shifts by 1; Leap year → day shifts by 2. Trap: Tuesday = shifts by only 1 (ordinary year rule); Thursday = shifts by 3.', 'MEDIUM', 'Reasoning', 'Calendar and Day Calculations — Odd Days Method, Day Finding and Century Rules (W13 B1)', 'RSN_CALENDAR_DAYS_W13_B1', '[{"option_text": "Tuesday", "is_correct": false}, {"option_text": "Wednesday", "is_correct": true}, {"option_text": "Thursday", "is_correct": false}, {"option_text": "Friday", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b9ddbcea-a7c3-5e63-911e-866aeb6f2493', 'Today is Wednesday. What day will it be 100 days from now?', NULL, 'C is correct. 100 ÷ 7 = 14 weeks + 2 days remainder. Wednesday + 2 = Friday. SHORTCUT: only the remainder matters for the day shift. 100 mod 7 = 2 (since 14×7=98, remainder=2). Advance by 2 days from Wednesday: Thursday, Friday. Trap: Saturday = 100 mod 7 done as 100/7≈14.28; 0.28×7=2; Wednesday+3=Saturday (wrong rounding).', 'MEDIUM', 'Reasoning', 'Calendar and Day Calculations — Odd Days Method, Day Finding and Century Rules (W13 B1)', 'RSN_CALENDAR_DAYS_W13_B1', '[{"option_text": "Tuesday", "is_correct": false}, {"option_text": "Thursday", "is_correct": false}, {"option_text": "Friday", "is_correct": true}, {"option_text": "Saturday", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2857b498-44de-50ff-973a-7aaf0edfc35f', 'If 2nd July 2023 was a Sunday, what day was 2nd July 2022?', NULL, 'B is correct. Going BACKWARDS from 2023 to 2022: the year 2022 is an ordinary year (365 days = 52 weeks + 1 odd day). So going back one ordinary year, the day moves back by 1. July 2, 2023 = Sunday; July 2, 2022 = Sunday − 1 = Saturday. Alternatively: from July 2, 2022 to July 2, 2023 = 365 days (ordinary year) = 52×7+1 → advance by 1 day → Saturday+1=Sunday ✓ so going back: Sunday−1=Saturday. Trap: Friday = going back 2 days (wrong — only 1 odd day in ordinary year).', 'MEDIUM', 'Reasoning', 'Calendar and Day Calculations — Odd Days Method, Day Finding and Century Rules (W13 B1)', 'RSN_CALENDAR_DAYS_W13_B1', '[{"option_text": "Friday", "is_correct": false}, {"option_text": "Saturday", "is_correct": true}, {"option_text": "Sunday", "is_correct": false}, {"option_text": "Monday", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2accf7d0-5190-57d6-ba4e-862292451e14', 'The 7th day of a month is a Friday. What day does the 1st of the same month fall on?', NULL, 'A is correct. From the 1st to the 7th = 6 days later. So 7th = 1st + 6 days. If 7th = Friday, then 1st = Friday − 6 days. Friday = day 6 (Mon=1...Sun=7). 6−6=0 ≡ 7 (mod 7) = Sunday? Let me recount directly: go back 6 days from Friday: Thursday(−1), Wednesday(−2), Tuesday(−3), Monday(−4), Sunday(−5), Saturday(−6). 1st = Saturday. Trap: Thursday = going back only 1 day; Sunday = going back 5 days. Count carefully: 7th to 6th=1 day back, 6th to 5th=2, 5th to 4th=3, 4th to 3rd=4, 3rd to 2nd=5, 2nd to 1st=6. Six days back from Friday = Saturday.', 'MEDIUM', 'Reasoning', 'Calendar and Day Calculations — Odd Days Method, Day Finding and Century Rules (W13 B1)', 'RSN_CALENDAR_DAYS_W13_B1', '[{"option_text": "Saturday", "is_correct": true}, {"option_text": "Sunday", "is_correct": false}, {"option_text": "Thursday", "is_correct": false}, {"option_text": "Friday", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('17d24615-6a80-57be-b5de-88fb3213782c', '15th March of a year falls on a Thursday. What day does 1st April of the same year fall on?', NULL, 'C is correct. From 15th March to 1st April: remaining March days = 31−15 = 16 days. Plus April 1 itself = 16+1 = 17 days forward. 17 ÷ 7 = 2 weeks + 3 days. Thursday + 3 = Sunday. Verify: Thursday + 1=Friday, +2=Saturday, +3=Sunday ✓. Trap: Friday = +1 only; Saturday = +2; Monday = +4.', 'MEDIUM', 'Reasoning', 'Calendar and Day Calculations — Odd Days Method, Day Finding and Century Rules (W13 B1)', 'RSN_CALENDAR_DAYS_W13_B1', '[{"option_text": "Friday", "is_correct": false}, {"option_text": "Saturday", "is_correct": false}, {"option_text": "Sunday", "is_correct": true}, {"option_text": "Monday", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('78abaff7-2e72-54d9-8967-5e93f9985e8c', 'How many odd days are in a leap year?', NULL, 'C is correct. A leap year = 366 days = 52 weeks + 2 days. The extra 2 days beyond complete weeks are called ODD DAYS. For ordinary year: 365 = 52×7+1 → 1 odd day. For leap year: 366 = 52×7+2 → 2 odd days. These odd days determine the day-shift when calculating what day a date falls on across years. In 400 years, total odd days = 400 years × various = 0 (mod 7), which is why the Gregorian calendar repeats every 400 years exactly. Trap: 1 = for ordinary year; 3 = 3 odd days (no standard year type).', 'HARD', 'Reasoning', 'Calendar and Day Calculations — Odd Days Method, Day Finding and Century Rules (W13 B1)', 'RSN_CALENDAR_DAYS_W13_B1', '[{"option_text": "0", "is_correct": false}, {"option_text": "1", "is_correct": false}, {"option_text": "2", "is_correct": true}, {"option_text": "3", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('539279a0-82e6-5be3-b608-00f9aed8f90e', 'Which of the following CANNOT be the last day of a century?', NULL, 'B is correct. In 100 years: 76 ordinary years + 24 leap years = 76×1 + 24×2 = 76+48 = 124 odd days. 124 ÷ 7 = 17 weeks + 5 odd days. So each century the day advances by 5. If century 1 ends on some day, century 2 ends 5 days later, etc. Starting from Monday (1): Mon, Sat, Thu, Tue, Sun, Fri, Wed... (cycle of 7). The last days of centuries (in sequence) are: Friday (for years 100, 500, 900...), Wednesday (200, 600...), Monday (300, 700...), Sunday (400, 800...). NEVER Tuesday, Thursday or Saturday. Trap: Friday/Sunday/Monday = can be last days of a century.', 'HARD', 'Reasoning', 'Calendar and Day Calculations — Odd Days Method, Day Finding and Century Rules (W13 B1)', 'RSN_CALENDAR_DAYS_W13_B1', '[{"option_text": "Monday", "is_correct": false}, {"option_text": "Tuesday", "is_correct": true}, {"option_text": "Sunday", "is_correct": false}, {"option_text": "Friday", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('603f7c65-3337-50ab-a880-fbcd99cdab5a', 'February 1, 2020 was a Saturday. What day was February 29, 2020?', NULL, 'C is correct. 2020 is a leap year (2020÷4=505, ÷100≠0 exactly... 2020÷100=20.2, so NOT a century year, and ÷4 yes → leap year). From Feb 1 to Feb 29: 28 days = exactly 4 weeks = 0 odd days. Saturday + 0 = Saturday. Verify: Feb has 29 days in 2020 (leap). Feb 1 to Feb 29 = 28 days gap. 28 ÷ 7 = 4 complete weeks → same day of week. Trap: Students who think ''29 days in February'' and add 29 days forward instead of counting the gap (28 days = from 1st to 29th).', 'HARD', 'Reasoning', 'Calendar and Day Calculations — Odd Days Method, Day Finding and Century Rules (W13 B1)', 'RSN_CALENDAR_DAYS_W13_B1', '[{"option_text": "Thursday", "is_correct": false}, {"option_text": "Friday", "is_correct": false}, {"option_text": "Saturday", "is_correct": true}, {"option_text": "Sunday", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('77ccc361-9800-53d2-beea-53e56eb5b7eb', 'A man says ''The day before yesterday was Saturday.'' On what day is he speaking?', NULL, 'A is correct. ''Day before yesterday'' = two days ago. If two days ago = Saturday, then: Yesterday = Saturday+1 = Sunday. Today = Sunday+1 = Monday. Verify: If today = Monday, yesterday = Sunday, day before yesterday = Saturday ✓. Trap: Sunday = confusing ''day before yesterday'' with ''yesterday''; Tuesday = confusing the direction (going forward instead of backward); Wednesday = three days after Saturday.', 'HARD', 'Reasoning', 'Calendar and Day Calculations — Odd Days Method, Day Finding and Century Rules (W13 B1)', 'RSN_CALENDAR_DAYS_W13_B1', '[{"option_text": "Monday", "is_correct": true}, {"option_text": "Sunday", "is_correct": false}, {"option_text": "Tuesday", "is_correct": false}, {"option_text": "Wednesday", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
