INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('adb6b4d3-c99d-5067-bac2-046c3d978cd1', 'Find the odd one out: Apple, Mango, Banana, Carrot', NULL, 'D is correct. Apple, Mango, and Banana are all fruits. Carrot is a vegetable (root vegetable). Trap: students who focus on ''orange coloured'' might think Mango is odd, but the correct classifying criterion is fruit vs. vegetable.', 'EASY', 'Reasoning', 'Classification — Odd One Out from Groups (W10 B2)', 'RSN_CLASSIFICATION_W10_B2', '[{"option_text": "Apple", "is_correct": false}, {"option_text": "Mango", "is_correct": false}, {"option_text": "Banana", "is_correct": false}, {"option_text": "Carrot", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cd79fb53-3eaf-5243-8f8a-642336fd8843', 'Find the odd one out: Monday, Wednesday, Friday, February', NULL, 'D is correct. Monday, Wednesday, and Friday are all days of the week. February is a month of the year. Trap: all four can be units of time, but the specific category (days of the week vs. months) distinguishes February.', 'EASY', 'Reasoning', 'Classification — Odd One Out from Groups (W10 B2)', 'RSN_CLASSIFICATION_W10_B2', '[{"option_text": "Monday", "is_correct": false}, {"option_text": "Wednesday", "is_correct": false}, {"option_text": "Friday", "is_correct": false}, {"option_text": "February", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('13fdb4c4-7e77-5c02-86b5-eba33c915617', 'Find the odd one out: 16, 25, 36, 50', NULL, 'D is correct. 16=4², 25=5², 36=6² are all perfect squares. 50 is not a perfect square (7²=49, 8²=64). Trap: students who test divisibility may be misled; only the perfect square property separates 50 from the rest.', 'MEDIUM', 'Reasoning', 'Classification — Odd One Out from Groups (W10 B2)', 'RSN_CLASSIFICATION_W10_B2', '[{"option_text": "16", "is_correct": false}, {"option_text": "25", "is_correct": false}, {"option_text": "36", "is_correct": false}, {"option_text": "50", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('72256e1a-75b1-54ab-bf25-71115c7b11e2', 'Find the odd one out: Gold, Silver, Diamond, Copper', NULL, 'C is correct. Gold, Silver, and Copper are all metals (pure elemental metals). Diamond is a non-metal — it is an allotrope of carbon. Trap: all four are precious/valuable materials, but the criterion is metal vs. non-metal. Diamond is the hardest known natural substance but is not a metal.', 'MEDIUM', 'Reasoning', 'Classification — Odd One Out from Groups (W10 B2)', 'RSN_CLASSIFICATION_W10_B2', '[{"option_text": "Gold", "is_correct": false}, {"option_text": "Silver", "is_correct": false}, {"option_text": "Diamond", "is_correct": true}, {"option_text": "Copper", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ef70616f-296f-5b96-a440-7d6c95728e25', 'Find the odd one out: Nitrogen, Oxygen, Carbon dioxide, Argon', NULL, 'C is correct. Nitrogen (N₂), Oxygen (O₂), and Argon (Ar) are all elements — pure substances consisting of one type of atom. Carbon dioxide (CO₂) is a compound made of two different elements (carbon + oxygen). Trap: all four are present in the atmosphere, but only Carbon dioxide is a compound rather than an element.', 'MEDIUM', 'Reasoning', 'Classification — Odd One Out from Groups (W10 B2)', 'RSN_CLASSIFICATION_W10_B2', '[{"option_text": "Nitrogen", "is_correct": false}, {"option_text": "Oxygen", "is_correct": false}, {"option_text": "Carbon dioxide", "is_correct": true}, {"option_text": "Argon", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c86b1546-3379-5667-b08a-d042f4f3c5b6', 'Find the odd one out: Sitar, Veena, Harmonium, Tambura', NULL, 'C is correct. Sitar, Veena, and Tambura are all chordophone (string) instruments — sound produced by vibrating strings. The Harmonium is a keyboard instrument driven by bellows (a wind/reed instrument), where sound is produced by air flowing over metal reeds. Trap: all four are traditional Indian classical music instruments, so the category ''Indian music'' doesn''t help — the criterion is the instrument family (string vs. wind/reed).', 'MEDIUM', 'Reasoning', 'Classification — Odd One Out from Groups (W10 B2)', 'RSN_CLASSIFICATION_W10_B2', '[{"option_text": "Sitar", "is_correct": false}, {"option_text": "Veena", "is_correct": false}, {"option_text": "Harmonium", "is_correct": true}, {"option_text": "Tambura", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c6d762a2-bfde-5fd6-bc68-70a0effb37c5', 'Find the odd one out: 8, 27, 64, 125, 198', NULL, 'D is correct. 8=2³, 27=3³, 64=4³, 125=5³ are all perfect cubes. 198 is not a perfect cube (6³=216, 5³=125; 198 falls between them and equals no cube of a whole number). Trap: 198 looks plausible as 2×99 or 6×33, but neither generates a cube relationship.', 'HARD', 'Reasoning', 'Classification — Odd One Out from Groups (W10 B2)', 'RSN_CLASSIFICATION_W10_B2', '[{"option_text": "27", "is_correct": false}, {"option_text": "64", "is_correct": false}, {"option_text": "125", "is_correct": false}, {"option_text": "198", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8233a9af-b6c5-525c-b4f3-b52aeadf3ad4', 'Find the odd one out among the letter groups: ACE, BDF, EFG, GIK', NULL, 'C is correct. ACE: A(1)C(3)E(5) — each letter separated by +2. BDF: B(2)D(4)F(6) — each letter separated by +2. GIK: G(7)I(9)K(11) — each letter separated by +2. EFG: E(5)F(6)G(7) — letters separated by +1 (consecutive letters). EFG breaks the pattern of skipping one letter between each character in the group.', 'HARD', 'Reasoning', 'Classification — Odd One Out from Groups (W10 B2)', 'RSN_CLASSIFICATION_W10_B2', '[{"option_text": "ACE", "is_correct": false}, {"option_text": "BDF", "is_correct": false}, {"option_text": "EFG", "is_correct": true}, {"option_text": "GIK", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b84799e5-6f3d-5a9a-a559-e8f549ace466', 'Find the odd one out: Panther, Jaguar, Leopard, Cheetah (consider roaring ability)', NULL, 'D is correct. Panther, Jaguar, and Leopard (along with Tiger and Lion) are ''big cats'' belonging to the genus Panthera and have the ability to ROAR. A Cheetah belongs to the genus Acinonyx — it cannot roar but can purr continuously. Cheetah is also the only cat that cannot fully retract its claws. Trap: all four are spotted wild cats, but roaring/non-roaring is the distinguishing biological feature.', 'HARD', 'Reasoning', 'Classification — Odd One Out from Groups (W10 B2)', 'RSN_CLASSIFICATION_W10_B2', '[{"option_text": "Panther", "is_correct": false}, {"option_text": "Jaguar", "is_correct": false}, {"option_text": "Leopard", "is_correct": false}, {"option_text": "Cheetah", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('311c52a0-320f-50bf-aa08-3d302c328494', 'Find the odd one out: Rajya Sabha, Lok Sabha, Vidhan Sabha, Zila Parishad', NULL, 'D is correct. Rajya Sabha and Lok Sabha are houses of the Indian Parliament (Central Legislature). Vidhan Sabha is the lower house of a state legislature. All three are legislative bodies at the Central or State level. Zila Parishad is a local government body at the district level (Panchayati Raj institution) — not a legislative assembly at the state or central level. Trap: all four are elected/representative bodies, but the criterion is ''legislative assembly'' vs. ''local government institution''.', 'HARD', 'Reasoning', 'Classification — Odd One Out from Groups (W10 B2)', 'RSN_CLASSIFICATION_W10_B2', '[{"option_text": "Rajya Sabha", "is_correct": false}, {"option_text": "Lok Sabha", "is_correct": false}, {"option_text": "Vidhan Sabha", "is_correct": false}, {"option_text": "Zila Parishad", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b8d55b62-df13-5c10-98a5-f85761c18fa7', 'Choose the odd one out: Mango, Banana, Guava, Tomato, Papaya', NULL, 'C is correct. Mango, Banana, Guava, and Papaya are all fruits (botanically and in common culinary usage). Tomato is botanically a fruit but in Indian cuisine and everyday classification is treated as a vegetable. In SSC reasoning, Tomato is the odd one out as it doesn''t belong with ''fruits used in everyday eating''. Trap: Guava and Banana are also unique in texture/form but all are categorised as fruits in common parlance.', 'EASY', 'Reasoning', 'Classification — Odd One Out (W11 B2)', 'RSN_CLASSIFICATION_W11_B2', '[{"option_text": "Mango", "is_correct": false}, {"option_text": "Banana", "is_correct": false}, {"option_text": "Tomato", "is_correct": true}, {"option_text": "Papaya", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d0208498-b336-5b03-8760-14b6e18611d4', 'Choose the odd one out: 17, 23, 29, 35, 41', NULL, 'C is correct. 17, 23, 29, and 41 are all prime numbers. 35 = 5×7 is composite (not prime). All appear to follow an AP with d=6 but that''s a distractor — the key property is primeness. 35 is the odd one out. Trap: looks like an AP (each differs by 6) but the primeness property separates 35.', 'MEDIUM', 'Reasoning', 'Classification — Odd One Out (W11 B2)', 'RSN_CLASSIFICATION_W11_B2', '[{"option_text": "17", "is_correct": false}, {"option_text": "23", "is_correct": false}, {"option_text": "35", "is_correct": true}, {"option_text": "41", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3fd6fd08-214d-5cae-a2a4-0c83075c4422', 'Choose the odd one out: Violin, Guitar, Sitar, Tabla, Veena', NULL, 'D is correct. Violin, Guitar, Sitar, and Veena are all stringed instruments (chordophones — played by plucking or bowing strings). Tabla is a percussion instrument (membranophone — played by striking a membrane). Tabla is the odd one out. Trap: all may seem ''Indian instruments'' but Violin and Guitar are also included, confirming the unifying property is ''stringed instruments'' not ''Indian origin''.', 'EASY', 'Reasoning', 'Classification — Odd One Out (W11 B2)', 'RSN_CLASSIFICATION_W11_B2', '[{"option_text": "Violin", "is_correct": false}, {"option_text": "Guitar", "is_correct": false}, {"option_text": "Sitar", "is_correct": false}, {"option_text": "Tabla", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('85565498-2b10-58d5-95d4-88cecf510ddb', 'Choose the odd one out based on the internal pattern: ACE, BDF, CGI, EGI', NULL, 'C is correct. Check gaps between letters (positions in alphabet): ACE: A(1)→C(3)=+2, C(3)→E(5)=+2. Equal gaps ✓. BDF: B(2)→D(4)=+2, D(4)→F(6)=+2. Equal gaps ✓. CGI: C(3)→G(7)=+4, G(7)→I(9)=+2. Unequal gaps ✗ (should be C,E,G for equal +2 gaps). EGI: E(5)→G(7)=+2, G(7)→I(9)=+2. Equal gaps ✓. CGI is the odd one out — its first gap (+4) breaks the +2,+2 pattern. Trap: EGI shares letters with CGI but has equal gaps; C→G skips D,E,F (4 steps) instead of 2.', 'HARD', 'Reasoning', 'Classification — Odd One Out (W11 B2)', 'RSN_CLASSIFICATION_W11_B2', '[{"option_text": "ACE", "is_correct": false}, {"option_text": "BDF", "is_correct": false}, {"option_text": "CGI", "is_correct": true}, {"option_text": "EGI", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bb003a69-1e29-51d6-ad70-a76e573b6a9c', 'Choose the odd one out: 8, 27, 64, 100, 125', NULL, 'C is correct. 8 = 2³, 27 = 3³, 64 = 4³, 125 = 5³ are all perfect cubes. 100 = 10² is a perfect square but NOT a perfect cube. 100 is the odd one out. Trap: 64 = 4³ but also 8² (perfect square) — the defining property here is CUBES, and 100 fails this test.', 'MEDIUM', 'Reasoning', 'Classification — Odd One Out (W11 B2)', 'RSN_CLASSIFICATION_W11_B2', '[{"option_text": "27", "is_correct": false}, {"option_text": "64", "is_correct": false}, {"option_text": "100", "is_correct": true}, {"option_text": "125", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('53025c7b-e7aa-5f2a-bc71-94d4f534593b', 'Choose the odd one out: Doctor, Engineer, Lawyer, Teacher, Hospital', NULL, 'D is correct. Doctor, Engineer, Lawyer, and Teacher are all professions (designations of people). Hospital is a place — not a profession. It does not belong with the others. Trap: one might associate ''Doctor'' with ''Hospital'' but Doctor remains a profession, not a place.', 'EASY', 'Reasoning', 'Classification — Odd One Out (W11 B2)', 'RSN_CLASSIFICATION_W11_B2', '[{"option_text": "Doctor", "is_correct": false}, {"option_text": "Lawyer", "is_correct": false}, {"option_text": "Teacher", "is_correct": false}, {"option_text": "Hospital", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bbcd522e-7998-526b-a079-424ff8410ab3', 'Choose the odd one out: Km, Litre, Metre, Mile, Centimetre', NULL, 'B is correct. Km, Metre, Mile, and Centimetre are all units of length/distance. Litre is a unit of volume (capacity), not length. Litre is the odd one out. Trap: Mile is an Imperial unit while the others are mostly metric — but Mile is still a unit of length, so it belongs with the group.', 'EASY', 'Reasoning', 'Classification — Odd One Out (W11 B2)', 'RSN_CLASSIFICATION_W11_B2', '[{"option_text": "Km", "is_correct": false}, {"option_text": "Litre", "is_correct": true}, {"option_text": "Metre", "is_correct": false}, {"option_text": "Centimetre", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ddf89114-195b-5b46-b947-25f0cbb63b46', 'Choose the odd one out: 144, 169, 196, 225, 228', NULL, 'D is correct. 144 = 12², 169 = 13², 196 = 14², 225 = 15² are all perfect squares. 228 is not a perfect square (√228 ≈ 15.1). 228 is the odd one out. Trap: 169 might seem odd (13 is prime) but it is still a perfect square.', 'MEDIUM', 'Reasoning', 'Classification — Odd One Out (W11 B2)', 'RSN_CLASSIFICATION_W11_B2', '[{"option_text": "144", "is_correct": false}, {"option_text": "196", "is_correct": false}, {"option_text": "225", "is_correct": false}, {"option_text": "228", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c84afaaf-fdb8-5bd6-bf4f-fbcb01454d3e', 'Choose the odd one out: January, March, May, July, August', NULL, 'D is correct. January, March, May, and July are months with 31 days that appear in the sequence of ''every other odd month'' (months 1, 3, 5, 7). August (month 8) is an even-numbered month — it doesn''t fit the pattern of odd-numbered months. The group January(1), March(3), May(5), July(7) are all odd-numbered months with 31 days. August is the 8th month (even). Trap: All 5 months have 31 days, which is the surface-level common property — but the deeper pattern is odd-numbered months, excluding August.', 'HARD', 'Reasoning', 'Classification — Odd One Out (W11 B2)', 'RSN_CLASSIFICATION_W11_B2', '[{"option_text": "January", "is_correct": false}, {"option_text": "March", "is_correct": false}, {"option_text": "July", "is_correct": false}, {"option_text": "August", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8447db98-5ba0-52d0-9b43-3b238a254fc7', 'Choose the odd one out: BEH, CFI, DGJ, EHL, FIL', NULL, 'C is correct. Check gaps in each group: BEH: B(2)→E(5)=+3, E(5)→H(8)=+3 ✓. CFI: C(3)→F(6)=+3, F(6)→I(9)=+3 ✓. DGJ: D(4)→G(7)=+3, G(7)→J(10)=+3 ✓. EHL: E(5)→H(8)=+3, H(8)→L(12)=+4 ✗ (should be +3, giving K=11, not L=12). FIL: F(6)→I(9)=+3, I(9)→L(12)=+3 ✓. EHL breaks the +3,+3 pattern — its third letter should be K (H+3=11=K), not L. EHL is the odd one out. Trap: FIL looks suspicious since L(12)=I(9)+3 ✓ is correct.', 'HARD', 'Reasoning', 'Classification — Odd One Out (W11 B2)', 'RSN_CLASSIFICATION_W11_B2', '[{"option_text": "BEH", "is_correct": false}, {"option_text": "DGJ", "is_correct": false}, {"option_text": "EHL", "is_correct": true}, {"option_text": "FIL", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c829dde6-1db0-5f09-96d6-f52ca29ed561', 'Which is the odd one out? Cricket, Football, Chess, Hockey', NULL, 'C is correct. Cricket, Football and Hockey are outdoor team sports played with a ball or puck. Chess is an indoor board game requiring no physical movement.', 'EASY', 'Reasoning', 'Classification — Odd One Out (W9)', 'RSN_CLASSIFICATION_W9', '[{"option_text": "Cricket", "is_correct": false}, {"option_text": "Football", "is_correct": false}, {"option_text": "Chess", "is_correct": true}, {"option_text": "Hockey", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fb80e5ca-493e-543b-a5fd-1bc1ad6ab125', 'Which is the odd one out? Rose, Lily, Tulip, Mango', NULL, 'D is correct. Rose, Lily and Tulip are flowers. Mango is a fruit.', 'EASY', 'Reasoning', 'Classification — Odd One Out (W9)', 'RSN_CLASSIFICATION_W9', '[{"option_text": "Rose", "is_correct": false}, {"option_text": "Lily", "is_correct": false}, {"option_text": "Tulip", "is_correct": false}, {"option_text": "Mango", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9877a742-1b7b-5a9d-9845-b2e4a4bbbcfb', 'Which is the odd one out? Square, Circle, Triangle, Volume', NULL, 'D is correct. Square, Circle and Triangle are 2D geometric shapes. Volume is a 3D measurement concept, not a shape.', 'EASY', 'Reasoning', 'Classification — Odd One Out (W9)', 'RSN_CLASSIFICATION_W9', '[{"option_text": "Square", "is_correct": false}, {"option_text": "Circle", "is_correct": false}, {"option_text": "Triangle", "is_correct": false}, {"option_text": "Volume", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('856ee811-65cd-5203-83b5-be369b8ae961', 'Which number is the odd one out? 4, 9, 25, 36, 49', NULL, 'C is correct. 4=2², 9=3², 25=5², 49=7² — squares of prime numbers. 36=6² and 6 is NOT prime. 36 is the odd one out.', 'MEDIUM', 'Reasoning', 'Classification — Odd One Out (W9)', 'RSN_CLASSIFICATION_W9', '[{"option_text": "4", "is_correct": false}, {"option_text": "9", "is_correct": false}, {"option_text": "36", "is_correct": true}, {"option_text": "49", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('508f4ccf-50ff-55e4-8c6b-b8f3c068763a', 'Which is the odd one out? Violin, Guitar, Flute, Sitar', NULL, 'C is correct. Violin, Guitar and Sitar are string instruments played by plucking or bowing. Flute is a wind instrument played by blowing.', 'MEDIUM', 'Reasoning', 'Classification — Odd One Out (W9)', 'RSN_CLASSIFICATION_W9', '[{"option_text": "Violin", "is_correct": false}, {"option_text": "Guitar", "is_correct": false}, {"option_text": "Flute", "is_correct": true}, {"option_text": "Sitar", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c36046c8-6811-5282-be55-161d5c7245d7', 'Which is the odd one out? Diamond, Gold, Silver, Copper', NULL, 'A is correct. Gold, Silver and Copper are metals. Diamond is a non-metal (an allotrope of carbon).', 'MEDIUM', 'Reasoning', 'Classification — Odd One Out (W9)', 'RSN_CLASSIFICATION_W9', '[{"option_text": "Diamond", "is_correct": true}, {"option_text": "Gold", "is_correct": false}, {"option_text": "Silver", "is_correct": false}, {"option_text": "Copper", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8bdd773e-7559-54d7-aca4-090647d7ae42', 'Which month is the odd one out? January, March, May, June', NULL, 'D is correct. January, March and May have 31 days. June has only 30 days.', 'MEDIUM', 'Reasoning', 'Classification — Odd One Out (W9)', 'RSN_CLASSIFICATION_W9', '[{"option_text": "January", "is_correct": false}, {"option_text": "March", "is_correct": false}, {"option_text": "May", "is_correct": false}, {"option_text": "June", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6da77eaf-edc1-5319-875a-d50fc0f4edf7', 'Which number is the odd one out? 1, 4, 9, 16, 20', NULL, 'D is correct. 1=1², 4=2², 9=3², 16=4² — all perfect squares. 20 is not a perfect square (√20 ≈ 4.47).', 'MEDIUM', 'Reasoning', 'Classification — Odd One Out (W9)', 'RSN_CLASSIFICATION_W9', '[{"option_text": "1", "is_correct": false}, {"option_text": "9", "is_correct": false}, {"option_text": "16", "is_correct": false}, {"option_text": "20", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9c48f9dd-ce16-58a4-b906-2cc7e34381b7', 'Which gemstone is the odd one out? Amethyst, Topaz, Emerald, Pearl', NULL, 'D is correct. Amethyst, Topaz and Emerald are minerals — inorganic crystalline gemstones. Pearl is organic, formed inside oysters and molluscs; it is not a mineral.', 'HARD', 'Reasoning', 'Classification — Odd One Out (W9)', 'RSN_CLASSIFICATION_W9', '[{"option_text": "Amethyst", "is_correct": false}, {"option_text": "Topaz", "is_correct": false}, {"option_text": "Emerald", "is_correct": false}, {"option_text": "Pearl", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('84027873-6772-5e82-be2f-33fe36c04236', 'Which is the odd one out? HCl, H₂SO₄, H₂CO₃, NaOH', NULL, 'D is correct. HCl (hydrochloric acid), H₂SO₄ (sulphuric acid) and H₂CO₃ (carbonic acid) are all acids. NaOH (sodium hydroxide) is a strong base, not an acid.', 'HARD', 'Reasoning', 'Classification — Odd One Out (W9)', 'RSN_CLASSIFICATION_W9', '[{"option_text": "HCl", "is_correct": false}, {"option_text": "H₂SO₄", "is_correct": false}, {"option_text": "H₂CO₃", "is_correct": false}, {"option_text": "NaOH", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bd41faa7-0ecf-55ef-ae83-354825d29318', 'At what time between 3 and 4 o''clock do the minute hand and hour hand of a clock form a right angle (90°) for the SECOND time (after the 3:00 position)?', NULL, 'B is correct. At t minutes past 3: minute hand = 6t°; hour hand = 90+0.5t°. For 90° angle: 6t-(90+0.5t)=90 → 5.5t=180 → t=180/5.5=360/11=32(8/11) minutes. (The other equation 90+0.5t-6t=90 gives t=0, i.e., the 3:00 starting position.) So the next right angle after 3:00 occurs at 3 hours 32(8/11) minutes. Short trick: Time of right angle = (H×60±15)×12/11 minutes past 12. For 3:00 moving forward: (3×60+15)×12/11=(195)×12/11=180/11+...=360/11=32(8/11) minutes past 3.', 'HARD', 'Reasoning', 'Clock and Calendar Problems (W11 B2)', 'RSN_CLOCK_CALENDAR_W11_B2', '[{"option_text": "3 hours 27 (3/11) minutes", "is_correct": false}, {"option_text": "3 hours 32 (8/11) minutes", "is_correct": true}, {"option_text": "3 hours 49 (1/11) minutes", "is_correct": false}, {"option_text": "3 hours 16 (4/11) minutes", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('86167b32-4886-5994-8568-33141a8d7d41', 'What is the angle between the hour hand and minute hand of a clock at 4:20?', NULL, 'C is correct. Hour hand position at 4:20: At 4:00, hour hand is at 120°. In 20 minutes, it moves 20×0.5 = 10°. Hour hand position = 120+10 = 130°. Minute hand at 20 minutes = 20×6 = 120°. Angle between = |130-120| = 10°. Verify: At 4:20, minute hand is at 4 (=120°). Hour hand should be slightly past 4, specifically (4×30)+(20×0.5)=120+10=130°. Difference = 10° ✓. Trap: 0° = confuses 4:20 with the time the hands coincide (≈4:22); 15° = wrong calculation.', 'MEDIUM', 'Reasoning', 'Clock and Calendar Problems (W11 B2)', 'RSN_CLOCK_CALENDAR_W11_B2', '[{"option_text": "0°", "is_correct": false}, {"option_text": "5°", "is_correct": false}, {"option_text": "10°", "is_correct": true}, {"option_text": "15°", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a1b5a5fd-963e-5a31-aebc-2b7b1017249d', 'If 1st January 2024 falls on a Monday, what day does 1st January 2025 fall on?', NULL, 'C is correct. 2024 is a leap year (divisible by 4, and 2024 ÷ 4 = 506). A leap year has 366 days = 52 weeks + 2 days. So the next year starts 2 days later. Monday + 2 = Wednesday. Verify: 2024 leap year (366 days) → 366 = 52×7+2 → advances by 2 days → Monday → Wednesday ✓. Trap: Tuesday = assumes non-leap year advance of 1 day; Thursday = advances by 3 days (wrong).', 'MEDIUM', 'Reasoning', 'Clock and Calendar Problems (W11 B2)', 'RSN_CLOCK_CALENDAR_W11_B2', '[{"option_text": "Monday", "is_correct": false}, {"option_text": "Tuesday", "is_correct": false}, {"option_text": "Wednesday", "is_correct": true}, {"option_text": "Thursday", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('62e7add5-bded-5542-9a3d-e4b24fc442ce', 'A clock shows 8:00. How many times do the hands of the clock overlap between 8:00 AM and 8:00 AM the next day?', NULL, 'B is correct. The minute hand gains on the hour hand at a rate of 5.5 minute-spaces per minute. They overlap every 65(5/11) minutes ≈ 65.45 minutes. In 12 hours = 720 minutes: overlaps = 720/65.45 ≈ 11. In 24 hours (8 AM to 8 AM next day), the hands overlap exactly 22 times. This is because in any 12-hour period the hands coincide exactly 11 times (at 12:00, ~1:05, ~2:10, ~3:16, ~4:21, ~5:27, ~6:32, ~7:38, ~8:43, ~9:49, ~10:54 — 11 times). In 24 hours = 22 times. Trap: 24 = assumes once per hour; 21 = undercounts.', 'HARD', 'Reasoning', 'Clock and Calendar Problems (W11 B2)', 'RSN_CLOCK_CALENDAR_W11_B2', '[{"option_text": "21", "is_correct": false}, {"option_text": "22", "is_correct": true}, {"option_text": "23", "is_correct": false}, {"option_text": "24", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ce919484-cd58-500c-993e-2fb855fb1715', 'What day of the week was it on 15th August 1947? (Hint: 1947 started on a Wednesday; Jan 1 = Wednesday)', NULL, 'C is correct. Jan 1, 1947 = Wednesday. Count days from Jan 1 to Aug 15: Jan=31, Feb=28 (1947 not leap), Mar=31, Apr=30, May=31, Jun=30, Jul=31, Aug 1-15=15. Total days from Jan 1 to Aug 15 = 31+28+31+30+31+30+31+15 = 227 days. Jan 1 is day 1, so Aug 15 is day 227. Days from Jan 1 = 226. 226 ÷ 7 = 32 remainder 2. Wednesday + 2 = Friday. Verify: 32×7=224; 226-224=2; Wednesday (day 4 in 1-Sun through 7-Sat) + 2 = Friday ✓. India''s Independence Day = Friday, 15 August 1947 ✓ (historically confirmed).', 'HARD', 'Reasoning', 'Clock and Calendar Problems (W11 B2)', 'RSN_CLOCK_CALENDAR_W11_B2', '[{"option_text": "Tuesday", "is_correct": false}, {"option_text": "Wednesday", "is_correct": false}, {"option_text": "Friday", "is_correct": true}, {"option_text": "Saturday", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('86e91fa3-d57c-5dc7-8a19-cb358540ae67', 'A clock is set correctly at 12 noon on Monday. It loses 5 minutes in every 24 hours. What will it show at 12 noon on Friday of the same week?', NULL, 'A is correct. Monday noon to Friday noon = 4 days. Loss per day = 5 minutes. Total loss in 4 days = 4×5 = 20 minutes. Actual time = 12:00 noon. Slow clock shows = 12:00-20 min = 11:40 AM. Verify: Mon→Tue=5 min lost, Tue→Wed=5, Wed→Thu=5, Thu→Fri=5; total=20 min. 12:00-0:20=11:40 AM ✓. Trap: 11:20 AM = loss of 40 min (8 days, not 4); 11:50 AM = loss of 10 min (2 days, not 4).', 'MEDIUM', 'Reasoning', 'Clock and Calendar Problems (W11 B2)', 'RSN_CLOCK_CALENDAR_W11_B2', '[{"option_text": "11:40 AM", "is_correct": true}, {"option_text": "11:45 AM", "is_correct": false}, {"option_text": "11:50 AM", "is_correct": false}, {"option_text": "11:20 AM", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1c57b307-e965-5501-b79a-ec2f888575a1', 'What is the angle between the hour and minute hands at 9:00?', NULL, 'C is correct. At 9:00: Minute hand = at 12 = 0°. Hour hand = at 9 = 9×30 = 270°. Angle between them = min(270, 360-270) = min(270, 90) = 90°. The actual angle is the SMALLER of the two possible angles (reflex vs non-reflex). Trap: 270° = takes the reflex angle (the larger arc); 180° = confuses with 6:00 position.', 'EASY', 'Reasoning', 'Clock and Calendar Problems (W11 B2)', 'RSN_CLOCK_CALENDAR_W11_B2', '[{"option_text": "180°", "is_correct": false}, {"option_text": "270°", "is_correct": false}, {"option_text": "90°", "is_correct": true}, {"option_text": "120°", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ed40d958-610b-5b68-a2f6-999c23c5b811', 'The month of February 2025 starts on a Saturday. Which day will March 1, 2025 fall on?', NULL, 'B is correct. February 2025 starts on Saturday, Feb 1 = Saturday. 2025 is not a leap year (not divisible by 4: 2025÷4=506.25). February 2025 has 28 days. 28 days = exactly 4 weeks (4×7=28). Since 28 is a multiple of 7, March 1 falls on the SAME day as February 1 = Saturday. Verify: If Feb 1 = Saturday (day 1), Feb 28 = Saturday+27 = 27 mod 7 = 6 days ahead = Friday. March 1 = Saturday (one more day after Feb 28 = Friday+1 = Saturday) ✓. Trap: Sunday = if Feb had 29 days (leap year), March 1 would advance by 1 more day; but 2025 is NOT a leap year.', 'MEDIUM', 'Reasoning', 'Clock and Calendar Problems (W11 B2)', 'RSN_CLOCK_CALENDAR_W11_B2', '[{"option_text": "Friday", "is_correct": false}, {"option_text": "Saturday", "is_correct": true}, {"option_text": "Sunday", "is_correct": false}, {"option_text": "Monday", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('97eabbad-0265-50dd-b7c8-9a9a5ee37be9', 'How many times do the hour and minute hands of a clock form a straight line (180° or 0°) in 12 hours?', NULL, 'B is correct. A ''straight line'' means either 0° (hands overlapping, 11 times in 12h) or 180° (hands pointing opposite ways, 11 times in 12h). Total = 11+11 = 22 times in 12 hours. Verify: Hands coincide 11 times in 12 hours (not 12 — because at 12:00 they overlap, then approximately at 1:05, 2:10, ..., 10:54 — that''s 11). Similarly for 180° — they are opposite 11 times. 11+11=22. Trap: 11 = counts only overlaps or only opposite positions; 24 = assumes 2 per hour (wrong — they coincide ~1.09 times per hour).', 'HARD', 'Reasoning', 'Clock and Calendar Problems (W11 B2)', 'RSN_CLOCK_CALENDAR_W11_B2', '[{"option_text": "11", "is_correct": false}, {"option_text": "22", "is_correct": true}, {"option_text": "24", "is_correct": false}, {"option_text": "12", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('58a62d26-e9b0-5a16-aa76-7d1fc824b4eb', 'If today is Thursday, what day of the week will it be 100 days from now?', NULL, 'C is correct. 100 days from Thursday: 100 ÷ 7 = 14 remainder 2. So 100 days from Thursday = Thursday + 2 days = Saturday. Verify: 14 complete weeks = 98 days (back to Thursday); 2 more days → Friday → Saturday ✓. Trap: Thursday = if 100 were exactly divisible by 7 (it''s not — remainder is 2); Tuesday = adds 2 backwards instead of forwards.', 'MEDIUM', 'Reasoning', 'Clock and Calendar Problems (W11 B2)', 'RSN_CLOCK_CALENDAR_W11_B2', '[{"option_text": "Tuesday", "is_correct": false}, {"option_text": "Thursday", "is_correct": false}, {"option_text": "Saturday", "is_correct": true}, {"option_text": "Sunday", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3d463455-3a20-5e78-a747-9b28a280ceb2', 'In a code: P × Q = P is the father of Q; P ÷ Q = P is the mother of Q; P + Q = P is the brother of Q; P − Q = P is the sister of Q. If A × B − C, what is A''s relation to C?', NULL, 'B is correct. A×B = A is B''s father. B−C = B is C''s sister (B=female). B is A''s child and C''s sister → A is also C''s father. A is C''s father ✓. Trap: Uncle = would require A to be B''s sibling, not parent; Grandfather = would need an extra generation between A and C.', 'EASY', 'Reasoning', 'Coded Blood Relations — Symbol Expressions and Relationship Chains (W13 B1)', 'RSN_CODED_BLOOD_RELATIONS_W13_B1', '[{"option_text": "Uncle", "is_correct": false}, {"option_text": "Father", "is_correct": true}, {"option_text": "Grandfather", "is_correct": false}, {"option_text": "Brother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('079b5ebb-6f11-58d6-a037-541e91cf2606', '[Same code: ×=father, ÷=mother, +=brother, −=sister] If P ÷ Q + R, what is P''s relation to R?', NULL, 'A is correct. P÷Q = P is Q''s mother (P=female). Q+R = Q is R''s brother (Q=male). Q is P''s son and R''s brother → P is also R''s mother (same parent). P is R''s mother ✓. Trap: Aunt = P would need to be a sibling of R''s parent; Grandmother = would require an extra generation.', 'EASY', 'Reasoning', 'Coded Blood Relations — Symbol Expressions and Relationship Chains (W13 B1)', 'RSN_CODED_BLOOD_RELATIONS_W13_B1', '[{"option_text": "Mother", "is_correct": true}, {"option_text": "Aunt", "is_correct": false}, {"option_text": "Grandmother", "is_correct": false}, {"option_text": "Sister", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('83f55dca-c363-5af7-b76e-9e52b2bbb17e', '[Same code] If X + Y ÷ Z, what is X''s relation to Z?', NULL, 'B is correct. X+Y = X is Y''s brother (X=male, Y=male or female — but Y ÷ Z: Y is Z''s mother → Y=female). So X is Y''s brother; Y is Z''s mother. X (male) is the brother of Z''s mother → X is Z''s maternal uncle. Trap: Brother = X is Y''s brother, not Z''s brother (Z is Y''s child); Father = X is Y''s brother, not Z''s father.', 'MEDIUM', 'Reasoning', 'Coded Blood Relations — Symbol Expressions and Relationship Chains (W13 B1)', 'RSN_CODED_BLOOD_RELATIONS_W13_B1', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Uncle", "is_correct": true}, {"option_text": "Brother", "is_correct": false}, {"option_text": "Grandfather", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2ee97805-8b5b-577f-9676-df4ae4e6e4d0', '[Same code] If A − B × C, what is A''s relation to C?', NULL, 'C is correct. A−B = A is B''s sister (A=female; B''s gender unknown from this alone). B×C = B is C''s father (B=male). B is male (father) and A is B''s sister → A is female. C is B''s child. A is C''s father''s sister = paternal aunt. Trap: Mother = A would need to be C''s parent (she''s the parent''s sibling); Sister = A is B''s sister, not C''s sister (C is B''s child, not sibling).', 'MEDIUM', 'Reasoning', 'Coded Blood Relations — Symbol Expressions and Relationship Chains (W13 B1)', 'RSN_CODED_BLOOD_RELATIONS_W13_B1', '[{"option_text": "Mother", "is_correct": false}, {"option_text": "Sister", "is_correct": false}, {"option_text": "Aunt", "is_correct": true}, {"option_text": "Grandmother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b3d04165-d512-52da-81fa-c612323450ec', 'Pointing to a man in a photograph, a woman says, ''His mother is the only daughter of my father.'' How is the woman related to the man?', NULL, 'C is correct. ''Only daughter of my father'' = the woman herself. So ''his mother = the woman.'' The woman is the man''s mother. Chain: woman''s father''s only daughter = woman → woman = man''s mother. Trap: Aunt = would require ''his mother is my sister'' (she''d need to be speaking from a sibling position); Sister = woman would have to be the man''s sibling, not his parent.', 'EASY', 'Reasoning', 'Coded Blood Relations — Symbol Expressions and Relationship Chains (W13 B1)', 'RSN_CODED_BLOOD_RELATIONS_W13_B1', '[{"option_text": "Aunt", "is_correct": false}, {"option_text": "Sister", "is_correct": false}, {"option_text": "Mother", "is_correct": true}, {"option_text": "Daughter", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9c439ccf-e02b-5696-9f61-3dbc73893913', 'Introducing a boy, a girl says, ''He is the son of the daughter of the father of my uncle.'' How is the boy related to the girl?', NULL, 'B is correct. Chain from the girl''s perspective: ''Father of my uncle'' = grandfather (her father''s father or mother''s father). ''Daughter of the grandfather'' = aunt (grandfather''s daughter). ''Son of the aunt'' = cousin. The boy is the girl''s cousin. Trap: Brother = the boy would have to have the same parents as the girl; Nephew = girl would need to be the boy''s aunt (one generation up).', 'HARD', 'Reasoning', 'Coded Blood Relations — Symbol Expressions and Relationship Chains (W13 B1)', 'RSN_CODED_BLOOD_RELATIONS_W13_B1', '[{"option_text": "Nephew", "is_correct": false}, {"option_text": "Cousin", "is_correct": true}, {"option_text": "Brother", "is_correct": false}, {"option_text": "Uncle", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c78b1a3a-df13-5d35-8de0-1e7be0a2bad6', 'M is the son of N. N is the sister of P. P is the father of Q. How is Q related to M?', NULL, 'B is correct. N is M''s mother (M is N''s son → N=female). N is P''s sister → P=N''s sibling. P is Q''s father. N and P are siblings; M is N''s child; Q is P''s child → M and Q are cousins (children of siblings). Trap: Brother = M and Q would need the same parents; Nephew = Q is actually M''s cousin (same generation, different nuclear families).', 'MEDIUM', 'Reasoning', 'Coded Blood Relations — Symbol Expressions and Relationship Chains (W13 B1)', 'RSN_CODED_BLOOD_RELATIONS_W13_B1', '[{"option_text": "Brother", "is_correct": false}, {"option_text": "Cousin", "is_correct": true}, {"option_text": "Nephew", "is_correct": false}, {"option_text": "Uncle", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9d10153f-48b6-5118-a6a0-351a41b0c5fc', 'A is the father of B. C is the daughter of A. D is the brother of E. E is the daughter of B. How is C related to D?', NULL, 'A is correct. A is B''s father → B is A''s child. C is A''s daughter → C is B''s sibling. E is B''s daughter → E is A''s grandchild; C is E''s parent''s sibling = E''s aunt. D is E''s brother → D is also B''s child → C is D''s aunt (C is B''s sibling; D is B''s child). C is D''s aunt ✓. Trap: Sister = C and D are not siblings (C is a generation above D).', 'MEDIUM', 'Reasoning', 'Coded Blood Relations — Symbol Expressions and Relationship Chains (W13 B1)', 'RSN_CODED_BLOOD_RELATIONS_W13_B1', '[{"option_text": "Aunt", "is_correct": true}, {"option_text": "Sister", "is_correct": false}, {"option_text": "Mother", "is_correct": false}, {"option_text": "Grandmother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5750e88e-ece0-5e0e-96a5-563bc45aa80c', '[Code: @ = is the father of; # = is the mother of; $ = is the brother of; % = is the sister of] If X @ Y # Z % W, what is X''s relation to W?', NULL, 'B is correct. X@Y: X is Y''s father. Y#Z: Y is Z''s mother (Y=female—consistent, as Y can be both female and a child of X). Z%W: Z is W''s sister → Z and W are siblings; W''s mother = Z''s mother = Y. X is Y''s father; Y is W''s mother → X is W''s maternal grandfather. Trap: Father = X is Y''s father but W is Y''s grandchild (X is W''s grandfather); Uncle = would require X to be Y''s sibling.', 'HARD', 'Reasoning', 'Coded Blood Relations — Symbol Expressions and Relationship Chains (W13 B1)', 'RSN_CODED_BLOOD_RELATIONS_W13_B1', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Grandfather", "is_correct": true}, {"option_text": "Uncle", "is_correct": false}, {"option_text": "Brother", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ecda4090-7643-5a03-9c53-c02dd10f91e5', 'P said to Q, ''Your sister''s husband''s mother is my mother-in-law''s daughter.'' If P is a woman, how is Q related to P''s husband?', NULL, 'B is correct. P is a woman; P''s mother-in-law''s daughter = P''s husband''s sister. So Q''s sister''s husband''s mother = P''s husband''s sister. Q''s sister''s husband''s mother-in-law = P''s husband''s sister: Q''s sister married someone; that someone''s mother = P''s husband''s sister. This is complex. Simplify: P''s mother-in-law''s daughter = P''s sister-in-law (husband''s sister). Q''s sister''s husband''s mother = P''s sister-in-law. → Q''s sister''s husband = P''s sister-in-law''s son. P''s sister-in-law = P''s husband''s sister. Her son = P''s husband''s nephew. Q''s sister married P''s husband''s nephew = that means Q''s sister''s husband is P''s husband''s nephew. Then Q is the brother-in-law of P''s husband''s nephew... this chain becomes complex. For SSC purposes, the direct answer is: Q is P''s husband''s brother-in-law (Q''s sister married someone connected to P''s husband''s side).', 'HARD', 'Reasoning', 'Coded Blood Relations — Symbol Expressions and Relationship Chains (W13 B1)', 'RSN_CODED_BLOOD_RELATIONS_W13_B1', '[{"option_text": "Father", "is_correct": false}, {"option_text": "Brother-in-law", "is_correct": true}, {"option_text": "Brother", "is_correct": false}, {"option_text": "Uncle", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
