INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('49df0d42-5fcc-5913-8917-6bc45af40fa5', 'If APPLE is coded as BQQMF (each letter shifted +1), how is BALL coded?', NULL, 'A is correct. Each letter shifts +1: B→C, A→B, L→M, L→M → CBMM.', 'EASY', 'Reasoning', 'Coding-Decoding — Advanced (W9)', 'RSN_CODING_DECODING_ADV_W9', '[{"option_text": "CBMM", "is_correct": true}, {"option_text": "BCMM", "is_correct": false}, {"option_text": "CAMM", "is_correct": false}, {"option_text": "CBNN", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('38adea0f-2e2f-59fc-8549-256f9a458d26', 'If PENCIL = 72 and PAPER = 60, where the code is (number of letters) × 12, what is the code for PEN?', NULL, 'C is correct. PENCIL has 6 letters → 6×12=72 ✓. PAPER has 5 letters → 5×12=60 ✓. PEN has 3 letters → 3×12=36.', 'EASY', 'Reasoning', 'Coding-Decoding — Advanced (W9)', 'RSN_CODING_DECODING_ADV_W9', '[{"option_text": "28", "is_correct": false}, {"option_text": "32", "is_correct": false}, {"option_text": "36", "is_correct": true}, {"option_text": "48", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('491e1226-a19d-5124-8923-4d7e71d40331', 'If FLOWER is coded as GMPXFS (each letter +1), what word is coded as EBSL?', NULL, 'A is correct. Reverse the +1 shift (subtract 1 from each): E→D, B→A, S→R, L→K → DARK.', 'EASY', 'Reasoning', 'Coding-Decoding — Advanced (W9)', 'RSN_CODING_DECODING_ADV_W9', '[{"option_text": "DARK", "is_correct": true}, {"option_text": "EARL", "is_correct": false}, {"option_text": "CARL", "is_correct": false}, {"option_text": "DARL", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d748f2b6-382f-53ed-b93e-36a9e8400061', 'In a code, if ''go up'' = ''ne ja'' and ''up down'' = ''ja ka'', what does ''go'' mean in that code?', NULL, 'C is correct. ''up'' is common to both sentences and ''ja'' is common to both codes → up = ja. Therefore go = ne.', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Advanced (W9)', 'RSN_CODING_DECODING_ADV_W9', '[{"option_text": "ja", "is_correct": false}, {"option_text": "ka", "is_correct": false}, {"option_text": "ne", "is_correct": true}, {"option_text": "Cannot be determined", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('437e93c4-e4f9-5b80-9ab1-0c71994ad76a', 'If MANGO is written as PCOIQ (each letter +3), what is APPLE written as?', NULL, 'A is correct. Each letter +3: A(1)→D(4), P(16)→S(19), P(16)→S(19), L(12)→O(15), E(5)→H(8) → DSSOH.', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Advanced (W9)', 'RSN_CODING_DECODING_ADV_W9', '[{"option_text": "DSSOH", "is_correct": true}, {"option_text": "DRSOH", "is_correct": false}, {"option_text": "CSSOH", "is_correct": false}, {"option_text": "DSROH", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('474a54ba-5dc5-5c64-8205-891dae36705a', 'If RATE is coded as SBUF (each letter +1), what is the code for GATE?', NULL, 'B is correct. G(7)→H(8), A(1)→B(2), T(20)→U(21), E(5)→F(6) → HBUF. Option A has V instead of U — a common slip.', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Advanced (W9)', 'RSN_CODING_DECODING_ADV_W9', '[{"option_text": "HBVF", "is_correct": false}, {"option_text": "HBUF", "is_correct": true}, {"option_text": "IBUF", "is_correct": false}, {"option_text": "HCUF", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('48f9fa8f-70f3-53b1-a449-8571c208c708', 'In a code language, ''white milk is good'' = ''ka pa re na''; ''good milk is bad'' = ''na re ka da''; ''milk is bad water'' = ''ka re da ma''. What is the code for ''water''?', NULL, 'C is correct. Comparing sentences 2 and 3: common words ''milk, is, bad'' → codes ka, re, da (in some order). Unique to sentence 3 is ''water'' → unique code = ''ma''.', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Advanced (W9)', 'RSN_CODING_DECODING_ADV_W9', '[{"option_text": "ka", "is_correct": false}, {"option_text": "da", "is_correct": false}, {"option_text": "ma", "is_correct": true}, {"option_text": "re", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6452f9cd-0770-5c36-b196-65b1870a2c5c', 'If STABLE is coded as UVCBNG (each letter +2), what is HORSE coded as?', NULL, 'A is correct. Each letter +2: H(8)→J(10), O(15)→Q(17), R(18)→T(20), S(19)→U(21), E(5)→G(7) → JQTUG.', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Advanced (W9)', 'RSN_CODING_DECODING_ADV_W9', '[{"option_text": "JQTUG", "is_correct": true}, {"option_text": "IQTUG", "is_correct": false}, {"option_text": "JRTUG", "is_correct": false}, {"option_text": "JQUGG", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4048b105-bf51-5edb-93c7-516f8ba2f0c9', 'In a code, CAT = 24 (sum of alphabetical positions: C=3, A=1, T=20). What is the code for DOG?', NULL, 'C is correct. D=4, O=15, G=7 → sum = 26. Verify CAT: C=3, A=1, T=20 → 24 ✓.', 'HARD', 'Reasoning', 'Coding-Decoding — Advanced (W9)', 'RSN_CODING_DECODING_ADV_W9', '[{"option_text": "24", "is_correct": false}, {"option_text": "25", "is_correct": false}, {"option_text": "26", "is_correct": true}, {"option_text": "27", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('33292e08-455d-550f-ad03-380eaa6a85bb', 'In a code, BRAIN is coded as CTBJO (each letter +1). If LOGIC is coded using the same scheme, what is the third character of the code?', NULL, 'A is correct. Apply +1 shift: L→M, O→P, G→H, I→J, C→D → code is MPHJD. The third character is H.', 'HARD', 'Reasoning', 'Coding-Decoding — Advanced (W9)', 'RSN_CODING_DECODING_ADV_W9', '[{"option_text": "H", "is_correct": true}, {"option_text": "J", "is_correct": false}, {"option_text": "K", "is_correct": false}, {"option_text": "I", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('23551328-f871-5bea-8841-b8cd9031c5c9', 'In a code language, COLD is written as DPME. What is HEAT written as?', NULL, 'A is correct. Rule: each letter shifted +1. C(3)+1=D(4)✓; O(15)+1=P(16)✓; L(12)+1=M(13)✓; D(4)+1=E(5)✓. Apply to HEAT: H(8)+1=I(9); E(5)+1=F(6); A(1)+1=B(2); T(20)+1=U(21). Code = IFBU. Trap: GDZS = shifts by −1 (backward); IFAT = A is unchanged; IEAT = only first letter shifted.', 'EASY', 'Reasoning', 'Coding-Decoding — Letter Shift, Reversal, Number and Sentence Coding (W12 B1)', 'RSN_CODING_DECODING_III_W12_B1', '[{"option_text": "IFBU", "is_correct": true}, {"option_text": "GDZS", "is_correct": false}, {"option_text": "IFAT", "is_correct": false}, {"option_text": "IEAT", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f0cdb105-662f-5faa-973b-fc8e592b45b7', 'In a code: STAR = UVCT. What is the code for MOON?', NULL, 'A is correct. Rule: each letter shifted +2. S(19)+2=U(21)✓; T(20)+2=V(22)✓; A(1)+2=C(3)✓; R(18)+2=T(20)✓. Apply to MOON: M(13)+2=O(15); O(15)+2=Q(17); O(15)+2=Q(17); N(14)+2=P(16). Code = OQQP. Trap: NLLM = shifts by −1; OQNP = N unchanged (error at position 3); PRRQ = shifts by +3.', 'EASY', 'Reasoning', 'Coding-Decoding — Letter Shift, Reversal, Number and Sentence Coding (W12 B1)', 'RSN_CODING_DECODING_III_W12_B1', '[{"option_text": "OQQP", "is_correct": true}, {"option_text": "NLLM", "is_correct": false}, {"option_text": "OQNP", "is_correct": false}, {"option_text": "PRRQ", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fb0c32c4-34ff-53a5-a916-44f659736900', 'In a certain code, the word CLOCK is written as KCOLC. By the same logic, what is FLAME written as?', NULL, 'B is correct. Rule: reverse the word. CLOCK (C-L-O-C-K) reversed = K-C-O-L-C = KCOLC ✓. Apply to FLAME (F-L-A-M-E) reversed = E-M-A-L-F = EMALF. Trap: EMALP = wrong last letter P instead of F; FMALE = rearranges without strict reversal; AMLEF = anagram, not a reverse.', 'EASY', 'Reasoning', 'Coding-Decoding — Letter Shift, Reversal, Number and Sentence Coding (W12 B1)', 'RSN_CODING_DECODING_III_W12_B1', '[{"option_text": "EMALP", "is_correct": false}, {"option_text": "EMALF", "is_correct": true}, {"option_text": "FMALE", "is_correct": false}, {"option_text": "AMLEF", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ca37b78b-d53a-54d7-8058-854960c8eecb', 'In a code language: CAT = 24 and DOG = 26. By the same rule, what is BIRD = ?', NULL, 'D is correct. Rule: sum of alphabetical position values of all letters. CAT: C=3, A=1, T=20 → 3+1+20=24 ✓. DOG: D=4, O=15, G=7 → 4+15+7=26 ✓. BIRD: B=2, I=9, R=18, D=4 → 2+9+18+4=33. Trap: 30 = common guess (B+I+R+D with I=10, off by one); 32 = B=2+I=10+R=18+D=4-2=32 (wrong I value and wrong operation); 28 = undercount.', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Letter Shift, Reversal, Number and Sentence Coding (W12 B1)', 'RSN_CODING_DECODING_III_W12_B1', '[{"option_text": "28", "is_correct": false}, {"option_text": "30", "is_correct": false}, {"option_text": "32", "is_correct": false}, {"option_text": "33", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bc4a82d0-6a83-51e1-89ec-f7d42f013330', 'If COME is coded as BNLD, how is GRID coded?', NULL, 'A is correct. Rule: each letter shifted −1 (one position backward). C(3)−1=B(2)✓; O(15)−1=N(14)✓; M(13)−1=L(12)✓; E(5)−1=D(4)✓. Apply to GRID: G(7)−1=F(6); R(18)−1=Q(17); I(9)−1=H(8); D(4)−1=C(3). Code = FQHC. Trap: HSJF = shifts forward by +1 (G+1=H, R+1=S, I+1=J, D+1=F); GQHC = G unchanged, rest shifted −1 (inconsistent); FRHD = R and D unchanged.', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Letter Shift, Reversal, Number and Sentence Coding (W12 B1)', 'RSN_CODING_DECODING_III_W12_B1', '[{"option_text": "FQHC", "is_correct": true}, {"option_text": "HSJF", "is_correct": false}, {"option_text": "FRHD", "is_correct": false}, {"option_text": "GQHC", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3788105b-507b-59f0-bc17-31bdf3431aa2', 'In a code language, FINE is written as ILQH. What is CAKE coded as?', NULL, 'A is correct. Rule: each letter shifted +3. F(6)+3=I(9)✓; I(9)+3=L(12)✓; N(14)+3=Q(17)✓; E(5)+3=H(8)✓. Apply to CAKE: C(3)+3=F(6); A(1)+3=D(4); K(11)+3=N(14); E(5)+3=H(8). Code = FDNH. Trap: FDMH = K shifted by only +2 giving M instead of N; ECMG = all letters shifted +2 (one less than the correct +3); GEOI = all letters shifted +4.', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Letter Shift, Reversal, Number and Sentence Coding (W12 B1)', 'RSN_CODING_DECODING_III_W12_B1', '[{"option_text": "FDNH", "is_correct": true}, {"option_text": "FDMH", "is_correct": false}, {"option_text": "ECMG", "is_correct": false}, {"option_text": "GEOI", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('82a830e0-8256-5d86-b980-25497ce4e37a', 'In a code language: CALM = ECON and DARK = FCTM. What is BARK = ?', NULL, 'A is correct. Confirm rule using CALM: C(3)+2=E(5)✓; A(1)+2=C(3)✓; L(12)+2=N(14)✓; M(13)+2=O(15)✓ → ECON ✓. Confirm with DARK: D(4)+2=F(6)✓; A(1)+2=C(3)✓; R(18)+2=T(20)✓; K(11)+2=M(13)✓ → FCTM ✓. Rule: +2 shift. BARK: B(2)+2=D(4); A(1)+2=C(3); R(18)+2=T(20); K(11)+2=M(13). Code = DCTM. Trap: DCTK = K unchanged; DCTN = K shifted by +3 giving N(14); EBNL = B shifted by +3 and inconsistent other shifts.', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Letter Shift, Reversal, Number and Sentence Coding (W12 B1)', 'RSN_CODING_DECODING_III_W12_B1', '[{"option_text": "DCTM", "is_correct": true}, {"option_text": "DCTK", "is_correct": false}, {"option_text": "DCTN", "is_correct": false}, {"option_text": "EBNL", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('332d8c97-ccad-58e1-9db9-b4b447dce1d9', 'In a code: FACE = 6135 and FADE = 6145. What is the code for ACED?', NULL, 'B is correct. From FACE=6135: F=6, A=1, C=3, E=5. From FADE=6145: F=6(✓), A=1(✓), D=4, E=5(✓) — D=4 confirmed. Now ACED: A=1, C=3, E=5, D=4 → 1354. Verify: 1-3-5-4 maps A-C-E-D. All letter-digit pairs are consistent across both source words ✓. Trap: 1345 = swaps D and E values (uses D=5, E=4); 3154 = C and A swapped; 1453 = rearranges digits without following the letter order.', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Letter Shift, Reversal, Number and Sentence Coding (W12 B1)', 'RSN_CODING_DECODING_III_W12_B1', '[{"option_text": "1345", "is_correct": false}, {"option_text": "1354", "is_correct": true}, {"option_text": "3154", "is_correct": false}, {"option_text": "1453", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('604b7bef-54b8-5553-bdeb-517a4e987958', 'In a code: PLACE = 32145 and CAPE = 4135. What is the code for PALE?', NULL, 'B is correct. From PLACE=32145: P=3, L=2, A=1, C=4, E=5. Verify with CAPE=4135: C=4(✓), A=1(✓), P=3(✓), E=5(✓) — all consistent. PALE: P=3, A=1, L=2, E=5 → 3125. Verify: 3(P)−1(A)−2(L)−5(E) = 3125 ✓. Trap: 3152 = L and E swapped (2 and 5 interchanged); 2135 = L and P positions swapped; 3215 = L=2 and A=1 are swapped in the output.', 'HARD', 'Reasoning', 'Coding-Decoding — Letter Shift, Reversal, Number and Sentence Coding (W12 B1)', 'RSN_CODING_DECODING_III_W12_B1', '[{"option_text": "3152", "is_correct": false}, {"option_text": "3125", "is_correct": true}, {"option_text": "2135", "is_correct": false}, {"option_text": "3215", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9bde8fa3-3111-58b2-b2ab-299ba19f3de7', 'In a coded language: ''ka la ma'' = ''sky is blue''; ''na la pa'' = ''flower is red''; ''ka ra ta'' = ''sky looks beautiful''; ''pa la ka'' = ''red is sky''. What does the code word ''na'' stand for?', NULL, 'B is correct. Step 1: Compare S1(''ka la ma''=''sky is blue'') and S2(''na la pa''=''flower is red'') — common code ''la'', common word ''is'' → la = ''is''. Step 2: Compare S1 and S3(''ka ra ta''=''sky looks beautiful'') — common code ''ka'', common word ''sky'' → ka = ''sky''. Step 3: In S4(''pa la ka''=''red is sky''): la=''is'' and ka=''sky'', so pa = ''red''. Step 4: In S2(''na la pa''=''flower is red''): la=''is'' and pa=''red'', so na = ''flower''. Trap: ''sky''=ka; ''red''=pa; ''beautiful'' is either ra or ta (indeterminate from given data).', 'HARD', 'Reasoning', 'Coding-Decoding — Letter Shift, Reversal, Number and Sentence Coding (W12 B1)', 'RSN_CODING_DECODING_III_W12_B1', '[{"option_text": "sky", "is_correct": false}, {"option_text": "flower", "is_correct": true}, {"option_text": "beautiful", "is_correct": false}, {"option_text": "red", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('88b8a660-68ae-57be-98dc-9b5ee470d4ee', 'In a code language, MASTER is coded as OCUVGT. What will FASTER be coded as?', NULL, 'A is correct. Rule: each letter shifts +2. M→O, A→C, S→U, T→V, E→G, R→T. MASTER→OCUVGT ✓. FASTER: F(6)→H(8), A→C, S→U, T→V, E→G, R→T = HCUVGT. Trap: ICUVGT shifts F by +3; HCUWGT shifts R by +4; HBUVGT shifts A by +1 only.', 'EASY', 'Reasoning', 'Coding-Decoding — Set II: Letter Shift, Reverse, Number Code (W11 B1)', 'RSN_CODING_DECODING_II_W11_B1', '[{"option_text": "HCUVGT", "is_correct": true}, {"option_text": "ICUVGT", "is_correct": false}, {"option_text": "HBUVGT", "is_correct": false}, {"option_text": "HCUWGT", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e709161a-e39f-5e26-a4b5-7604951bec64', 'In a code language, CAT is coded as ZXG. What is the rule, and what will DOG be coded as?', NULL, 'A is correct. Rule: each letter is replaced by its mirror-opposite (position + mirror-position = 27). C(3)↔X(24), A(1)↔Z(26), T(20)↔G(7). CAT→ZXG ✓. DOG: D(4)↔W(23), O(15)↔L(12), G(7)↔T(20) = WLT. Trap: WLU uses T(20)→U(21) instead of G; VLT uses D(4)→V(22) instead of W.', 'EASY', 'Reasoning', 'Coding-Decoding — Set II: Letter Shift, Reverse, Number Code (W11 B1)', 'RSN_CODING_DECODING_II_W11_B1', '[{"option_text": "WLT", "is_correct": true}, {"option_text": "WLU", "is_correct": false}, {"option_text": "VLT", "is_correct": false}, {"option_text": "WMT", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('751bc566-7ac3-596a-aadd-80cec0e9f18d', 'In a code, each word is assigned a value equal to the sum of the alphabetical positions of its letters (A=1, B=2, ..., Z=26). RING = 48. Using the same rule, what is the code for SING?', NULL, 'D is correct. RING: R=18+I=9+N=14+G=7=48 ✓. SING: S=19+I=9+N=14+G=7=49. SING differs from RING only in S(19) vs R(18), so SING = RING+1 = 49. Trap: 48 = confuses S with R; 47 = RING−1; 45 = random wrong sum.', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Set II: Letter Shift, Reverse, Number Code (W11 B1)', 'RSN_CODING_DECODING_II_W11_B1', '[{"option_text": "45", "is_correct": false}, {"option_text": "47", "is_correct": false}, {"option_text": "48", "is_correct": false}, {"option_text": "49", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('807e63c4-d1ea-50f3-8267-3049a2d6e6d9', 'In a code language: FIRE = 6935, ROSE = 3085. What is the code for FORE?', NULL, 'A is correct. From FIRE=6935: F=6, I=9, R=3, E=5. From ROSE=3085: R=3, O=0, S=8, E=5. Consistent (R=3, E=5 in both). FORE = F(6)+O(0)+R(3)+E(5) = 6035. Trap: 6350 = wrong order FROE; 6305 = wrong digit for O; 3065 = starts with R''s code, wrong order.', 'EASY', 'Reasoning', 'Coding-Decoding — Set II: Letter Shift, Reverse, Number Code (W11 B1)', 'RSN_CODING_DECODING_II_W11_B1', '[{"option_text": "6035", "is_correct": true}, {"option_text": "6350", "is_correct": false}, {"option_text": "6305", "is_correct": false}, {"option_text": "3065", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a5317168-9ece-5982-a224-ddfa0db267cb', 'In a code: BIRD = DKTF. What is the rule, and what will FISH be coded as?', NULL, 'A is correct. B(2)→D(4): +2, I(9)→K(11): +2, R(18)→T(20): +2, D(4)→F(6): +2. Rule: each letter +2. FISH: F(6)→H(8), I(9)→K(11), S(19)→U(21), H(8)→J(10) = HKUJ. Trap: GKUJ shifts F by +1; HKVJ shifts S by +3; HJUK reorders the letters.', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Set II: Letter Shift, Reverse, Number Code (W11 B1)', 'RSN_CODING_DECODING_II_W11_B1', '[{"option_text": "HKUJ", "is_correct": true}, {"option_text": "GKUJ", "is_correct": false}, {"option_text": "HKVJ", "is_correct": false}, {"option_text": "HJUK", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('170bbdb2-be21-5ac4-ac41-7f8a92763091', 'In a code: ''go to school'' = ''5 2 9'' and ''come back home'' = ''3 7 4'' and ''home is good'' = ''4 6 8''. What is the code for ''school is home''?', NULL, 'A is correct. From ''home is good''=4 6 8 and ''come back home''=3 7 4: home=4 (common). ''home is good''=4 6 8; home=4, so ''is''=6 and ''good''=8. From ''go to school''=5 2 9: by elimination with other sentences, ''school''=9. So ''school is home'' = 9 6 4. Trap: 9 4 3 uses 3 (code for ''come'', not ''is''); 5 6 4 uses 5 (code for ''go'') instead of 9 for ''school''; 9 4 6 reverses ''is'' and ''home''.', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Set II: Letter Shift, Reverse, Number Code (W11 B1)', 'RSN_CODING_DECODING_II_W11_B1', '[{"option_text": "9 6 4", "is_correct": true}, {"option_text": "9 4 3", "is_correct": false}, {"option_text": "5 6 4", "is_correct": false}, {"option_text": "9 4 6", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8f9ad93f-b28c-5d09-a9a2-06180b4a6a45', 'In a code language, PENCIL is written as LICNEP. Using the same rule, how is GARDEN written?', NULL, 'A is correct. PENCIL → LICNEP: the word is reversed. P-E-N-C-I-L → L-I-C-N-E-P ✓. GARDEN: G-A-R-D-E-N reversed = N-E-D-R-A-G = NEDRAG. Trap: NERDGA, REDGAN, NERGAD are all incorrect scrambles that are not simple reversals of GARDEN.', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Set II: Letter Shift, Reverse, Number Code (W11 B1)', 'RSN_CODING_DECODING_II_W11_B1', '[{"option_text": "NEDRAG", "is_correct": true}, {"option_text": "NERDGA", "is_correct": false}, {"option_text": "REDGAN", "is_correct": false}, {"option_text": "NERGAD", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c8c73891-d81d-5150-8173-ddc80b77f312', 'In a code language, TABLE is written as ELBAT. Using the same rule, how is CHAIR written in the code?', NULL, 'A is correct. TABLE→ELBAT: the word is reversed. T-A-B-L-E → E-L-B-A-T ✓. CHAIR: C-H-A-I-R reversed = R-I-A-H-C = RIAHC. Trap: RAHIC rearranges letters; HCAIR starts with H (wrong starting letter of reversed CHAIR); RCIAH is another wrong scramble.', 'HARD', 'Reasoning', 'Coding-Decoding — Set II: Letter Shift, Reverse, Number Code (W11 B1)', 'RSN_CODING_DECODING_II_W11_B1', '[{"option_text": "RIAHC", "is_correct": true}, {"option_text": "RAHIC", "is_correct": false}, {"option_text": "RCIAH", "is_correct": false}, {"option_text": "HCAIR", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b7c7d8be-0a1c-54c7-a6e3-2b02c57769f3', 'In a code language, words are assigned values by summing the alphabetical positions of all letters (A=1, B=2, ..., Z=26). STAMP = 69. Which of the following words has the code value 48?', NULL, 'D is correct. Verify STAMP: S=19+T=20+A=1+M=13+P=16=69 ✓. Check each option: MINE=M(13)+I(9)+N(14)+E(5)=41. KING=K(11)+I(9)+N(14)+G(7)=41. SING=S(19)+I(9)+N(14)+G(7)=49. RING=R(18)+I(9)+N(14)+G(7)=48 ✓. Answer = RING. Trap: SING=49 (closest, off by 1 because S=19 vs R=18); MINE and KING both=41.', 'HARD', 'Reasoning', 'Coding-Decoding — Set II: Letter Shift, Reverse, Number Code (W11 B1)', 'RSN_CODING_DECODING_II_W11_B1', '[{"option_text": "MINE", "is_correct": false}, {"option_text": "KING", "is_correct": false}, {"option_text": "SING", "is_correct": false}, {"option_text": "RING", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('86065c0a-9af9-5367-994d-6f8a34981a4a', 'In a code: P=1, Q=2, R=3, S=4. A four-letter word''s code value is the sum of all its letters'' codes. Which word has a code value of 10?', NULL, 'B is correct. P=1, Q=2, R=3, S=4. Calculate each: PPQS = 1+1+2+4 = 8. QRPS = 2+3+1+4 = 10 ✓. SRPP = 4+3+1+1 = 9. RQPR = 3+2+1+3 = 9. Only QRPS sums to 10. Trap: SRPP and RQPR both give 9 (close, but not 10); PPQS=8 (furthest away).', 'HARD', 'Reasoning', 'Coding-Decoding — Set II: Letter Shift, Reverse, Number Code (W11 B1)', 'RSN_CODING_DECODING_II_W11_B1', '[{"option_text": "PPQS", "is_correct": false}, {"option_text": "QRPS", "is_correct": true}, {"option_text": "SRPP", "is_correct": false}, {"option_text": "RQPR", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('49ca8f10-352b-5c13-b685-7e83d5652f6d', 'In a code language, EASY is written as 5-1-19-25. Using the same code (each letter = its position in the alphabet), what will HARD be written as?', NULL, 'B is correct. Rule: each letter → its alphabetical position. E=5, A=1, S=19, Y=25 ✓. H=8, A=1, R=18, D=4 → 8-1-18-4. Trap: option A uses H=7 (off by 1); option D shifts every value up by 1.', 'EASY', 'Reasoning', 'Coding-Decoding — Letter Shift, Position and Number Codes (W10)', 'RSN_CODING_DECODING_W10', '[{"option_text": "7-1-18-3", "is_correct": false}, {"option_text": "8-1-18-4", "is_correct": true}, {"option_text": "8-2-19-4", "is_correct": false}, {"option_text": "9-1-18-5", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('53c36c46-00fe-539c-a9d6-0ba730c60bfb', 'In a code, CAT = 3-1-20. What will DOG be written as?', NULL, 'C is correct. Rule: each letter → its alphabetical position. C=3, A=1, T=20 ✓. D=4, O=15, G=7 → 4-15-7. Trap: option B uses O=14 (confusing O with N); option D adds 1 to each value.', 'EASY', 'Reasoning', 'Coding-Decoding — Letter Shift, Position and Number Codes (W10)', 'RSN_CODING_DECODING_W10', '[{"option_text": "3-15-7", "is_correct": false}, {"option_text": "4-14-7", "is_correct": false}, {"option_text": "4-15-7", "is_correct": true}, {"option_text": "5-15-8", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('366004f6-551c-5234-b205-4b46cca5fbf4', 'If SPRING is coded as TQSJOH (each letter shifted +1 ahead in the alphabet), how will WINTER be coded?', NULL, 'A is correct. Verify: S→T, P→Q, R→S, I→J, N→O, G→H = TQSJOH ✓. Apply +1 to WINTER: W→X, I→J, N→O, T→U, E→F, R→S → XJOUFS. Trap: XIOVFS shifts I and N incorrectly; WJOUFS keeps W unchanged; XJOUFR shifts R to R (no shift on last letter).', 'EASY', 'Reasoning', 'Coding-Decoding — Letter Shift, Position and Number Codes (W10)', 'RSN_CODING_DECODING_W10', '[{"option_text": "XJOUFS", "is_correct": true}, {"option_text": "XIOVFS", "is_correct": false}, {"option_text": "WJOUFS", "is_correct": false}, {"option_text": "XJOUFR", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('33f1826d-8e2f-5373-b7bb-945113510527', 'In a code, CHAIR = 3-8-1-9-18 and BRAIN = 2-18-1-9-14. What word does the code 19-20-1-18 represent?', NULL, 'A is correct. Rule: each number = alphabetical position of that letter. S=19, T=20, A=1, R=18 → STAR. Trap: STOP would require S=19, T=20, O=15, P=16 (doesn''t match 19-20-1-18 since 1≠15); STIR requires I=9 not 1.', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Letter Shift, Position and Number Codes (W10)', 'RSN_CODING_DECODING_W10', '[{"option_text": "STAR", "is_correct": true}, {"option_text": "STOP", "is_correct": false}, {"option_text": "STIR", "is_correct": false}, {"option_text": "STAY", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('55675ab9-1d5c-5171-a143-0f660766635b', 'Each letter is coded by the letter that is 3 positions after it (A→D, B→E, …, X→A, Y→B, Z→C). What is the code for QUIZ?', NULL, 'B is correct. Q(17)+3=T(20), U(21)+3=X(24), I(9)+3=L(12), Z(26)+3=C(3) [wraps: 26→27→28→29 → position 3=C] → TXLC. Trap: TXLB uses Z→B (only +2); SXLC shifts Q to S (+2); TYMC shifts U to Y (+4).', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Letter Shift, Position and Number Codes (W10)', 'RSN_CODING_DECODING_W10', '[{"option_text": "TXLB", "is_correct": false}, {"option_text": "TXLC", "is_correct": true}, {"option_text": "SXLC", "is_correct": false}, {"option_text": "TYMC", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d83d076c-bae4-5388-8441-30a1d443e8cd', 'In a code, each letter is replaced by its complementary alphabet (A↔Z, B↔Y, C↔X, and so on, so that position + complement = 27). What is the code for LION?', NULL, 'A is correct. Complementary coding: position + code-position = 27. L(12)→O(15), I(9)→R(18), O(15)→L(12), N(14)→M(13) → ORLM. Trap: ORLN substitutes N→N (no change, 14+14≠27); OIPM leaves I unchanged; ORML swaps M and L at the end.', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Letter Shift, Position and Number Codes (W10)', 'RSN_CODING_DECODING_W10', '[{"option_text": "ORLM", "is_correct": true}, {"option_text": "ORLN", "is_correct": false}, {"option_text": "OIPM", "is_correct": false}, {"option_text": "ORML", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('530b22ab-7b86-5af2-af70-7b909417565f', 'If SUNDAY is coded as VXQGDB (each letter +3 in the alphabet), what is the code for MONDAY?', NULL, 'A is correct. Verify SUNDAY+3: S→V, U→X, N→Q, D→G, A→D, Y→B = VXQGDB ✓. Apply to MONDAY: M→P, O→R, N→Q, D→G, A→D, Y→B = PRQGDB. Trap: QSRHEC shifts by +4; PQQGDB changes O→Q (skipping +3 for one letter).', 'MEDIUM', 'Reasoning', 'Coding-Decoding — Letter Shift, Position and Number Codes (W10)', 'RSN_CODING_DECODING_W10', '[{"option_text": "PRQGDB", "is_correct": true}, {"option_text": "QSRHEC", "is_correct": false}, {"option_text": "PQQGDB", "is_correct": false}, {"option_text": "NSQGDB", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('25827fd6-d41d-557c-a186-dfbbc93985aa', 'In a code, FACE = 6+1+3+5 = 15 (sum of alphabetical position values). What is the code for GOLD?', NULL, 'C is correct. Rule: sum of alphabetical position values. Verify FACE: F=6, A=1, C=3, E=5 → 6+1+3+5=15 ✓. GOLD: G=7, O=15, L=12, D=4 → 7+15+12+4=38. Trap: 32 uses G=5 (incorrect position); 35 drops one letter; 41 adds an extra 3.', 'HARD', 'Reasoning', 'Coding-Decoding — Letter Shift, Position and Number Codes (W10)', 'RSN_CODING_DECODING_W10', '[{"option_text": "32", "is_correct": false}, {"option_text": "35", "is_correct": false}, {"option_text": "38", "is_correct": true}, {"option_text": "41", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e30702bf-8e8b-57e5-aed5-6b1372bde446', 'In a code: ROSE = 18+15+19+5 = 57. What is the code for BLUE?', NULL, 'B is correct. Rule: sum of alphabetical positions. Verify ROSE: R=18, O=15, S=19, E=5 → 57 ✓. BLUE: B=2, L=12, U=21, E=5 → 2+12+21+5=40. Trap: 43 adds 3 extra (confuses U=24 with X=24 or applies a shift); 37 uses U=18 (confusing U with R).', 'HARD', 'Reasoning', 'Coding-Decoding — Letter Shift, Position and Number Codes (W10)', 'RSN_CODING_DECODING_W10', '[{"option_text": "37", "is_correct": false}, {"option_text": "40", "is_correct": true}, {"option_text": "43", "is_correct": false}, {"option_text": "45", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3458ef5d-53d0-58c2-bf78-3db0dc11ce48', 'In a code, each odd-positioned letter in a word (1st, 3rd, 5th…) is shifted by +2 and each even-positioned letter (2nd, 4th…) is shifted by −2. What is the code for PLAIN?', NULL, 'A is correct. Apply rule to PLAIN: P(1st, odd)+2=R; L(2nd, even)−2=J; A(3rd, odd)+2=C; I(4th, even)=9−2=G(7); N(5th, odd)+2=P → RJCGP. Trap B: RJCJP applies +2 (not −2) to I, giving J(10) instead of G(7). Trap C: RKCGP applies −2 to L correctly but uses +3 on P giving R+1=S? No — K=L−2+1 error. Trap D: RJCGQ shifts N by +3 instead of +2.', 'HARD', 'Reasoning', 'Coding-Decoding — Letter Shift, Position and Number Codes (W10)', 'RSN_CODING_DECODING_W10', '[{"option_text": "RJCGP", "is_correct": true}, {"option_text": "RJCJP", "is_correct": false}, {"option_text": "RKCGP", "is_correct": false}, {"option_text": "RJCGQ", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('87121437-0a3e-515e-9c91-d2205394c238', 'On a standard die where opposite faces sum to 7, which number is opposite to 4?', NULL, 'C is correct. On a standard die, opposite face pairs each sum to 7: 1↔6, 2↔5, 3↔4. Opposite of 4 = 7−4 = 3. Visualise: if 4 is on top, 3 is at bottom. Trap: 5 = opposite of 2 (not 4); 1 = opposite of 6 (not 4); 2 = opposite of 5 (not 4). Memory: 3-4, 2-5, 1-6 (smallest-largest pairs; or just remember sum=7).', 'EASY', 'Reasoning', 'Cubes and Dice — Face Counting, Painting Problems and Dice Logic (W12 B1)', 'RSN_CUBES_DICE_W12_B1', '[{"option_text": "1", "is_correct": false}, {"option_text": "2", "is_correct": false}, {"option_text": "3", "is_correct": true}, {"option_text": "5", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('aac88202-90f6-5790-86af-ec9b60a09549', 'A 3×3×3 cube is painted red on all faces, then cut into 27 unit cubes. How many unit cubes have NO face painted?', NULL, 'B is correct. Only the centre cube (completely surrounded by other cubes) has no face touching any painted surface. Formula: for n×n×n cube: 0-face painted = (n−2)³ = (3−2)³ = 1. Verify: the 3×3×3 cube has exactly 1 interior cube (the very centre). Trap: 6 = face-centre cubes (1 face painted); 8 = corner cubes (3 faces painted); 0 = wrong — the centre cube does exist.', 'EASY', 'Reasoning', 'Cubes and Dice — Face Counting, Painting Problems and Dice Logic (W12 B1)', 'RSN_CUBES_DICE_W12_B1', '[{"option_text": "0", "is_correct": false}, {"option_text": "1", "is_correct": true}, {"option_text": "6", "is_correct": false}, {"option_text": "8", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c5523c68-e060-54fa-afc3-e4f837744255', 'A 3×3×3 cube is painted on all faces and cut into 27 unit cubes. How many unit cubes have exactly 3 faces painted?', NULL, 'C is correct. Unit cubes with 3 faces painted are the CORNER cubes — each cube occupies a corner of the large cube where 3 faces meet. A cube has exactly 8 corners. Formula: 3-face painted = 8 (always 8 for any n×n×n cube, n≥2). Trap: 12 = edge cubes (2 faces painted); 6 = face-centre cubes (1 face painted); 4 = half the corners (wrong).', 'EASY', 'Reasoning', 'Cubes and Dice — Face Counting, Painting Problems and Dice Logic (W12 B1)', 'RSN_CUBES_DICE_W12_B1', '[{"option_text": "4", "is_correct": false}, {"option_text": "6", "is_correct": false}, {"option_text": "8", "is_correct": true}, {"option_text": "12", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6a9cdf60-0953-5700-aa76-1ae538681976', 'In a special dice, the opposite face pairs are: 1 opposite 5, 2 opposite 6, 3 opposite 4. If face 2 is on top, what face is at the bottom?', NULL, 'D is correct. Given pairs: 1↔5, 2↔6, 3↔4. If 2 is on top, its opposite face (6) is at the bottom. Trap: students may use standard die rule (top+bottom=7 → 2+5=7) but this is a NON-STANDARD die with pair 2↔6. Always read the given pairing — don''t assume standard configuration unless stated.', 'MEDIUM', 'Reasoning', 'Cubes and Dice — Face Counting, Painting Problems and Dice Logic (W12 B1)', 'RSN_CUBES_DICE_W12_B1', '[{"option_text": "3", "is_correct": false}, {"option_text": "4", "is_correct": false}, {"option_text": "5", "is_correct": false}, {"option_text": "6", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3bc946b8-7eb6-54e2-ad67-c434dc730978', 'A 4×4×4 cube is painted on all faces and cut into 64 unit cubes. How many unit cubes have exactly 2 faces painted?', NULL, 'C is correct. Formula for 2-face painted unit cubes = 12×(n−2) where n is the side length. For n=4: 12×(4−2) = 12×2 = 24. These are the edge cubes (not corners). A cube has 12 edges; each edge of 4×4×4 cube has 4−2=2 non-corner unit cubes = 12×2=24 ✓. Verify cube: 8(3-face)+24(2-face)+6×(2²)(1-face)+(2)³(0-face)=8+24+24+8=64 ✓. Trap: 8 = only corner cubes; 16 = 12×(4-3) (wrong formula).', 'MEDIUM', 'Reasoning', 'Cubes and Dice — Face Counting, Painting Problems and Dice Logic (W12 B1)', 'RSN_CUBES_DICE_W12_B1', '[{"option_text": "8", "is_correct": false}, {"option_text": "16", "is_correct": false}, {"option_text": "24", "is_correct": true}, {"option_text": "32", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7653e0a1-7a13-5dff-aed6-49713d5d11ef', 'A 3×3×3 cube is painted on all faces and cut into 27 unit cubes. How many unit cubes have exactly 2 faces painted?', NULL, 'C is correct. Formula: 2-face painted = 12×(n−2) = 12×(3−2) = 12×1 = 12. These are the edge-middle cubes (not corners). A cube has 12 edges; each edge of 3×3×3 has 3−2=1 non-corner unit cube = 12×1=12. Verify: 8(3-face)+12(2-face)+6(1-face)+1(0-face)=27 ✓. Trap: 6 = face-centre cubes (1 face); 8 = corners (3 faces); 18 = 12+6 (mixing 1-face and 2-face counts).', 'MEDIUM', 'Reasoning', 'Cubes and Dice — Face Counting, Painting Problems and Dice Logic (W12 B1)', 'RSN_CUBES_DICE_W12_B1', '[{"option_text": "6", "is_correct": false}, {"option_text": "8", "is_correct": false}, {"option_text": "12", "is_correct": true}, {"option_text": "18", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1955ee09-4bb7-5602-b9b5-43c88cad3af1', 'On a standard die, if face 3 is at the bottom, which face is on top?', NULL, 'C is correct. On a standard die: opposite pairs sum to 7. 3+4=7, so 3 is opposite to 4. If 3 is at bottom, 4 is at top. Trap: 6 = opposite of 1 (not 3); 1 = opposite of 6 (not 3); 3 = a face cannot be opposite to itself.', 'MEDIUM', 'Reasoning', 'Cubes and Dice — Face Counting, Painting Problems and Dice Logic (W12 B1)', 'RSN_CUBES_DICE_W12_B1', '[{"option_text": "1", "is_correct": false}, {"option_text": "3", "is_correct": false}, {"option_text": "4", "is_correct": true}, {"option_text": "6", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f33bd897-9cfc-5ca6-871c-3143306bfe1a', 'A 3×3×3 cube has all 6 faces painted. It is cut into 27 unit cubes. How many unit cubes have AT LEAST one face painted?', NULL, 'C is correct. Total unit cubes = 27. Unit cubes with NO face painted = 1 (the centre cube). Unit cubes with at least one face painted = 27−1 = 26. Alternatively: 8(3-face)+12(2-face)+6(1-face) = 8+12+6 = 26. Trap: 27 = counts even the interior cube (wrong — it has no painted face); 24 = 8+12+4 (miscounts the 1-face cubes).', 'MEDIUM', 'Reasoning', 'Cubes and Dice — Face Counting, Painting Problems and Dice Logic (W12 B1)', 'RSN_CUBES_DICE_W12_B1', '[{"option_text": "24", "is_correct": false}, {"option_text": "25", "is_correct": false}, {"option_text": "26", "is_correct": true}, {"option_text": "27", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('faf8a174-0834-5613-b0ec-9ba8419382ef', 'A 4×4×4 cube painted on all faces is cut into 64 unit cubes. How many unit cubes have exactly 1 face painted?', NULL, 'B is correct. Formula: 1-face painted = 6×(n−2)² = 6×(4−2)² = 6×4 = 24. These are the face-centre cubes (not on any edge or corner). Each face of 4×4×4 has (4−2)²=4 interior unit cubes = 6 faces × 4 = 24 ✓. Verify: 8(3-face)+24(2-face)+24(1-face)+(4−2)³×1(0-face) = 8+24+24+8=64 ✓. Trap: 16 = (4−2)⁴=16 (wrong formula with wrong exponent); 48 = overcounts.', 'HARD', 'Reasoning', 'Cubes and Dice — Face Counting, Painting Problems and Dice Logic (W12 B1)', 'RSN_CUBES_DICE_W12_B1', '[{"option_text": "16", "is_correct": false}, {"option_text": "24", "is_correct": true}, {"option_text": "32", "is_correct": false}, {"option_text": "48", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4867b9d8-f29d-5b94-ac5a-bb0c30778bb4', 'Two standard dice are thrown simultaneously. What is the probability that the sum of the two faces is 7?', NULL, 'B is correct. Total outcomes = 6×6 = 36. Outcomes giving sum=7: (1,6),(2,5),(3,4),(4,3),(5,2),(6,1) = 6 outcomes. Probability = 6/36 = 1/6. Note: 7 is the most likely sum when two dice are rolled (more ways to make 7 than any other sum). Verify: sums from 2–12; sum=7 has 6 combinations out of 36 = 1/6 ✓. Trap: 7/36 = confuses 7 (sum) with favourable outcomes (there ARE 6, not 7, ways to get sum=7); 1/9 = 4/36 = probability of sum=5 or sum=9.', 'HARD', 'Reasoning', 'Cubes and Dice — Face Counting, Painting Problems and Dice Logic (W12 B1)', 'RSN_CUBES_DICE_W12_B1', '[{"option_text": "1/9", "is_correct": false}, {"option_text": "1/6", "is_correct": true}, {"option_text": "7/36", "is_correct": false}, {"option_text": "1/4", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
