INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3fbc1626-d707-5db3-8b49-8076aba00fe4', 'In a class of 50 students, 30 study Science and 25 study Arts. 10 students study both. How many study only Science?', NULL, 'B is correct. Only Science = Total Science − Both = 30−10 = 20. Students who study only Arts = 25−10 = 15. Trap: 25 = only Arts (wrong label); 30 includes those who study both subjects.', 'EASY', 'Reasoning', 'Venn Diagrams — Set Operations and Cardinality (W10 B2)', 'RSN_VENN_DIAGRAMS_W10_B2', '[{"option_text": "15", "is_correct": false}, {"option_text": "20", "is_correct": true}, {"option_text": "25", "is_correct": false}, {"option_text": "30", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('39295f73-762e-537f-b9c7-2c4cf16830a7', 'In a survey of 100 people, 60 like Product A and 50 like Product B. 25 like both. How many like A or B (or both)?', NULL, 'C is correct. |A∪B| = |A|+|B|−|A∩B| = 60+50−25 = 85 (Inclusion-Exclusion Principle). Trap: 110 = 60+50 (double-counts the 25 who like both); 75 = 60+50−35 (wrong intersection value).', 'EASY', 'Reasoning', 'Venn Diagrams — Set Operations and Cardinality (W10 B2)', 'RSN_VENN_DIAGRAMS_W10_B2', '[{"option_text": "75", "is_correct": false}, {"option_text": "80", "is_correct": false}, {"option_text": "85", "is_correct": true}, {"option_text": "110", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3dfe7ef7-a193-5da1-98f8-e86399774efd', 'In a group of 80 people, 55 like Cricket, 45 like Football, and 30 like both. How many like neither sport?', NULL, 'C is correct. |C∪F| = 55+45−30 = 70. Neither = 80−70 = 10. Trap: 5 = 80−(55+45−25) using wrong ''both'' value; 15 = 80−65 (uses |C∪F|=65 from 55+45−35).', 'MEDIUM', 'Reasoning', 'Venn Diagrams — Set Operations and Cardinality (W10 B2)', 'RSN_VENN_DIAGRAMS_W10_B2', '[{"option_text": "5", "is_correct": false}, {"option_text": "8", "is_correct": false}, {"option_text": "10", "is_correct": true}, {"option_text": "15", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('91cd3bec-a7fd-5459-95e6-2a15279147f1', 'In a class, 35 students play Cricket, 30 play Football, and 20 play both. Exactly how many play only ONE sport?', NULL, 'B is correct. Only Cricket = 35−20 = 15. Only Football = 30−20 = 10. Exactly one sport = 15+10 = 25. Trap: 45 = total who play at least one sport (35+30−20); 20 confuses ''exactly two'' (both) with ''exactly one''.', 'MEDIUM', 'Reasoning', 'Venn Diagrams — Set Operations and Cardinality (W10 B2)', 'RSN_VENN_DIAGRAMS_W10_B2', '[{"option_text": "20", "is_correct": false}, {"option_text": "25", "is_correct": true}, {"option_text": "30", "is_correct": false}, {"option_text": "45", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('def5d889-23e1-5a17-829f-c86a7822209e', 'Sets A, B, C have |A|=20, |B|=28, |C|=25, |A∩B|=8, |B∩C|=10, |A∩C|=6, |A∩B∩C|=3. Find |A∪B∪C|.', NULL, 'C is correct. |A∪B∪C| = |A|+|B|+|C|−|A∩B|−|B∩C|−|A∩C|+|A∩B∩C| = 20+28+25−8−10−6+3 = 73−24+3 = 52. This is the three-set Inclusion-Exclusion formula — a key Tier 2 topic. Trap: 55 omits the +|A∩B∩C| correction; 49 uses the wrong sign for the triple intersection.', 'MEDIUM', 'Reasoning', 'Venn Diagrams — Set Operations and Cardinality (W10 B2)', 'RSN_VENN_DIAGRAMS_W10_B2', '[{"option_text": "46", "is_correct": false}, {"option_text": "49", "is_correct": false}, {"option_text": "52", "is_correct": true}, {"option_text": "55", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f0af3650-7640-5186-8746-7b5757a2a3e3', 'In a survey of 250 people, 155 read Newspaper A, 130 read Newspaper B, and 45 read both. How many read neither newspaper?', NULL, 'C is correct. |A∪B| = 155+130−45 = 240. Neither = 250−240 = 10. Trap: 5 = 250−(155+90) (wrong B calculation); 15 = 250−235 (uses both=45 but adds wrong total).', 'MEDIUM', 'Reasoning', 'Venn Diagrams — Set Operations and Cardinality (W10 B2)', 'RSN_VENN_DIAGRAMS_W10_B2', '[{"option_text": "5", "is_correct": false}, {"option_text": "8", "is_correct": false}, {"option_text": "10", "is_correct": true}, {"option_text": "15", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('113f3ad8-ff95-5705-ba96-fdeaf1c87376', '100 people are surveyed. 60 like Math, 55 like Science, 45 like English. 10 like all three. 15 like Math & Science only (not English), 12 like Science & English only (not Math), 8 like Math & English only (not Science). How many like ONLY Math?', NULL, 'C is correct. ''Only Math'' = |Math| − (Math∩Science only) − (Math∩English only) − (all three) = 60−15−8−10 = 27. The pairs given are already ''only that pair'' (excluding the triple overlap). Trap: 25 omits one pairwise overlap; 22 subtracts all overlaps twice.', 'HARD', 'Reasoning', 'Venn Diagrams — Set Operations and Cardinality (W10 B2)', 'RSN_VENN_DIAGRAMS_W10_B2', '[{"option_text": "22", "is_correct": false}, {"option_text": "25", "is_correct": false}, {"option_text": "27", "is_correct": true}, {"option_text": "30", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('478b436b-37cd-5260-8e03-633adc9854ee', 'In a class, every student plays at least one game. 20 play Cricket, 16 play Football, 12 play Badminton. 8 play Cricket & Football, 6 play Football & Badminton, 5 play Cricket & Badminton, and 3 play all three. Find the total number of students.', NULL, 'C is correct. |C∪F∪B| = 20+16+12−8−6−5+3 = 48−19+3 = 32. Since every student plays at least one game, total = 32. Trap: 36 = 20+16+12−8−6+2 (forgets to add back the triple intersection); 30 uses |C∩F|+|F∩B|+|C∩B| = 19 but misses the triple correction.', 'HARD', 'Reasoning', 'Venn Diagrams — Set Operations and Cardinality (W10 B2)', 'RSN_VENN_DIAGRAMS_W10_B2', '[{"option_text": "28", "is_correct": false}, {"option_text": "30", "is_correct": false}, {"option_text": "32", "is_correct": true}, {"option_text": "36", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dfb9b5ed-9b6c-5711-8fde-1c773fade981', 'Out of 200 students, 80 study Physics, 100 study Chemistry, and 70 study Biology. 30 study Physics & Chemistry, 20 study Chemistry & Biology, 25 study Physics & Biology, and 10 study all three. How many students study EXACTLY two subjects?', NULL, 'C is correct. ''Exactly two'' means pairwise overlaps minus the triple. P∩C only = 30−10=20. C∩B only = 20−10=10. P∩B only = 25−10=15. Exactly two = 20+10+15 = 45. Trap: 35 subtracts triple from total pairwise (30+20+25−10=65... wrong); 50 = 30+20+25−10+5 (wrong).', 'HARD', 'Reasoning', 'Venn Diagrams — Set Operations and Cardinality (W10 B2)', 'RSN_VENN_DIAGRAMS_W10_B2', '[{"option_text": "35", "is_correct": false}, {"option_text": "40", "is_correct": false}, {"option_text": "45", "is_correct": true}, {"option_text": "50", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0662bd76-0059-5b08-852b-fb45324b298f', 'In a class of 60, every student studies at least one of Hindi or English. 40 study Hindi and 35 study English. How many study Hindi but NOT English?', NULL, 'C is correct. |H∪E| = 60 (all students study at least one). |H∩E| = |H|+|E|−|H∪E| = 40+35−60 = 15. Hindi only (not English) = |H|−|H∩E| = 40−15 = 25. Trap: 30 = 60−30 (confuses ''neither'' with something else); 20 = 35−15 gives English only, not Hindi only.', 'HARD', 'Reasoning', 'Venn Diagrams — Set Operations and Cardinality (W10 B2)', 'RSN_VENN_DIAGRAMS_W10_B2', '[{"option_text": "20", "is_correct": false}, {"option_text": "23", "is_correct": false}, {"option_text": "25", "is_correct": true}, {"option_text": "30", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('39721b9b-f842-5047-82a9-f49d2492b4b1', 'In a class of 60 students, 35 play cricket, 20 play football, and 10 play both. How many students play neither sport?', NULL, 'B is correct. |Cricket ∪ Football| = |Cricket| + |Football| - |Both| = 35+20-10 = 45. Students who play neither = Total - |Cricket ∪ Football| = 60-45 = 15. Verify: Only cricket = 35-10=25; Only football = 20-10=10; Both=10; Neither=15; Total=25+10+10+15=60 ✓. Trap: 20 = forgets to subtract the overlap (35+20=55, 60-55=5? No — 55 is wrong too since overlap is added twice).', 'EASY', 'Reasoning', 'Venn Diagrams — Set Relationships (W11 B2)', 'RSN_VENN_DIAGRAMS_W11_B2', '[{"option_text": "10", "is_correct": false}, {"option_text": "15", "is_correct": true}, {"option_text": "20", "is_correct": false}, {"option_text": "25", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('205a7a64-f8c4-5315-938d-58cdaa11a62d', 'Which Venn diagram correctly shows the relationship among: Animals — Wolves — Dogs?', NULL, 'B is correct. Animals is the broadest set — it contains all animals. Wolves and Dogs are both subsets of Animals, but they are separate species (no wolf is a dog, no dog is a wolf). So both wolves and dogs sit inside the Animals circle, but they are separate circles from each other. Trap: Three concentric = would mean Dogs are all Wolves or Wolves are all Dogs (wrong); Overlapping inside Animals = would mean some dogs are wolves (wrong); Completely separate = ignores that both are types of animals.', 'MEDIUM', 'Reasoning', 'Venn Diagrams — Set Relationships (W11 B2)', 'RSN_VENN_DIAGRAMS_W11_B2', '[{"option_text": "Three completely separate circles", "is_correct": false}, {"option_text": "Two circles inside one large circle, with the two inner circles separate", "is_correct": true}, {"option_text": "Three concentric circles (one inside another inside another)", "is_correct": false}, {"option_text": "Two overlapping circles inside one large circle", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('53c475f4-2a68-58f4-ba10-f2ac507a135a', 'In a survey of 100 people, 72 like tea, 52 like coffee, and every person likes at least one. How many people like both tea and coffee?', NULL, 'B is correct. Since every person likes at least one: |Tea ∪ Coffee| = 100. Formula: |Both| = |Tea| + |Coffee| - |Tea ∪ Coffee| = 72+52-100 = 124-100 = 24. Verify: Only tea = 72-24=48; Only coffee = 52-24=28; Both=24; Total=48+28+24=100 ✓. Trap: 20 = 72-52 (just difference, wrong); 26 = arithmetic error.', 'EASY', 'Reasoning', 'Venn Diagrams — Set Relationships (W11 B2)', 'RSN_VENN_DIAGRAMS_W11_B2', '[{"option_text": "20", "is_correct": false}, {"option_text": "24", "is_correct": true}, {"option_text": "26", "is_correct": false}, {"option_text": "28", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('29be6f82-335b-5f14-8104-50d7fcce182e', 'Which Venn diagram best represents the relationship: Males — Fathers — Humans?', NULL, 'B is correct. All Males are Humans (Males ⊂ Humans). All Fathers are Males — by definition, a father is a male parent (Fathers ⊂ Males). Not all Males are Fathers (many males are not fathers). This creates a strict subset chain: Fathers ⊂ Males ⊂ Humans = three concentric circles (Humans outermost, Males middle, Fathers innermost). Trap: ''All overlapping equally'' = wrong (no father or male is non-human); ''Partially outside Humans'' = wrong (no father can be non-human); ''All separate'' = wrong (all fathers are males and all males are humans).', 'HARD', 'Reasoning', 'Venn Diagrams — Set Relationships (W11 B2)', 'RSN_VENN_DIAGRAMS_W11_B2', '[{"option_text": "All three circles overlapping equally", "is_correct": false}, {"option_text": "Males inside Humans; Fathers inside Males (three concentric circles)", "is_correct": true}, {"option_text": "Males inside Humans; Fathers overlapping Males and partially outside Humans", "is_correct": false}, {"option_text": "All three are separate circles", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('35f4f0cc-5cd7-57c5-9f63-a47be139854b', 'Out of 50 students, 30 passed in English, 22 passed in Maths, and 5 failed in both. How many passed in both subjects?', NULL, 'B is correct. Students who passed at least one = Total - Failed in both = 50-5 = 45. |English ∪ Maths| = 45. Passed both = |English| + |Maths| - |English ∪ Maths| = 30+22-45 = 52-45 = 7. Verify: Only English = 30-7=23; Only Maths = 22-7=15; Both=7; Failed both=5; Total=23+15+7+5=50 ✓. Trap: 5 = confuses ''failed both'' with ''passed both''; 8 = arithmetic error.', 'MEDIUM', 'Reasoning', 'Venn Diagrams — Set Relationships (W11 B2)', 'RSN_VENN_DIAGRAMS_W11_B2', '[{"option_text": "5", "is_correct": false}, {"option_text": "7", "is_correct": true}, {"option_text": "8", "is_correct": false}, {"option_text": "10", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f1d1b4e0-f819-571b-8b21-de4517a8cee5', 'Which Venn diagram correctly shows the relationship: Squares — Rectangles — Quadrilaterals?', NULL, 'B is correct. Logic: All squares are rectangles (a square has all properties of a rectangle plus equal sides). All rectangles are quadrilaterals (a rectangle has 4 sides). So: Squares ⊂ Rectangles ⊂ Quadrilaterals. This gives three concentric circles (each smaller one completely inside the larger one). Trap: Overlapping = wrong (ALL squares are rectangles, not just some); Separate = wrong (every square IS a rectangle IS a quadrilateral).', 'MEDIUM', 'Reasoning', 'Venn Diagrams — Set Relationships (W11 B2)', 'RSN_VENN_DIAGRAMS_W11_B2', '[{"option_text": "Three separate circles", "is_correct": false}, {"option_text": "Squares inside Rectangles inside Quadrilaterals (three concentric circles)", "is_correct": true}, {"option_text": "Squares and Rectangles inside Quadrilaterals, with Squares and Rectangles overlapping", "is_correct": false}, {"option_text": "Squares inside Quadrilaterals; Rectangles separate from Quadrilaterals", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('319bc245-be33-5824-ad9f-d7f8374e6bda', 'In a group of 80 people, 45 speak Hindi, 30 speak English, and 15 speak both. How many speak only Hindi?', NULL, 'C is correct. Only Hindi = |Hindi| - |Both| = 45-15 = 30. No calculation of the total is needed here — just subtract those who speak both from the total Hindi speakers. Verify: Only Hindi=30; Both=15; Only English=30-15=15; Total Hindi speakers = 30+15=45 ✓; Total English speakers = 15+15=30 ✓. Trap: 35 = subtracts English count from Hindi count (45-10? wrong); 25 = 45-20 (uses wrong ''both'' number).', 'EASY', 'Reasoning', 'Venn Diagrams — Set Relationships (W11 B2)', 'RSN_VENN_DIAGRAMS_W11_B2', '[{"option_text": "20", "is_correct": false}, {"option_text": "25", "is_correct": false}, {"option_text": "30", "is_correct": true}, {"option_text": "35", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('61578fd2-3fde-59d8-997d-c5a3000ff73c', 'In a class: 40 students study Science, 30 study Commerce, 20 study both, and 10 study neither. What is the total number of students in the class?', NULL, 'A is correct. |Science ∪ Commerce| = 40+30-20 = 50. Total = |Science ∪ Commerce| + Neither = 50+10 = 60. Verify: Only Science=40-20=20; Only Commerce=30-20=10; Both=20; Neither=10; Total=20+10+20+10=60 ✓. Trap: 70 = 40+30=70 (double-counts the ''both'' students and ignores neither); 80 = 40+30+10 (adds neither but doesn''t subtract overlap).', 'EASY', 'Reasoning', 'Venn Diagrams — Set Relationships (W11 B2)', 'RSN_VENN_DIAGRAMS_W11_B2', '[{"option_text": "60", "is_correct": true}, {"option_text": "70", "is_correct": false}, {"option_text": "80", "is_correct": false}, {"option_text": "90", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('306f39e3-1580-58ad-8a12-73c68be1ec68', 'In a class, 60% of students passed Maths, 70% passed English, and 20% failed both. What percentage passed both Maths and English?', NULL, 'C is correct. Failed both = 20% → Passed at least one = 80%. |Maths ∪ English| = 80%. Both = |Maths| + |English| - |Maths ∪ English| = 60+70-80 = 50%. Verify: Only Maths = 60-50=10%; Only English = 70-50=20%; Both=50%; Failed both=20%; Total=10+20+50+20=100% ✓. Trap: 40% = 60-20 (wrong); 45% = arithmetic error.', 'HARD', 'Reasoning', 'Venn Diagrams — Set Relationships (W11 B2)', 'RSN_VENN_DIAGRAMS_W11_B2', '[{"option_text": "40%", "is_correct": false}, {"option_text": "45%", "is_correct": false}, {"option_text": "50%", "is_correct": true}, {"option_text": "55%", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f8ae15f0-16e8-5e41-b914-f0205c0ea244', 'Which Venn diagram best represents: Doctors — Women — Surgeons?', NULL, 'C is correct. Analysis: Some doctors are women (not all doctors are women; not all women are doctors). Some doctors are surgeons (not all doctors are surgeons; not all surgeons are doctors — consider dentists, vets). Some women are surgeons (a female surgeon is both). These sets share partial overlaps with each other. No set is fully contained within another. Result: Three intersecting circles with a central region where all three overlap (women who are also doctors and surgeons). Trap: Concentric = wrong (not all surgeons are doctors in the broader sense; the three groups have independent members); All separate = wrong (they DO share members).', 'MEDIUM', 'Reasoning', 'Venn Diagrams — Set Relationships (W11 B2)', 'RSN_VENN_DIAGRAMS_W11_B2', '[{"option_text": "Three separate circles", "is_correct": false}, {"option_text": "Three concentric circles (Surgeons inside Doctors inside Women)", "is_correct": false}, {"option_text": "Three partially overlapping circles (each intersecting the other two)", "is_correct": true}, {"option_text": "Women and Surgeons inside Doctors", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('75780ccc-4e7b-5259-8920-de73d57d0b91', 'In a group of 50 people: 30 like cricket, 25 like football, and 10 like both. How many like neither?', NULL, 'A is correct. |C∪F| = 30+25−10 = 45. Neither = 50−45 = 5.', 'EASY', 'Reasoning', 'Venn Diagrams (W9)', 'RSN_VENN_DIAGRAM_W9', '[{"option_text": "5", "is_correct": true}, {"option_text": "10", "is_correct": false}, {"option_text": "15", "is_correct": false}, {"option_text": "20", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1d5c5e6b-e070-5f79-a209-797761168851', 'Which Venn diagram best represents the relationship: India, Maharashtra, Mumbai?', NULL, 'A is correct. Mumbai ⊂ Maharashtra ⊂ India — each is fully contained within the next. Three concentric circles (nested) represent this perfectly.', 'EASY', 'Reasoning', 'Venn Diagrams (W9)', 'RSN_VENN_DIAGRAM_W9', '[{"option_text": "Three concentric circles (Mumbai innermost, Maharashtra middle, India outermost)", "is_correct": true}, {"option_text": "Three overlapping but separate circles", "is_correct": false}, {"option_text": "Two separate circles inside a bigger circle", "is_correct": false}, {"option_text": "Three completely separate circles", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e2f10e4f-bf19-59e3-98b5-7bfd80a3d37c', 'Which Venn diagram best represents: Triangles, Quadrilaterals, Polygons?', NULL, 'C is correct. Triangles ⊂ Polygons and Quadrilaterals ⊂ Polygons, but Triangles and Quadrilaterals are mutually exclusive (no figure is both). So: two separate circles inside a larger Polygons circle.', 'EASY', 'Reasoning', 'Venn Diagrams (W9)', 'RSN_VENN_DIAGRAM_W9', '[{"option_text": "Two overlapping circles inside a bigger circle", "is_correct": false}, {"option_text": "Three concentric circles", "is_correct": false}, {"option_text": "Two separate non-overlapping circles both inside a bigger circle", "is_correct": true}, {"option_text": "Three completely separate circles", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5d0e718d-8c65-5988-8f5b-394738235a5d', 'In a class of 40 students: 25 play cricket, 20 play football, 15 play both. How many play only cricket?', NULL, 'B is correct. Only cricket = total cricket − both = 25−15 = 10.', 'MEDIUM', 'Reasoning', 'Venn Diagrams (W9)', 'RSN_VENN_DIAGRAM_W9', '[{"option_text": "5", "is_correct": false}, {"option_text": "10", "is_correct": true}, {"option_text": "15", "is_correct": false}, {"option_text": "20", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('efd6a2a5-a481-5bb5-bf00-47776a13e655', 'In a class of 60: 35 like Math, 45 like Science. All students like at least one subject. How many like both?', NULL, 'B is correct. |M∪S| = total = 60 (everyone likes at least one). |M∪S| = |M|+|S|−|M∩S| → 60 = 35+45−|M∩S| → |M∩S| = 20.', 'MEDIUM', 'Reasoning', 'Venn Diagrams (W9)', 'RSN_VENN_DIAGRAM_W9', '[{"option_text": "15", "is_correct": false}, {"option_text": "20", "is_correct": true}, {"option_text": "25", "is_correct": false}, {"option_text": "30", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ff18dfa3-5b00-51bd-9bed-de724aebd6c9', 'Circle A has 12 elements, Circle B has 15 elements, and their intersection has 5 elements. What is |A∪B|?', NULL, 'C is correct. |A∪B| = |A|+|B|−|A∩B| = 12+15−5 = 22.', 'MEDIUM', 'Reasoning', 'Venn Diagrams (W9)', 'RSN_VENN_DIAGRAM_W9', '[{"option_text": "17", "is_correct": false}, {"option_text": "20", "is_correct": false}, {"option_text": "22", "is_correct": true}, {"option_text": "27", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('865ac4f7-9abd-5bfa-8e29-bf4eb8252f4e', 'In a group of 60 people: 35 like tea, 40 like coffee, 25 like both. How many like neither?', NULL, 'C is correct. |T∪C| = 35+40−25 = 50. Neither = 60−50 = 10.', 'MEDIUM', 'Reasoning', 'Venn Diagrams (W9)', 'RSN_VENN_DIAGRAM_W9', '[{"option_text": "5", "is_correct": false}, {"option_text": "8", "is_correct": false}, {"option_text": "10", "is_correct": true}, {"option_text": "15", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('56189e61-ef37-5596-8069-a2f9bafa1c6a', 'In a survey of 60 people who like Math, Science or English: 35 like Math, 40 like Science. If 15 like all three and 20 like exactly two, how many like only one subject?', NULL, 'C is correct. Total = only-one + exactly-two + all-three → 60 = only-one + 20 + 15 → only-one = 25.', 'MEDIUM', 'Reasoning', 'Venn Diagrams (W9)', 'RSN_VENN_DIAGRAM_W9', '[{"option_text": "15", "is_correct": false}, {"option_text": "20", "is_correct": false}, {"option_text": "25", "is_correct": true}, {"option_text": "30", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('298ad512-186e-5ada-bca8-f06c131d4dfd', '100 students: 60 like History, 55 like Geography, 50 like Civics. 30 like History & Geography, 25 like History & Civics, 20 like Geography & Civics, 10 like all three. How many like exactly two subjects?', NULL, 'C is correct. Exactly two (excluding those who like all three): (H∩G only)=30−10=20, (H∩C only)=25−10=15, (G∩C only)=20−10=10. Total exactly two = 20+15+10 = 45.', 'HARD', 'Reasoning', 'Venn Diagrams (W9)', 'RSN_VENN_DIAGRAM_W9', '[{"option_text": "35", "is_correct": false}, {"option_text": "40", "is_correct": false}, {"option_text": "45", "is_correct": true}, {"option_text": "50", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b98e5dc0-e72a-5f54-8aa9-34742cfded56', 'From the same survey (100 students, Q9 data), how many like at least one of the three subjects?', NULL, 'C is correct. |H∪G∪C| = 60+55+50−30−25−20+10 = 165−75+10 = 100. All 100 students like at least one subject — nobody likes none.', 'HARD', 'Reasoning', 'Venn Diagrams (W9)', 'RSN_VENN_DIAGRAM_W9', '[{"option_text": "90", "is_correct": false}, {"option_text": "95", "is_correct": false}, {"option_text": "100", "is_correct": true}, {"option_text": "85", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('819c2ff3-7337-54af-9d52-a251ab364c8c', 'The element with the highest electronegativity is:', NULL, 'Fluorine has the highest electronegativity (3.98 on Pauling scale); it attracts bonding electrons most strongly.', 'EASY', 'Chemistry', 'Periodic Table', 'CHE_PERIODIC_TABLE', '[{"option_text": "Oxygen", "is_correct": false}, {"option_text": "Chlorine", "is_correct": false}, {"option_text": "Nitrogen", "is_correct": false}, {"option_text": "Fluorine", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('611d4ff6-aebe-5191-9e36-4b5cff882f88', '''Benevolent'' means:', NULL, 'Bene- (well) + volent (to wish). Antonym: malevolent (mal- = bad).', 'EASY', 'English', 'Vocabulary — Word Roots', 'ENG_VOCAB_USAGE', '[{"option_text": "Well-wishing; inclined to do good", "is_correct": true}, {"option_text": "Hostile and aggressive", "is_correct": false}, {"option_text": "Indifferent", "is_correct": false}, {"option_text": "Strict and disciplinarian", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5fc7bf4b-37b4-5ace-b6a7-46f8dd049cef', '''Perspicacious'' means:', NULL, 'Latin: perspicax = sharp-sighted. Used in exams: ''a perspicacious analyst foresaw the crisis.''', 'HARD', 'English', 'Vocabulary — Word Roots', 'ENG_VOCAB_USAGE', '[{"option_text": "Having sharp, penetrating insight; shrewd", "is_correct": true}, {"option_text": "Easily angered", "is_correct": false}, {"option_text": "Extremely generous", "is_correct": false}, {"option_text": "Deceptively charming", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('797c3687-3d11-53e9-8a5b-3dd9926d50b6', 'MENDACIOUS : TRUTHFUL :: PARSIMONIOUS : ?', NULL, 'A is correct. Relationship: ANTONYM pairs. MENDACIOUS (habitually lying) is the opposite of TRUTHFUL (honest). PARSIMONIOUS (excessively unwilling to spend; miserly) is the opposite of GENEROUS (willing to give freely). Trap: FRUGAL = careful with money (a milder form of parsimony, actually a near-synonym, not antonym); MISERLY = same as parsimonious (synonym, not antonym). The relationship is ANTONYM so we need the opposite.', 'HARD', 'Vocabulary', 'Word Analogy — Advanced Relationships and Vocabulary (W12 B1)', 'VOCAB_ANALOGY_ADV_W12_B1', '[{"option_text": "generous", "is_correct": true}, {"option_text": "frugal", "is_correct": false}, {"option_text": "miserly", "is_correct": false}, {"option_text": "careful", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('371199d2-70c7-547d-a8d6-3249288c18f1', 'STETHOSCOPE : DOCTOR :: SEXTANT : ?', NULL, 'A is correct. Relationship: TOOL : USER. A stethoscope is the diagnostic tool used by a doctor. A sextant is a navigational instrument used by a navigator to measure angles between celestial objects and determine position at sea. Trap: astronomer = uses a telescope; surveyor = uses a theodolite; soldier = uses weapons/equipment. A sextant is specifically a maritime/aerial navigation tool.', 'MEDIUM', 'Vocabulary', 'Word Analogy — Advanced Relationships and Vocabulary (W12 B1)', 'VOCAB_ANALOGY_ADV_W12_B1', '[{"option_text": "navigator", "is_correct": true}, {"option_text": "soldier", "is_correct": false}, {"option_text": "astronomer", "is_correct": false}, {"option_text": "surveyor", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c0c559a0-4e48-5534-9314-25b720760254', 'ORNITHOLOGY : BIRDS :: ENTOMOLOGY : ?', NULL, 'B is correct. Relationship: STUDY OF : SUBJECT. Ornithology is the scientific study of birds. Entomology is the scientific study of insects (Greek entomos = cut in sections/notched, referring to insects'' segmented bodies). Trap: plants = botany; reptiles = herpetology; fossils = palaeontology. Key: entomo = insect (entomologist studies insects).', 'EASY', 'Vocabulary', 'Word Analogy — Advanced Relationships and Vocabulary (W12 B1)', 'VOCAB_ANALOGY_ADV_W12_B1', '[{"option_text": "plants", "is_correct": false}, {"option_text": "insects", "is_correct": true}, {"option_text": "reptiles", "is_correct": false}, {"option_text": "fossils", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('566b6c1b-ff69-5768-8dd0-dc5250a49e82', 'LOQUACIOUS : TACITURN :: FRUGAL : ?', NULL, 'B is correct. Relationship: ANTONYM pairs. LOQUACIOUS (talkative) is opposite to TACITURN (reserved, saying little). FRUGAL (careful with money, economical) is opposite to EXTRAVAGANT (spending excessively). Trap: THRIFTY = near-synonym of frugal (not antonym); MISERLY = also near-synonym (extreme frugality); CAREFUL = partial synonym of frugal. The antonym of frugal is extravagant/wasteful/spendthrift.', 'MEDIUM', 'Vocabulary', 'Word Analogy — Advanced Relationships and Vocabulary (W12 B1)', 'VOCAB_ANALOGY_ADV_W12_B1', '[{"option_text": "thrifty", "is_correct": false}, {"option_text": "extravagant", "is_correct": true}, {"option_text": "careful", "is_correct": false}, {"option_text": "miserly", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6667372f-abd0-5068-967a-649dc1a8788f', 'INK : CALLIGRAPHER :: CHISEL : ?', NULL, 'C is correct. Relationship: PRIMARY TOOL MATERIAL : USER. Ink is the primary medium used by a calligrapher (one who practises decorative handwriting). A chisel is the primary tool used by a sculptor (one who carves/shapes stone, wood or metal). Trap: carpenter = uses a saw, hammer, nails (chisel is used by both carpenters and sculptors, but a sculptor''s PRIMARY tool is the chisel for shaping; a painter uses brushes/paint not chisels).', 'EASY', 'Vocabulary', 'Word Analogy — Advanced Relationships and Vocabulary (W12 B1)', 'VOCAB_ANALOGY_ADV_W12_B1', '[{"option_text": "plumber", "is_correct": false}, {"option_text": "carpenter", "is_correct": false}, {"option_text": "sculptor", "is_correct": true}, {"option_text": "painter", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('266205a3-b946-5c06-b5df-e8accdc7d241', 'FORTITUDE : COWARDICE :: CANDOUR : ?', NULL, 'C is correct. Relationship: ANTONYM pairs. FORTITUDE (courage in facing adversity) is opposite to COWARDICE (lack of courage). CANDOUR (frankness, honesty, openness) is opposite to DECEIT (dishonesty, concealment, trickery). Trap: SINCERITY and HONESTY are near-synonyms of candour (not antonyms); BOLDNESS = near-synonym of fortitude (not relevant to candour). The pattern is consistently antonyms.', 'HARD', 'Vocabulary', 'Word Analogy — Advanced Relationships and Vocabulary (W12 B1)', 'VOCAB_ANALOGY_ADV_W12_B1', '[{"option_text": "sincerity", "is_correct": false}, {"option_text": "honesty", "is_correct": false}, {"option_text": "deceit", "is_correct": true}, {"option_text": "boldness", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('04eb76cd-0a19-566a-81dc-25c2632b2672', 'FLEDGLING : BIRD :: CYGNET : ?', NULL, 'B is correct. Relationship: YOUNG ONE : SPECIES. A fledgling is a young bird that has recently grown its feathers (generic young bird). A cygnet is specifically the young of a swan. Trap: duck''s young = duckling; eagle''s young = eaglet; goose''s young = gosling. The classic set SSC loves: cygnet (swan), foal (horse), calf (cow/elephant), lamb (sheep), kitten (cat), puppy (dog), leveret (hare), fawn (deer).', 'MEDIUM', 'Vocabulary', 'Word Analogy — Advanced Relationships and Vocabulary (W12 B1)', 'VOCAB_ANALOGY_ADV_W12_B1', '[{"option_text": "duck", "is_correct": false}, {"option_text": "swan", "is_correct": true}, {"option_text": "eagle", "is_correct": false}, {"option_text": "goose", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('558c16d3-ca2a-52d0-a8c9-31bcf218eed8', 'LACONIC : VERBOSE :: ERUDITE : ?', NULL, 'C is correct. Relationship: ANTONYM pairs. LACONIC (using very few words; brief) is opposite to VERBOSE (using too many words; long-winded). ERUDITE (having or showing great learning) is opposite to IGNORANT (lacking knowledge or education). Trap: LEARNED, SCHOLARLY, STUDIOUS = all near-synonyms of ERUDITE (not antonyms). The pattern demands antonyms throughout.', 'HARD', 'Vocabulary', 'Word Analogy — Advanced Relationships and Vocabulary (W12 B1)', 'VOCAB_ANALOGY_ADV_W12_B1', '[{"option_text": "learned", "is_correct": false}, {"option_text": "scholarly", "is_correct": false}, {"option_text": "ignorant", "is_correct": true}, {"option_text": "studious", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6e3dd99c-b09a-5552-9344-5b02c118aaed', 'EPHEMERAL : ENDURING :: ARCHAIC : ?', NULL, 'C is correct. Relationship: ANTONYM pairs. EPHEMERAL (lasting for only a short time; short-lived) is opposite to ENDURING (lasting a long time; permanent). ARCHAIC (very old or old-fashioned; belonging to an earlier period) is opposite to CONTEMPORARY (belonging to or occurring in the present time; modern). Trap: ANCIENT, OUTDATED, OBSOLETE = all near-synonyms of archaic (not antonyms). CONTEMPORARY = modern/current = true antonym of archaic.', 'MEDIUM', 'Vocabulary', 'Word Analogy — Advanced Relationships and Vocabulary (W12 B1)', 'VOCAB_ANALOGY_ADV_W12_B1', '[{"option_text": "ancient", "is_correct": false}, {"option_text": "outdated", "is_correct": false}, {"option_text": "contemporary", "is_correct": true}, {"option_text": "obsolete", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('64b89f1a-c94f-5914-b7fe-ba7b3f42c8ae', 'PHILOLOGIST : LANGUAGE :: PALAEONTOLOGIST : ?', NULL, 'A is correct. Relationship: EXPERT : FIELD OF STUDY. A philologist studies the historical development and structure of language. A palaeontologist studies fossils — the preserved remains of prehistoric organisms — to understand ancient life (Greek palaios = ancient + ontos = being + -logia = study). Trap: rocks = geologist; ancient art = archaeologist or art historian; plants = botanist. Palaeontology ≠ geology (though related); fossils are the specific subject.', 'MEDIUM', 'Vocabulary', 'Word Analogy — Advanced Relationships and Vocabulary (W12 B1)', 'VOCAB_ANALOGY_ADV_W12_B1', '[{"option_text": "fossils", "is_correct": true}, {"option_text": "ancient art", "is_correct": false}, {"option_text": "plants", "is_correct": false}, {"option_text": "rocks", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('206fde30-a435-53b9-9e12-97d59a1d1c17', 'What is the antonym of LOQUACIOUS?', NULL, 'C is correct. LOQUACIOUS = excessively talkative; using too many words. TACITURN = reserved; saying very little; temperamentally disinclined to talk. These are exact antonyms on the speech-quantity spectrum. Trap: verbose and garrulous = SYNONYMS of loquacious (both mean excessively wordy); talkative = also a synonym. Mnemonic: TACiturn = TACT of keeping quiet (silent).', 'EASY', 'Vocabulary', 'Antonyms — Advanced SSC-Level Vocabulary Pairs (W13 B1)', 'VOCAB_ANTONYMS_ADVANCED_W13_B1', '[{"option_text": "verbose", "is_correct": false}, {"option_text": "talkative", "is_correct": false}, {"option_text": "taciturn", "is_correct": true}, {"option_text": "garrulous", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f9c4986c-9877-5110-b9de-57f24c2e6a2e', 'What is the antonym of MENDACIOUS?', NULL, 'B is correct. MENDACIOUS = not telling the truth; habitually dishonest; lying. TRUTHFUL = honest; telling the truth; veracious. Antonym pair: mendacious↔truthful. Root: Latin mendax = lying. Trap: deceptive, cunning, manipulative = all synonyms of mendacious (all involve dishonesty or trickery, not honesty).', 'EASY', 'Vocabulary', 'Antonyms — Advanced SSC-Level Vocabulary Pairs (W13 B1)', 'VOCAB_ANTONYMS_ADVANCED_W13_B1', '[{"option_text": "deceptive", "is_correct": false}, {"option_text": "truthful", "is_correct": true}, {"option_text": "cunning", "is_correct": false}, {"option_text": "manipulative", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9d484211-737a-5570-bb47-7b6f8135db2d', 'What is the antonym of EBULLIENT?', NULL, 'C is correct. EBULLIENT = cheerful and full of energy; overflowing with enthusiasm and excitement. DESPONDENT = in low spirits from loss of hope or courage; dejected. Direct antonyms on the energy/mood scale. Trap: enthusiastic, vivacious, exuberant = all synonyms of ebullient (high energy/positive mood). Mnemonic: EBULLIENT = bubbling over with joy (ebullition = boiling); DESPONDENT = deeply sinking in spirit.', 'MEDIUM', 'Vocabulary', 'Antonyms — Advanced SSC-Level Vocabulary Pairs (W13 B1)', 'VOCAB_ANTONYMS_ADVANCED_W13_B1', '[{"option_text": "enthusiastic", "is_correct": false}, {"option_text": "vivacious", "is_correct": false}, {"option_text": "despondent", "is_correct": true}, {"option_text": "exuberant", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1a3deb9d-098b-5d36-b5b3-ec94eb3949c2', 'What is the antonym of BENEVOLENT?', NULL, 'B is correct. BENEVOLENT = well-meaning and kindly; wishing well to others (Latin bene = well + velle = to wish). MALEVOLENT = wishing evil to others; malicious (Latin male = badly + velle = to wish). These are exact Latin-rooted antonyms. Trap: charitable, munificent, philanthropic = synonyms of benevolent (all involve generosity or good will). The bene/male prefix pair is fundamental: benevolent↔malevolent, beneficial↔maleficent.', 'EASY', 'Vocabulary', 'Antonyms — Advanced SSC-Level Vocabulary Pairs (W13 B1)', 'VOCAB_ANTONYMS_ADVANCED_W13_B1', '[{"option_text": "charitable", "is_correct": false}, {"option_text": "malevolent", "is_correct": true}, {"option_text": "munificent", "is_correct": false}, {"option_text": "philanthropic", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('78a48e6b-9393-51b2-9c85-714a36c1e91a', 'What is the antonym of PERSPICACIOUS?', NULL, 'D is correct. PERSPICACIOUS = having a ready insight into things; shrewd; keenly perceptive. OBTUSE = annoyingly insensitive or slow to understand; lacking sharpness of mental acuity. Antonym pair: perceptive/sharp↔dull/slow-witted. Trap: shrewd, discerning, astute = all synonyms of perspicacious. Root of perspicacious: Latin perspicax = clear-sighted (per = through + specere = to look). Obtuse literally = blunt-angled (not sharp), applied to the mind = not sharp.', 'HARD', 'Vocabulary', 'Antonyms — Advanced SSC-Level Vocabulary Pairs (W13 B1)', 'VOCAB_ANTONYMS_ADVANCED_W13_B1', '[{"option_text": "shrewd", "is_correct": false}, {"option_text": "discerning", "is_correct": false}, {"option_text": "astute", "is_correct": false}, {"option_text": "obtuse", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3f57064d-9712-5416-abf7-11dcb86dc7a3', 'What is the antonym of TRUCULENT?', NULL, 'C is correct. TRUCULENT = eager or quick to argue or fight; aggressively defiant. DOCILE = ready to accept control or instruction; submissive; easily managed. Antonym pair: aggressive/combative↔submissive/compliant. Trap: aggressive, belligerent, pugnacious = all synonyms of truculent (fighting-word cluster). Mnemonic: DOCILE = DOCks easily, follows instructions; TRUCULENT = like a truck barreling forward aggressively.', 'HARD', 'Vocabulary', 'Antonyms — Advanced SSC-Level Vocabulary Pairs (W13 B1)', 'VOCAB_ANTONYMS_ADVANCED_W13_B1', '[{"option_text": "aggressive", "is_correct": false}, {"option_text": "belligerent", "is_correct": false}, {"option_text": "docile", "is_correct": true}, {"option_text": "pugnacious", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ce9612a9-79ca-5242-8ce5-a9542723a925', 'What is the antonym of TENACIOUS?', NULL, 'C is correct. TENACIOUS = tending to keep a firm hold; not readily giving up; persistent. IRRESOLUTE = showing or feeling uncertainty about how to act; lacking resoluteness; wavering. Antonym pair: firm/persistent↔uncertain/wavering. Trap: persistent, resolute, determined = synonyms of tenacious. Root: TENACIOUS from Latin tenax = holding fast (tenere = to hold); IRRESOLUTE = not (ir-) resolved = unable to decide.', 'MEDIUM', 'Vocabulary', 'Antonyms — Advanced SSC-Level Vocabulary Pairs (W13 B1)', 'VOCAB_ANTONYMS_ADVANCED_W13_B1', '[{"option_text": "persistent", "is_correct": false}, {"option_text": "resolute", "is_correct": false}, {"option_text": "irresolute", "is_correct": true}, {"option_text": "determined", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7f051b06-443c-55c9-b30d-c4113151b26e', 'What is the antonym of MAGNANIMOUS?', NULL, 'C is correct. MAGNANIMOUS = generous or forgiving, especially towards a rival or someone less powerful; noble in mind and spirit. PETTY = having or showing a small, mean, ungenerous spirit; trivially small-minded. Antonym pair: noble-spirited/generous↔small-minded/mean. Root: MAGNANIMOUS from Latin magnus (great) + animus (spirit). PETTY = Latin petitus (small). Trap: generous, noble, charitable = synonyms of magnanimous.', 'MEDIUM', 'Vocabulary', 'Antonyms — Advanced SSC-Level Vocabulary Pairs (W13 B1)', 'VOCAB_ANTONYMS_ADVANCED_W13_B1', '[{"option_text": "generous", "is_correct": false}, {"option_text": "noble", "is_correct": false}, {"option_text": "petty", "is_correct": true}, {"option_text": "charitable", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('da788fc4-ea5f-5513-a34a-48f0ac5799d3', 'What is the antonym of PAROCHIAL?', NULL, 'C is correct. PAROCHIAL = having a limited or narrow outlook confined to a local area; provincial (from ''parish'' = local church district). COSMOPOLITAN = familiar with and at ease in many different countries and cultures; having a sophisticated, international outlook. Antonym pair: narrow local view↔broad global view. Trap: provincial, narrow-minded, insular = synonyms of parochial. Mnemonic: COSMOpolitan = COSMO (universe/world) + politan (citizen) = citizen of the world.', 'MEDIUM', 'Vocabulary', 'Antonyms — Advanced SSC-Level Vocabulary Pairs (W13 B1)', 'VOCAB_ANTONYMS_ADVANCED_W13_B1', '[{"option_text": "provincial", "is_correct": false}, {"option_text": "narrow-minded", "is_correct": false}, {"option_text": "cosmopolitan", "is_correct": true}, {"option_text": "insular", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('360c0f3b-5df0-575f-8eae-fb2df7ff7c1a', 'What is the antonym of PENURIOUS?', NULL, 'C is correct. PENURIOUS = extremely poor; characterized by poverty. OPULENT = ostentatiously rich and luxurious; wealthy. Antonym pair: extremely poor↔extremely wealthy. Trap: miserly and parsimonious = about SPENDING little money (not necessarily about poverty — a miser can be rich but stingy); indigent = synonym of penurious (also extremely poor). SSC loves testing penurious because students confuse it with parsimonious (which is about spending, not wealth level).', 'HARD', 'Vocabulary', 'Antonyms — Advanced SSC-Level Vocabulary Pairs (W13 B1)', 'VOCAB_ANTONYMS_ADVANCED_W13_B1', '[{"option_text": "miserly", "is_correct": false}, {"option_text": "indigent", "is_correct": false}, {"option_text": "opulent", "is_correct": true}, {"option_text": "parsimonious", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('94b79705-b431-5765-8cf5-cbfc63ae8308', 'Choose the antonym of LOQUACIOUS.', NULL, 'C is correct. LOQUACIOUS = tending to talk a great deal; talkative. Antonym = RETICENT = not revealing one''s thoughts or feelings readily; quiet/reserved. Trap: Talkative (A) = synonym; Verbose (B) = synonym (using more words than needed); Garrulous (D) = synonym (excessively talkative). All three options are synonyms — reticent is the only antonym.', 'MEDIUM', 'Vocabulary', 'Antonyms — Advanced SSC CGL Tier 2 Set (W11 B1)', 'VOCAB_ANTONYMS_ADV_W11_B1', '[{"option_text": "Talkative", "is_correct": false}, {"option_text": "Verbose", "is_correct": false}, {"option_text": "Reticent", "is_correct": true}, {"option_text": "Garrulous", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9f35111c-5cfe-53ce-8543-aed59909f38e', 'Choose the antonym of MAGNANIMOUS.', NULL, 'C is correct. MAGNANIMOUS = very generous, forgiving, or noble in spirit. Antonym = PETTY = small-minded, ungenerous, or concerned with trivial matters. Root: ''magnus'' (great) + ''animus'' (soul) = great-souled. Trap: Generous (A), Noble (B), Benevolent (D) are all synonyms of magnanimous. Only Petty is the antonym.', 'MEDIUM', 'Vocabulary', 'Antonyms — Advanced SSC CGL Tier 2 Set (W11 B1)', 'VOCAB_ANTONYMS_ADV_W11_B1', '[{"option_text": "Generous", "is_correct": false}, {"option_text": "Noble", "is_correct": false}, {"option_text": "Petty", "is_correct": true}, {"option_text": "Benevolent", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f8a363da-1787-555b-a019-d8d99a4dd47a', 'Choose the antonym of INDOLENT.', NULL, 'D is correct. INDOLENT = avoiding activity or exertion; habitually lazy. Antonym = INDUSTRIOUS = hard-working, diligent. Trap: Slothful (A), Torpid (B), Lethargic (C) are all synonyms of indolent (all mean lazy/slow). SSC often packs the options with synonyms to trick students who don''t know the word''s antonym clearly.', 'EASY', 'Vocabulary', 'Antonyms — Advanced SSC CGL Tier 2 Set (W11 B1)', 'VOCAB_ANTONYMS_ADV_W11_B1', '[{"option_text": "Slothful", "is_correct": false}, {"option_text": "Torpid", "is_correct": false}, {"option_text": "Lethargic", "is_correct": false}, {"option_text": "Industrious", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8f6233f7-27de-5864-a9dd-315f7b6c2b3c', 'Choose the antonym of PROFLIGATE.', NULL, 'B is correct. PROFLIGATE = recklessly extravagant or wasteful in the use of resources; also, licentious. Antonym = THRIFTY = using money and other resources carefully and not wastefully. Trap: Dissipated (A), Dissolute (C), Debauched (D) are all synonyms of profligate''s second meaning (immoral/licentious). Only Thrifty opposes the extravagance meaning.', 'HARD', 'Vocabulary', 'Antonyms — Advanced SSC CGL Tier 2 Set (W11 B1)', 'VOCAB_ANTONYMS_ADV_W11_B1', '[{"option_text": "Dissipated", "is_correct": false}, {"option_text": "Thrifty", "is_correct": true}, {"option_text": "Dissolute", "is_correct": false}, {"option_text": "Debauched", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f5f3c8c7-f8cf-585b-b00b-6d2655d1120c', 'Choose the antonym of TRUCULENT.', NULL, 'C is correct. TRUCULENT = eager or quick to argue or fight; aggressively defiant. Antonym = PLACID = not easily upset or excited; calm and peaceful. Trap: Belligerent (A), Aggressive (B), Combative (D) are all synonyms of truculent. Only Placid (calm, peaceable) is the antonym.', 'HARD', 'Vocabulary', 'Antonyms — Advanced SSC CGL Tier 2 Set (W11 B1)', 'VOCAB_ANTONYMS_ADV_W11_B1', '[{"option_text": "Belligerent", "is_correct": false}, {"option_text": "Aggressive", "is_correct": false}, {"option_text": "Placid", "is_correct": true}, {"option_text": "Combative", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('21ea2cf0-ef05-54e2-a431-88f61a6c05a6', 'Choose the antonym of RECONDITE.', NULL, 'C is correct. RECONDITE = not known by many people; obscure, abstruse. Antonym = MANIFEST = clear or obvious to the eye or mind. Root: ''reconditus'' = hidden away (Latin). Trap: Esoteric (A), Abstruse (B), Arcane (D) are all synonyms of recondite (all mean obscure/little-known). Manifest is the only antonym (= openly known/obvious).', 'HARD', 'Vocabulary', 'Antonyms — Advanced SSC CGL Tier 2 Set (W11 B1)', 'VOCAB_ANTONYMS_ADV_W11_B1', '[{"option_text": "Esoteric", "is_correct": false}, {"option_text": "Abstruse", "is_correct": false}, {"option_text": "Manifest", "is_correct": true}, {"option_text": "Arcane", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('10824624-200f-5b86-9e1a-0a7ae7d32cee', 'Choose the antonym of EBULLIENT.', NULL, 'C is correct. EBULLIENT = cheerful and full of energy; exuberant. Antonym = DESPONDENT = in low spirits from loss of hope or courage; dejected. Trap: Exuberant (A), Vivacious (B), Effervescent (D) are all synonyms of ebullient (high-energy, enthusiastic). Despondent (gloomy, hopeless) is the clear antonym.', 'MEDIUM', 'Vocabulary', 'Antonyms — Advanced SSC CGL Tier 2 Set (W11 B1)', 'VOCAB_ANTONYMS_ADV_W11_B1', '[{"option_text": "Exuberant", "is_correct": false}, {"option_text": "Vivacious", "is_correct": false}, {"option_text": "Despondent", "is_correct": true}, {"option_text": "Effervescent", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2cf330b7-3b9f-562d-80cb-360f642ef724', 'Choose the antonym of PARSIMONIOUS.', NULL, 'C is correct. PARSIMONIOUS = unwilling to spend money or use resources; extremely frugal. Antonym = MUNIFICENT = larger in amount than is necessary or expected; very generous. Trap: Miserly (A), Niggardly (B), Penurious (D) are all synonyms of parsimonious (all mean stingy/mean with money). Munificent (lavishly generous) is the antonym.', 'HARD', 'Vocabulary', 'Antonyms — Advanced SSC CGL Tier 2 Set (W11 B1)', 'VOCAB_ANTONYMS_ADV_W11_B1', '[{"option_text": "Miserly", "is_correct": false}, {"option_text": "Niggardly", "is_correct": false}, {"option_text": "Munificent", "is_correct": true}, {"option_text": "Penurious", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('047aa27b-ff48-5d3a-ac7b-3da36693b26e', 'Choose the antonym of DIFFIDENT.', NULL, 'C is correct. DIFFIDENT = modest or shy, especially because of a lack of self-confidence. Antonym = ASSERTIVE = having or showing a confident and forceful personality. Trap: Timid (A), Bashful (B), Meek (D) are all synonyms of diffident (all suggest shyness/lack of confidence). Assertive (confident, self-assured) is the antonym.', 'MEDIUM', 'Vocabulary', 'Antonyms — Advanced SSC CGL Tier 2 Set (W11 B1)', 'VOCAB_ANTONYMS_ADV_W11_B1', '[{"option_text": "Timid", "is_correct": false}, {"option_text": "Bashful", "is_correct": false}, {"option_text": "Assertive", "is_correct": true}, {"option_text": "Meek", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b5a26bd9-f035-578d-a367-c7fdec08e355', 'Choose the antonym of GARRULOUS.', NULL, 'B is correct. GARRULOUS = excessively talkative, especially on trivial matters. Antonym = LACONIC = using very few words; brief and concise. Root of laconic: Laconians (Spartans) were famous for speaking briefly. Trap: Verbose (A), Loquacious (C), Voluble (D) are all synonyms of garrulous (all mean talkative). Laconic (brief/terse) is the antonym.', 'MEDIUM', 'Vocabulary', 'Antonyms — Advanced SSC CGL Tier 2 Set (W11 B1)', 'VOCAB_ANTONYMS_ADV_W11_B1', '[{"option_text": "Verbose", "is_correct": false}, {"option_text": "Laconic", "is_correct": true}, {"option_text": "Loquacious", "is_correct": false}, {"option_text": "Voluble", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d127a7ef-1987-54d1-9950-02221313d0bd', 'Choose the ANTONYM of SAGACIOUS:', NULL, 'B is correct. SAGACIOUS = having or showing keen mental discernment and good judgement; wise. Its antonym = OBTUSE (slow to understand; lacking sharpness of mind; dull). Prudent, perceptive, and judicious are all SYNONYMS of sagacious (all imply wisdom or good judgement). OBTUSE is the only antonym here, meaning mentally slow or stupid.', 'HARD', 'Vocabulary', 'Advanced Antonyms and Synonyms (W11 B2)', 'VOCAB_ANTONYMS_ADV_W11_B2', '[{"option_text": "Prudent", "is_correct": false}, {"option_text": "Obtuse", "is_correct": true}, {"option_text": "Perceptive", "is_correct": false}, {"option_text": "Judicious", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8e5011ee-e2e2-58db-b579-84195a795546', 'Choose the SYNONYM of OBDURATE:', NULL, 'C is correct. OBDURATE = stubbornly refusing to change one''s opinion or course of action. Synonyms: stubborn, intransigent, unyielding, inflexible, recalcitrant. ''Flexible'' and ''agreeable'' are antonyms. ''Compassionate'' is unrelated — obdurate has no connection to compassion (though an obdurate person might also be uncompassionate, they are different concepts). Trap: ''Flexible'' = direct antonym.', 'HARD', 'Vocabulary', 'Advanced Antonyms and Synonyms (W11 B2)', 'VOCAB_ANTONYMS_ADV_W11_B2', '[{"option_text": "Flexible", "is_correct": false}, {"option_text": "Compassionate", "is_correct": false}, {"option_text": "Stubborn", "is_correct": true}, {"option_text": "Agreeable", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ae0614dd-5ad3-5be1-a792-3c1e98245cd7', 'Choose the ANTONYM of LOQUACIOUS:', NULL, 'C is correct. LOQUACIOUS = tending to talk a great deal; talkative. Antonym = TACITURN = reserved or uncommunicative in speech; saying little. Garrulous and voluble are SYNONYMS of loquacious (all mean talkative). Verbose = using too many words (also a synonym of loquacious). Trap: All other options mean ''talkative'' in various degrees — only taciturn means ''quiet/reserved''.', 'MEDIUM', 'Vocabulary', 'Advanced Antonyms and Synonyms (W11 B2)', 'VOCAB_ANTONYMS_ADV_W11_B2', '[{"option_text": "Garrulous", "is_correct": false}, {"option_text": "Verbose", "is_correct": false}, {"option_text": "Taciturn", "is_correct": true}, {"option_text": "Voluble", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('68736342-6553-50ca-a29e-8fab57c5e696', 'Choose the SYNONYM of ACRIMONY:', NULL, 'B is correct. ACRIMONY = bitterness or ill feeling, especially in speech or manner. Synonyms: bitterness, rancour, hostility, asperity. ''The negotiations ended in acrimony'' = they ended bitterly. Antonyms: harmony, goodwill, cordiality. Trap: Harmony and sweetness are antonyms; generosity is unrelated.', 'MEDIUM', 'Vocabulary', 'Advanced Antonyms and Synonyms (W11 B2)', 'VOCAB_ANTONYMS_ADV_W11_B2', '[{"option_text": "Harmony", "is_correct": false}, {"option_text": "Bitterness", "is_correct": true}, {"option_text": "Sweetness", "is_correct": false}, {"option_text": "Generosity", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('27298f4f-19b9-5a32-90e1-a50a993dc06c', 'Choose the ANTONYM of MUNIFICENT:', NULL, 'D is correct. MUNIFICENT = larger or more generous than is usual or necessary; very generous. Antonym = NIGGARDLY = ungenerous with money; stingy; miserly. Generous, lavish, and bountiful are all SYNONYMS of munificent. NIGGARDLY is the only antonym in the list. Trap: ''Generous'' appears to be the opposite of what many expect, but it is a synonym; the antonym is niggardly/miserly.', 'HARD', 'Vocabulary', 'Advanced Antonyms and Synonyms (W11 B2)', 'VOCAB_ANTONYMS_ADV_W11_B2', '[{"option_text": "Generous", "is_correct": false}, {"option_text": "Lavish", "is_correct": false}, {"option_text": "Bountiful", "is_correct": false}, {"option_text": "Niggardly", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e8e80f02-e393-5981-91dd-7d4b88de1dc1', 'Choose the SYNONYM of EBULLIENT:', NULL, 'B is correct. EBULLIENT = cheerful and full of energy; exuberant. Synonyms: exuberant, buoyant, effervescent, vivacious. Antonyms: subdued, melancholic, depressed. ''Her ebullient personality lifted everyone''s spirits'' = her exuberant, energetic personality. Trap: Depressed, subdued, melancholic are all antonyms of ebullient — they describe the opposite of high energy and cheerfulness.', 'MEDIUM', 'Vocabulary', 'Advanced Antonyms and Synonyms (W11 B2)', 'VOCAB_ANTONYMS_ADV_W11_B2', '[{"option_text": "Depressed", "is_correct": false}, {"option_text": "Exuberant", "is_correct": true}, {"option_text": "Subdued", "is_correct": false}, {"option_text": "Melancholic", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7bf5489e-cffd-5b1d-af8a-99948b6ee6f3', 'Choose the ANTONYM of PAUCITY:', NULL, 'C is correct. PAUCITY = the presence of something in only small or insufficient quantities; scarcity. Antonym = ABUNDANCE (a very large quantity of something). Scarcity, dearth, and deficiency are all SYNONYMS of paucity. Only ABUNDANCE is the antonym. Trap: All three wrong options (scarcity, dearth, deficiency) mean ''shortage'' — same as paucity; only abundance means ''plenty''.', 'MEDIUM', 'Vocabulary', 'Advanced Antonyms and Synonyms (W11 B2)', 'VOCAB_ANTONYMS_ADV_W11_B2', '[{"option_text": "Scarcity", "is_correct": false}, {"option_text": "Dearth", "is_correct": false}, {"option_text": "Abundance", "is_correct": true}, {"option_text": "Deficiency", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6d9a1a03-1a7b-5696-9ae9-598f9643b513', 'Choose the SYNONYM of OSTENSIBLE:', NULL, 'C is correct. OSTENSIBLE = stated or appearing to be true, but not necessarily so; apparent (often used to suggest the stated reason is not the real one). ''The ostensible reason for the visit was to inspect the building, but the real purpose was a negotiation.'' Synonyms: apparent, professed, supposed, seeming. Antonyms: genuine, authentic, real. Trap: Genuine and authentic are antonyms (they mean truly what they appear to be, not merely seemingly so); hidden = not a synonym (ostensible = visible/stated, not hidden).', 'HARD', 'Vocabulary', 'Advanced Antonyms and Synonyms (W11 B2)', 'VOCAB_ANTONYMS_ADV_W11_B2', '[{"option_text": "Genuine", "is_correct": false}, {"option_text": "Hidden", "is_correct": false}, {"option_text": "Apparent", "is_correct": true}, {"option_text": "Authentic", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('acb16d27-2b22-524d-932a-8cfd4c0fc704', 'Choose the ANTONYM of INTREPID:', NULL, 'C is correct. INTREPID = fearless; adventurous (often the heading of Explorer/adventurer stories). Antonym = PUSILLANIMOUS = showing a lack of courage or determination; timid; faint-hearted. Brave, audacious, and valiant are all SYNONYMS of intrepid. PUSILLANIMOUS is a high-frequency SSC word meaning ''cowardly in a petty way''. Trap: All wrong options are synonyms of intrepid — the antonym is pusillanimous (or timid/cowardly).', 'HARD', 'Vocabulary', 'Advanced Antonyms and Synonyms (W11 B2)', 'VOCAB_ANTONYMS_ADV_W11_B2', '[{"option_text": "Brave", "is_correct": false}, {"option_text": "Audacious", "is_correct": false}, {"option_text": "Pusillanimous", "is_correct": true}, {"option_text": "Valiant", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0bc90d78-de3a-5753-bae0-8c60b280d33d', 'Choose the SYNONYM of IMPETUOUS:', NULL, 'B is correct. IMPETUOUS = acting or done quickly and without thought or care; impulsive. Synonyms: rash, impulsive, hasty, reckless. Antonyms: cautious, deliberate, measured, calculated. ''An impetuous decision'' = a rash, hasty decision without proper thought. Trap: Cautious, deliberate, and measured are antonyms of impetuous (they all imply careful, thoughtful action).', 'MEDIUM', 'Vocabulary', 'Advanced Antonyms and Synonyms (W11 B2)', 'VOCAB_ANTONYMS_ADV_W11_B2', '[{"option_text": "Cautious", "is_correct": false}, {"option_text": "Rash", "is_correct": true}, {"option_text": "Deliberate", "is_correct": false}, {"option_text": "Measured", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fad4486c-4c6a-5c0b-8267-fa355f164275', 'What is the best ANTONYM of IMPETUOUS?', NULL, 'B is correct. IMPETUOUS = acting or done quickly and without thought or care; rash; impulsive (Latin impetere = to attack). Its antonym must mean the opposite: DELIBERATE = done consciously and intentionally; careful and unhurried in considering options. ''An impetuous decision'' vs ''a deliberate decision''. Trap: ''courageous'' = brave (impetuous people are bold but not necessarily brave — different quality); ''energetic'' = full of energy (impetuous can be energetic, but energy is not the defining quality); ''optimistic'' = unrelated to decision-making speed/care.', 'MEDIUM', 'Vocabulary', 'Antonyms III — Advanced SSC CGL Words with Confusable Near-Synonyms as Distractors (W13 B1)', 'VOCAB_ANTONYMS_III_W13_B1', '[{"option_text": "courageous", "is_correct": false}, {"option_text": "deliberate", "is_correct": true}, {"option_text": "energetic", "is_correct": false}, {"option_text": "optimistic", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('eb84ac71-7e18-5e65-a046-2f7afd3314d2', 'What is the best ANTONYM of OBSEQUIOUS?', NULL, 'C is correct. OBSEQUIOUS = obedient or attentive to an excessive or servile degree; fawning; sycophantic (Latin obsequiosus = compliant). One who is obsequious submits excessively; the antonym should describe someone who dominates others: DOMINEERING = asserting one''s will over others in an arrogant way. The contrast: obsequious (over-submissive) ↔ domineering (over-assertive). Trap: ''humble'' = a positive quality vs obsequious (a negative trait of excessive servility); humble is close to obsequious in meaning, not opposite; ''generous'' = giving freely (unrelated to social submission/dominance dynamic).', 'MEDIUM', 'Vocabulary', 'Antonyms III — Advanced SSC CGL Words with Confusable Near-Synonyms as Distractors (W13 B1)', 'VOCAB_ANTONYMS_III_W13_B1', '[{"option_text": "humble", "is_correct": false}, {"option_text": "generous", "is_correct": false}, {"option_text": "domineering", "is_correct": true}, {"option_text": "talkative", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('535e3100-50e5-550a-a41d-4a3b431e8879', 'What is the best ANTONYM of SANGUINE?', NULL, 'B is correct. SANGUINE = optimistic or positive, especially in a difficult situation (Latin sanguineus = blood-red; historically blood = cheerful temperament in humorism). Its antonym: PESSIMISTIC = tending to see the worst aspect of things; expecting bad outcomes. Trap: ''bloodless'' = a trap for students who think ''sanguine'' means ''blood'' (it did historically) and pick the literal antonym — wrong usage; ''healthy'' = sanguine once meant ''ruddy/healthy-looking'' but its current and test-relevant meaning is ''optimistic''; ''excited'' = similar to sanguine in mood but not antonym.', 'MEDIUM', 'Vocabulary', 'Antonyms III — Advanced SSC CGL Words with Confusable Near-Synonyms as Distractors (W13 B1)', 'VOCAB_ANTONYMS_III_W13_B1', '[{"option_text": "healthy", "is_correct": false}, {"option_text": "pessimistic", "is_correct": true}, {"option_text": "bloodless", "is_correct": false}, {"option_text": "excited", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('70223f57-94c8-5f5e-a7fc-667c13af05ee', 'What is the best ANTONYM of INTREPID?', NULL, 'A is correct. INTREPID = fearless; adventurous; characterized by resolution and boldness (Latin intrepidus = not trembling). Antonym: COWARDLY = lacking courage; contemptibly fearful. Intrepid ↔ Cowardly (both about courage/fear). Synonyms of intrepid: dauntless, valiant, audacious, bold, undaunted. Antonyms: cowardly, timid, craven, pusillanimous. Trap: ''weak'' = physically weak (intrepid is about mental/emotional courage, not physical strength — a weak person can be intrepid); ''passive'' = inactive (intrepid involves action, but passive ≠ fearful).', 'MEDIUM', 'Vocabulary', 'Antonyms III — Advanced SSC CGL Words with Confusable Near-Synonyms as Distractors (W13 B1)', 'VOCAB_ANTONYMS_III_W13_B1', '[{"option_text": "cowardly", "is_correct": true}, {"option_text": "unintelligent", "is_correct": false}, {"option_text": "weak", "is_correct": false}, {"option_text": "passive", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('af67857c-f9b3-5916-93d3-13f030e58121', 'What is the best ANTONYM of PERFIDIOUS?', NULL, 'B is correct. PERFIDIOUS = deceitful and untrustworthy; guilty of betrayal; treacherous (Latin perfidia = faithlessness). Antonym: LOYAL = giving or showing firm and constant support to a person or institution; faithful. Perfidious = betrayer ↔ Loyal = faithful. Synonyms of perfidious: treacherous, faithless, disloyal, duplicitous, traitorous. Trap: ''fearless'' = sounds like it could pair with ''perfidious'' since both suggest risk-taking, but fearless relates to courage, not faithfulness; ''generous'' = unrelated to trustworthiness/betrayal spectrum.', 'MEDIUM', 'Vocabulary', 'Antonyms III — Advanced SSC CGL Words with Confusable Near-Synonyms as Distractors (W13 B1)', 'VOCAB_ANTONYMS_III_W13_B1', '[{"option_text": "fearless", "is_correct": false}, {"option_text": "loyal", "is_correct": true}, {"option_text": "generous", "is_correct": false}, {"option_text": "skilled", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d3da81bc-8b7c-5699-9d68-55ac9d068226', 'What is the best ANTONYM of DIFFIDENT?', NULL, 'C is correct. DIFFIDENT = modest or shy because of a lack of self-confidence (Latin diffidere = to mistrust). Antonym: CONFIDENT = feeling or showing confidence in oneself; self-assured. The di- prefix is not ''not different'' — it comes from Latin ''diffidere''. Trap: ''different'' = a classic false-cognate trap; students see ''diff-'' and think it''s the antonym of ''different'', but ''diffident'' has nothing to do with ''different''; ''indifferent'' = showing no interest (also unrelated to confidence); ''eloquent'' = persuasive in speech (related to speaking, not confidence level per se).', 'MEDIUM', 'Vocabulary', 'Antonyms III — Advanced SSC CGL Words with Confusable Near-Synonyms as Distractors (W13 B1)', 'VOCAB_ANTONYMS_III_W13_B1', '[{"option_text": "different", "is_correct": false}, {"option_text": "indifferent", "is_correct": false}, {"option_text": "confident", "is_correct": true}, {"option_text": "eloquent", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ef9cc42a-c893-59f2-bbfa-a25f8ec3a58d', 'What is the best ANTONYM of CLANDESTINE?', NULL, 'C is correct. CLANDESTINE = kept secret or done secretively, especially because illicit; covert (Latin clandestinus = secret). Antonym: OVERT = done openly; not concealed; visible; public (opposite of covert). Clandestine operation ↔ Overt operation. Word pair: covert/clandestine ↔ overt/open. Trap: ''secretive'' = a near-synonym of clandestine, not the antonym; ''violent'' = unrelated to secrecy vs. openness; ''hasty'' = done quickly (clandestine meetings can be hasty, but haste is not the defining quality of clandestine).', 'HARD', 'Vocabulary', 'Antonyms III — Advanced SSC CGL Words with Confusable Near-Synonyms as Distractors (W13 B1)', 'VOCAB_ANTONYMS_III_W13_B1', '[{"option_text": "secretive", "is_correct": false}, {"option_text": "violent", "is_correct": false}, {"option_text": "overt", "is_correct": true}, {"option_text": "hasty", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('139003ef-04c7-5e1d-8bb3-e80c9fda4c79', 'What is the best ANTONYM of BELLIGERENT?', NULL, 'B is correct. BELLIGERENT = hostile and aggressive; inclined to start quarrels or wars (Latin belligerare = to wage war). Antonym: AMICABLE = having a spirit of friendliness; without serious disagreement; peaceful. Belligerent ↔ Amicable/Peaceful. Synonyms of belligerent: aggressive, combative, pugnacious, bellicose, quarrelsome. Trap: ''intelligent'' = a false-friend trap (''belligerent'' ends in ''-ent'', similar to ''intelligent''); ''powerful'' = strength is different from hostility; ''stubborn'' = inflexible (belligerent includes hostility, which stubborn doesn''t fully capture).', 'HARD', 'Vocabulary', 'Antonyms III — Advanced SSC CGL Words with Confusable Near-Synonyms as Distractors (W13 B1)', 'VOCAB_ANTONYMS_III_W13_B1', '[{"option_text": "intelligent", "is_correct": false}, {"option_text": "amicable", "is_correct": true}, {"option_text": "powerful", "is_correct": false}, {"option_text": "stubborn", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ad4cd319-2a27-5a75-9e2c-6e5e93178653', 'What is the best ANTONYM of PROLIFIC?', NULL, 'B is correct. PROLIFIC = producing many works, results, or offspring; highly productive (Latin proles = offspring + facere = to make). ''A prolific author'' = one who writes many books. Antonym: UNPRODUCTIVE = not producing or giving results; barren; yielding little. Prolific ↔ Unproductive/Barren. Trap: ''famous'' = well-known (prolific writers are often famous, but fame ≠ the defining quality — an obscure prolific writer exists); ''harmful'' = damaging (unrelated to quantity of output); ''rigid'' = inflexible (unrelated to productivity).', 'HARD', 'Vocabulary', 'Antonyms III — Advanced SSC CGL Words with Confusable Near-Synonyms as Distractors (W13 B1)', 'VOCAB_ANTONYMS_III_W13_B1', '[{"option_text": "famous", "is_correct": false}, {"option_text": "unproductive", "is_correct": true}, {"option_text": "harmful", "is_correct": false}, {"option_text": "rigid", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b11b1951-2f1a-5b8d-8c1d-1ebbe08996c1', 'What is the best ANTONYM of RETICENT?', NULL, 'C is correct. RETICENT = not revealing one''s thoughts or feelings readily; reserved in communication; inclined to be silent (Latin reticere = to keep silent). Antonym: COMMUNICATIVE = willing to talk or impart information; open and talkative. Reticent = reluctant to speak ↔ Communicative = eager/willing to speak. Synonyms of reticent: reserved, taciturn, uncommunicative, tight-lipped, introverted. Trap: ''relevant'' = a near-homophone trap (''reticent'' vs ''relevant''); ''obstinate'' = stubborn (reticent people can seem stubborn but stubbornness ≠ the core meaning); ''generous'' = giving (no direct connection to communication/silence).', 'HARD', 'Vocabulary', 'Antonyms III — Advanced SSC CGL Words with Confusable Near-Synonyms as Distractors (W13 B1)', 'VOCAB_ANTONYMS_III_W13_B1', '[{"option_text": "relevant", "is_correct": false}, {"option_text": "obstinate", "is_correct": false}, {"option_text": "communicative", "is_correct": true}, {"option_text": "generous", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
