INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a23d8498-b094-5bc2-9439-2b9072b00096', 'Choose the antonym of OSTENTATIOUS.', NULL, 'B is correct. OSTENTATIOUS = making an exaggerated display of wealth or knowledge to impress others. Antonym = UNPRETENTIOUS = modest, not trying to impress. Trap: Flamboyant, Pompous, Extravagant are all synonyms (showy/elaborate) — the distractor cluster is the synonym group.', 'EASY', 'Vocabulary', 'Antonyms — Third Advanced Set (W10 B2)', 'VOCAB_ANTONYMS_SET3_W10_B2', '[{"option_text": "Flamboyant", "is_correct": false}, {"option_text": "Unpretentious", "is_correct": true}, {"option_text": "Pompous", "is_correct": false}, {"option_text": "Extravagant", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a13da8f3-b8c6-508f-bb4f-f7957dd9a695', 'Choose the antonym of VINDICTIVE.', NULL, 'B is correct. VINDICTIVE = having or showing a strong or unreasonable desire for revenge. Antonym = MERCIFUL = showing compassion/forgiveness, especially to an offender. Trap: Spiteful, Resentful, Vengeful are all synonyms of vindictive — each indicates desire to cause harm or seek revenge.', 'EASY', 'Vocabulary', 'Antonyms — Third Advanced Set (W10 B2)', 'VOCAB_ANTONYMS_SET3_W10_B2', '[{"option_text": "Spiteful", "is_correct": false}, {"option_text": "Merciful", "is_correct": true}, {"option_text": "Resentful", "is_correct": false}, {"option_text": "Vengeful", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('19b24e66-73df-53ce-8385-b7d919bedba5', 'Choose the antonym of PERFIDIOUS.', NULL, 'C is correct. PERFIDIOUS = guilty of betrayal or treachery. Antonym = FAITHFUL = remaining loyal and true. Trap: Treacherous, Deceitful, Duplicitous are synonyms (all mean deceptive or disloyal). Root trick: ''perfid-'' comes from Latin ''perfidia'' = bad faith; its antonym must denote good faith = faithful.', 'MEDIUM', 'Vocabulary', 'Antonyms — Third Advanced Set (W10 B2)', 'VOCAB_ANTONYMS_SET3_W10_B2', '[{"option_text": "Treacherous", "is_correct": false}, {"option_text": "Deceitful", "is_correct": false}, {"option_text": "Faithful", "is_correct": true}, {"option_text": "Duplicitous", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6690be16-57b5-5f41-aceb-df5f02018233', 'Choose the antonym of EPHEMERAL.', NULL, 'C is correct. EPHEMERAL = lasting for a very short time. Antonym = ENDURING = lasting over a long period; permanent. Trap: Fleeting, Transitory, Momentary are all synonyms (all mean short-lived). The ''-epi-'' (on) + ''-hemera-'' (day) Greek roots help: ephemeral = lasts only one day. Opposite = lasts much longer = enduring/perpetual.', 'MEDIUM', 'Vocabulary', 'Antonyms — Third Advanced Set (W10 B2)', 'VOCAB_ANTONYMS_SET3_W10_B2', '[{"option_text": "Fleeting", "is_correct": false}, {"option_text": "Transitory", "is_correct": false}, {"option_text": "Enduring", "is_correct": true}, {"option_text": "Momentary", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3d52d8e1-8384-531d-8841-268345f007a9', 'Choose the antonym of IGNOBLE.', NULL, 'D is correct. IGNOBLE = not honourable in character or purpose; base or vile. Antonym = HONOURABLE = bringing or worthy of honour and respect. Trap: Dishonourable and Contemptible are synonyms; Magnanimous (generous in forgiving) is not the direct antonym of ignoble, though it is a positive trait.', 'MEDIUM', 'Vocabulary', 'Antonyms — Third Advanced Set (W10 B2)', 'VOCAB_ANTONYMS_SET3_W10_B2', '[{"option_text": "Dishonourable", "is_correct": false}, {"option_text": "Contemptible", "is_correct": false}, {"option_text": "Magnanimous", "is_correct": false}, {"option_text": "Honourable", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e6edd118-e743-5d7e-8ebb-d1042419869e', 'Choose the antonym of VERBOSE.', NULL, 'C is correct. VERBOSE = using or expressed in more words than are needed; long-winded. Antonym = TERSE = sparing in the use of words; brief and concise. Trap: Wordy, Garrulous, Loquacious are all synonyms of verbose (all mean talking too much). SSC frequently tests the synonyms and antonyms of VERBOSE — also know: laconic, pithy, succinct as antonyms.', 'MEDIUM', 'Vocabulary', 'Antonyms — Third Advanced Set (W10 B2)', 'VOCAB_ANTONYMS_SET3_W10_B2', '[{"option_text": "Wordy", "is_correct": false}, {"option_text": "Garrulous", "is_correct": false}, {"option_text": "Terse", "is_correct": true}, {"option_text": "Loquacious", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ecad2d85-f129-5d53-8a2f-5d2747b9cdcf', 'Choose the antonym of IMPERIOUS.', NULL, 'C is correct. IMPERIOUS = assuming power or authority without justification; arrogant and domineering. Antonym = HUMBLE = having or showing a modest opinion of one''s own importance. Trap: Commanding, Overbearing, Domineering are all synonyms (varying degrees of imperious behaviour). Root trick: ''imperium'' = power/command; anti-meaning = not commanding = humble.', 'HARD', 'Vocabulary', 'Antonyms — Third Advanced Set (W10 B2)', 'VOCAB_ANTONYMS_SET3_W10_B2', '[{"option_text": "Commanding", "is_correct": false}, {"option_text": "Overbearing", "is_correct": false}, {"option_text": "Humble", "is_correct": true}, {"option_text": "Domineering", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('82140c41-bd59-5b99-bdff-b30484dc0412', 'Choose the antonym of SYCOPHANTIC.', NULL, 'C is correct. SYCOPHANTIC = behaving or acting in an obsequious way in order to gain advantage; excessively flattering. Antonym = FORTHRIGHT = direct and outspoken; frank (the opposite of using flattery to please). Trap: Obsequious, Fawning, Servile are all synonyms — they all describe excessive deference or flattery. Note: do not confuse ''forthright'' with ''forceful'' — both start with ''f'' but mean different things.', 'HARD', 'Vocabulary', 'Antonyms — Third Advanced Set (W10 B2)', 'VOCAB_ANTONYMS_SET3_W10_B2', '[{"option_text": "Obsequious", "is_correct": false}, {"option_text": "Fawning", "is_correct": false}, {"option_text": "Forthright", "is_correct": true}, {"option_text": "Servile", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b2b408d8-1062-5bff-b42a-5bd7514e7549', 'Choose the antonym of MENDACIOUS.', NULL, 'B is correct. MENDACIOUS = not telling the truth; lying. Antonym = VERACIOUS = speaking or representing the truth; truthful. Root trick: ''mendaci-'' = lie (Latin), ''verac-'' = truth (Latin, also root of ''verify''). Trap: Deceptive, Fraudulent, Duplicitous are synonyms of mendacious (all involve dishonesty). SSC tests mendacious/veracious pair regularly in Tier 2.', 'HARD', 'Vocabulary', 'Antonyms — Third Advanced Set (W10 B2)', 'VOCAB_ANTONYMS_SET3_W10_B2', '[{"option_text": "Deceptive", "is_correct": false}, {"option_text": "Veracious", "is_correct": true}, {"option_text": "Fraudulent", "is_correct": false}, {"option_text": "Duplicitous", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('07e68fa6-d466-54da-b9ba-aead485648c6', 'Choose the antonym of ACRIMONIOUS.', NULL, 'C is correct. ACRIMONIOUS = angry and bitter (especially of a speech, argument, or manner). Antonym = CORDIAL = warm and friendly. Trap: Bitter, Rancorous, Caustic are synonyms (acrimonious = bitter; rancorous = resentful; caustic = sharp/biting). Context clue: acrimonious disputes vs. cordial relations — a classic SSC contrast pair.', 'HARD', 'Vocabulary', 'Antonyms — Third Advanced Set (W10 B2)', 'VOCAB_ANTONYMS_SET3_W10_B2', '[{"option_text": "Bitter", "is_correct": false}, {"option_text": "Rancorous", "is_correct": false}, {"option_text": "Cordial", "is_correct": true}, {"option_text": "Caustic", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ac2f20db-e839-5e52-a909-a70e7a4876d1', 'Choose the SYNONYM of COGENT:', NULL, 'B is correct. COGENT = clear, logical, and convincing; a cogent argument is one that is powerfully persuasive. Synonyms: compelling, convincing, persuasive, valid. Antonym: weak, unconvincing. Trap: ''Vague'' and ''irrelevant'' are antonyms of cogent; ''Weak'' is the antonym (a cogent argument is strong, not weak).', 'HARD', 'Vocabulary', 'Antonyms and Synonyms Mixed — SSC CGL Vocabulary (W11 B2)', 'VOCAB_ANTONYMS_SYNONYMS_MIXED_W11_B2', '[{"option_text": "Weak", "is_correct": false}, {"option_text": "Convincing", "is_correct": true}, {"option_text": "Vague", "is_correct": false}, {"option_text": "Irrelevant", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('62f08ecc-689b-5233-b99a-1f333efa0dba', 'Choose the ANTONYM of BELLIGERENT:', NULL, 'C is correct. BELLIGERENT = hostile and aggressive; eager to fight or argue. Antonym = peaceful, pacifist, amicable. Trap: Aggressive, Warlike, Hostile are all synonyms of belligerent; only Peaceful is the antonym.', 'MEDIUM', 'Vocabulary', 'Antonyms and Synonyms Mixed — SSC CGL Vocabulary (W11 B2)', 'VOCAB_ANTONYMS_SYNONYMS_MIXED_W11_B2', '[{"option_text": "Aggressive", "is_correct": false}, {"option_text": "Warlike", "is_correct": false}, {"option_text": "Peaceful", "is_correct": true}, {"option_text": "Hostile", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f315bc00-8b26-580d-b036-5b4647c747c6', 'Choose the SYNONYM of TACITURN:', NULL, 'B is correct. TACITURN = habitually silent; reluctant to talk. Synonyms: reserved, reticent, uncommunicative, withdrawn. Trap: Talkative, Expressive, Outgoing are all antonyms of taciturn — they describe someone who talks a lot. Reserved is the correct synonym (choosing not to express feelings openly).', 'MEDIUM', 'Vocabulary', 'Antonyms and Synonyms Mixed — SSC CGL Vocabulary (W11 B2)', 'VOCAB_ANTONYMS_SYNONYMS_MIXED_W11_B2', '[{"option_text": "Talkative", "is_correct": false}, {"option_text": "Reserved", "is_correct": true}, {"option_text": "Expressive", "is_correct": false}, {"option_text": "Outgoing", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7fc8b3be-1e64-570c-a324-b56f50e8c232', 'Choose the ANTONYM of LOQUACIOUS:', NULL, 'C is correct. LOQUACIOUS = tending to talk a great deal; talkative. Antonym = TACITURN (habitually silent and reserved). Trap: Verbose (using too many words), Garrulous (excessively talkative), Voluble (speaking at length easily) are ALL synonyms of loquacious. Only Taciturn is the antonym. This is a hard question because all distractors are synonyms in a field where synonyms cluster.', 'HARD', 'Vocabulary', 'Antonyms and Synonyms Mixed — SSC CGL Vocabulary (W11 B2)', 'VOCAB_ANTONYMS_SYNONYMS_MIXED_W11_B2', '[{"option_text": "Verbose", "is_correct": false}, {"option_text": "Garrulous", "is_correct": false}, {"option_text": "Taciturn", "is_correct": true}, {"option_text": "Voluble", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('40da27bf-b7d4-52f4-bc94-872876e2f4b4', 'Choose the SYNONYM of INTREPID:', NULL, 'C is correct. INTREPID = fearless and adventurous; remarkably brave in the face of danger. Synonyms: fearless, bold, dauntless, audacious, valiant. Trap: Timid and Cowardly are antonyms; Cautious = careful (not the same as fearless).', 'MEDIUM', 'Vocabulary', 'Antonyms and Synonyms Mixed — SSC CGL Vocabulary (W11 B2)', 'VOCAB_ANTONYMS_SYNONYMS_MIXED_W11_B2', '[{"option_text": "Timid", "is_correct": false}, {"option_text": "Cowardly", "is_correct": false}, {"option_text": "Fearless", "is_correct": true}, {"option_text": "Cautious", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c7edd3ac-9d73-501e-9e3a-13fb0c37e1e9', 'Choose the ANTONYM of PARSIMONIOUS:', NULL, 'C is correct. PARSIMONIOUS = excessively unwilling to spend money; extremely stingy. Antonym = Generous (willing to give freely). Trap: Miserly, Frugal, Thrifty are all related to not spending money and are near-synonyms of parsimonious. Generous is the only antonym. Note: Frugal and Thrifty have a positive connotation (careful with money) while Parsimonious has a negative connotation (excessively stingy).', 'MEDIUM', 'Vocabulary', 'Antonyms and Synonyms Mixed — SSC CGL Vocabulary (W11 B2)', 'VOCAB_ANTONYMS_SYNONYMS_MIXED_W11_B2', '[{"option_text": "Miserly", "is_correct": false}, {"option_text": "Frugal", "is_correct": false}, {"option_text": "Generous", "is_correct": true}, {"option_text": "Thrifty", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('022ac1b0-6c4e-5cf6-a30e-b7b13a19120b', 'Choose the SYNONYM of ELUCIDATE:', NULL, 'B is correct. ELUCIDATE = to make clear; to explain or clarify. Example: ''Could you elucidate your point?'' Synonyms: clarify, explain, illuminate, expound. Trap: Confuse, Obscure, Complicate are all antonyms of elucidate (they add confusion rather than clarity). Root: Latin ''elucidare'' = to make light/clear (''lux'' = light).', 'MEDIUM', 'Vocabulary', 'Antonyms and Synonyms Mixed — SSC CGL Vocabulary (W11 B2)', 'VOCAB_ANTONYMS_SYNONYMS_MIXED_W11_B2', '[{"option_text": "Confuse", "is_correct": false}, {"option_text": "Clarify", "is_correct": true}, {"option_text": "Obscure", "is_correct": false}, {"option_text": "Complicate", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5e84150f-9109-522c-b0d4-5b4f1075aa39', 'Choose the ANTONYM of TRANSIENT:', NULL, 'C is correct. TRANSIENT = lasting only for a short time; temporary; fleeting. Antonym = Permanent (lasting forever or a very long time). Trap: Fleeting, Momentary, Ephemeral are all synonyms of transient (all mean brief/short-lived). Permanent is the correct antonym.', 'MEDIUM', 'Vocabulary', 'Antonyms and Synonyms Mixed — SSC CGL Vocabulary (W11 B2)', 'VOCAB_ANTONYMS_SYNONYMS_MIXED_W11_B2', '[{"option_text": "Fleeting", "is_correct": false}, {"option_text": "Momentary", "is_correct": false}, {"option_text": "Permanent", "is_correct": true}, {"option_text": "Ephemeral", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b3d8d99f-0956-5368-b9be-fc0afda2c7b3', 'Choose the SYNONYM of LACONIC:', NULL, 'C is correct. LACONIC = using very few words; brief and concise in speech or expression. Origin: from the ancient Spartans (Laconians), who were famously terse. Synonyms: brief, concise, terse, pithy, succinct. Trap: Verbose (using too many words), Wordy (long-winded), Elaborate (detailed and complicated) are all antonyms of laconic.', 'HARD', 'Vocabulary', 'Antonyms and Synonyms Mixed — SSC CGL Vocabulary (W11 B2)', 'VOCAB_ANTONYMS_SYNONYMS_MIXED_W11_B2', '[{"option_text": "Verbose", "is_correct": false}, {"option_text": "Wordy", "is_correct": false}, {"option_text": "Brief", "is_correct": true}, {"option_text": "Elaborate", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('17783b7f-97b7-5427-b7de-01d6d538c9c6', 'Choose the ANTONYM of GREGARIOUS:', NULL, 'C is correct. GREGARIOUS = fond of company; sociable; enjoying the company of others. Antonym = Reclusive (avoiding the company of others; hermit-like). Trap: Sociable, Outgoing, Friendly are synonyms of gregarious. Reclusive is the antonym (a recluse avoids social contact). Root: Latin ''gregarius'' = belonging to a flock/herd (''grex'' = flock).', 'MEDIUM', 'Vocabulary', 'Antonyms and Synonyms Mixed — SSC CGL Vocabulary (W11 B2)', 'VOCAB_ANTONYMS_SYNONYMS_MIXED_W11_B2', '[{"option_text": "Sociable", "is_correct": false}, {"option_text": "Outgoing", "is_correct": false}, {"option_text": "Reclusive", "is_correct": true}, {"option_text": "Friendly", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('27972c9a-3209-5307-bfbc-264fe5c48d27', 'Choose the word most OPPOSITE in meaning to: ABUNDANT', NULL, 'B is correct. ABUNDANT = existing or available in large quantities. Its antonym is SCARCE = deficient in quantity, hard to find. Trap: ''Plentiful'' and ''Excessive'' are synonyms of Abundant; ''Sufficient'' means just enough — not the direct opposite of large quantities.', 'EASY', 'Vocabulary', 'Antonyms — SSC CGL Level Word Pairs (W10)', 'VOCAB_ANTONYMS_W10', '[{"option_text": "Plentiful", "is_correct": false}, {"option_text": "Scarce", "is_correct": true}, {"option_text": "Excessive", "is_correct": false}, {"option_text": "Sufficient", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4ccd767b-a4b2-5ce9-b72f-e9978ca453ab', 'Choose the word most OPPOSITE in meaning to: VICTORY', NULL, 'B is correct. VICTORY = winning, success in a contest. Its direct antonym is DEFEAT = failure, being beaten. Trap: ''Triumph'' and ''Success'' are synonyms of Victory; ''Achievement'' is a broader positive accomplishment — not the opposite of winning a contest.', 'EASY', 'Vocabulary', 'Antonyms — SSC CGL Level Word Pairs (W10)', 'VOCAB_ANTONYMS_W10', '[{"option_text": "Triumph", "is_correct": false}, {"option_text": "Defeat", "is_correct": true}, {"option_text": "Success", "is_correct": false}, {"option_text": "Achievement", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('eb828e47-d688-5d79-8cfd-e3c4cf18a3b5', 'Choose the word most OPPOSITE in meaning to: ELOQUENT', NULL, 'C is correct. ELOQUENT = fluent, persuasive, and powerfully expressive in speech. INARTICULATE = unable to express thoughts clearly in words — the direct opposite. Trap: ''Articulate'' and ''Fluent'' are synonyms of Eloquent; ''Verbose'' means using too many words (wordy), which is the opposite in style but not meaning.', 'MEDIUM', 'Vocabulary', 'Antonyms — SSC CGL Level Word Pairs (W10)', 'VOCAB_ANTONYMS_W10', '[{"option_text": "Articulate", "is_correct": false}, {"option_text": "Fluent", "is_correct": false}, {"option_text": "Inarticulate", "is_correct": true}, {"option_text": "Verbose", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('ecff170b-7bd6-5953-b5ca-5aaaed9b3201', 'Choose the word most OPPOSITE in meaning to: BENEVOLENT', NULL, 'C is correct. BENEVOLENT = well-wishing, kind, and generous in spirit (bene = well + vole = wish). MALEVOLENT = having or showing a wish to do evil (male = ill + vole = wish) — a perfect antonym by Latin prefix reversal. Trap: ''Kind'', ''Generous'', and ''Charitable'' are all synonyms of Benevolent.', 'MEDIUM', 'Vocabulary', 'Antonyms — SSC CGL Level Word Pairs (W10)', 'VOCAB_ANTONYMS_W10', '[{"option_text": "Kind", "is_correct": false}, {"option_text": "Generous", "is_correct": false}, {"option_text": "Malevolent", "is_correct": true}, {"option_text": "Charitable", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('260e1ff6-4677-5635-a00c-4b3531fe2a00', 'Choose the word most OPPOSITE in meaning to: TRANSIENT', NULL, 'D is correct. TRANSIENT = passing away quickly, not lasting (from Latin transire = to pass over). Its antonym is PERMANENT = lasting or intended to last indefinitely. Trap: ''Brief'', ''Temporary'', and ''Fleeting'' are all synonyms of Transient — this is a classic SSC trap where three similar words are offered as distractors.', 'MEDIUM', 'Vocabulary', 'Antonyms — SSC CGL Level Word Pairs (W10)', 'VOCAB_ANTONYMS_W10', '[{"option_text": "Brief", "is_correct": false}, {"option_text": "Temporary", "is_correct": false}, {"option_text": "Fleeting", "is_correct": false}, {"option_text": "Permanent", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('eac90fa6-d11a-5420-9468-ad24bf2f04dd', 'Choose the word most OPPOSITE in meaning to: LETHARGY', NULL, 'C is correct. LETHARGY = a lack of energy and enthusiasm, sluggishness. VIGOUR = physical and mental energy, strength, and activeness — the direct antonym. Trap: ''Laziness'', ''Sloth'', and ''Apathy'' (lack of enthusiasm) are all synonymous with Lethargy, not antonymous.', 'MEDIUM', 'Vocabulary', 'Antonyms — SSC CGL Level Word Pairs (W10)', 'VOCAB_ANTONYMS_W10', '[{"option_text": "Laziness", "is_correct": false}, {"option_text": "Sloth", "is_correct": false}, {"option_text": "Vigour", "is_correct": true}, {"option_text": "Apathy", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7dac3ef8-dbf4-52c4-950b-981f1e03d047', 'Choose the word most OPPOSITE in meaning to: OBSEQUIOUS', NULL, 'C is correct. OBSEQUIOUS = excessively submissive and eager to please, fawning and cringing. Its antonym is ASSERTIVE = confident, self-assured, and willing to defend one''s own rights and views directly. Trap: ''Servile'', ''Sycophantic'', and ''Flattering'' are all synonyms of Obsequious. Knowing ''obsequious'' is essential — it appears in SSC CGL comprehension and antonym questions.', 'HARD', 'Vocabulary', 'Antonyms — SSC CGL Level Word Pairs (W10)', 'VOCAB_ANTONYMS_W10', '[{"option_text": "Servile", "is_correct": false}, {"option_text": "Sycophantic", "is_correct": false}, {"option_text": "Assertive", "is_correct": true}, {"option_text": "Flattering", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('635bda45-bc79-53f0-8cdd-a4e256af2509', 'Choose the word most OPPOSITE in meaning to: LOQUACIOUS', NULL, 'D is correct. LOQUACIOUS = very talkative, fond of talking at length. TACITURN = habitually silent and reserved, saying little — the precise antonym. Trap: ''Talkative'', ''Garrulous'' (excessively talkative), and ''Verbose'' (using too many words) are all synonyms of Loquacious. Students who don''t know ''taciturn'' often pick ''verbose'' by elimination error.', 'HARD', 'Vocabulary', 'Antonyms — SSC CGL Level Word Pairs (W10)', 'VOCAB_ANTONYMS_W10', '[{"option_text": "Talkative", "is_correct": false}, {"option_text": "Garrulous", "is_correct": false}, {"option_text": "Verbose", "is_correct": false}, {"option_text": "Taciturn", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('88f2f1a5-9a9f-54d9-84ee-c709920328eb', 'Choose the word most OPPOSITE in meaning to: EPHEMERAL', NULL, 'D is correct. EPHEMERAL = lasting for a very short time, momentary (from Greek ephemeros = lasting only a day). EVERLASTING = lasting forever, eternal — its antonym. Trap: ''Temporary'', ''Brief'', and ''Transient'' are all synonyms of Ephemeral. The pattern of three synonyms as distractors is a classic SSC format that rewards knowing the target word.', 'HARD', 'Vocabulary', 'Antonyms — SSC CGL Level Word Pairs (W10)', 'VOCAB_ANTONYMS_W10', '[{"option_text": "Temporary", "is_correct": false}, {"option_text": "Brief", "is_correct": false}, {"option_text": "Transient", "is_correct": false}, {"option_text": "Everlasting", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0c638fda-d835-52f1-80be-85b4ce57f9d8', 'Choose the word most OPPOSITE in meaning to: AUDACIOUS', NULL, 'C is correct. AUDACIOUS = showing willingness to take bold risks; daring, brave, and sometimes recklessly so. TIMID = lacking courage, easily frightened, shrinking from bold action — the direct antonym. Trap: ''Brave'', ''Bold'', and ''Daring'' are all synonyms of Audacious. Students must recognise that TIMID is the only contrasting option.', 'HARD', 'Vocabulary', 'Antonyms — SSC CGL Level Word Pairs (W10)', 'VOCAB_ANTONYMS_W10', '[{"option_text": "Brave", "is_correct": false}, {"option_text": "Bold", "is_correct": false}, {"option_text": "Timid", "is_correct": true}, {"option_text": "Daring", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b9f274b6-ca2b-51e4-9977-584c7ffcdfe3', 'Choose the word most OPPOSITE in meaning to: PERNICIOUS', NULL, 'C is correct. PERNICIOUS = having a harmful effect, especially in a gradual or subtle way. Its antonym is BENEFICIAL = producing good results; favourable. Trap: ''Harmful'', ''Destructive'', and ''Lethal'' are all synonyms of pernicious. Root: Latin ''pernicies'' = ruin/destruction (per = thoroughly + nex = death).', 'MEDIUM', 'Vocabulary', 'Antonyms — Advanced SSC CGL Word Pairs (W10 B2)', 'VOCAB_ANTONYMS_W10_B2', '[{"option_text": "Harmful", "is_correct": false}, {"option_text": "Destructive", "is_correct": false}, {"option_text": "Beneficial", "is_correct": true}, {"option_text": "Lethal", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('12bbf908-d186-56a4-b455-a186d9771d12', 'Choose the word most OPPOSITE in meaning to: VERBOSE', NULL, 'C is correct. VERBOSE = using or containing more words than necessary; long-winded. CONCISE = giving a lot of information clearly in a few words; brief but comprehensive. Trap: ''Wordy'', ''Garrulous'', and ''Loquacious'' are all synonyms of verbose. ''Concise'' is the precise antonym — quality expression with minimal words.', 'MEDIUM', 'Vocabulary', 'Antonyms — Advanced SSC CGL Word Pairs (W10 B2)', 'VOCAB_ANTONYMS_W10_B2', '[{"option_text": "Wordy", "is_correct": false}, {"option_text": "Garrulous", "is_correct": false}, {"option_text": "Concise", "is_correct": true}, {"option_text": "Loquacious", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1f6fb208-5e48-5e2e-9a43-69963ee7dfa5', 'Choose the word most OPPOSITE in meaning to: OSTENTATIOUS', NULL, 'C is correct. OSTENTATIOUS = displaying wealth or skill in a way intended to impress or attract notice; showy. UNPRETENTIOUS = not attempting to impress; modest, unassuming. Trap: ''Showy'', ''Flamboyant'', and ''Flaunting'' are all synonyms of ostentatious. ''Modest'' would also be an acceptable antonym.', 'MEDIUM', 'Vocabulary', 'Antonyms — Advanced SSC CGL Word Pairs (W10 B2)', 'VOCAB_ANTONYMS_W10_B2', '[{"option_text": "Showy", "is_correct": false}, {"option_text": "Flamboyant", "is_correct": false}, {"option_text": "Unpretentious", "is_correct": true}, {"option_text": "Flaunting", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('cba0a0e5-9344-5649-af5d-d119f7e1a366', 'Choose the word most OPPOSITE in meaning to: BENIGN', NULL, 'C is correct. BENIGN = gentle and kindly; (of a tumour) not harmful to health. MALIGNANT = very harmful; (of a tumour) tending to be severe and become progressively worse. The medical antonym pair benign/malignant is frequently tested by SSC. Trap: ''Gentle'', ''Harmless'', and ''Kind'' are synonyms of benign.', 'MEDIUM', 'Vocabulary', 'Antonyms — Advanced SSC CGL Word Pairs (W10 B2)', 'VOCAB_ANTONYMS_W10_B2', '[{"option_text": "Gentle", "is_correct": false}, {"option_text": "Harmless", "is_correct": false}, {"option_text": "Malignant", "is_correct": true}, {"option_text": "Kind", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a1970e74-c746-5b9c-bce4-61f4208e7013', 'Choose the word most OPPOSITE in meaning to: LUCID', NULL, 'D is correct. LUCID = expressed clearly; easy to understand; (of a person) able to think clearly. OBSCURE = not clearly expressed or easily understood; unclear. Trap: ''Clear'', ''Transparent'', and ''Intelligible'' are all synonyms of lucid. The three synonyms as options is the classic SSC trap for this question.', 'HARD', 'Vocabulary', 'Antonyms — Advanced SSC CGL Word Pairs (W10 B2)', 'VOCAB_ANTONYMS_W10_B2', '[{"option_text": "Clear", "is_correct": false}, {"option_text": "Transparent", "is_correct": false}, {"option_text": "Intelligible", "is_correct": false}, {"option_text": "Obscure", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dc25b8e4-1f3f-5363-9b11-099691385959', 'Choose the word most OPPOSITE in meaning to: ACRIMONIOUS', NULL, 'C is correct. ACRIMONIOUS = (of speech or manner) angry and bitter. AMICABLE = having a spirit of friendliness; without serious disagreement. ''An amicable settlement'' vs. ''an acrimonious dispute'' — these are natural antonyms. Trap: ''Bitter'', ''Caustic'', and ''Hostile'' are all synonyms of acrimonious.', 'HARD', 'Vocabulary', 'Antonyms — Advanced SSC CGL Word Pairs (W10 B2)', 'VOCAB_ANTONYMS_W10_B2', '[{"option_text": "Bitter", "is_correct": false}, {"option_text": "Caustic", "is_correct": false}, {"option_text": "Amicable", "is_correct": true}, {"option_text": "Hostile", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f451eb4e-ed18-59ad-825d-93bd2dd5fa39', 'Choose the word most OPPOSITE in meaning to: OBDURATE', NULL, 'C is correct. OBDURATE = stubbornly refusing to change one''s opinion or course of action. YIELDING = giving way under pressure; flexible, accommodating. Trap: ''Stubborn'', ''Intractable'', and ''Inflexible'' are all synonyms of obdurate. Root: Latin ''obdurare'' = to harden against (ob = against + durus = hard).', 'HARD', 'Vocabulary', 'Antonyms — Advanced SSC CGL Word Pairs (W10 B2)', 'VOCAB_ANTONYMS_W10_B2', '[{"option_text": "Stubborn", "is_correct": false}, {"option_text": "Intractable", "is_correct": false}, {"option_text": "Yielding", "is_correct": true}, {"option_text": "Inflexible", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('814e6d01-efee-5009-a714-37925b4750d8', 'Choose the word most OPPOSITE in meaning to: PRODIGAL', NULL, 'C is correct. PRODIGAL = spending money or resources freely and recklessly; wasteful. FRUGAL = sparing or economical with regard to money; careful not to waste. The ''Prodigal Son'' parable is a classic reference point. Trap: ''Extravagant'', ''Wasteful'', and ''Lavish'' are all synonyms of prodigal.', 'HARD', 'Vocabulary', 'Antonyms — Advanced SSC CGL Word Pairs (W10 B2)', 'VOCAB_ANTONYMS_W10_B2', '[{"option_text": "Extravagant", "is_correct": false}, {"option_text": "Wasteful", "is_correct": false}, {"option_text": "Frugal", "is_correct": true}, {"option_text": "Lavish", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f0e6b0d9-1f4a-54fb-914e-c5016349d9eb', 'Choose the word most OPPOSITE in meaning to: IMPETUOUS', NULL, 'D is correct. IMPETUOUS = acting or done quickly and without thought or care; impulsive. DELIBERATE = done consciously and intentionally; careful and unhurried. Trap: ''Rash'', ''Hasty'', and ''Impulsive'' are all synonyms of impetuous — the classic SSC trap of three synonyms as distractors. The antonym captures the quality of careful, thoughtful action.', 'HARD', 'Vocabulary', 'Antonyms — Advanced SSC CGL Word Pairs (W10 B2)', 'VOCAB_ANTONYMS_W10_B2', '[{"option_text": "Rash", "is_correct": false}, {"option_text": "Hasty", "is_correct": false}, {"option_text": "Impulsive", "is_correct": false}, {"option_text": "Deliberate", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('81b019db-4e4f-5361-a7fa-6fca8bf7160f', 'Choose the word most OPPOSITE in meaning to: INDIGENOUS', NULL, 'D is correct. INDIGENOUS = originating or occurring naturally in a particular place; native. EXOTIC = originating in or characteristic of a distant foreign country; not native. Trap: ''Native'', ''Local'', and ''Endemic'' are all synonyms of indigenous. ''Foreign'' or ''Alien'' would also be acceptable antonyms.', 'HARD', 'Vocabulary', 'Antonyms — Advanced SSC CGL Word Pairs (W10 B2)', 'VOCAB_ANTONYMS_W10_B2', '[{"option_text": "Native", "is_correct": false}, {"option_text": "Local", "is_correct": false}, {"option_text": "Endemic", "is_correct": false}, {"option_text": "Exotic", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2e66ae49-c520-5b07-b400-5a5f0dc55cfc', 'Choose the ANTONYM of BENEVOLENT:', NULL, 'A is correct. Benevolent = wishing good. Malevolent = wishing evil (mal = bad). Indifferent means uncaring, not actively hostile — too mild to be the antonym.', 'EASY', 'Vocabulary', 'Antonyms (W9)', 'VOCAB_ANTONYMS_W9', '[{"option_text": "Malevolent", "is_correct": true}, {"option_text": "Indifferent", "is_correct": false}, {"option_text": "Generous", "is_correct": false}, {"option_text": "Compassionate", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('77c1621a-71bf-5405-931d-53093f10f2fa', 'Choose the ANTONYM of COURAGEOUS:', NULL, 'B is correct. Courageous = brave. Its antonym is cowardly (lacking courage). Reckless means carelessly brave; bold and daring are synonyms, not antonyms.', 'EASY', 'Vocabulary', 'Antonyms (W9)', 'VOCAB_ANTONYMS_W9', '[{"option_text": "Reckless", "is_correct": false}, {"option_text": "Cowardly", "is_correct": true}, {"option_text": "Bold", "is_correct": false}, {"option_text": "Daring", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('93334c09-27c8-5912-ab78-cf20b0539b96', 'Choose the ANTONYM of ANCIENT:', NULL, 'C is correct. Ancient = very old. Modern = of the present or recent time. ''Old'', ''historical'', and ''bygone'' all relate to the past — they are synonyms or near-synonyms, not antonyms.', 'EASY', 'Vocabulary', 'Antonyms (W9)', 'VOCAB_ANTONYMS_W9', '[{"option_text": "Old", "is_correct": false}, {"option_text": "Historical", "is_correct": false}, {"option_text": "Modern", "is_correct": true}, {"option_text": "Bygone", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('869ec4f4-b87c-5f4a-85bf-d03e295b4b47', 'Choose the ANTONYM of VERBOSE:', NULL, 'C is correct. Verbose = using more words than needed. Concise = expressing much in few words. Talkative and eloquent relate to speaking ability, not word economy.', 'MEDIUM', 'Vocabulary', 'Antonyms (W9)', 'VOCAB_ANTONYMS_W9', '[{"option_text": "Talkative", "is_correct": false}, {"option_text": "Eloquent", "is_correct": false}, {"option_text": "Concise", "is_correct": true}, {"option_text": "Fluent", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7f9e3029-0663-5a33-8f45-04c5f320117c', 'Choose the ANTONYM of ZENITH:', NULL, 'C is correct. Zenith = the highest point. Nadir = the lowest point (directly opposite in astronomy). Peak, pinnacle, and apex are synonyms of zenith.', 'MEDIUM', 'Vocabulary', 'Antonyms (W9)', 'VOCAB_ANTONYMS_W9', '[{"option_text": "Peak", "is_correct": false}, {"option_text": "Pinnacle", "is_correct": false}, {"option_text": "Nadir", "is_correct": true}, {"option_text": "Apex", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0e2f76b1-3a3f-5c6b-94c9-46615748233c', 'Choose the ANTONYM of SPURIOUS:', NULL, 'B is correct. Spurious = not genuine, counterfeit. Genuine = authentic. Fake, doubtful, and dubious are all synonyms or near-synonyms of spurious.', 'MEDIUM', 'Vocabulary', 'Antonyms (W9)', 'VOCAB_ANTONYMS_W9', '[{"option_text": "Fake", "is_correct": false}, {"option_text": "Genuine", "is_correct": true}, {"option_text": "Doubtful", "is_correct": false}, {"option_text": "Dubious", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('005979af-81e4-54e9-9c0a-9bd03b4389b9', 'Choose the ANTONYM of BELLIGERENT:', NULL, 'C is correct. Belligerent = hostile and aggressive, eager to fight. Peaceful (or pacifist) is its antonym. Aggressive, hostile, and pugnacious are synonyms.', 'MEDIUM', 'Vocabulary', 'Antonyms (W9)', 'VOCAB_ANTONYMS_W9', '[{"option_text": "Aggressive", "is_correct": false}, {"option_text": "Hostile", "is_correct": false}, {"option_text": "Peaceful", "is_correct": true}, {"option_text": "Pugnacious", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0d052af7-d910-59da-95f5-53fbf8b3ce04', 'Choose the ANTONYM of OPAQUE:', NULL, 'C is correct. Opaque = not allowing light to pass through (or not easily understood). Transparent = allowing light through (or easily understood). Dark, solid, and dense are unrelated or partially overlapping.', 'MEDIUM', 'Vocabulary', 'Antonyms (W9)', 'VOCAB_ANTONYMS_W9', '[{"option_text": "Dark", "is_correct": false}, {"option_text": "Solid", "is_correct": false}, {"option_text": "Transparent", "is_correct": true}, {"option_text": "Dense", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('606e593d-ae3b-5559-a293-840166ce0388', 'Choose the ANTONYM of PENURY:', NULL, 'C is correct. Penury = extreme poverty. Affluence = great wealth. Scarcity, deprivation, and poverty are synonyms of penury, not antonyms.', 'HARD', 'Vocabulary', 'Antonyms (W9)', 'VOCAB_ANTONYMS_W9', '[{"option_text": "Scarcity", "is_correct": false}, {"option_text": "Deprivation", "is_correct": false}, {"option_text": "Affluence", "is_correct": true}, {"option_text": "Poverty", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('6cd503d1-606a-51e8-a959-4cbc439fadca', 'Choose the ANTONYM of SYCOPHANT:', NULL, 'B is correct. A sycophant is someone who uses excessive flattery to gain favour. A critic is someone who offers honest, often negative evaluation — the opposite behaviour. Flatterer and admirer are synonyms; supporter is too neutral.', 'HARD', 'Vocabulary', 'Antonyms (W9)', 'VOCAB_ANTONYMS_W9', '[{"option_text": "Flatterer", "is_correct": false}, {"option_text": "Critic", "is_correct": true}, {"option_text": "Supporter", "is_correct": false}, {"option_text": "Admirer", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('5c7b3b5b-bdcc-5a76-9ae7-38fee860da35', 'Choose the correct collocation: ''She _______ a decision to resign from her job.''', NULL, 'B is correct. ''MAKE a decision'' is the correct collocation in English. We say: make a decision, make a mistake, make progress, make an effort. Trap: ''Do'' collocates with: do homework, do business, do damage — not ''decision''; ''Take'' collocates with: take action, take a break, take a risk — ''take a decision'' is common in British English but ''make a decision'' is the standard universal form and the expected answer in SSC exams; ''Have'' does not collocate with ''decision'' meaningfully.', 'EASY', 'Vocabulary', 'Collocations — Common Verb-Noun and Adjective-Noun Pairs (W11 B1)', 'VOCAB_COLLOCATIONS_W11_B1', '[{"option_text": "did", "is_correct": false}, {"option_text": "made", "is_correct": true}, {"option_text": "took", "is_correct": false}, {"option_text": "had", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('33a140ae-2869-56a2-9461-e61569807dd3', 'Choose the correct collocation: ''The medicine had a _______ effect on the patient.''', NULL, 'D is correct. ''MARKED effect'' = a clearly noticeable/significant effect. This is the standard collocation used in medical and formal contexts. Trap: ''Profound effect'' is also used but with more abstract/intellectual subjects (''had a profound effect on his thinking''); ''Strong effect'' is possible but less idiomatic than ''marked''; ''Deep effect'' is not a standard collocation in formal English. In formal prose, ''marked'' = distinctly noticeable (examiner''s favourite).', 'HARD', 'Vocabulary', 'Collocations — Common Verb-Noun and Adjective-Noun Pairs (W11 B1)', 'VOCAB_COLLOCATIONS_W11_B1', '[{"option_text": "deep", "is_correct": false}, {"option_text": "strong", "is_correct": false}, {"option_text": "profound", "is_correct": false}, {"option_text": "marked", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d622105c-550c-5715-87d7-048f00a96d79', 'Choose the correct collocation: ''The company _______ a loss of ₹5 crore in the last quarter.''', NULL, 'C is correct. ''SUFFER a loss'' is the standard collocation in business and financial contexts. Similarly: suffer a defeat, suffer an injury, suffer consequences. Trap: ''Made a loss'' — we ''make a profit'' but not typically ''make a loss'' (British English occasionally says ''make a loss'' but standard usage favours ''incur'' or ''suffer''); ''Did a loss'' is completely wrong; ''Had a loss'' is informal and not standard. SSC exams test ''suffer a loss'' as the correct form.', 'MEDIUM', 'Vocabulary', 'Collocations — Common Verb-Noun and Adjective-Noun Pairs (W11 B1)', 'VOCAB_COLLOCATIONS_W11_B1', '[{"option_text": "did", "is_correct": false}, {"option_text": "made", "is_correct": false}, {"option_text": "suffered", "is_correct": true}, {"option_text": "had", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('93cedde3-6173-5a7a-8d8c-4b4ed4c4c132', 'Choose the correct collocation: ''The politician _______ a speech at the rally.''', NULL, 'B is correct. ''DELIVER a speech'' is the correct formal collocation. Also valid: ''give a speech'' and ''make a speech''. However, ''deliver'' is the most formal and is frequently expected in SSC English. Trap: ''Told a speech'' — we ''tell a story/joke'' but not a ''speech''; ''Said a speech'' — we ''say words'' but not ''say a speech''; ''Made a speech'' is also correct in informal contexts but ''delivered'' is the preferred formal collocation.', 'EASY', 'Vocabulary', 'Collocations — Common Verb-Noun and Adjective-Noun Pairs (W11 B1)', 'VOCAB_COLLOCATIONS_W11_B1', '[{"option_text": "made", "is_correct": false}, {"option_text": "delivered", "is_correct": true}, {"option_text": "told", "is_correct": false}, {"option_text": "said", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('33819dad-c0c7-5dec-a6e0-f41a79c8fbdf', 'Choose the correct collocation: ''She _______ great importance to punctuality.''', NULL, 'C is correct. ''ATTACH importance to something'' = to regard something as important. This is a fixed idiomatic collocation in formal English. Trap: ''Give importance to'' is common in informal and Indian English but not the standard idiom; ''Put importance on'' is non-standard; ''Hold importance'' is also non-standard. The examiner tests this distinction: in standard British English, the correct form is ''attach importance/significance to''.', 'HARD', 'Vocabulary', 'Collocations — Common Verb-Noun and Adjective-Noun Pairs (W11 B1)', 'VOCAB_COLLOCATIONS_W11_B1', '[{"option_text": "gave", "is_correct": false}, {"option_text": "put", "is_correct": false}, {"option_text": "attached", "is_correct": true}, {"option_text": "held", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b50a3bf3-8987-5352-b7b4-c357bc51da5e', 'Choose the correct collocation: ''He _______ his promise and returned the money.''', NULL, 'B is correct. ''KEEP a promise'' = to do what one has promised. ''Kept his promise'' is the natural English collocation. Trap: ''Fulfilled his promise'' is also acceptable and means completing the terms of a promise, but ''kept'' is the more natural everyday collocation tested in SSC; ''Did a promise'' is wrong; ''Maintained a promise'' is not standard. Antonym: ''BREAK a promise'' (not ''un-keep'').', 'MEDIUM', 'Vocabulary', 'Collocations — Common Verb-Noun and Adjective-Noun Pairs (W11 B1)', 'VOCAB_COLLOCATIONS_W11_B1', '[{"option_text": "did", "is_correct": false}, {"option_text": "kept", "is_correct": true}, {"option_text": "fulfilled", "is_correct": false}, {"option_text": "maintained", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1faf40ad-37df-5375-a2b4-8134a53d36be', 'Choose the correct collocation: ''The earthquake _______ widespread damage across the region.''', NULL, 'C is correct. ''CAUSE damage'' is the standard collocation with natural disasters. Other strong collocations: cause harm, cause problems, cause disruption. Trap: ''Do damage'' is also a valid collocation (''did a lot of damage''), but ''cause damage'' is more formal and standard; ''Make damage'' is incorrect; ''Take damage'' — in gaming/action contexts but not standard English for natural phenomena. When in doubt between ''do'' and ''cause'' in SSC, ''cause'' is more formal and almost always right for disasters.', 'EASY', 'Vocabulary', 'Collocations — Common Verb-Noun and Adjective-Noun Pairs (W11 B1)', 'VOCAB_COLLOCATIONS_W11_B1', '[{"option_text": "made", "is_correct": false}, {"option_text": "did", "is_correct": false}, {"option_text": "caused", "is_correct": true}, {"option_text": "took", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e0a3f96d-94e3-5f44-b77b-c8f928843734', 'Choose the correct collocation: ''The minister _______ an inquiry into the corruption allegations.''', NULL, 'C is correct. ''ORDER an inquiry'' = to officially instruct that an investigation be carried out. This is the precise formal collocation used in legal and political contexts. Trap: ''Started an inquiry'' is grammatically possible but not the formal bureaucratic/legal collocation; ''Initiated an inquiry'' is also acceptable and used in formal writing — however, ''ordered'' specifically implies authority/command which fits ''minister''; ''Created an inquiry'' is not standard.', 'MEDIUM', 'Vocabulary', 'Collocations — Common Verb-Noun and Adjective-Noun Pairs (W11 B1)', 'VOCAB_COLLOCATIONS_W11_B1', '[{"option_text": "started", "is_correct": false}, {"option_text": "initiated", "is_correct": false}, {"option_text": "ordered", "is_correct": true}, {"option_text": "created", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('bd84e815-326d-5b45-8f55-023166477a40', 'Choose the correct collocation: ''The director _______ a new record at the box office.''', NULL, 'C is correct. ''BREAK a record'' = to surpass a previous best performance. This is a fixed collocation — you ''break'' records, not ''make'' or ''create'' them. After breaking, you ''set a new record'' or ''hold a record''. Collocations: break a record / set a record / hold a record / break into / break down / break up. Trap: ''Made a record'' = to produce a music recording (different meaning); ''Did a record'' = wrong; ''Created a record'' = grammatically wrong in this context.', 'MEDIUM', 'Vocabulary', 'Collocations — Common Verb-Noun and Adjective-Noun Pairs (W11 B1)', 'VOCAB_COLLOCATIONS_W11_B1', '[{"option_text": "did", "is_correct": false}, {"option_text": "made", "is_correct": false}, {"option_text": "broke", "is_correct": true}, {"option_text": "created", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d2c002b9-6e6e-54f3-ab92-65f9569352f9', 'Choose the correct collocation: ''The new policy is expected to _______ a major impact on employment rates.''', NULL, 'C is correct. ''HAVE an impact'' is the correct collocation. Impact specifically collocates with ''have'': have an impact, have an effect, have a bearing. Trap: ''Cause an impact'' is not standard (we say ''cause damage/harm'' but not ''cause an impact''); ''Create an impact'' is Indian English usage but not standard formal English; ''Do an impact'' is completely wrong. Memorise: HAVE an impact/effect/influence; CAUSE damage/harm/problems; MAKE progress/effort/mistake.', 'MEDIUM', 'Vocabulary', 'Collocations — Common Verb-Noun and Adjective-Noun Pairs (W11 B1)', 'VOCAB_COLLOCATIONS_W11_B1', '[{"option_text": "cause", "is_correct": false}, {"option_text": "create", "is_correct": false}, {"option_text": "have", "is_correct": true}, {"option_text": "do", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dba3e0d3-08db-504a-9c35-47fddfb70105', 'Choose the correct collocation: The mayor will ___ a press conference tomorrow to address the water crisis.', NULL, 'C is correct. The correct collocation is HOLD a press conference / HOLD a meeting / HOLD an event. You HOLD (not make/do/give) scheduled formal events. Similarly: hold a rally, hold an election, hold a seminar. Trap: ''give a press conference'' — while ''give a speech/presentation'' is valid, ''give a press conference'' is non-standard; the fixed collocation is ''hold''. ''Make a press conference'' = incorrect. ''Do a press conference'' = informal and non-standard.', 'MEDIUM', 'Vocabulary', 'Collocations — Verb + Noun, Adjective + Noun Fixed Pairs for SSC CGL (W13 B1)', 'VOCAB_COLLOCATIONS_W13_B1', '[{"option_text": "make", "is_correct": false}, {"option_text": "do", "is_correct": false}, {"option_text": "hold", "is_correct": true}, {"option_text": "give", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4b5ec732-3390-508a-af4c-c34a7535db1d', 'Choose the correct collocation: The new tax regulation will ___ effect from the first of April.', NULL, 'B is correct. TAKE EFFECT = to begin to operate or be implemented (the law/policy becomes active). Fixed collocation: a law/rule/medicine ''takes effect''. Other TAKE collocations: take action, take responsibility, take a risk, take notice, take turns. Trap: ''make effect'' = incorrect; ''bring effect'' = non-standard (the phrase is ''bring into effect'' which is acceptable, but not ''bring effect'' alone); ''do effect'' = completely wrong.', 'MEDIUM', 'Vocabulary', 'Collocations — Verb + Noun, Adjective + Noun Fixed Pairs for SSC CGL (W13 B1)', 'VOCAB_COLLOCATIONS_W13_B1', '[{"option_text": "make", "is_correct": false}, {"option_text": "take", "is_correct": true}, {"option_text": "do", "is_correct": false}, {"option_text": "bring", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d7bec14b-e033-5e3e-810d-345a3727d2ce', 'Choose the correct collocation: The new research has ___ light on the causes of the mysterious ancient extinction.', NULL, 'B is correct. SHED LIGHT ON = to make something clearer; to illuminate an issue. This is the standard collocation in formal written English (essays, articles, editorials). ''Cast light on'' is also used but less formal. ''Throw light on'' is another variant. In SSC English, the standard answer expected is SHED. Careful: all three (shed, throw, cast) appear in different dictionaries as acceptable, but SSC typically marks SHED as the primary collocation. Trap: ''given light on'' = completely incorrect (you don''t ''give light on'' a problem).', 'MEDIUM', 'Vocabulary', 'Collocations — Verb + Noun, Adjective + Noun Fixed Pairs for SSC CGL (W13 B1)', 'VOCAB_COLLOCATIONS_W13_B1', '[{"option_text": "thrown", "is_correct": false}, {"option_text": "shed", "is_correct": true}, {"option_text": "cast", "is_correct": false}, {"option_text": "given", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('60f682ca-2df2-5284-a2f2-9148d96e6662', 'Choose the correct collocation: The government must ___ awareness about the dangers of antibiotic resistance among the general public.', NULL, 'C is correct. RAISE AWARENESS = to increase public consciousness of an issue. RAISE is transitive — it takes an object. ''Raise'' collocations: raise awareness, raise funds, raise a question, raise an objection, raise the bar, raise eyebrows. Trap: ''rise'' = intransitive (prices rise, standards rise — no object). ''Arise'' = to appear or come into existence (a problem arises — intransitive). ''Rouse'' = to awaken or provoke emotion (rouse a crowd, rouse suspicion) — while similar, ''rouse awareness'' is non-standard. Only RAISE AWARENESS is the fixed collocation.', 'MEDIUM', 'Vocabulary', 'Collocations — Verb + Noun, Adjective + Noun Fixed Pairs for SSC CGL (W13 B1)', 'VOCAB_COLLOCATIONS_W13_B1', '[{"option_text": "rise", "is_correct": false}, {"option_text": "arise", "is_correct": false}, {"option_text": "raise", "is_correct": true}, {"option_text": "rouse", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9bb78419-abf3-59fd-8a5a-47532acf8637', 'Choose the correct collocation: Despite the setbacks, the team managed to ___ a victory against all odds.', NULL, 'C is correct. SNATCH A VICTORY = to unexpectedly win at the last moment, especially when winning seems unlikely. This collocation perfectly captures ''against all odds'' (unexpected outcome). Other uses: ''snatch defeat from the jaws of victory'' (famous idiom). Trap: ''make a victory'' = non-standard; ''do a victory'' = incorrect; ''take a victory'' = ''take a win'' is informal sports usage but ''take a victory'' is less standard than ''snatch a victory'' when the context specifies ''against all odds''.', 'MEDIUM', 'Vocabulary', 'Collocations — Verb + Noun, Adjective + Noun Fixed Pairs for SSC CGL (W13 B1)', 'VOCAB_COLLOCATIONS_W13_B1', '[{"option_text": "do", "is_correct": false}, {"option_text": "make", "is_correct": false}, {"option_text": "snatch", "is_correct": true}, {"option_text": "take", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d2b01cf3-497e-59bf-b0e7-510edbfd4a43', 'Choose the correct collocation: The journalist was known for ___ a grudge against any politician who refused to speak to her.', NULL, 'C is correct. HOLD A GRUDGE = to continue to feel resentment or anger towards someone; the fixed collocation. ''Hold a grudge'' is the dominant form in written English (formal/journalistic). Note: ''bear a grudge'' is also correct and used in formal English (''bear no grudge''). ''Keep a grudge'' = non-standard. ''Carry a grudge'' = occasionally used but less standard than ''hold''. In SSC, ''HOLD a grudge'' is the preferred answer. Trap: ''bearing a grudge'' is also acceptable but when given as an option alongside ''holding'', SSC typically marks ''holding'' as the primary collocation.', 'MEDIUM', 'Vocabulary', 'Collocations — Verb + Noun, Adjective + Noun Fixed Pairs for SSC CGL (W13 B1)', 'VOCAB_COLLOCATIONS_W13_B1', '[{"option_text": "keeping", "is_correct": false}, {"option_text": "carrying", "is_correct": false}, {"option_text": "holding", "is_correct": true}, {"option_text": "bearing", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b22229b8-6a9a-526d-b5eb-ee3b8cb7413c', 'Choose the correct collocation: The new infrastructure investment is expected to ___ rise to thousands of jobs in rural areas.', NULL, 'B is correct. GIVE RISE TO = to cause something to happen; to be the origin or source of something. Fixed phrase: ''give rise to + noun''. Examples: ''The decision gave rise to widespread protests.'' ''Warm temperatures give rise to more frequent storms.'' Trap: ''take rise to'' = incorrect (not a standard phrase); ''make rise to'' = incorrect; ''bring rise to'' = non-standard. ''Bring about'' is valid but ''bring rise to'' is not. Only GIVE RISE TO is the fixed expression.', 'HARD', 'Vocabulary', 'Collocations — Verb + Noun, Adjective + Noun Fixed Pairs for SSC CGL (W13 B1)', 'VOCAB_COLLOCATIONS_W13_B1', '[{"option_text": "take", "is_correct": false}, {"option_text": "give", "is_correct": true}, {"option_text": "make", "is_correct": false}, {"option_text": "bring", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e1c8a004-e304-55fa-bcb8-11e2f453c8a4', 'Choose the correct collocation: The CEO''s announcement ___ a wave of panic among investors, leading to a sharp drop in share prices.', NULL, 'D is correct. TRIGGER A WAVE OF PANIC = to set off or cause a sudden surge of fear. ''Trigger'' collocates naturally with strong, sudden reactions: trigger a reaction, trigger panic, trigger a response, trigger an alarm. The metaphor of ''wave'' (a wave of panic, a wave of protests) pairs with ''triggered'' because waves follow from a sudden cause. Trap: ''created panic'' = acceptable in general use but ''created a wave of panic'' is less idiomatic than ''triggered''; ''made a wave'' = incorrect; ''did panic'' = completely wrong.', 'HARD', 'Vocabulary', 'Collocations — Verb + Noun, Adjective + Noun Fixed Pairs for SSC CGL (W13 B1)', 'VOCAB_COLLOCATIONS_W13_B1', '[{"option_text": "made", "is_correct": false}, {"option_text": "did", "is_correct": false}, {"option_text": "created", "is_correct": false}, {"option_text": "triggered", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('e33d0044-8f7e-518c-9801-fd752ab89733', 'Choose the correct collocation: The defence minister assured that the government would ___ no stone unturned to bring the perpetrators to justice.', NULL, 'B is correct. LEAVE NO STONE UNTURNED = to try every possible means; to make every effort. This is a fixed idiom that must be used in its EXACT form. ''Leave no stone unturned'' = standard expression meaning to do everything possible. The verb is ALWAYS ''leave'' in this idiom — no substitution is allowed. Trap: ''keep no stone unturned'' = grammatically sounds similar but is NOT the correct idiom; the correct form is ''leave''. This tests whether students know the idiom''s exact wording, which is a common SSC distinction test.', 'HARD', 'Vocabulary', 'Collocations — Verb + Noun, Adjective + Noun Fixed Pairs for SSC CGL (W13 B1)', 'VOCAB_COLLOCATIONS_W13_B1', '[{"option_text": "keep", "is_correct": false}, {"option_text": "leave", "is_correct": true}, {"option_text": "put", "is_correct": false}, {"option_text": "let", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('623aea69-240d-5f31-b8c1-637f4ec982cb', 'Choose the correct collocation: The investigative report ___ serious doubts about the integrity of the procurement process.', NULL, 'B is correct. RAISE DOUBTS = to cause someone to have doubts; to introduce reasons for scepticism. RAISE collocates with: raise doubts, raise concerns, raise questions, raise objections, raise eyebrows, raise suspicion. These are all situations where an issue is being put forward (raised) for consideration. Trap: ''create doubts'' = while ''create'' can introduce things, ''raise doubts'' is the established collocation in formal/journalistic English; ''make doubts'' = incorrect; ''brought doubts'' = ''bring'' would need ''brought up doubts'' or ''brought doubts to light'' but not ''brought doubts'' alone.', 'HARD', 'Vocabulary', 'Collocations — Verb + Noun, Adjective + Noun Fixed Pairs for SSC CGL (W13 B1)', 'VOCAB_COLLOCATIONS_W13_B1', '[{"option_text": "made", "is_correct": false}, {"option_text": "raised", "is_correct": true}, {"option_text": "created", "is_correct": false}, {"option_text": "brought", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
