INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d94c7a65-793d-5ff2-8448-2b969059b846', 'Choose the pair that best expresses the same relationship as: AUTHOR : BOOK', NULL, 'A is correct. AUTHOR creates a BOOK (creator → creation). Similarly, ARTIST creates a PAINTING (creator → creation). Trap: Reader : Library = user → place (different relationship); Editor : Newspaper = curator/modifier → publication (not creator in the same direct sense — an editor edits but doesn''t create from scratch); Printer : Press = operator → tool (different).', 'EASY', 'Vocabulary', 'Word Pairs — Analogy and Relationship (W11 B2)', 'VOCAB_WORD_PAIRS_III_W11_B2', '[{"option_text": "Artist : Painting", "is_correct": true}, {"option_text": "Reader : Library", "is_correct": false}, {"option_text": "Editor : Newspaper", "is_correct": false}, {"option_text": "Printer : Press", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('65623eeb-b1d1-550a-95c5-eaf3bab5c2f7', 'Choose the pair that best expresses the same relationship as: STETHOSCOPE : DOCTOR', NULL, 'B is correct. STETHOSCOPE is the professional TOOL that symbolises/is used by a DOCTOR. Similarly, GAVEL is the tool that symbolises/is used by a JUDGE. Relationship: tool → professional who uses it symbolically. Trap: Knife : Chef = chef uses a knife, but a knife is not the professional symbol of a chef (many professions use knives); Scale : Weight = instrument : unit (different relationship).', 'MEDIUM', 'Vocabulary', 'Word Pairs — Analogy and Relationship (W11 B2)', 'VOCAB_WORD_PAIRS_III_W11_B2', '[{"option_text": "Knife : Chef", "is_correct": false}, {"option_text": "Gavel : Judge", "is_correct": true}, {"option_text": "Pen : Ink", "is_correct": false}, {"option_text": "Scale : Weight", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('3cfac12a-3983-5a98-bce4-fb6fdf564f3c', 'Choose the pair that best expresses the same relationship as: TIMID : BOLD', NULL, 'C is correct. TIMID and BOLD are ANTONYMS (opposites). Among the options, GLOOMY and CHEERFUL are also antonyms. Trap: Cowardly : Brave = antonyms ✓ BUT the question asks for the SAME RELATIONSHIP TYPE and degree — TIMID:BOLD is near-identical in meaning to COWARDLY:BRAVE. Wait — TIMID means shy/easily frightened and BOLD means confident/daring, which is very close to COWARDLY:BRAVE. However, GLOOMY:CHEERFUL is about mood, not courage. Both C and A seem to work... A=Cowardly:Brave has the closest semantic match to Timid:Bold. But wait — ''timid'' ≠ ''cowardly''; timid = shy/hesitant, cowardly = lacking bravery. I should mark A=Cowardly:Brave. Let me reconsider: B=Swift:Rapid (synonyms, wrong relationship); D=Tiny:Small (synonyms, wrong); A=Cowardly:Brave (antonyms, closer semantic match); C=Gloomy:Cheerful (antonyms). Both A and C are antonym pairs. The best parallel to TIMID:BOLD is GLOOMY:CHEERFUL because both pairs contrast emotional/behavioral states without a hierarchy. SSC would mark C=Gloomy:Cheerful as the better answer since cowardly/brave implies a stronger moral dimension vs timid/bold which is more temperament-based. I''ll keep C as correct.', 'MEDIUM', 'Vocabulary', 'Word Pairs — Analogy and Relationship (W11 B2)', 'VOCAB_WORD_PAIRS_III_W11_B2', '[{"option_text": "Cowardly : Brave", "is_correct": false}, {"option_text": "Swift : Rapid", "is_correct": false}, {"option_text": "Gloomy : Cheerful", "is_correct": true}, {"option_text": "Tiny : Small", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('357ca365-ccea-5350-83fb-4b9f8a8cdcd0', 'Choose the pair that best expresses the same relationship as: CALF : COW', NULL, 'A is correct. CALF is the young of a COW (young animal → adult female animal). PUPPY is the young of a DOG (young animal → adult animal). Relationship: young → adult of same species. Trap: All options show young-adult pairs; however, ''dog'' can be male or female (like ''cow'' is specifically female cattle). ''Kitten:Cat'', ''Fawn:Deer'', ''Chick:Hen'' are also valid young-adult pairs. Among them, ''Puppy:Dog'' is the most direct parallel since both ''calf:cow'' and ''puppy:dog'' use the most common species names. All four are young-adult relationships — SSC typically accepts A as the most straightforward parallel.', 'EASY', 'Vocabulary', 'Word Pairs — Analogy and Relationship (W11 B2)', 'VOCAB_WORD_PAIRS_III_W11_B2', '[{"option_text": "Puppy : Dog", "is_correct": true}, {"option_text": "Kitten : Cat", "is_correct": false}, {"option_text": "Fawn : Deer", "is_correct": false}, {"option_text": "Chick : Hen", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('7cb39320-ec8e-50e3-9e3f-79b7fbf5280e', 'Choose the pair that best expresses the same relationship as: SURGEON : SCALPEL', NULL, 'A is correct. SURGEON uses a SCALPEL as a cutting tool of their trade. CARPENTER uses a SAW as a cutting tool of their trade. Relationship: professional → cutting/precision tool used in their work. Trap: Painter : Canvas = professional → surface worked on (not a tool); Teacher : Classroom = professional → workplace (not a tool); Soldier : Uniform = professional → attire (not a tool).', 'MEDIUM', 'Vocabulary', 'Word Pairs — Analogy and Relationship (W11 B2)', 'VOCAB_WORD_PAIRS_III_W11_B2', '[{"option_text": "Carpenter : Saw", "is_correct": true}, {"option_text": "Painter : Canvas", "is_correct": false}, {"option_text": "Teacher : Classroom", "is_correct": false}, {"option_text": "Soldier : Uniform", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('0f7365d1-1bf1-5457-8ffb-c9c8f7f6cc79', 'Choose the pair that best expresses the same relationship as: DROUGHT : FLOOD', NULL, 'C is correct. DROUGHT = extreme lack of water; FLOOD = extreme excess of water. The relationship is: severe deficiency ↔ severe excess of the same resource. SCARCITY = extreme lack; ABUNDANCE = extreme excess. This mirrors the drought:flood relationship (deficiency:excess extremes). Trap: War:Peace = conflict vs absence-of-conflict (not the same deficiency:excess pattern); Famine:Surplus = close but ''surplus'' implies enough and extra, not ''flooding/overwhelming excess''; Hot:Cold = temperature extremes, not deficiency:excess of one thing.', 'HARD', 'Vocabulary', 'Word Pairs — Analogy and Relationship (W11 B2)', 'VOCAB_WORD_PAIRS_III_W11_B2', '[{"option_text": "War : Peace", "is_correct": false}, {"option_text": "Famine : Surplus", "is_correct": false}, {"option_text": "Scarcity : Abundance", "is_correct": true}, {"option_text": "Hot : Cold", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c0387ef4-ded7-56ec-99c0-221b7b418a93', 'Choose the pair that best expresses the same relationship as: ARCHIPELAGO : ISLANDS', NULL, 'A is correct. ARCHIPELAGO = a group/collection of ISLANDS (collective noun → what it consists of). FOREST = a large area consisting of TREES (collective term → what it consists of). Relationship: collective entity → the individual units it is composed of. Trap: Ocean : Fish = a body of water that contains fish (container → contained creature, different relationship); Mountain : Height = object → property (different relationship); Desert : Sand = environment → constituent material (similar but less precise — a desert is defined by aridity not just sand).', 'HARD', 'Vocabulary', 'Word Pairs — Analogy and Relationship (W11 B2)', 'VOCAB_WORD_PAIRS_III_W11_B2', '[{"option_text": "Forest : Trees", "is_correct": true}, {"option_text": "Ocean : Fish", "is_correct": false}, {"option_text": "Mountain : Height", "is_correct": false}, {"option_text": "Desert : Sand", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('4cc9c087-a1e5-52e8-abd2-efe49e62acc3', 'Choose the pair that best expresses the same relationship as: BIOGRAPHY : PERSON', NULL, 'D is correct. BIOGRAPHY = a written account of a PERSON''s life (written record about its subject). BIBLIOGRAPHY = a list/written record of BOOKS (written record about its subject). Both follow the pattern: ''written record/account'' → ''what it documents''. Trap: Itinerary : Journey = a plan FOR a journey (not a record OF it); Obituary : Death = a notice about a person''s death (related to a person, not death itself as a concept); Topography : Land = the study or mapping of the surface (similar but ''topography'' is a study method, not a life account).', 'HARD', 'Vocabulary', 'Word Pairs — Analogy and Relationship (W11 B2)', 'VOCAB_WORD_PAIRS_III_W11_B2', '[{"option_text": "Itinerary : Journey", "is_correct": false}, {"option_text": "Obituary : Death", "is_correct": false}, {"option_text": "Topography : Land", "is_correct": false}, {"option_text": "Bibliography : Books", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c7714f66-08b7-5d2a-be68-5a2030a24302', 'Choose the pair that best expresses the same relationship as: MUSIC : DISCORD', NULL, 'D is correct. MUSIC = organised, harmonious sound; DISCORD = unpleasant, disorganised sound (a corrupted/failed form of music). LANGUAGE = organised, meaningful communication; BABBLE = disorganised, meaningless speech (a corrupted/failed form of language). The relationship: organised form → its disorganised/failed corruption. Trap: Order:Chaos = abstract opposites (not specifically ''failed form of''); Speech:Noise = broader category vs random sound (not the same ''musical harmony → disharmony'' parallel); Art:Mediocrity = quality spectrum (not the ''organised vs disorganised form'' pattern).', 'HARD', 'Vocabulary', 'Word Pairs — Analogy and Relationship (W11 B2)', 'VOCAB_WORD_PAIRS_III_W11_B2', '[{"option_text": "Speech : Noise", "is_correct": false}, {"option_text": "Order : Chaos", "is_correct": false}, {"option_text": "Art : Mediocrity", "is_correct": false}, {"option_text": "Language : Babble", "is_correct": true}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('283c9a2e-6f43-59a4-a0e4-d91be7d3f7da', 'Choose the pair that best expresses the same relationship as: MISERLY : FRUGAL', NULL, 'A is correct. MISERLY = extremely stingy (negative connotation); FRUGAL = careful with money (neutral/positive connotation). They describe similar behaviour but with very different value judgments — MISERLY is the extreme, negative-connotation version of FRUGAL. GENEROUS = giving freely (neutral/positive); EXTRAVAGANT = excessively wasteful (negative connotation). The relationship: one word carries the excessive/negative form while the other carries the restrained/positive version of the same behaviour. Trap: Angry:Furious = degree intensification on same connotation scale (both negative); Cold:Chilly = degree difference (both neutral); Smart:Brilliant = positive degree intensification.', 'HARD', 'Vocabulary', 'Word Pairs — Analogy and Relationship (W11 B2)', 'VOCAB_WORD_PAIRS_III_W11_B2', '[{"option_text": "Generous : Extravagant", "is_correct": true}, {"option_text": "Angry : Furious", "is_correct": false}, {"option_text": "Cold : Chilly", "is_correct": false}, {"option_text": "Smart : Brilliant", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d7e51016-c421-5bd0-83fb-84d481f3b465', 'Choose the correctly used pair:
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('403990a5-ea74-5612-97e6-68cc77329ee2', 'Which sentence uses the word ''LIE'' correctly?', NULL, 'B is correct. LIE (to be situated/positioned, intransitive) — present tense ''lies'': ''The solution lies in communication'' ✓. Confusable: LAY (transitive, to place something — takes an object): ''Lay the book on the table.'' Past tense of LIE = LAY: ''He lay down for a nap'' (NOT ''lied down'' — ''lied'' is past of ''to lie'' = to tell a falsehood). ''Please lie down carefully'' (intransitive — no object). Trap: ''lied the book on the table'' = LAY is correct here; ''lied down'' = should be ''lay down'' (past tense of lie = to recline).', 'HARD', 'Vocabulary', 'Vocabulary Word Pairs — Commonly Confused and Misused Words (W11 B1)', 'VOCAB_WORD_PAIRS_W11_B1', '[{"option_text": "She lied the book on the table.", "is_correct": false}, {"option_text": "The solution lies in communication.", "is_correct": true}, {"option_text": "He lied down for a nap.", "is_correct": false}, {"option_text": "Please lay down carefully.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('37f5d87d-cf32-5d68-ba2f-42c6f57a9c74', 'Choose the sentence that correctly uses FEWER vs LESS:', NULL, 'C is correct. FEWER = used with countable nouns (people, students, books are countable). LESS = used with uncountable nouns (money, water, time). ''Fewer than ten people'' ✓ (people is countable). Trap: ''less students'' = wrong (students is countable → should be FEWER); ''fewer money'' = wrong (money is uncountable → should be LESS); ''less books'' = wrong (books is countable → should be FEWER).', 'HARD', 'Vocabulary', 'Vocabulary Word Pairs — Commonly Confused and Misused Words (W11 B1)', 'VOCAB_WORD_PAIRS_W11_B1', '[{"option_text": "There are less students in the class today.", "is_correct": false}, {"option_text": "He earns fewer money than his brother.", "is_correct": false}, {"option_text": "Fewer than ten people attended the event.", "is_correct": true}, {"option_text": "She has less books than he does.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1455de6d-504e-54ad-8398-d26d33807922', 'Which of the following correctly uses FURTHER vs FARTHER?', NULL, 'B is correct. FARTHER = physical distance (comparative of ''far''). FURTHER = additional extent, degree, or figurative distance. ''We need to go farther down the road'' ✓ (literal physical distance). Trap: ''farther discussion'' = should be FURTHER (figurative/non-physical); ''walk farther into the matter'' = should be FURTHER (figurative — delving deeper); ''further investigation about the distance'' = mixed use (distance = physical, but ''investigation'' is abstract — overall FURTHER is correct here, making C wrong only because of ''about the distance'' at the end being unnatural).', 'HARD', 'Vocabulary', 'Vocabulary Word Pairs — Commonly Confused and Misused Words (W11 B1)', 'VOCAB_WORD_PAIRS_W11_B1', '[{"option_text": "The hospital is farther discussion from here.", "is_correct": false}, {"option_text": "We need to go farther down the road.", "is_correct": true}, {"option_text": "Further investigation is needed about the distance.", "is_correct": false}, {"option_text": "Let''s walk farther into the matter.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('59b0a9d7-762f-5104-b67d-375d0e8ef350', 'Choose the sentence that correctly uses ASSURE, ENSURE, or INSURE:', NULL, 'C is correct. ASSURE = to tell someone confidently to remove their doubts (assure a PERSON). ENSURE = to make certain that something happens (ensure an OUTCOME). INSURE = to take out insurance on property/life. ''Assured the client'' = told the client confidently ✓. Trap: ''ensure me'' = ASSURE is used with a person, ENSURE with an outcome; ''insure the success'' = SUCCESS is not an insurance policy — should be ENSURE; ''assured the car'' = the car is not a person — should be INSURED.', 'HARD', 'Vocabulary', 'Vocabulary Word Pairs — Commonly Confused and Misused Words (W11 B1)', 'VOCAB_WORD_PAIRS_W11_B1', '[{"option_text": "Please ensure me that you will attend.", "is_correct": false}, {"option_text": "We need to insure the success of the event.", "is_correct": false}, {"option_text": "The manager assured the client that refunds would be processed.", "is_correct": true}, {"option_text": "He assured the car against theft.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('9bf3bc92-624e-5709-b76d-7ebbeae4ad6f', 'Which sentence correctly uses EMINENT vs IMMINENT?', NULL, 'C is correct. EMINENT = famous and respected in a particular field. IMMINENT = about to happen very soon. ''An eminent judge'' = a well-respected, distinguished judge ✓. Trap: ''Rain is eminent'' = should be IMMINENT (rain is about to happen); ''an imminent scientist'' = should be EMINENT (famous scientist); ''eminent to go bankrupt'' = should be IMMINENT (about to go bankrupt).', 'MEDIUM', 'Vocabulary', 'Vocabulary Word Pairs — Commonly Confused and Misused Words (W11 B1)', 'VOCAB_WORD_PAIRS_W11_B1', '[{"option_text": "Rain is eminent as the sky darkens.", "is_correct": false}, {"option_text": "He is an imminent scientist in the field.", "is_correct": false}, {"option_text": "An eminent judge presided over the case.", "is_correct": true}, {"option_text": "The company is eminent to go bankrupt.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1dc78846-3fbb-5d3b-a8e2-66845e7911ab', 'Which sentence correctly uses ACCEPT vs EXCEPT?', NULL, 'C is correct. ACCEPT (verb) = to receive or agree to something. EXCEPT (preposition/conjunction) = not including; other than. ''Please accept our sincere apologies'' = please receive/agree to our apologies ✓. Trap: ''Everyone accept Rahul'' = should be EXCEPT (not including Rahul); ''she excepted the award'' = should be ACCEPTED (received the award); ''all members accept three'' = should be EXCEPT three.', 'MEDIUM', 'Vocabulary', 'Vocabulary Word Pairs — Commonly Confused and Misused Words (W11 B1)', 'VOCAB_WORD_PAIRS_W11_B1', '[{"option_text": "Everyone accept Rahul agreed to the plan.", "is_correct": false}, {"option_text": "She excepted the award graciously.", "is_correct": false}, {"option_text": "Please accept our sincere apologies.", "is_correct": true}, {"option_text": "All members accept three voted in favour.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('dd66560a-1340-589e-a4bc-c06926dc360a', 'Choose the sentence that correctly uses ADVERSE vs AVERSE:', NULL, 'B is correct. ADVERSE (adjective) = harmful or unfavourable (collocates with: conditions, effects, circumstances). AVERSE (adjective) = having a strong dislike or opposition to something (collocates with: to + noun/gerund — ''averse to risk''). ''Adverse weather conditions'' = unfavourable weather ✓. Trap: ''adverse to taking risks'' = should be AVERSE to (personal dislike/reluctance); ''an averse effect'' = should be ADVERSE effect (harmful/negative effect); ''adverse from'' = ungrammatical (AVERSE takes ''to'', not ''from'').', 'HARD', 'Vocabulary', 'Vocabulary Word Pairs — Commonly Confused and Misused Words (W11 B1)', 'VOCAB_WORD_PAIRS_W11_B1', '[{"option_text": "She is adverse to taking risks.", "is_correct": false}, {"option_text": "The project faced adverse weather conditions.", "is_correct": true}, {"option_text": "The plan had an averse effect on sales.", "is_correct": false}, {"option_text": "He is adverse from travelling alone.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('132a134d-4659-5aec-8dd9-35c01321e6a6', 'Which sentence correctly uses CONTINUOUS vs CONTINUAL?', NULL, 'B is correct. CONTINUAL = frequently recurring but with breaks in between. CONTINUOUS = happening without any pause or break. ''Continual mistakes'' = he kept making mistakes repeatedly (but there were pauses between each mistake) ✓. Trap: ''the machine runs continual'' = machines that run without stopping are CONTINUOUS (no pauses); ''a continuous series of interruptions'' = interruptions by definition have gaps = CONTINUAL is better; ''the river flows with continual movement'' = a river flows without stopping = CONTINUOUS.', 'HARD', 'Vocabulary', 'Vocabulary Word Pairs — Commonly Confused and Misused Words (W11 B1)', 'VOCAB_WORD_PAIRS_W11_B1', '[{"option_text": "The machine runs continual without stopping.", "is_correct": false}, {"option_text": "He made continual mistakes throughout the test.", "is_correct": true}, {"option_text": "There was a continuous series of interruptions.", "is_correct": false}, {"option_text": "The river flows with continual movement.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('2e51f3e8-0764-5ff6-958d-79dfd9d05c0c', 'Which sentence correctly uses COMPOSED vs COMPRISED?', NULL, 'C is correct. COMPOSED OF = made up of (passive: ''is composed of''). COMPRISE = to include or contain (active, no ''of'' needed): ''The committee comprises ten members.'' ''Is composed of twelve directors'' ✓ (correct passive usage). Trap: ''is comprised of'' = widely used but technically incorrect; the correct form is either ''comprises X'' (active) or ''is composed of X'' (passive); ''comprises of'' = wrong (''of'' is redundant after comprises); ''comprised from'' = wrong preposition.', 'HARD', 'Vocabulary', 'Vocabulary Word Pairs — Commonly Confused and Misused Words (W11 B1)', 'VOCAB_WORD_PAIRS_W11_B1', '[{"option_text": "The team is comprised of five members.", "is_correct": false}, {"option_text": "The committee comprises of ten members.", "is_correct": false}, {"option_text": "The board is composed of twelve directors.", "is_correct": true}, {"option_text": "The army comprised from three battalions.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('89e8e8d6-74ef-5b93-aae7-ce1561ad4c1c', 'The root ''BENE'' (as in BENEFICIAL, BENEVOLENT) means:', NULL, 'B is correct. ''BENE'' = good/well (Latin). Examples: Beneficial (producing good results), Benevolent (well-wishing, kind), Benefactor (one who does good deeds), Benign (kind, harmless). Antonym root: ''MAL'' = bad/evil (malevolent, malicious, malefactor). Trap: ''Below'' = ''sub-''; ''Against'' = ''anti-'' or ''contra-''; ''Bad'' = ''mal-''.', 'EASY', 'Vocabulary', 'Word Roots and Prefixes — Meaning from Word Structure (W11 B1)', 'VOCAB_WORD_ROOTS_W11_B1', '[{"option_text": "Bad or evil", "is_correct": false}, {"option_text": "Good or well", "is_correct": true}, {"option_text": "Against", "is_correct": false}, {"option_text": "Below", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1cff303c-c613-58f6-b7b3-dff7bef97462', 'The suffix ''-CIDE'' (as in HOMICIDE, PESTICIDE, PATRICIDE) means:', NULL, 'C is correct. ''-CIDE'' = killing of (Latin: caedere = to kill). Homicide = killing of a human; Pesticide = killer of pests; Patricide = killing of one''s father; Genocide = killing of a racial group; Infanticide = killing of an infant. Trap: ''Study of'' = ''-ology''; ''Rule of'' = ''-cracy''; ''Fear of'' = ''-phobia''.', 'EASY', 'Vocabulary', 'Word Roots and Prefixes — Meaning from Word Structure (W11 B1)', 'VOCAB_WORD_ROOTS_W11_B1', '[{"option_text": "Study of", "is_correct": false}, {"option_text": "Rule or government of", "is_correct": false}, {"option_text": "Killing of", "is_correct": true}, {"option_text": "Fear of", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8c3981f7-21ed-5936-92fb-b792e253b7e1', 'Which word uses the root ''LOGY'' (meaning ''study of'') INCORRECTLY?', NULL, 'B is incorrect. ANTHOLOGY does NOT mean ''study of flowers''. ANTHOLOGY = a collection of literary works (poems, stories). Root: ''antho'' = flower + ''logia'' = collection — originally a ''gathering of flowers'' used metaphorically for a collection of literary pieces. The word for ''study of flowers'' is BOTANY or specifically ANTHOLOGY is wrongly associated with ''study''. ''ANTHROLOGY'' doesn''t exist; the correct term would be part of BOTANY. Geology ✓ (geo=earth), Zoology ✓ (zoo=animal), Physiology ✓ (physio=nature/function).', 'MEDIUM', 'Vocabulary', 'Word Roots and Prefixes — Meaning from Word Structure (W11 B1)', 'VOCAB_WORD_ROOTS_W11_B1', '[{"option_text": "Geology — study of the earth", "is_correct": false}, {"option_text": "Anthology — study of flowers", "is_correct": true}, {"option_text": "Zoology — study of animals", "is_correct": false}, {"option_text": "Physiology — study of body functions", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('734c25a5-aea9-572f-ad24-e81df7352e46', 'The prefix ''PHIL'' or ''PHILO'' (as in PHILOSOPHY, PHILANTHROPIST) means:', NULL, 'C is correct. ''PHIL/PHILO'' = love (Greek: philos = loving/beloved). Philosophy = love of wisdom (sophia = wisdom). Philanthropist = lover of humanity (anthropos = human). Bibliophile = book lover. Antonym: ''MISO'' = hatred (misanthrope = one who hates humanity). Trap: Fear = phob-; Hatred = miso-; Wisdom = sophia (component in philosophy but not the prefix).', 'MEDIUM', 'Vocabulary', 'Word Roots and Prefixes — Meaning from Word Structure (W11 B1)', 'VOCAB_WORD_ROOTS_W11_B1', '[{"option_text": "Fear", "is_correct": false}, {"option_text": "Hatred", "is_correct": false}, {"option_text": "Love", "is_correct": true}, {"option_text": "Wisdom", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('8548a5b3-8b7e-5421-b070-6f0b6cfb56f3', 'Which pair correctly pairs a ''-CRACY'' suffix word with its meaning?', NULL, 'B is correct. ''-CRACY'' = rule/government (Greek: kratos = power). THEOCRACY = rule by God or religious leaders (theos = God). Plutocracy = rule by the wealthy (ploutos = wealth). Ochlocracy = rule by the mob (ochlos = mob). Meritocracy = rule by the most able/talented (merit = deserved reward). Trap: Plutocracy ≠ military (that''s stratocracy); Ochlocracy ≠ individual rule (that''s autocracy/monarchy); Meritocracy ≠ elderly (that''s gerontocracy).', 'MEDIUM', 'Vocabulary', 'Word Roots and Prefixes — Meaning from Word Structure (W11 B1)', 'VOCAB_WORD_ROOTS_W11_B1', '[{"option_text": "Plutocracy — rule by military", "is_correct": false}, {"option_text": "Theocracy — rule by the church/religious leaders", "is_correct": true}, {"option_text": "Ochlocracy — rule by a single individual", "is_correct": false}, {"option_text": "Meritocracy — rule by the elderly", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fb3ad8a3-e286-5521-80cc-ef5af5c1f4a7', 'The prefix ''ANTE'' (as in ANTECEDENT, ANTEROOM) means:', NULL, 'C is correct. ''ANTE'' = before (Latin). Antecedent = something that comes before; Anteroom = a room before another/a waiting room. Compare with ''ANTI'' (= against) — these are commonly confused. ''Ante-'' = before (in time or space); ''Anti-'' = against or opposed to. Other ''ante-'' words: antenatal (before birth), antediluvian (before the flood = very old). Trap: Against = anti-; After = post-; Below = sub-.', 'HARD', 'Vocabulary', 'Word Roots and Prefixes — Meaning from Word Structure (W11 B1)', 'VOCAB_WORD_ROOTS_W11_B1', '[{"option_text": "Against", "is_correct": false}, {"option_text": "After or following", "is_correct": false}, {"option_text": "Before", "is_correct": true}, {"option_text": "Beneath or below", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('32bdeae9-0c07-5dcd-b22c-f42e49f15ed4', 'Which word does NOT contain the root ''CHRON'' (= time, from Greek ''chronos'')?', NULL, 'C is correct. ANTHOLOGY does NOT contain the ''chron'' root. Anthology = a collection of literary works; root = ''antho'' (Greek: flower) + ''logia'' (collection) — literally a ''gathering of flowers'' used metaphorically. It has nothing to do with time. The other three all use ''chron'': Chronological (chrono = time + logos = order/study), Synchronize (syn = together + chron = at the same time), Anachronism (ana = against + chron = wrong in time). Trap: ''Synchronize'' starts with ''sy'' so students might miss the ''chron'' inside it.', 'HARD', 'Vocabulary', 'Word Roots and Prefixes — Meaning from Word Structure (W11 B1)', 'VOCAB_WORD_ROOTS_W11_B1', '[{"option_text": "Chronological", "is_correct": false}, {"option_text": "Synchronize", "is_correct": false}, {"option_text": "Anthology", "is_correct": true}, {"option_text": "Anachronism", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('fee316d1-c5f9-5e98-ae8c-1f98a9b82ad7', 'The root ''BREV'' (as in BRIEF, ABBREVIATE, BREVITY) means:', NULL, 'B is correct. ''BREV'' = short (Latin: brevis). Brief = short; Brevity = shortness/conciseness; Abbreviate = to shorten; Breve (music) = a short note. Antonym: ''LONG/LONGI'' = long (longitude, elongate). Trap: ''Long'' is the exact antonym of ''brev-''; ''Wide'' = ''lati-''; ''Strong'' = ''fort-''.', 'MEDIUM', 'Vocabulary', 'Word Roots and Prefixes — Meaning from Word Structure (W11 B1)', 'VOCAB_WORD_ROOTS_W11_B1', '[{"option_text": "Long", "is_correct": false}, {"option_text": "Short", "is_correct": true}, {"option_text": "Wide", "is_correct": false}, {"option_text": "Strong", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('89b18377-ec76-50b8-9187-f477d48f1f8a', 'Which word correctly uses the prefix ''PSEUDO'' (= false, fake)?', NULL, 'B is correct. PSEUDONYM = a false or assumed name (pseudo = false, nym = name). Authors use pseudonyms to publish under a different name. Examples: George Eliot (Mary Ann Evans), Mark Twain (Samuel Clemens). Other ''pseudo-'' words: Pseudoscience (false science), Pseudopod (false foot — structure in amoeba). Trap: A says ''real name'' (opposite); C and D give wrong definitions.', 'EASY', 'Vocabulary', 'Word Roots and Prefixes — Meaning from Word Structure (W11 B1)', 'VOCAB_WORD_ROOTS_W11_B1', '[{"option_text": "Pseudonym — a real name used in publications", "is_correct": false}, {"option_text": "Pseudonym — a false or pen name used instead of one''s real name", "is_correct": true}, {"option_text": "Pseudonym — an abbreviation of a long name", "is_correct": false}, {"option_text": "Pseudonym — a name given at birth", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d02f97c1-4dfd-5719-a61e-b630d00c2f0c', 'The root ''GREG'' (as in AGGREGATE, CONGREGATE, SEGREGATE) means:', NULL, 'C is correct. ''GREG'' = flock/herd/crowd (Latin: grex). Aggregate = gather into a mass (ad + grex); Congregate = gather together (con + grex); Segregate = separate from the flock (se + grex); Gregarious = sociable, fond of being in a group. Trap: ''To lead'' = ''ag-'' or ''duc-''; ''To separate'' is what ''segregate'' does but the root itself means ''flock''; ''To measure'' = ''metr-''.', 'HARD', 'Vocabulary', 'Word Roots and Prefixes — Meaning from Word Structure (W11 B1)', 'VOCAB_WORD_ROOTS_W11_B1', '[{"option_text": "To lead or guide", "is_correct": false}, {"option_text": "To separate or divide", "is_correct": false}, {"option_text": "A flock or crowd", "is_correct": true}, {"option_text": "To measure or count", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('1af33820-334d-5e99-b5d9-792d1d7d2100', 'Choose the sentence that uses ''PERENNIAL'' correctly.', NULL, 'C is correct. PERENNIAL = lasting or existing for a long or seemingly endless time; recurring year after year. ''Poverty remains a perennial problem'' — poverty persists endlessly/recurrently. Trap: A uses ''perennial'' for a short event (contradictory); B (''perennial smile'') makes sense only if it was a lifelong, constant smile (not wrong but unusual usage); D (''perennial examination'') is illogical — an exam result is a one-time event.', 'MEDIUM', 'Vocabulary', 'Correct Word Usage — Choose the Right Context (W10)', 'VOCAB_WORD_USAGE_W10', '[{"option_text": "The perennial summer vacation lasted only two weeks.", "is_correct": false}, {"option_text": "She wore a perennial smile whenever she met old friends.", "is_correct": false}, {"option_text": "Poverty remains a perennial problem in many developing nations.", "is_correct": true}, {"option_text": "The perennial examination result was announced yesterday.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('50ba4c5b-204e-55d9-80c5-634df3435087', 'Choose the sentence that uses ''MITIGATE'' correctly.', NULL, 'B is correct. MITIGATE = to make less severe, serious, or painful; to lessen the impact of something negative. ''Mitigate the effects of climate change'' = reduce the harmful impacts. Trap: A confuses ''mitigate'' with ''apply'' or ''enact''; C confuses it with ''sentence'' (a judge sentences, not mitigates, people); D misuses ''mitigate'' for positive emotions (you don''t mitigate joy).', 'MEDIUM', 'Vocabulary', 'Correct Word Usage — Choose the Right Context (W10)', 'VOCAB_WORD_USAGE_W10', '[{"option_text": "The government mitigated the new tax law to all citizens.", "is_correct": false}, {"option_text": "Planting trees can help mitigate the effects of climate change.", "is_correct": true}, {"option_text": "The judge mitigated the criminal to life imprisonment.", "is_correct": false}, {"option_text": "She mitigated her feelings of joy during the celebration.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c356c505-4995-5b8a-a51b-25c03ff7e115', 'Choose the sentence that uses ''PLAUSIBLE'' correctly.', NULL, 'B is correct. PLAUSIBLE = seeming reasonable or probable; appearing valid even if not verified. ''His excuse seemed plausible'' — it appeared credible. Trap: A misuses ''plausible'' for a factually false claim (Earth being flat is not plausible but is claimed); C uses it for a verified fact (''plausible fact'' is a contradiction — facts don''t need to ''seem'' plausible); D confuses ''plausible'' with ''talented'' or ''likable.''', 'MEDIUM', 'Vocabulary', 'Correct Word Usage — Choose the Right Context (W10)', 'VOCAB_WORD_USAGE_W10', '[{"option_text": "It is plausible that the Earth is flat.", "is_correct": false}, {"option_text": "His excuse seemed plausible, though the manager remained sceptical.", "is_correct": true}, {"option_text": "The plausible fact about water is that it is H₂O.", "is_correct": false}, {"option_text": "She was a plausible singer at the concert.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('f0a0aacb-a5ae-5c9f-bc96-8dfafdbf775b', 'Choose the sentence that uses ''AMBIGUOUS'' correctly.', NULL, 'A is correct. AMBIGUOUS = open to more than one interpretation; unclear or doubtful in meaning. ''Instructions were ambiguous, leaving workers confused'' — unclear instructions causing uncertainty. Trap: B uses ''ambiguous'' for a praised performance (contradictory — ambiguous implies uncertainty, not excellence); C pairs ''ambiguous'' with ''dedication'' (dedication implies clarity of purpose, the opposite); D uses it with ''success'' (success is not ambiguous unless specified as partial).', 'MEDIUM', 'Vocabulary', 'Correct Word Usage — Choose the Right Context (W10)', 'VOCAB_WORD_USAGE_W10', '[{"option_text": "The instructions were ambiguous, leaving workers confused about the procedure.", "is_correct": true}, {"option_text": "She gave an ambiguous performance that won universal praise.", "is_correct": false}, {"option_text": "His ambiguous dedication to the project was evident from his long hours.", "is_correct": false}, {"option_text": "The ambiguous success of the campaign surprised the analysts.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('a74cbd42-a07a-5b08-b170-0e89e25d4503', 'Choose the sentence that uses ''RETICENT'' correctly.', NULL, 'A is correct. RETICENT = not revealing one''s thoughts or feelings readily; reluctant to speak or express opinions. ''Reticent about sharing her views'' = unwilling to express herself openly. Trap: B contradicts itself (reticent = silent/reserved, but ''applauded loudly'' is the opposite); C misuses reticent as ''humble'' or ''reluctant to brag'' (incorrect meaning); D uses it for test performance (unrelated to reticence).', 'HARD', 'Vocabulary', 'Correct Word Usage — Choose the Right Context (W10)', 'VOCAB_WORD_USAGE_W10', '[{"option_text": "She was reticent about sharing her views during the debate.", "is_correct": true}, {"option_text": "The reticent audience applauded loudly after the performance.", "is_correct": false}, {"option_text": "He was reticent to accept the generous compliment graciously.", "is_correct": false}, {"option_text": "The child was reticent in answering all questions correctly.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('d8049dee-a9eb-54da-9d45-e671949ab4aa', 'Choose the sentence that uses ''ENERVATE'' correctly.', NULL, 'B is correct. ENERVATE = to cause someone to feel drained of energy or vitality; to weaken. ''The long hike...enervated the hikers'' = drained them of energy. Trap: A confuses ''enervate'' with ''energize'' or ''invigorate'' (opposites); C uses it for positive news (promotion = enervating? — illogical); D confuses it with ''hamper'' or ''suppress'' in economic context (though loosely possible, ''enervate'' is primarily about draining people, not economies).', 'HARD', 'Vocabulary', 'Correct Word Usage — Choose the Right Context (W10)', 'VOCAB_WORD_USAGE_W10', '[{"option_text": "The motivational speech enervated the team to work harder.", "is_correct": false}, {"option_text": "The long hike in the scorching heat completely enervated the hikers.", "is_correct": true}, {"option_text": "She was enervated by the news of her promotion.", "is_correct": false}, {"option_text": "The new policy enervated economic growth in the region.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('22b32c8b-e8cd-53db-87b2-518a523a16ef', 'Choose the sentence that uses ''TACIT'' correctly.', NULL, 'B is correct. TACIT = understood or implied without being stated; silent, unspoken. ''A tacit understanding...no words were needed'' — something known between people without being said. Trap: A contradicts itself (''tacit speech'' is an oxymoron — tacit means unspoken); C misuses ''tacit'' for ''quick'' or ''thorough''; D confuses ''tacit'' with ''formal'' or ''official'' (resolutions are explicit, not tacit).', 'HARD', 'Vocabulary', 'Correct Word Usage — Choose the Right Context (W10)', 'VOCAB_WORD_USAGE_W10', '[{"option_text": "She gave a tacit speech at the conference that moved everyone.", "is_correct": false}, {"option_text": "There was a tacit understanding between them that no words were needed.", "is_correct": true}, {"option_text": "He was tacit in answering every question during the interview.", "is_correct": false}, {"option_text": "The committee issued a tacit resolution about the new policy.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('44c72234-1611-5173-bf7a-ca32b376d215', 'Choose the sentence that uses ''GREGARIOUS'' correctly.', NULL, 'B is correct. GREGARIOUS = fond of company; sociable; enjoying being in crowds or groups. ''Gregarious nature made her the centre of attention at parties'' = she is sociable and thrives in social settings. Trap: A pairs it with a hermit (who is, by definition, reclusive — the opposite of gregarious); C contradicts itself (gregarious + prefers silence); D misuses it as an adjective for a restrictive policy (incorrect context entirely).', 'HARD', 'Vocabulary', 'Correct Word Usage — Choose the Right Context (W10)', 'VOCAB_WORD_USAGE_W10', '[{"option_text": "The gregarious hermit spent decades in solitary meditation.", "is_correct": false}, {"option_text": "Her gregarious nature made her the centre of attention at parties.", "is_correct": true}, {"option_text": "He was known for his gregarious work habits — he preferred silence.", "is_correct": false}, {"option_text": "The gregarious policy restricted public gatherings.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('b57ac401-6fe4-5320-a8a5-c69fe7069e9d', 'Choose the sentence that uses ''VERBOSE'' correctly.', NULL, 'B is correct. VERBOSE = using or expressed in more words than are needed; wordy, long-winded. ''Her verbose explanation ran to thirty minutes when three would have sufficed'' — she used far more words than necessary. Trap: A describes a writer of minimal output (opposite of verbose); C is an oxymoron (verbose + silence); D contradicts itself (a verbose summary that is brief is a contradiction).', 'HARD', 'Vocabulary', 'Correct Word Usage — Choose the Right Context (W10)', 'VOCAB_WORD_USAGE_W10', '[{"option_text": "The verbose poet wrote only three short haiku in his entire life.", "is_correct": false}, {"option_text": "Her verbose explanation ran to thirty minutes when three would have sufficed.", "is_correct": true}, {"option_text": "He was verbose in his silence, conveying much without speaking.", "is_correct": false}, {"option_text": "The verbose summary captured all key points in two sentences.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quiz_questions (id, question_text, image_url, explanation, difficulty, subject, topic, topic_code, options, created_at) VALUES ('c7e9b91d-0bf0-5e3c-8fa9-925736664680', 'Choose the sentence that uses ''SPURIOUS'' correctly.', NULL, 'B is correct. SPURIOUS = not being what it purports to be; false, fake, or counterfeit. ''Spurious claim that the medication cured all diseases'' = a false, unverifiable, or fraudulent claim. Trap: A contradicts itself (genuine and spurious are opposites — cannot be both); C misuses spurious for hard work (spurious ≠ diligent); D pairs ''spurious'' with ''real achievements'' (contradictory — if achievements are real, the announcement about them isn''t spurious).', 'HARD', 'Vocabulary', 'Correct Word Usage — Choose the Right Context (W10)', 'VOCAB_WORD_USAGE_W10', '[{"option_text": "The evidence presented in court was genuine and spurious.", "is_correct": false}, {"option_text": "The scientist dismissed the spurious claim that the medication cured all diseases.", "is_correct": true}, {"option_text": "Her spurious efforts led to the successful completion of the project.", "is_correct": false}, {"option_text": "The chairman made a spurious announcement praising the team''s real achievements.", "is_correct": false}]', NOW()) ON CONFLICT (id) DO NOTHING;
